def _slider_preview_rig(context):
    if not context or not getattr(context, "scene", None):
        return None
    settings = getattr(context.scene, "wgame_rigging_assistant", None)
    rig_obj = bpy.data.objects.get(settings.rig_name) if settings else None
    if rig_obj and rig_obj.type == "ARMATURE" and rig_obj.get("wgame_rig_kind") == "deform_skeleton":
        return rig_obj
    return next(
        (
            obj
            for obj in context.scene.objects
            if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"
        ),
        None,
    )


def _capture_slider_preview_base(rig_obj):
    if SLIDER_PREVIEW_BACKUP_KEY in rig_obj:
        return
    pose = {
        bone.name: [float(value) for row in bone.matrix_basis for value in row]
        for bone in rig_obj.pose.bones
    }
    rig_obj[SLIDER_PREVIEW_BACKUP_KEY] = json.dumps(pose, separators=(",", ":"))


def _restore_slider_preview_base(rig_obj, clear=False):
    raw = rig_obj.get(SLIDER_PREVIEW_BACKUP_KEY)
    if not raw:
        return False
    try:
        pose = json.loads(raw)
    except (TypeError, ValueError):
        return False
    for name, values in pose.items():
        bone = rig_obj.pose.bones.get(name)
        if bone and isinstance(values, list) and len(values) == 16:
            bone.matrix_basis = Matrix((values[0:4], values[4:8], values[8:12], values[12:16]))
    if clear:
        del rig_obj[SLIDER_PREVIEW_BACKUP_KEY]
    return True


def _reset_slider_properties(settings):
    global _SLIDER_PREVIEW_APPLYING
    _SLIDER_PREVIEW_APPLYING = True
    try:
        for name in SLIDER_PREVIEW_PROPERTIES:
            setattr(settings, name, 0.0)
    finally:
        _SLIDER_PREVIEW_APPLYING = False


def _apply_wgame_slider_preview(settings, context):
    global _SLIDER_PREVIEW_APPLYING
    if _SLIDER_PREVIEW_APPLYING:
        return
    rig_obj = _slider_preview_rig(context)
    if not rig_obj:
        return
    values = {name: float(getattr(settings, name, 0.0)) for name in SLIDER_PREVIEW_PROPERTIES}
    if not any(abs(value) > 1e-6 for value in values.values()):
        if _restore_slider_preview_base(rig_obj, clear=True):
            context.view_layer.update()
        settings.wgame_preview_active = False
        settings.wgame_preview_preset = ""
        return
    if getattr(context, "object", None) and context.object.mode == "EDIT":
        return
    if SLIDER_PREVIEW_BACKUP_KEY not in rig_obj and POSE_BACKUP_KEY in rig_obj:
        _restore_pose_backup(rig_obj)
    _capture_slider_preview_base(rig_obj)
    _restore_slider_preview_base(rig_obj, clear=False)

    side_mode = settings.wgame_muscle_side

    def side_enabled(side):
        return side_mode == "BOTH" or side_mode == side

    def rotate(name, axis, angle):
        bone = rig_obj.pose.bones.get(name)
        if bone and abs(angle) > 1e-8:
            bone.matrix_basis = bone.matrix_basis @ Matrix.Rotation(angle, 4, axis)

    body_bend = values["wgame_muscle_body_bend"]
    body_twist = values["wgame_muscle_body_twist"]
    rotate("spine_01.x", "X", body_bend * 0.16)
    rotate("spine_02.x", "X", body_bend * 0.20)
    rotate("upper_chest.x", "X", body_bend * 0.12)
    rotate("spine_01.x", "Y", body_twist * 0.16)
    rotate("spine_02.x", "Y", body_twist * 0.22)
    rotate("upper_chest.x", "Y", body_twist * 0.14)
    rotate("neck.x", "Y", body_twist * -0.10)

    arm_close = values["wgame_muscle_arm_close"]
    arm_front = values["wgame_muscle_arm_front"]
    elbow_bend = values["wgame_muscle_elbow_bend"]
    forearm_twist = values["wgame_muscle_forearm_twist"]
    for side, suffix, sign in (("LEFT", ".l", 1.0), ("RIGHT", ".r", -1.0)):
        if not side_enabled(side):
            continue
        rotate("upper_arm" + suffix, "X", arm_close * 1.05)
        rotate("upper_arm" + suffix, "Z", arm_front * 0.75 * sign)
        rotate("forearm" + suffix, "X", elbow_bend * 1.45)
        rotate("forearm" + suffix, "Y", forearm_twist * 0.95 * sign)

    finger_curl = values["wgame_muscle_finger_curl"]
    finger_spread = values["wgame_muscle_finger_spread"]
    for side, suffix, sign in (("LEFT", ".l", 1.0), ("RIGHT", ".r", -1.0)):
        if not side_enabled(side):
            continue
        for finger_index, finger in enumerate(("thumb", "index", "middle", "ring", "pinky")):
            for segment, factor in ((1, 0.42), (2, 0.70), (3, 0.82)):
                rotate(f"{finger}_{segment:02d}{suffix}", "X", finger_curl * factor * sign)
            spread_factor = (finger_index - 2) * 0.06
            rotate(f"{finger}_01{suffix}", "Z", finger_spread * spread_factor * sign)

    leg_open = values["wgame_muscle_leg_open"]
    leg_front = values["wgame_muscle_leg_front"]
    knee_bend = values["wgame_muscle_knee_bend"]
    foot_bend = values["wgame_muscle_foot_bend"]
    for side, suffix, sign in (("LEFT", ".l", 1.0), ("RIGHT", ".r", -1.0)):
        if not side_enabled(side):
            continue
        rotate("thigh" + suffix, "Z", leg_open * 0.55 * sign)
        rotate("thigh" + suffix, "X", leg_front * 0.90)
        rotate("lower_leg" + suffix, "X", knee_bend * -1.45)
        rotate("foot" + suffix, "X", foot_bend * 0.60)

    cape_swing = values["wgame_muscle_cape_swing"]
    for name in ("cape.l_01", "cape.x_01", "cape.r_01"):
        rotate(name, "X", cape_swing * 0.52)
    attachment_swing = values["wgame_muscle_attachment_swing"]
    for name, factor in (
        ("swing_01.x_01", 0.60),
        ("swing_02.x_01", -0.55),
        ("pouch_01.r", 0.45),
        ("quiver_01.l", -0.40),
    ):
        rotate(name, "Y", attachment_swing * factor)

    context.view_layer.update()
    settings.wgame_preview_active = True
    settings.wgame_preview_preset = "MUSCLE_SLIDERS"
    _tag_view3d_redraw()


def _wgame_slider_preview_updated(settings, context):
    if context:
        _apply_wgame_slider_preview(settings, context)


def _cached_enum_items(key, items):
    # Blender keeps pointers to strings returned by dynamic EnumProperty callbacks.
    # Retain the complete tuples for the module lifetime so translated labels are
    # not garbage-collected and later rendered as corrupted bytes.
    cached = [tuple(item) for item in items]
    _ENUM_ITEM_CACHE[key] = cached
    return cached

