def _joint_guide_object_name(guide_id):
    return "WGameGuide_" + guide_id.replace(".", "_")


def _sanitize_attachment_key(value):
    value = (value or "").strip().lower().replace(" ", "_").replace("-", "_")
    value = "".join(character for character in value if character.isascii() and (character.isalnum() or character == "_"))
    while "__" in value:
        value = value.replace("__", "_")
    return value.strip("_")


def _sync_attachment_generated_fields(settings, _context=None):
    attachment_type = getattr(settings, "unrigged_attachment_type", "POUCH")
    if attachment_type == "CUSTOM":
        key = _sanitize_attachment_key(getattr(settings, "unrigged_attachment_custom_key", "")) or "attachment"
    else:
        key = ATTACHMENT_TYPE_KEYS.get(attachment_type, "attachment")
    index = max(1, min(99, int(getattr(settings, "unrigged_attachment_index", 1))))
    side = getattr(settings, "unrigged_attachment_side", "L").lower()
    settings.unrigged_binding_target_bone = f"{key}_{index:02d}.{side}"
    parent_anchor = getattr(settings, "unrigged_attachment_parent_anchor", "PELVIS")
    settings.unrigged_binding_parent_bone = ATTACHMENT_PARENT_BONES.get(parent_anchor, "pelvis")


