def _secondary_weight_bone_items(settings, context):
    if not context or not getattr(context, "scene", None):
        return _cached_enum_items(
            "secondary:none",
            [("NONE", "无可用次级骨", "当前场景没有可编辑的次级骨")],
        )
    rig_obj = next(
        (
            obj
            for obj in context.scene.objects
            if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"
        ),
        None,
    )
    if not rig_obj:
        return _cached_enum_items(
            "secondary:no_rig",
            [("NONE", "无可用次级骨", "当前场景没有 WGame 骨架")],
        )
    scope = getattr(settings, "wgame_secondary_edit_scope", "CAPE")
    cape = [bone.name for bone in rig_obj.data.bones if bone.name.startswith("cape.")]
    swing = [bone.name for bone in rig_obj.data.bones if bone.name.startswith("swing_")]
    attachment_targets = {
        group.get("target_bone", "")
        for group in _unrigged_binding_groups(settings)
        if group.get("status") == "COMPLETE"
    }
    attachments = [bone.name for bone in rig_obj.data.bones if bone.name in attachment_targets]
    names = cape if scope == "CAPE" else swing if scope == "SWING" else attachments if scope == "ATTACHMENT" else cape + swing + attachments

    def display_name(name):
        if name.startswith("cape."):
            side, segment = name.split(".", 1)[1].split("_", 1)
            side_label = {"l": "左列", "x": "中列", "r": "右列"}.get(side, side)
            return f"{side_label} {int(segment)}"
        if name.startswith("swing_"):
            chain, segment = name.rsplit("_", 1)
            chain_index = chain.split("_", 1)[1].split(".", 1)[0]
            return f"摆动链 {int(chain_index)}-{int(segment)}"
        group_name = next(
            (group.get("name", "挂件") for group in _unrigged_binding_groups(settings) if group.get("target_bone") == name),
            "挂件",
        )
        return group_name

    items = [(name, display_name(name), f"编辑顶点组 {name}") for name in names] or [
        ("NONE", "无可用次级骨", "当前类型没有生成次级骨")
    ]
    return _cached_enum_items(f"secondary:{rig_obj.name}:{scope}", items)


def _weight_browser_bones(settings, context, category=None):
    if not context or not getattr(context, "scene", None):
        return []
    rig_obj = next(
        (
            obj
            for obj in context.scene.objects
            if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"
        ),
        None,
    )
    if not rig_obj:
        return []
    category = category or getattr(settings, "wgame_weight_browser_category", "ALL")
    snapshot_names = set(_base_skeleton_snapshot(rig_obj))

    def bone_category(name):
        return "BASE" if name in snapshot_names else "CUSTOM"

    return [
        bone.name
        for bone in rig_obj.data.bones
        if bone.use_deform and (category == "ALL" or bone_category(bone.name) == category)
    ]


def _weight_browser_bone_items(settings, context):
    names = _weight_browser_bones(settings, context)
    rig_obj = _wgame_rig_object(context) if context else None
    breast_roles = _detect_breast_bone_chains(rig_obj).get("roles", {}) if rig_obj else {}
    body_labels = {
        "pelvis.x": "骨盆",
        "spine_01.x": "腰椎",
        "spine_02.x": "胸椎",
        "upper_chest.x": "上胸",
        "neck.x": "颈部",
        "head.x": "头部",
        "shoulder.l": "左肩",
        "upper_arm.l": "左上臂",
        "forearm.l": "左前臂",
        "hand.l": "左手掌",
        "shoulder.r": "右肩",
        "upper_arm.r": "右上臂",
        "forearm.r": "右前臂",
        "hand.r": "右手掌",
        "thigh.l": "左大腿",
        "lower_leg.l": "左小腿",
        "foot.l": "左脚",
        "toes.l": "左前掌",
        "thigh.r": "右大腿",
        "lower_leg.r": "右小腿",
        "foot.r": "右脚",
        "toes.r": "右前掌",
    }
    finger_labels = {
        "thumb": "拇指",
        "index": "食指",
        "middle": "中指",
        "ring": "无名指",
        "pinky": "小指",
    }
    groups = _unrigged_binding_groups(settings)

    def label(name):
        if name in breast_roles:
            return breast_roles[name] + f" · {name}"
        if name in body_labels:
            return body_labels[name]
        if name.startswith(("eye.", "jaw.")):
            return {"eye.l": "左眼", "eye.r": "右眼", "jaw.x": "下颌"}.get(name, name)
        for prefix, finger_label in finger_labels.items():
            if name.startswith(prefix + "_"):
                stem, side = name.rsplit(".", 1)
                segment = int(stem.rsplit("_", 1)[1])
                return f"{'左' if side == 'l' else '右'}手{finger_label} {segment}"
        if name.startswith("cape."):
            side, segment = name.split(".", 1)[1].split("_", 1)
            side_label = {"l": "左", "x": "中", "r": "右"}.get(side, side)
            return f"披风{side_label}列 {int(segment)}"
        if name.startswith("swing_"):
            chain, segment = name.rsplit("_", 1)
            chain_index = chain.split("_", 1)[1].split(".", 1)[0]
            return f"摆动链 {int(chain_index)}-{int(segment)}"
        return next((group.get("name", "挂件") for group in groups if group.get("target_bone") == name), name)

    items = [(name, label(name), f"查看 {name} 的真实顶点权重") for name in names] or [
        ("NONE", "当前分类没有骨骼", "请选择其它分类")
    ]
    category = getattr(settings, "wgame_weight_browser_category", "ALL")
    rig_name = context.scene.wgame_rigging_assistant.rig_name if context and context.scene else ""
    return _cached_enum_items(f"browser:{rig_name}:{category}", items)


def _weight_browser_category_updated(settings, context):
    items = _weight_browser_bone_items(settings, context)
    if items and items[0][0] != "NONE":
        try:
            settings.wgame_weight_browser_bone = items[0][0]
        except TypeError:
            pass


def _custom_mesh_items(settings, context):
    names = sorted(_scope_vertex_ids_by_object(settings, "CUSTOM_BIND", context)) if settings and context else []
    items = [(name, name, f"在 {name} 上绘制自定义绑定权重") for name in names]
    return _cached_enum_items("custom-mesh:" + "|".join(names), items or [("NONE", "没有自定义 Mesh", "当前没有自定义绑定顶点")])


def _custom_weight_bone_items(settings, context):
    rig_obj = _wgame_rig_object(context) if context else None
    if not rig_obj:
        return _cached_enum_items("custom-bone:none", [("NONE", "没有可用骨骼", "请先生成并验收 WGame 基础骨架")])
    base_names = set(_base_skeleton_snapshot(rig_obj))
    breast_roles = _detect_breast_bone_chains(rig_obj).get("roles", {})
    bones = sorted((bone for bone in rig_obj.data.bones if bone.use_deform), key=lambda bone: bone.name)
    items = [
        (
            bone.name,
            (
                "基础 · " + bone.name
                if bone.name in base_names
                else (
                    breast_roles[bone.name] + " · " + bone.name
                    if bone.name in breast_roles
                    else "自定义 · " + bone.name
                )
            ),
            f"创建或激活 {bone.name} 的空权重组；不会自动赋权",
        )
        for bone in bones
    ]
    return _cached_enum_items(
        "custom-bone:" + rig_obj.name + ":" + "|".join(bone.name for bone in bones),
        items or [("NONE", "没有变形骨", "当前骨架没有 Deform Bone")],
    )


def _attachment_metadata_from_group(group):
    target = (group.get("target_bone") or "pouch_01.l").strip()
    stem, separator, side = target.rpartition(".")
    if not separator or side.upper() not in {"L", "R", "X"}:
        stem, side = target, "L"
    base = stem
    index = 1
    prefix, underscore, suffix = stem.rpartition("_")
    if underscore and suffix.isdigit():
        base = prefix
        index = max(1, min(99, int(suffix)))
    attachment_type = next((key for key, value in ATTACHMENT_TYPE_KEYS.items() if value == base), "CUSTOM")
    parent_bone = (group.get("parent_bone") or "pelvis").strip()
    parent_anchor = next((key for key, value in ATTACHMENT_PARENT_BONES.items() if value == parent_bone), "PELVIS")
    return {
        "attachment_type": group.get("attachment_type") or attachment_type,
        "custom_key": group.get("custom_key") or base,
        "side": group.get("side") or side.upper(),
        "index": int(group.get("index") or index),
        "parent_anchor": group.get("parent_anchor") or parent_anchor,
    }


def _load_attachment_group_fields(settings, group):
    metadata = _attachment_metadata_from_group(group)
    settings.unrigged_attachment_type = metadata["attachment_type"]
    settings.unrigged_attachment_custom_key = metadata["custom_key"]
    settings.unrigged_attachment_side = metadata["side"]
    settings.unrigged_attachment_index = metadata["index"]
    settings.unrigged_attachment_parent_anchor = metadata["parent_anchor"]
    _sync_attachment_generated_fields(settings)


def _joint_guide_state(settings):
    try:
        value = json.loads(settings.unrigged_joint_guides_json or "{}")
        return value if isinstance(value, dict) else {}
    except ValueError:
        return {}


def _save_joint_guide_state(settings, state):
    settings.unrigged_joint_guides_json = json.dumps(state, ensure_ascii=False, separators=(",", ":"))


def _joint_guides_complete(settings):
    state = _joint_guide_state(settings)
    return all(bool(state.get(guide_id, {}).get("accepted")) for guide_id, _label, _description in JOINT_GUIDE_DEFINITIONS)


def _joint_guide_object(guide_id):
    return bpy.data.objects.get(_joint_guide_object_name(guide_id))


def _mirrored_guide_id(guide_id):
    return guide_id[:-2] + ".r" if guide_id.endswith(".l") else ""


def _set_joint_guide_position(settings, guide_id, position):
    obj = _joint_guide_object(guide_id)
    if not obj:
        return False
    obj.location = position
    mirrored_id = _mirrored_guide_id(guide_id)
    if mirrored_id and settings.unrigged_joint_mirror:
        mirrored = _joint_guide_object(mirrored_id)
        if mirrored:
            mirrored.location = Vector((-position.x, position.y, position.z))
    return True


def _sync_all_joint_guide_mirrors(settings):
    for guide_id, _label, _description in JOINT_GUIDE_DEFINITIONS:
        mirrored_id = _mirrored_guide_id(guide_id)
        if not mirrored_id:
            continue
        left = _joint_guide_object(guide_id)
        right = _joint_guide_object(mirrored_id)
        if not left or not right:
            continue
        if settings.unrigged_joint_mirror:
            desired = Vector((-left.location.x, left.location.y, left.location.z))
            if (right.location - desired).length > 0.0000001:
                right.location = desired
        right.hide_select = bool(settings.unrigged_joint_mirror)


def _joint_mirror_setting_updated(settings, _context=None):
    _sync_all_joint_guide_mirrors(settings)
    _tag_view3d_redraw()


@persistent
def _joint_guide_live_mirror_handler(scene, _depsgraph):
    if scene.get('wgame_baked_preview', False):
        return
    if any(update.is_updated_geometry or update.is_updated_transform for update in _depsgraph.updates):
        _RIGID_MARKS_CACHE.clear()
    settings = getattr(scene, "wgame_rigging_assistant", None)
    if settings and settings.unrigged_joint_mirror:
        _sync_all_joint_guide_mirrors(settings)

    if settings and settings.unrigged_preflight_passed and not any(obj.type == "ARMATURE" for obj in scene.objects):
        if any(update.is_updated_geometry or update.is_updated_transform for update in _depsgraph.updates):
            if scene == bpy.context.scene:
                _current_model_preflight(bpy.context, settings)


def _legacy_joint_guide_positions(mesh_obj):
    points = [mesh_obj.matrix_world @ vertex.co for vertex in mesh_obj.data.vertices]
    minimum = Vector(tuple(min(point[axis] for point in points) for axis in range(3)))
    maximum = Vector(tuple(max(point[axis] for point in points) for axis in range(3)))
    height = max(maximum.z - minimum.z, 0.0001)
    center_x = (minimum.x + maximum.x) * 0.5
    center_y = (minimum.y + maximum.y) * 0.5
    z0 = minimum.z
    return {
        "pelvis.x": Vector((center_x, center_y, z0 + height * 0.49)),
        "chest.x": Vector((center_x, center_y, z0 + height * 0.76)),
        "neck.x": Vector((center_x, center_y, z0 + height * 0.81)),
        "head_top.x": Vector((center_x, center_y, z0 + height * 0.96)),
        "jaw.x": Vector((center_x, center_y - height * 0.025, z0 + height * 0.84)),
        "shoulder.l": Vector((center_x + height * 0.071, center_y, z0 + height * 0.789)),
        "elbow.l": Vector((center_x + height * 0.222, center_y, z0 + height * 0.789)),
        "wrist.l": Vector((center_x + height * 0.376, center_y - height * 0.012, z0 + height * 0.776)),
        "hand_end.l": Vector((center_x + height * 0.436, center_y - height * 0.012, z0 + height * 0.776)),
        "hip.l": Vector((center_x + height * 0.053, center_y, z0 + height * 0.508)),
        "knee.l": Vector((center_x + height * 0.092, center_y, z0 + height * 0.287)),
        "ankle.l": Vector((center_x + height * 0.131, center_y, z0 + height * 0.032)),
        "ball.l": Vector((center_x + height * 0.131, center_y - height * 0.041, z0 + height * 0.010)),
        "toe.l": Vector((center_x + height * 0.131, center_y - height * 0.070, z0 + height * 0.010)),
    }


def _default_joint_guide_positions(mesh_obj, body_points=None):
    """Estimate upright T/A-pose joint centers from local body cross-sections."""
    fallback = _legacy_joint_guide_positions(mesh_obj)
    full = [mesh_obj.matrix_world @ vertex.co for vertex in mesh_obj.data.vertices]
    points = list(body_points) if body_points else full
    z0, z1 = min(p.z for p in full), max(p.z for p in full)
    height = max(z1 - z0, 0.0001)
    cx = (min(p.x for p in full) + max(p.x for p in full)) * 0.5

    def quantile(values, fraction):
        values = sorted(values)
        position = (len(values) - 1) * fraction
        lo = int(position)
        return values[lo] + (values[min(lo + 1, len(values) - 1)] - values[lo]) * (position - lo)

    def section(predicate):
        selected = [p for p in points if predicate(p)]
        return selected if len(selected) >= 4 else [p for p in full if predicate(p)]

    def center(samples):
        # Opposing surface quantiles estimate the volume center without favoring dense front topology.
        return Vector(tuple((quantile([p[a] for p in samples], .15) + quantile([p[a] for p in samples], .85)) * .5 for a in range(3)))

    result = {name: value.copy() for name, value in fallback.items()}
    for name, fraction in (("pelvis.x", .535), ("chest.x", .765), ("neck.x", .835), ("jaw.x", .865)):
        z = z0 + height * fraction
        samples = section(lambda p: abs(p.z - z) < height * .018 and abs(p.x - cx) < height * .055)
        if samples:
            result[name] = Vector((cx, center(samples).y, z))
    head = section(lambda p: p.z > z0 + height * .9 and abs(p.x - cx) < height * .06)
    if head:
        result["head_top.x"] = Vector((cx, center(head).y, quantile([p.z for p in head], .98)))

    arms = section(lambda p: p.x - cx > height * .13 and z0 + height * .62 < p.z < z0 + height * .9)
    if len(arms) >= 8:
        reach = quantile([p.x - cx for p in arms], .995)
        # Avoid inventing a lateral arm chain when the pose has no extended arm evidence.
        if reach > height * .23:
            shoulder_x = min(height * .09, reach * .26)
            wrist_x = reach * .84
            for name, offset in (("shoulder.l", shoulder_x), ("elbow.l", (shoulder_x + wrist_x) * .5),
                                 ("wrist.l", wrist_x), ("hand_end.l", reach * .94)):
                samples = section(lambda p: abs(p.x - cx - offset) < height * .012 and z0 + height * .62 < p.z < z0 + height * .9)
                if samples:
                    c = center(samples)
                    result[name] = Vector((cx + offset, c.y, c.z))

    for name, fraction in (("hip.l", .515), ("knee.l", .285), ("ankle.l", .055)):
        z = z0 + height * fraction
        samples = section(lambda p: abs(p.z - z) < height * .018 and height * .012 < p.x - cx < height * .18)
        if samples:
            c = center(samples)
            result[name] = Vector((c.x, c.y, z))
    foot = section(lambda p: p.z < z0 + height * .065 and abs(p.x - result["ankle.l"].x) < height * .045)
    if foot:
        ys = [p.y for p in foot]
        front, rear = quantile(ys, .03), quantile(ys, .97)
        for name, fraction in (("ball.l", .30), ("toe.l", .06)):
            y = front + (rear - front) * fraction
            samples = [p for p in foot if abs(p.y - y) < height * .012]
            if samples:
                c = center(samples)
                result[name] = Vector((c.x, y, c.z))
    return result


def _joint_guide_default_is_untouched(obj, legacy_position, tolerance):
    if obj is None:
        return True
    previous = obj.get("wgame_joint_default_position")
    reference = Vector(previous) if previous is not None else legacy_position
    return (obj.location - reference).length <= tolerance


def _joint_guide_view_distance(context, guide_id):
    meshes = [item for item in context.scene.objects if _is_formal_character_mesh(item)]
    mesh_obj = max(meshes, key=lambda item: len(item.data.vertices), default=None)
    height = max(float(mesh_obj.dimensions.z), 0.0001) if mesh_obj else 1.0
    base = guide_id.rsplit(".", 1)[0]
    if base in {"wrist", "hand_end", "ankle", "ball", "toe"}:
        return max(height * 0.16, 0.08)
    if base in {"head_top", "jaw", "neck"}:
        return max(height * 0.22, 0.08)
    if _joint_guide_category(guide_id) == "ARM":
        return max(height * 0.25, 0.08)
    if _joint_guide_category(guide_id) == "LEG":
        return max(height * 0.28, 0.08)
    return max(height * 0.34, 0.08)


def _joint_guide_window_screen(context):
    window = context.window
    screen = context.screen
    if window and screen:
        return window, screen
    window = next(iter(context.window_manager.windows), None)
    return (window, window.screen) if window else (None, None)


def _sync_joint_guide_view_centers(context, guide_id):
    obj = _joint_guide_object(guide_id)
    window, screen = _joint_guide_window_screen(context)
    if not obj or not screen:
        return []
    distance = _joint_guide_view_distance(context, guide_id)
    areas = sorted((area for area in screen.areas if area.type == "VIEW_3D"), key=lambda area: area.x)
    for area in areas:
        area.spaces.active.region_3d.view_location = obj.matrix_world.translation
        area.spaces.active.region_3d.view_distance = distance
        area.tag_redraw()
    return areas


def _tag_view3d_redraw():
    for window in bpy.context.window_manager.windows:
        screen = window.screen
        if not screen:
            continue
        for area in screen.areas:
            if area.type == "VIEW_3D":
                area.tag_redraw()


def _point_to_segment(point, head, tail):
    vector = tail - head
    factor = max(0.0, min(1.0, (point - head).dot(vector) / max(vector.length_squared, 1e-12)))
    closest = head + vector * factor
    return (point - closest).length, closest


def _focus_world_points():
    rig_obj = bpy.data.objects.get(_FOCUS_STATE.get("rig_name", ""))
    if not rig_obj or rig_obj.type != "ARMATURE":
        return {}
    diagnostic_name = _FOCUS_STATE.get("diagnostic_name") or _FOCUS_STATE.get("bone_name", "")
    pose_bone = rig_obj.pose.bones.get(diagnostic_name)
    if not pose_bone:
        pose_bone = rig_obj.pose.bones.get(_FOCUS_STATE.get("bone_name", ""))
    if not pose_bone:
        return {}
    points = {
        "bone_head": rig_obj.matrix_world @ pose_bone.head,
        "bone_tail": rig_obj.matrix_world @ pose_bone.tail,
        "bone_mid": rig_obj.matrix_world @ ((pose_bone.head + pose_bone.tail) * 0.5),
    }
    mesh_obj = bpy.data.objects.get(_FOCUS_STATE.get("mesh_name", ""))
    group_name = _FOCUS_STATE.get("group_name", "")
    weight_session_active = bool(mesh_obj and mesh_obj.type == "MESH" and mesh_obj.mode == "WEIGHT_PAINT")
    if mesh_obj and mesh_obj.type == "MESH" and group_name and (
        _FOCUS_STATE.get("kind") != "WEIGHT_BROWSER" or weight_session_active
    ):
        centroid = _weighted_centroid(mesh_obj, group_name)
        if centroid is not None:
            points["mesh"] = mesh_obj.matrix_world @ centroid
            if _FOCUS_STATE.get("kind") == "WEIGHT_BROWSER":
                _distance, closest = _point_to_segment(
                    points["mesh"],
                    points["bone_head"],
                    points["bone_tail"],
                )
                points["bone_mid"] = closest
    return points


def _joint_guide_category(guide_id):
    base = guide_id.rsplit(".", 1)[0]
    if base in {"head_top", "jaw"}:
        return "HEAD"
    if base in {"shoulder", "elbow", "wrist", "hand_end"}:
        return "ARM"
    if base in {"hip", "knee", "ankle", "ball", "toe"}:
        return "LEG"
    return "CENTER"


def _joint_guide_short_label(guide_id):
    labels = {
        "pelvis": "骨盆",
        "chest": "胸",
        "neck": "颈",
        "head_top": "头顶",
        "jaw": "下颌",
        "shoulder": "肩",
        "elbow": "肘",
        "wrist": "腕",
        "hand_end": "掌",
        "hip": "髋",
        "knee": "膝",
        "ankle": "踝",
        "ball": "前掌",
        "toe": "趾",
    }
    base, separator, side = guide_id.rpartition(".")
    if not separator:
        base, side = guide_id, ""
    suffix = " L" if side == "l" else " R" if side == "r" else ""
    return labels.get(base, base) + suffix


def _joint_guide_hit_test(context, mouse):
    settings = context.scene.wgame_rigging_assistant
    index = min(settings.unrigged_joint_guide_index, len(JOINT_GUIDE_DEFINITIONS) - 1)
    current = JOINT_GUIDE_DEFINITIONS[index][0]
    state = _joint_guide_state(settings)
    hits = []
    for guide_id, _label, _description in JOINT_GUIDE_DEFINITIONS:
        for display_id in (guide_id, _mirrored_guide_id(guide_id)):
            obj = _joint_guide_object(display_id) if display_id else None
            if not obj or obj.hide_get() or obj.name not in context.view_layer.objects:
                continue
            point = view3d_utils.location_3d_to_region_2d(context.region, context.space_data.region_3d, obj.matrix_world.translation)
            if point is None:
                continue
            radius = 15.0 if guide_id == current else 10.0
            distance = (Vector(mouse) - point).length
            if distance <= radius + 5.0:
                hits.append((0, distance, display_id))
                continue
            label = ("✓ " if state.get(guide_id, {}).get("accepted") else "") + _joint_guide_short_label(display_id)
            blf.size(0, 16.0 if guide_id == current else 14.0)
            width, height = blf.dimensions(0, label)
            left, bottom = point.x + radius + 5.0, point.y - 5.0
            if left - 3 <= mouse[0] <= left + width + 3 and bottom - 4 <= mouse[1] <= bottom + height + 4:
                hits.append((1, distance, display_id))
    return min(hits)[2] if hits else None


def _draw_joint_guides_overlay():
    try:
        scene = bpy.context.scene
        settings = getattr(scene, "wgame_rigging_assistant", None)
        collection = bpy.data.collections.get("WGame_RigGuides")
        region = bpy.context.region
        space = bpy.context.space_data
        if not settings or not collection or collection.hide_viewport or not region or not space or space.type != "VIEW_3D":
            return
        state = _joint_guide_state(settings)
        current_index = min(settings.unrigged_joint_guide_index, len(JOINT_GUIDE_DEFINITIONS) - 1)
        current_id = JOINT_GUIDE_DEFINITIONS[current_index][0]
        definition_ids = [guide_id for guide_id, _label, _description in JOINT_GUIDE_DEFINITIONS]
        display_ids = []
        for guide_id in definition_ids:
            display_ids.append(guide_id)
            mirrored = _mirrored_guide_id(guide_id)
            if mirrored:
                display_ids.append(mirrored)
        projected = {}
        for guide_id in display_ids:
            obj = _joint_guide_object(guide_id)
            if not obj:
                continue
            point = view3d_utils.location_3d_to_region_2d(region, space.region_3d, obj.matrix_world.translation)
            if point is not None:
                projected[guide_id] = point
        if not projected:
            return

        colors = {
            "CENTER": (0.10, 0.90, 1.00, 0.95),
            "HEAD": (1.00, 0.25, 0.78, 0.95),
            "ARM": (1.00, 0.42, 0.05, 0.95),
            "LEG": (0.25, 1.00, 0.32, 0.95),
        }
        chains = [
            (["pelvis.x", "chest.x", "neck.x", "head_top.x"], "CENTER"),
            (["neck.x", "jaw.x"], "HEAD"),
            (["shoulder.l", "elbow.l", "wrist.l", "hand_end.l"], "ARM"),
            (["shoulder.r", "elbow.r", "wrist.r", "hand_end.r"], "ARM"),
            (["hip.l", "knee.l", "ankle.l", "ball.l", "toe.l"], "LEG"),
            (["hip.r", "knee.r", "ankle.r", "ball.r", "toe.r"], "LEG"),
        ]
        shader = gpu.shader.from_builtin("UNIFORM_COLOR")
        gpu.state.blend_set("ALPHA")
        shader.bind()
        for chain, category in chains:
            points = [projected[item] for item in chain if item in projected]
            if len(points) < 2:
                continue
            gpu.state.line_width_set(3.0)
            color = colors[category]
            shader.uniform_float("color", (color[0], color[1], color[2], 0.55))
            batch_for_shader(shader, "LINE_STRIP", {"pos": [(point.x, point.y) for point in points]}).draw(shader)

        definition_by_id = {guide_id: (label, description) for guide_id, label, description in JOINT_GUIDE_DEFINITIONS}
        for guide_id, point in projected.items():
            source_id = guide_id[:-2] + ".l" if guide_id.endswith(".r") else guide_id
            category = _joint_guide_category(guide_id)
            accepted = bool(state.get(source_id, {}).get("accepted"))
            is_current = source_id == current_id
            base_color = colors[category]
            color = (1.0, 0.88, 0.12, 1.0) if is_current else (0.25, 1.0, 0.45, 0.95) if accepted else base_color
            radius = 15.0 if is_current else 10.0
            circle = [
                (
                    float(point.x) + math.cos(math.tau * index / 48.0) * radius,
                    float(point.y) + math.sin(math.tau * index / 48.0) * radius,
                )
                for index in range(49)
            ]
            gpu.state.line_width_set(4.0 if is_current else 2.5)
            shader.uniform_float("color", color)
            batch_for_shader(shader, "LINE_STRIP", {"pos": circle}).draw(shader)
            if is_current:
                cross = [
                    (point.x - radius - 5.0, point.y),
                    (point.x + radius + 5.0, point.y),
                    (point.x, point.y - radius - 5.0),
                    (point.x, point.y + radius + 5.0),
                ]
                batch_for_shader(shader, "LINES", {"pos": cross}, indices=((0, 1), (2, 3))).draw(shader)
            font_id = 0
            try:
                blf.size(font_id, 14.0 if not is_current else 16.0)
            except TypeError:
                blf.size(font_id, 14.0 if not is_current else 16.0, 72)
            blf.color(font_id, *color)
            blf.position(font_id, float(point.x) + radius + 5.0, float(point.y) - 5.0, 0.0)
            blf.draw(font_id, ("✓ " if accepted else "") + _joint_guide_short_label(guide_id))
    except Exception:
        pass
    finally:
        try:
            gpu.state.line_width_set(1.0)
            gpu.state.blend_set("NONE")
        except Exception:
            pass


def _invalidate_base_region_overlay_cache():
    global _BASE_REGION_OVERLAY_REVISION
    _BASE_REGION_OVERLAY_REVISION += 1
    _BASE_REGION_OVERLAY_CACHE.clear()
    _BASE_REGION_ASSIGNMENTS_CACHE.clear()
    _COMPONENT_SCOPE_COUNTS_CACHE.clear()
    _WEIGHTED_CENTROID_CACHE.clear()


def _base_region_overlay_data(scene, settings):
    cached_names = _BASE_REGION_OVERLAY_CACHE.get("object_names", ())
    participants = [scene.objects.get(name) for name in cached_names]
    participants = [obj for obj in participants if obj and obj.type == "MESH"]
    if (
        _BASE_REGION_OVERLAY_CACHE.get("scene_pointer") != scene.as_pointer()
        or _BASE_REGION_OVERLAY_CACHE.get("revision") != _BASE_REGION_OVERLAY_REVISION
        or len(participants) != len(cached_names)
    ):
        participants = _participant_meshes(bpy.context, settings)
    object_signature = tuple(
        (
            obj.name,
            tuple(float(value) for row in obj.matrix_world for value in row),
            len(obj.data.vertices),
            len(obj.data.edges),
            len(obj.data.polygons),
        )
        for obj in participants
    )
    signature = (scene.as_pointer(), _BASE_REGION_OVERLAY_REVISION, object_signature)
    if _BASE_REGION_OVERLAY_CACHE.get("signature") == signature:
        return _BASE_REGION_OVERLAY_CACHE

    assignments_by_object = _base_region_assignments_by_object(bpy.context, settings)
    base_by_object = _scope_vertex_ids_by_object(settings, "BASE_SKIN", bpy.context)
    geometry = []
    for mesh_obj in participants:
        assignments = assignments_by_object.get(mesh_obj.name, {})
        base_ids = base_by_object.get(mesh_obj.name, set())
        for region_name in BASE_REGION_KEYS:
            positions = [
                tuple(mesh_obj.matrix_world @ mesh_obj.data.vertices[vertex_id].co)
                for vertex_id, assigned_region in assignments.items()
                if assigned_region == region_name
                and vertex_id in base_ids
                and 0 <= vertex_id < len(mesh_obj.data.vertices)
                and not mesh_obj.data.vertices[vertex_id].hide
            ]
            if positions:
                geometry.append((mesh_obj.name, region_name, positions))

    labels = []
    components = _unrigged_components(settings)
    custom_by_object = _custom_mask_vertex_ids_by_object(bpy.context, settings)
    for component_index, component in enumerate(components):
        mesh_obj = scene.objects.get(component.get("object", ""))
        if not mesh_obj or mesh_obj.type != "MESH":
            continue
        base_ids = _component_vertex_ids_for_scope(
            bpy.context,
            settings,
            component,
            "BASE_SKIN",
            custom_by_object,
        )
        assignments = assignments_by_object.get(mesh_obj.name, {})
        for region_name in BASE_REGION_KEYS:
            vertex_ids = [vertex_id for vertex_id in base_ids if assignments.get(vertex_id) == region_name]
            if not vertex_ids:
                continue
            center_local = sum((mesh_obj.data.vertices[vertex_id].co for vertex_id in vertex_ids), Vector()) / len(vertex_ids)
            labels.append((component_index, mesh_obj.name, region_name, tuple(mesh_obj.matrix_world @ center_local), len(vertex_ids)))

    _BASE_REGION_OVERLAY_CACHE.update(
        signature=signature,
        scene_pointer=scene.as_pointer(),
        revision=_BASE_REGION_OVERLAY_REVISION,
        object_names=tuple(obj.name for obj in participants),
        geometry=geometry,
        labels=labels,
    )
    return _BASE_REGION_OVERLAY_CACHE


_CUSTOM_CHAIN_VERTICES_CACHE = {}


def _custom_chain_active_vertices_data(scene, settings, rig_obj, chain):
    records = chain.get("regions", [])
    if not records:
        return ((), (), (), ())
    payload = _custom_weight_chain_payload(rig_obj)
    raw_payload_str = rig_obj.get(CUSTOM_WEIGHT_CHAINS_KEY, "")
    mesh_matrices = []
    has_edit_mesh = False
    for r in records:
        obj = scene.objects.get(r.get("object", ""))
        if obj and obj.type == "MESH":
            mesh_matrices.append((obj.name, tuple(float(v) for row in obj.matrix_world for v in row)))
            if obj.mode == "EDIT":
                has_edit_mesh = True
    signature = (
        scene.as_pointer(),
        chain.get("id", ""),
        raw_payload_str,
        tuple(mesh_matrices),
        has_edit_mesh,
    )
    cached = _CUSTOM_CHAIN_VERTICES_CACHE.get("signature")
    if cached == signature:
        return (
            _CUSTOM_CHAIN_VERTICES_CACHE.get("exclusive", ()),
            _CUSTOM_CHAIN_VERTICES_CACHE.get("shared", ()),
            _CUSTOM_CHAIN_VERTICES_CACHE.get("roots", ()),
            _CUSTOM_CHAIN_VERTICES_CACHE.get("tips", ()),
        )

    other_assigned = set()
    for other in payload.get("chains", []):
        if other.get("id") == chain.get("id"):
            continue
        for other_rec in other.get("regions", []):
            o_name = other_rec.get("object", "")
            for vid in other_rec.get("vertex_ids", []):
                other_assigned.add((o_name, vid))

    exclusive_positions = []
    shared_positions = []
    root_positions = []
    tip_positions = []

    for r in records:
        obj_name = r.get("object", "")
        mesh_obj = scene.objects.get(obj_name)
        if not mesh_obj or mesh_obj.type != "MESH" or mesh_obj.hide_get():
            continue
        vertex_ids = r.get("vertex_ids", [])
        if not vertex_ids:
            continue
        roots = set(r.get("roots", []))
        tips = set(r.get("tips", []))
        mat = mesh_obj.matrix_world
        if mesh_obj.mode == "EDIT":
            bm = bmesh.from_edit_mesh(mesh_obj.data)
            bm.verts.ensure_lookup_table()
            max_v = len(bm.verts)
            for vid in vertex_ids:
                if 0 <= vid < max_v and not bm.verts[vid].hide:
                    pos = mat @ bm.verts[vid].co
                    if (obj_name, vid) in other_assigned:
                        shared_positions.append(pos)
                    else:
                        exclusive_positions.append(pos)
                    if vid in roots:
                        root_positions.append(pos)
                    if vid in tips:
                        tip_positions.append(pos)
        else:
            verts = mesh_obj.data.vertices
            max_v = len(verts)
            for vid in vertex_ids:
                if 0 <= vid < max_v and not verts[vid].hide:
                    pos = mat @ verts[vid].co
                    if (obj_name, vid) in other_assigned:
                        shared_positions.append(pos)
                    else:
                        exclusive_positions.append(pos)
                    if vid in roots:
                        root_positions.append(pos)
                    if vid in tips:
                        tip_positions.append(pos)

    ex_tuple = tuple(exclusive_positions)
    sh_tuple = tuple(shared_positions)
    rt_tuple = tuple(root_positions)
    tp_tuple = tuple(tip_positions)

    _CUSTOM_CHAIN_VERTICES_CACHE.clear()
    _CUSTOM_CHAIN_VERTICES_CACHE.update({
        "signature": signature,
        "exclusive": ex_tuple,
        "shared": sh_tuple,
        "roots": rt_tuple,
        "tips": tp_tuple,
    })
    return ex_tuple, sh_tuple, rt_tuple, tp_tuple


def _draw_custom_chain_geometry():
    try:
        scene = bpy.context.scene
        settings = getattr(scene, "wgame_rigging_assistant", None) if scene else None
        if not settings or not getattr(settings, "wgame_custom_chain_show_3d_overlay", True):
            return
        rig_obj = _wgame_rig_object(bpy.context)
        if not rig_obj or rig_obj.hide_get():
            return
        status = _custom_weight_chain_status(rig_obj)
        if not status.get("scanned") or not status.get("chains"):
            return
        chain = _current_custom_weight_chain(settings, rig_obj)
        if not chain:
            return
        lines, dashes, joints = [], [], []
        for name in chain.get("bones", []):
            pb = rig_obj.pose.bones.get(name) if rig_obj.pose else None
            if pb:
                head = rig_obj.matrix_world @ pb.head
                tail = rig_obj.matrix_world @ pb.tail
            else:
                b = rig_obj.data.bones.get(name)
                if not b:
                    continue
                head = rig_obj.matrix_world @ b.head_local
                tail = rig_obj.matrix_world @ b.tail_local
            lines.extend((head, tail))
            joints.extend((head, tail))
            for part in range(0, 16, 2):
                dashes.extend((head.lerp(tail, part / 16.0), head.lerp(tail, (part + 1) / 16.0)))

        shader = gpu.shader.from_builtin("UNIFORM_COLOR")
        shader.bind()
        gpu.state.blend_set("ALPHA")

        if lines:
            gpu.state.depth_test_set("GREATER")
            gpu.state.depth_mask_set(False)
            gpu.state.line_width_set(2.5)
            shader.uniform_float("color", (1.0, 0.75, 0.15, 0.45))
            batch_for_shader(shader, "LINES", {"pos": dashes}).draw(shader)
            gpu.state.depth_test_set("LESS_EQUAL")
            gpu.state.line_width_set(5.0)
            shader.uniform_float("color", (1.0, 0.80, 0.12, 1.0))
            batch_for_shader(shader, "LINES", {"pos": lines}).draw(shader)
            gpu.state.point_size_set(8.0)
            shader.uniform_float("color", (0.15, 0.95, 1.0, 1.0))
            batch_for_shader(shader, "POINTS", {"pos": joints}).draw(shader)

        if getattr(settings, "wgame_custom_chain_show_vertex_overlay", True):
            ex_pts, sh_pts, rt_pts, tp_pts = _custom_chain_active_vertices_data(scene, settings, rig_obj, chain)
            gpu.state.depth_mask_set(False)
            if ex_pts:
                gpu.state.depth_test_set("GREATER")
                gpu.state.point_size_set(4.0)
                shader.uniform_float("color", (0.15, 0.98, 0.35, 0.28))
                batch_for_shader(shader, "POINTS", {"pos": ex_pts}).draw(shader)
                gpu.state.depth_test_set("LESS_EQUAL")
                gpu.state.point_size_set(6.5)
                shader.uniform_float("color", (0.12, 0.98, 0.38, 0.95))
                batch_for_shader(shader, "POINTS", {"pos": ex_pts}).draw(shader)
            if sh_pts:
                gpu.state.depth_test_set("GREATER")
                gpu.state.point_size_set(4.0)
                shader.uniform_float("color", (1.0, 0.60, 0.10, 0.28))
                batch_for_shader(shader, "POINTS", {"pos": sh_pts}).draw(shader)
                gpu.state.depth_test_set("LESS_EQUAL")
                gpu.state.point_size_set(6.5)
                shader.uniform_float("color", (1.0, 0.60, 0.10, 0.95))
                batch_for_shader(shader, "POINTS", {"pos": sh_pts}).draw(shader)
            if rt_pts:
                gpu.state.depth_test_set("NONE")
                gpu.state.point_size_set(9.5)
                shader.uniform_float("color", (1.0, 0.18, 0.75, 1.0))
                batch_for_shader(shader, "POINTS", {"pos": rt_pts}).draw(shader)
            if tp_pts:
                gpu.state.depth_test_set("NONE")
                gpu.state.point_size_set(9.5)
                shader.uniform_float("color", (1.0, 0.95, 0.12, 1.0))
                batch_for_shader(shader, "POINTS", {"pos": tp_pts}).draw(shader)
    except Exception:
        pass
    finally:
        try:
            gpu.state.line_width_set(1.0)
            gpu.state.point_size_set(1.0)
            gpu.state.depth_test_set("NONE")
            gpu.state.blend_set("NONE")
        except Exception:
            pass


def _draw_base_region_geometry():
    _draw_rigid_feedback_geometry()
    _draw_custom_chain_geometry()
    try:
        scene = bpy.context.scene
        settings = getattr(scene, "wgame_rigging_assistant", None) if scene else None
        if not settings or not settings.show_wgame_base_region_overlays:
            return
        overlay = _base_region_overlay_data(scene, settings)
        if not overlay.get("geometry"):
            return
        shader = gpu.shader.from_builtin("UNIFORM_COLOR")
        gpu.state.blend_set("ALPHA")
        gpu.state.depth_test_set("NONE")
        gpu.state.point_size_set(5.0)
        shader.bind()
        for object_name, region_name, positions in overlay["geometry"]:
            obj = scene.objects.get(object_name)
            if not obj or obj.type != "MESH" or obj.hide_get():
                continue
            shader.uniform_float("color", BASE_REGION_COLORS[region_name])
            batch_for_shader(shader, "POINTS", {"pos": positions}).draw(shader)
    except Exception:
        pass
    finally:
        try:
            gpu.state.point_size_set(1.0)
            gpu.state.depth_test_set("NONE")
            gpu.state.blend_set("NONE")
        except Exception:
            pass


def _draw_base_region_labels():
    try:
        scene = bpy.context.scene
        settings = getattr(scene, "wgame_rigging_assistant", None) if scene else None
        region = bpy.context.region
        space = bpy.context.space_data
        if (
            not settings
            or not settings.show_wgame_base_region_overlays
            or not region
            or not space
            or space.type != "VIEW_3D"
        ):
            return
        components = _unrigged_components(settings)
        overlay = _base_region_overlay_data(scene, settings)
        current_index = min(settings.unrigged_component_index, len(components) - 1) if components else -1
        for component_index, object_name, region_name, center_world, vertex_count in overlay.get("labels", []):
            obj = scene.objects.get(object_name)
            if not obj or obj.type != "MESH" or obj.hide_get():
                continue
            point = view3d_utils.location_3d_to_region_2d(region, space.region_3d, Vector(center_world))
            if point is None:
                continue
            color = BASE_REGION_COLORS[region_name]
            font_id = 0
            try:
                blf.size(font_id, 16.0 if component_index == current_index else 13.0)
            except TypeError:
                blf.size(font_id, 16.0 if component_index == current_index else 13.0, 72)
            blf.color(font_id, *color)
            blf.position(font_id, float(point.x) + 8.0, float(point.y) + 8.0, 0.0)
            prefix = "▶ " if component_index == current_index else ""
            blf.draw(font_id, f"{prefix}{region_name} ✓ · 组件{component_index + 1} · {vertex_count}点")
    except Exception:
        pass


def _draw_custom_chain_labels():
    try:
        scene = bpy.context.scene
        settings = getattr(scene, "wgame_rigging_assistant", None) if scene else None
        if not settings or not getattr(settings, "wgame_custom_chain_show_3d_overlay", True):
            return
        rig_obj = _wgame_rig_object(bpy.context)
        if not rig_obj or rig_obj.hide_get():
            return
        status = _custom_weight_chain_status(rig_obj)
        if not status.get("scanned") or not status.get("chains"):
            return
        chain = _current_custom_weight_chain(settings, rig_obj)
        if not chain:
            return
        region, space = bpy.context.region, bpy.context.space_data
        if not region or not space or space.type != "VIEW_3D":
            return
        root_name = chain.get("root_bone", "")
        root_pb = rig_obj.pose.bones.get(root_name) if rig_obj.pose else None
        if root_pb:
            root_pos = rig_obj.matrix_world @ root_pb.head
        else:
            b = rig_obj.data.bones.get(root_name)
            if not b:
                return
            root_pos = rig_obj.matrix_world @ b.head_local
        root_2d = view3d_utils.location_3d_to_region_2d(region, space.region_3d, root_pos)
        font_id = 0

        ex_pts, sh_pts, rt_pts, tp_pts = (), (), (), ()
        if getattr(settings, "wgame_custom_chain_show_vertex_overlay", True):
            ex_pts, sh_pts, rt_pts, tp_pts = _custom_chain_active_vertices_data(scene, settings, rig_obj, chain)

        if root_2d is not None:
            try:
                blf.size(font_id, 15.0)
            except TypeError:
                blf.size(font_id, 15.0, 72)
            blf.color(font_id, 1.0, 0.85, 0.20, 1.0)
            chains = status.get("chains", [])
            idx = min(max(int(settings.wgame_custom_chain_index), 0), len(chains) - 1)
            blf.position(font_id, float(root_2d.x) + 12.0, float(root_2d.y) + 10.0, 0.0)
            region_tag = ""
            if ex_pts or sh_pts:
                parts = []
                if ex_pts:
                    parts.append(f"独占 {len(ex_pts)} 点")
                if sh_pts:
                    parts.append(f"共享 {len(sh_pts)} 点")
                region_tag = f" · {' / '.join(parts)}"
            blf.draw(font_id, f"▶ 当前骨链 [{idx + 1}/{len(chains)}]: {root_name} ({len(chain.get('bones', []))} 骨){region_tag}")

        try:
            blf.size(font_id, 13.0)
        except TypeError:
            blf.size(font_id, 13.0, 72)
        blf.color(font_id, 0.2, 0.95, 1.0, 0.95)
        for order, name in enumerate(chain.get("bones", []), 1):
            pb = rig_obj.pose.bones.get(name) if rig_obj.pose else None
            if pb:
                mid_world = rig_obj.matrix_world @ ((pb.head + pb.tail) * 0.5)
            else:
                b = rig_obj.data.bones.get(name)
                if not b:
                    continue
                mid_world = rig_obj.matrix_world @ ((b.head_local + b.tail_local) * 0.5)
            pt_2d = view3d_utils.location_3d_to_region_2d(region, space.region_3d, mid_world)
            if pt_2d is not None:
                blf.position(font_id, float(pt_2d.x) + 8.0, float(pt_2d.y) + 2.0, 0.0)
                blf.draw(font_id, f"#{order}")

        if ex_pts:
            cen = sum(ex_pts, Vector()) / len(ex_pts)
            ex_2d = view3d_utils.location_3d_to_region_2d(region, space.region_3d, cen)
            if ex_2d is not None:
                try:
                    blf.size(font_id, 12.0)
                except TypeError:
                    blf.size(font_id, 12.0, 72)
                blf.color(font_id, 0.15, 0.98, 0.38, 0.95)
                blf.position(font_id, float(ex_2d.x) + 8.0, float(ex_2d.y) - 6.0, 0.0)
                blf.draw(font_id, f"● 独占区域: {len(ex_pts)} 点")

        if rt_pts:
            rt_cen = sum(rt_pts, Vector()) / len(rt_pts)
            rt_2d = view3d_utils.location_3d_to_region_2d(region, space.region_3d, rt_cen)
            if rt_2d is not None:
                try:
                    blf.size(font_id, 11.0)
                except TypeError:
                    blf.size(font_id, 11.0, 72)
                blf.color(font_id, 1.0, 0.25, 0.80, 0.95)
                blf.position(font_id, float(rt_2d.x) + 8.0, float(rt_2d.y) + 4.0, 0.0)
                blf.draw(font_id, f"▲ 根部 ({len(rt_pts)})")

        if tp_pts:
            tp_cen = sum(tp_pts, Vector()) / len(tp_pts)
            tp_2d = view3d_utils.location_3d_to_region_2d(region, space.region_3d, tp_cen)
            if tp_2d is not None:
                try:
                    blf.size(font_id, 11.0)
                except TypeError:
                    blf.size(font_id, 11.0, 72)
                blf.color(font_id, 1.0, 0.95, 0.15, 0.95)
                blf.position(font_id, float(tp_2d.x) + 8.0, float(tp_2d.y) + 4.0, 0.0)
                blf.draw(font_id, f"▼ 末梢 ({len(tp_pts)})")
    except Exception:
        pass


def _draw_focus_marker():
    if _CHAIN_WEIGHT_VIEW and _CHAIN_WEIGHT_VIEW.get("scene") == bpy.context.scene:
        _draw_chain_weight_labels()
        return
    _draw_rigid_feedback_label()
    _draw_joint_guides_overlay()
    _draw_base_region_labels()
    _draw_custom_chain_labels()
    if not _FOCUS_STATE:
        return
    try:
        region = bpy.context.region
        space = bpy.context.space_data
        if not region or not space or space.type != "VIEW_3D":
            return
        world_points = _focus_world_points()
        if not world_points:
            return
        projected = {
            key: view3d_utils.location_3d_to_region_2d(region, space.region_3d, value)
            for key, value in world_points.items()
        }
        projected = {key: value for key, value in projected.items() if value is not None}
        if not projected:
            return
        focus_kind = _FOCUS_STATE.get("kind", "DIAGNOSTIC")

        shader = gpu.shader.from_builtin("UNIFORM_COLOR")
        gpu.state.blend_set("ALPHA")
        shader.bind()

        if "bone_head" in projected and "bone_tail" in projected:
            head_point = projected["bone_head"]
            tail_point = projected["bone_tail"]
            gpu.state.line_width_set(9.0)
            shader.uniform_float("color", (1.0, 0.20, 0.04, 0.96))
            batch_for_shader(
                shader,
                "LINES",
                {"pos": ((head_point.x, head_point.y), (tail_point.x, tail_point.y))},
            ).draw(shader)

        if "bone_mid" in projected and "mesh" in projected:
            bone_point = projected["bone_mid"]
            mesh_point = projected["mesh"]
            gpu.state.line_width_set(3.0)
            shader.uniform_float("color", (1.0, 0.42, 0.08, 0.90))
            batch_for_shader(
                shader,
                "LINES",
                {"pos": ((bone_point.x, bone_point.y), (mesh_point.x, mesh_point.y))},
            ).draw(shader)

        marker_styles = (
            {
                "bone_mid": ((1.0, 0.34, 0.04, 1.0), 25.0, "当前骨骼"),
                "mesh": ((0.10, 0.90, 1.0, 1.0), 21.0, "权重中心"),
            }
            if focus_kind == "WEIGHT_BROWSER"
            else {
                "bone_head": ((1.0, 0.18, 0.04, 1.0), 13.0, "Head"),
                "bone_tail": ((1.0, 0.48, 0.05, 1.0), 11.0, "Tail"),
                "bone_mid": ((1.0, 0.34, 0.04, 1.0), 25.0, "隐藏变形骨中点"),
                "mesh": ((0.10, 0.90, 1.0, 1.0), 21.0, "权重网格中心"),
            }
        )
        for key, point in projected.items():
            if focus_kind == "WEIGHT_BROWSER" and key in {"bone_head", "bone_tail"}:
                continue
            color, radius, marker_label = marker_styles.get(
                key,
                ((1.0, 0.72, 0.05, 0.98), 24.0, key),
            )
            center_x, center_y = float(point.x), float(point.y)
            circle = []
            for index in range(65):
                angle = math.tau * index / 64.0
                circle.append((center_x + math.cos(angle) * radius, center_y + math.sin(angle) * radius))
            cross = [
                (center_x - radius - 8.0, center_y),
                (center_x + radius + 8.0, center_y),
                (center_x, center_y - radius - 8.0),
                (center_x, center_y + radius + 8.0),
            ]
            gpu.state.line_width_set(4.0)
            shader.uniform_float("color", color)
            batch_for_shader(shader, "LINE_STRIP", {"pos": circle}).draw(shader)
            batch_for_shader(shader, "LINES", {"pos": cross}, indices=((0, 1), (2, 3))).draw(shader)

            font_id = 0
            try:
                blf.size(font_id, 16.0)
            except TypeError:
                blf.size(font_id, 16.0, 72)
            blf.color(font_id, *color)
            blf.position(font_id, center_x + radius + 10.0, center_y - 10.0, 0.0)
            blf.draw(font_id, marker_label)

        font_id = 0
        label = _FOCUS_STATE.get("label", "定位")
        diagnostic_name = _FOCUS_STATE.get("diagnostic_name", "")
        control_name = _FOCUS_STATE.get("bone_name", "")
        try:
            blf.size(font_id, 18.0)
        except TypeError:
            blf.size(font_id, 18.0, 72)
        blf.color(font_id, 1.0, 0.82, 0.18, 1.0)
        label_x = min(float(point.x) for point in projected.values())
        label_y = max(float(point.y) for point in projected.values()) + 48.0
        blf.position(font_id, label_x, label_y, 0.0)
        blf.draw(font_id, label)
        try:
            blf.size(font_id, 15.0)
        except TypeError:
            blf.size(font_id, 15.0, 72)
        blf.color(font_id, 1.0, 0.92, 0.52, 1.0)
        blf.position(font_id, label_x, label_y - 25.0, 0.0)
        if focus_kind == "WEIGHT_BROWSER":
            blf.draw(font_id, f"当前顶点组：{diagnostic_name}    当前骨骼：{control_name}")
        else:
            blf.draw(font_id, f"实际检测骨：{diagnostic_name}    操作控制器：{control_name}")
        blf.position(font_id, label_x, label_y - 48.0, 0.0)
        if focus_kind == "WEIGHT_BROWSER":
            blf.draw(font_id, "热力图：红色影响强，蓝色影响弱；粗橙线标出当前骨轴")
        else:
            blf.draw(font_id, "紫/蓝可见外形 = ARP 控制器显示；粗橙线 = 隐藏变形骨轴")
    except Exception:
        pass
    finally:
        try:
            gpu.state.line_width_set(1.0)
            gpu.state.blend_set("NONE")
        except Exception:
            pass


def _ensure_focus_draw_handler():
    global _FOCUS_DRAW_HANDLE, _BASE_REGION_DRAW_HANDLE
    if _FOCUS_DRAW_HANDLE is None:
        _FOCUS_DRAW_HANDLE = bpy.types.SpaceView3D.draw_handler_add(
            _draw_focus_marker,
            (),
            "WINDOW",
            "POST_PIXEL",
        )
    if _BASE_REGION_DRAW_HANDLE is None:
        _BASE_REGION_DRAW_HANDLE = bpy.types.SpaceView3D.draw_handler_add(
            _draw_base_region_geometry,
            (),
            "WINDOW",
            "POST_VIEW",
        )


def _remove_focus_draw_handler():
    global _FOCUS_DRAW_HANDLE, _BASE_REGION_DRAW_HANDLE
    if _FOCUS_DRAW_HANDLE is not None:
        try:
            bpy.types.SpaceView3D.draw_handler_remove(_FOCUS_DRAW_HANDLE, "WINDOW")
        except Exception:
            pass
        _FOCUS_DRAW_HANDLE = None
    if _BASE_REGION_DRAW_HANDLE is not None:
        try:
            bpy.types.SpaceView3D.draw_handler_remove(_BASE_REGION_DRAW_HANDLE, "WINDOW")
        except Exception:
            pass
        _BASE_REGION_DRAW_HANDLE = None


def _set_focus_marker(
    context,
    rig_obj,
    bone_name,
    label,
    mesh_obj=None,
    diagnostic_name=None,
    kind="DIAGNOSTIC",
    frame_view=True,
):
    _FOCUS_STATE.clear()
    _WEIGHTED_CENTROID_CACHE.clear()
    _FOCUS_STATE.update(
        {
            "rig_name": rig_obj.name,
            "bone_name": bone_name,
            "diagnostic_name": diagnostic_name or bone_name,
            "mesh_name": mesh_obj.name if mesh_obj else "",
            "group_name": diagnostic_name or "",
            "label": label,
            "kind": kind,
        }
    )
    _ensure_focus_draw_handler()
    points = _focus_world_points()
    if frame_view and points and context.screen:
        view_points = [
            points[key]
            for key in ("bone_head", "bone_tail", "mesh")
            if key in points
        ]
        center = sum(view_points, Vector((0.0, 0.0, 0.0))) / len(view_points)
        span = max(((point - center).length for point in view_points), default=0.0) * 2.0
        character_size = max((float(value) for value in mesh_obj.dimensions), default=1.0) if mesh_obj else 1.0
        focus_distance = max(character_size * 0.38, span * 2.4, 0.20)
        for area in context.screen.areas:
            if area.type != "VIEW_3D":
                continue
            try:
                region_3d = area.spaces.active.region_3d
                region_3d.view_location = center
                region_3d.view_distance = focus_distance
                area.tag_redraw()
            except (AttributeError, RuntimeError):
                pass
    _tag_view3d_redraw()


def _clear_focus_marker():
    _FOCUS_STATE.clear()
    _WEIGHTED_CENTROID_CACHE.clear()
    _tag_view3d_redraw()


def _armature_modifier(mesh_obj):
    if mesh_obj is None or mesh_obj.type != "MESH":
        return None
    return next((modifier for modifier in mesh_obj.modifiers if modifier.type == "ARMATURE"), None)


def _is_formal_character_mesh(obj):
    if not obj or obj.type != "MESH" or obj.name.startswith("cs_") or obj.get("wgame_rig_exclude_from_binding", False):
        return False
    upper_name = obj.name.upper()
    return not (
        upper_name.endswith("__TOPO_BACKUP")
        or upper_name.endswith("_TOPO_BACKUP")
        or upper_name.endswith("__BACKUP")
    )


def _largest_mesh(meshes):
    candidates = [obj for obj in meshes if obj and obj.type == "MESH"]
    return max(candidates, key=lambda obj: len(obj.data.vertices), default=None)


def _resolve_pair(context):
    settings = context.scene.wgame_rigging_assistant
    mesh_obj = bpy.data.objects.get(settings.mesh_name) if settings.mesh_name else None
    rig_obj = bpy.data.objects.get(settings.rig_name) if settings.rig_name else None

    if mesh_obj and not _is_formal_character_mesh(mesh_obj):
        mesh_obj = None
    if rig_obj and rig_obj.type != "ARMATURE":
        rig_obj = None

    active = context.view_layer.objects.active
    if active and _is_formal_character_mesh(active):
        mesh_obj = active
        modifier = _armature_modifier(mesh_obj)
        if modifier and modifier.object and modifier.object.type == "ARMATURE":
            rig_obj = modifier.object
    elif active and active.type == "ARMATURE":
        rig_obj = active
        matches = [
            obj
            for obj in context.scene.objects
            if _is_formal_character_mesh(obj)
            and (modifier := _armature_modifier(obj)) is not None
            and modifier.object == rig_obj
        ]
        mesh_obj = _largest_mesh(matches) or mesh_obj

    if mesh_obj and not rig_obj:
        modifier = _armature_modifier(mesh_obj)
        if modifier and modifier.object and modifier.object.type == "ARMATURE":
            rig_obj = modifier.object

    if rig_obj and not mesh_obj:
        matches = [
            obj
            for obj in context.scene.objects
            if _is_formal_character_mesh(obj)
            and (modifier := _armature_modifier(obj)) is not None
            and modifier.object == rig_obj
        ]
        mesh_obj = _largest_mesh(matches)

    if not mesh_obj:
        bound_meshes = [obj for obj in context.scene.objects if _is_formal_character_mesh(obj) and _armature_modifier(obj)]
        mesh_obj = _largest_mesh(bound_meshes)
        if mesh_obj:
            modifier = _armature_modifier(mesh_obj)
            rig_obj = modifier.object if modifier else rig_obj

    if not mesh_obj:
        # Pre-skin authoring files can have a generated WGame rig without an
        # Armature modifier yet. Recover stale helper selections by choosing
        # the largest formal mesh rather than returning the topology backup.
        mesh_obj = _largest_mesh(obj for obj in context.scene.objects if _is_formal_character_mesh(obj))

    if mesh_obj:
        settings.mesh_name = mesh_obj.name
    if rig_obj:
        settings.rig_name = rig_obj.name
    return mesh_obj, rig_obj


def _set_report(context, status, lines):
    settings = context.scene.wgame_rigging_assistant
    settings.last_status = status
    settings.last_report = "\n".join(str(line) for line in lines)


def _matrix_to_list(matrix):
    return [float(value) for row in matrix for value in row]


def _list_to_matrix(values):
    return Matrix((values[0:4], values[4:8], values[8:12], values[12:16]))


def _capture_pose_backup(rig_obj):
    pose = {bone.name: _matrix_to_list(bone.matrix_basis) for bone in rig_obj.pose.bones}
    switches = {}
    for side in (".l", ".r"):
        hand_ik = rig_obj.pose.bones.get("c_hand_ik" + side)
        if hand_ik and "ik_fk_switch" in hand_ik:
            switches[hand_ik.name] = float(hand_ik["ik_fk_switch"])
    rig_obj[POSE_BACKUP_KEY] = json.dumps({"pose": pose, "switches": switches})


def _restore_pose_backup(rig_obj):
    raw = rig_obj.get(POSE_BACKUP_KEY)
    if not raw:
        return False
    payload = json.loads(raw)
    for name, values in payload.get("pose", {}).items():
        pose_bone = rig_obj.pose.bones.get(name)
        if pose_bone:
            pose_bone.matrix_basis = _list_to_matrix(values)
    for name, value in payload.get("switches", {}).items():
        pose_bone = rig_obj.pose.bones.get(name)
        if pose_bone and "ik_fk_switch" in pose_bone:
            pose_bone["ik_fk_switch"] = value
    del rig_obj[POSE_BACKUP_KEY]
    bpy.context.view_layer.update()
    return True


def _weighted_centroid(mesh_obj, group_name):
    vertex_group = mesh_obj.vertex_groups.get(group_name)
    if not vertex_group:
        return None
    key = (mesh_obj.as_pointer(), mesh_obj.data.as_pointer(), group_name, vertex_group.index, len(mesh_obj.data.vertices))
    cached = _WEIGHTED_CENTROID_CACHE.get(key)
    now = time.monotonic()
    # The centroid is a locator hint, not live weight authority. Recomputing it
    # on a timer while Weight Paint is active scans the entire mesh and causes
    # periodic UI stalls. Target/bone changes call _set_focus_marker(), which
    # clears this cache and refreshes the centroid once.
    if cached:
        return cached["centroid"].copy() if cached["centroid"] is not None else None
    weighted_sum = Vector((0.0, 0.0, 0.0))
    total_weight = 0.0
    for vertex in mesh_obj.data.vertices:
        for assignment in vertex.groups:
            if assignment.group == vertex_group.index and assignment.weight > 0.0001:
                weighted_sum += vertex.co * assignment.weight
                total_weight += assignment.weight
                break
    centroid = weighted_sum / total_weight if total_weight > 0.0 else None
    _WEIGHTED_CENTROID_CACHE.clear()
    _WEIGHTED_CENTROID_CACHE[key] = {
        "time": now,
        "centroid": centroid.copy() if centroid is not None else None,
    }
    return centroid


def _fit_diagnostics(mesh_obj, rig_obj):
    inverse_mesh = mesh_obj.matrix_world.inverted()
    character_height = max(float(mesh_obj.dimensions.z), 0.0001)
    samples = []
    names = (
        "arm_twist.r",
        "arm_stretch.r",
        "forearm_stretch.r",
        "forearm_twist.r",
        "hand.r",
        "arm_twist.l",
        "arm_stretch.l",
        "forearm_stretch.l",
        "forearm_twist.l",
        "hand.l",
    )
    for name in names:
        centroid = _weighted_centroid(mesh_obj, name)
        bone = rig_obj.data.bones.get(name)
        if centroid is None or bone is None:
            continue
        head = inverse_mesh @ (rig_obj.matrix_world @ bone.head_local)
        tail = inverse_mesh @ (rig_obj.matrix_world @ bone.tail_local)
        # A deform group is not expected to have its weighted centroid exactly at
        # the geometric midpoint of the bone. Twist and stretch groups commonly
        # concentrate their weights toward one end. Measure the shortest distance
        # to the actual bone segment so the diagnostic reports lateral joint-fit
        # error instead of treating a valid along-bone weight bias as misalignment.
        segment = tail - head
        if segment.length_squared > 0.000000000001:
            factor = max(0.0, min(1.0, (centroid - head).dot(segment) / segment.length_squared))
            nearest = head + segment * factor
        else:
            nearest = head
        error = (centroid - nearest).length
        samples.append(
            {
                "name": name,
                "error": error,
                "percent": error / character_height * 100.0,
                "vertical": abs(centroid.z - nearest.z),
            }
        )
    samples.sort(key=lambda item: item["error"], reverse=True)
    return samples


def _connected_component_count(mesh):
    adjacency = [[] for _ in mesh.vertices]
    for edge in mesh.edges:
        a, b = edge.vertices
        adjacency[a].append(b)
        adjacency[b].append(a)
    seen = set()
    count = 0
    for start in range(len(mesh.vertices)):
        if start in seen:
            continue
        count += 1
        stack = [start]
        seen.add(start)
        while stack:
            current = stack.pop()
            for neighbor in adjacency[current]:
                if neighbor not in seen:
                    seen.add(neighbor)
                    stack.append(neighbor)
    return count


def _preflight(mesh_obj, rig_obj):
    mesh = mesh_obj.data
    zero_weight = 0
    non_normalized = 0
    over_four = 0
    max_influences = 0
    for vertex in mesh.vertices:
        weights = [assignment.weight for assignment in vertex.groups if assignment.weight > 0.000001]
        influence_count = len(weights)
        max_influences = max(max_influences, influence_count)
        if not weights:
            zero_weight += 1
        elif abs(sum(weights) - 1.0) > 0.01:
            non_normalized += 1
        if influence_count > 4:
            over_four += 1

    modifier = _armature_modifier(mesh_obj)
    pose_deviation_count = 0
    for pose_bone in rig_obj.pose.bones:
        location_delta = max(abs(value) for value in pose_bone.location)
        scale_delta = max(abs(value - 1.0) for value in pose_bone.scale)
        if pose_bone.rotation_mode == "QUATERNION":
            rotation_delta = max(
                abs(pose_bone.rotation_quaternion.w - 1.0),
                abs(pose_bone.rotation_quaternion.x),
                abs(pose_bone.rotation_quaternion.y),
                abs(pose_bone.rotation_quaternion.z),
            )
        else:
            rotation_delta = max(abs(value) for value in pose_bone.rotation_euler)
        if max(location_delta, scale_delta, rotation_delta) > 0.00001:
            pose_deviation_count += 1

    fit_samples = _fit_diagnostics(mesh_obj, rig_obj)
    worst_fit = fit_samples[0] if fit_samples else None
    average_fit = sum(item["percent"] for item in fit_samples) / len(fit_samples) if fit_samples else 0.0
    component_count = _connected_component_count(mesh)

    issues = []
    warnings = []
    if not modifier or modifier.object != rig_obj:
        issues.append("Armature 修改器没有指向当前骨架")
    if zero_weight:
        issues.append(f"{zero_weight} 个顶点没有权重")
    if non_normalized:
        issues.append(f"{non_normalized} 个顶点权重未归一化")
    if worst_fit and worst_fit["percent"] > 5.0:
        issues.append(
            f"手臂骨架拟合严重偏移：{worst_fit['name']} 为角色高度的 {worst_fit['percent']:.1f}%"
        )
    elif worst_fit and worst_fit["percent"] > 3.0:
        warnings.append(
            f"手臂骨架拟合需要复核：{worst_fit['name']} 为角色高度的 {worst_fit['percent']:.1f}%"
        )
    if over_four:
        warnings.append(f"{over_four} 个顶点超过 4 骨骼影响，Unity 导入可能截断")
    if any(abs(value - 1.0) > 0.0001 for value in rig_obj.scale):
        warnings.append(
            "骨架对象 Scale 不是 1：" + ", ".join(f"{value:.4f}" for value in rig_obj.scale)
        )
    if component_count > 1:
        warnings.append(f"单个 Mesh 内有 {component_count} 个不连通组件，配饰/披风应单独验收")
    if pose_deviation_count:
        warnings.append(f"当前有 {pose_deviation_count} 根骨骼保留 Pose 变换")

    status = "失败" if issues else ("警告" if warnings else "通过")
    lines = [
        f"结果：{status}",
        f"主体：{mesh_obj.name}",
        f"骨架：{rig_obj.name}",
        f"网格：{len(mesh.vertices)} 顶点 / {len(mesh.polygons)} 面 / {component_count} 个组件",
        f"权重：零权重 {zero_weight} / 未归一化 {non_normalized} / 最大影响 {max_influences} / 超过4根 {over_four}",
        f"姿势：{pose_deviation_count} 根骨骼有非零变换",
    ]
    if fit_samples:
        lines.append(f"手臂拟合：平均 {average_fit:.1f}% / 最差 {worst_fit['name']} {worst_fit['percent']:.1f}%")
        for sample in fit_samples[:4]:
            lines.append(
                f"  {sample['name']}: 偏移 {sample['error']:.3f}m（高度 {sample['percent']:.1f}%）"
            )
    if issues:
        lines.append("必须先修复：")
        lines.extend(f"  - {issue}" for issue in issues)
    if warnings:
        lines.append("注意：")
        lines.extend(f"  - {warning}" for warning in warnings)
    return status, lines


def _select_only(context, obj):
    context_object = getattr(context, "object", None)
    if context_object and context_object.mode != "OBJECT":
        bpy.ops.object.mode_set(mode="OBJECT")
    for candidate in context.view_layer.objects:
        candidate.select_set(False)
    obj.hide_set(False)
    obj.select_set(True)
    context.view_layer.objects.active = obj


def _show_bone_collections(bone):
    for collection in getattr(bone, "collections", ()):
        try:
            collection.is_visible = True
        except (AttributeError, RuntimeError):
            pass


def _frame_selected_pose_bone(context, rig_obj, bone_name, frame_view=False):
    bone = rig_obj.data.bones.get(bone_name)
    if bone is None:
        return False

    _select_only(context, rig_obj)
    bpy.ops.object.mode_set(mode="POSE")
    rig_obj.show_in_front = True
    for candidate in rig_obj.pose.bones:
        candidate.select = False
    _show_bone_collections(bone)
    bone.hide = False
    bone.hide_select = False
    rig_obj.pose.bones[bone_name].hide = False
    rig_obj.pose.bones[bone_name].select = True
    rig_obj.data.bones.active = bone
    if frame_view and context.screen:
        center = rig_obj.matrix_world @ ((bone.head_local + bone.tail_local) * 0.5)
        context_distance = max(float(rig_obj.dimensions.z) * 0.20, float(bone.length) * 3.5, 0.18)
        for area in context.screen.areas:
            if area.type != "VIEW_3D":
                continue
            area.spaces.active.region_3d.view_location = center
            area.spaces.active.region_3d.view_distance = context_distance
            area.tag_redraw()

    return True


def _diagnostic_control_name(deform_name):
    if not deform_name:
        return deform_name
    side = deform_name[-2:] if deform_name.endswith((".l", ".r")) else ""
    base = deform_name[:-2] if side else deform_name
    if base == "shoulder":
        return "c_shoulder" + side
    if base.startswith("arm_"):
        return "c_arm_fk" + side
    if base.startswith("forearm_"):
        return "c_forearm_fk" + side
    if base == "hand":
        return "c_hand_fk" + side
    return deform_name


def _joint_candidates(side, joint):
    if joint == "SHOULDER":
        return ("c_shoulder" + side, "c_arm_fk" + side, "shoulder" + side)
    if joint == "ELBOW":
        return ("c_forearm_fk" + side, "forearm_stretch" + side, "forearm_twist" + side)
    return ("c_hand_fk" + side, "hand" + side)


def _joint_fit_summary(mesh_obj, rig_obj, side, joint):
    samples = _fit_diagnostics(mesh_obj, rig_obj)
    if joint == "SHOULDER":
        prefixes = ("arm_twist", "arm_stretch", "shoulder")
    elif joint == "ELBOW":
        prefixes = ("forearm_stretch", "forearm_twist")
    else:
        prefixes = ("hand",)
    matches = [
        item
        for item in samples
        if item["name"].endswith(side) and item["name"].startswith(prefixes)
    ]
    return max(matches, key=lambda item: item["error"], default=None)


def _weight_group_statistics(mesh_obj, group_name):
    vertex_group = mesh_obj.vertex_groups.get(group_name)
    if not vertex_group:
        return None
    points = []
    weights = []
    for vertex in mesh_obj.data.vertices:
        for assignment in vertex.groups:
            if assignment.group == vertex_group.index and assignment.weight > 0.0001:
                points.append(mesh_obj.matrix_world @ vertex.co)
                weights.append(float(assignment.weight))
                break
    if not points:
        return None
    low = Vector(tuple(min(point[index] for point in points) for index in range(3)))
    high = Vector(tuple(max(point[index] for point in points) for index in range(3)))
    return {
        "count": len(points),
        "min_weight": min(weights),
        "max_weight": max(weights),
        "average_weight": sum(weights) / len(weights),
        "center": (low + high) * 0.5,
        "extent": max(float(high[index] - low[index]) for index in range(3)),
    }


def _frame_weight_group(context, mesh_obj, statistics):
    if not context.screen or not statistics:
        return
    focus_distance = max(statistics["extent"] * 1.5, 0.24)
    for area in context.screen.areas:
        if area.type != "VIEW_3D":
            continue
        try:
            region_3d = area.spaces.active.region_3d
            region_3d.view_location = statistics["center"]
            region_3d.view_distance = focus_distance
            area.tag_redraw()
        except (AttributeError, RuntimeError):
            pass


def _json_load(raw, fallback):
    if not raw:
        return fallback
    try:
        value = json.loads(raw)
        return value
    except (TypeError, ValueError):
        return fallback


def _hash_data(value):
    encoded = json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _pose_deviation_count(rig_obj):
    if POSE_BACKUP_KEY in rig_obj:
        return 0
    count = 0
    for pose_bone in rig_obj.pose.bones:
        location_delta = max(abs(value) for value in pose_bone.location)
        scale_delta = max(abs(value - 1.0) for value in pose_bone.scale)
        if pose_bone.rotation_mode == "QUATERNION":
            rotation_delta = max(
                abs(pose_bone.rotation_quaternion.w - 1.0),
                abs(pose_bone.rotation_quaternion.x),
                abs(pose_bone.rotation_quaternion.y),
                abs(pose_bone.rotation_quaternion.z),
            )
        else:
            rotation_delta = max(abs(value) for value in pose_bone.rotation_euler)
        if max(location_delta, scale_delta, rotation_delta) > 0.00001:
            count += 1
    return count


def _weight_data_summary(mesh_obj):
    zero_weight = 0
    non_normalized = 0
    over_four = 0
    max_influences = 0
    for vertex in mesh_obj.data.vertices:
        weights = [assignment.weight for assignment in vertex.groups if assignment.weight > 0.000001]
        influence_count = len(weights)
        max_influences = max(max_influences, influence_count)
        if not weights:
            zero_weight += 1
        elif abs(sum(weights) - 1.0) > 0.01:
            non_normalized += 1
        if influence_count > 4:
            over_four += 1
    return {
        "zero_weight": zero_weight,
        "non_normalized": non_normalized,
        "over_four": over_four,
        "max_influences": max_influences,
    }


def _groups_fingerprint(mesh_obj, rig_obj, group_names):
    group_names = [name for name in group_names if mesh_obj.vertex_groups.get(name)]
    vertex_groups = []
    for name in sorted(group_names):
        group = mesh_obj.vertex_groups.get(name)
        assignments = []
        for vertex in mesh_obj.data.vertices:
            for assignment in vertex.groups:
                if assignment.group == group.index and assignment.weight > 0.000001:
                    assignments.append(
                        (
                            vertex.index,
                            round(float(assignment.weight), 6),
                            tuple(round(float(value), 6) for value in vertex.co),
                        )
                    )
                    break
        vertex_groups.append((name, assignments))
    bones = []
    for name in sorted(set(group_names)):
        bone = rig_obj.data.bones.get(name)
        if not bone:
            continue
        bones.append(
            (
                name,
                [round(float(value), 6) for row in bone.matrix_local for value in row],
            )
        )
    return _hash_data(
        {
            "mesh": mesh_obj.name,
            "rig": rig_obj.name,
            "vertices": len(mesh_obj.data.vertices),
            "polygons": len(mesh_obj.data.polygons),
            "groups": vertex_groups,
            "bones": bones,
        }
    )


def _export_fingerprint(mesh_obj, rig_obj):
    summary = _weight_data_summary(mesh_obj)
    return _hash_data(
        {
            "mesh_matrix": [round(float(value), 6) for row in mesh_obj.matrix_world for value in row],
            "rig_matrix": [round(float(value), 6) for row in rig_obj.matrix_world for value in row],
            "weights": summary,
            "modifier": getattr(getattr(_armature_modifier(mesh_obj), "object", None), "name", None),
        }
    )


def _acceptances(settings):
    value = _json_load(settings.workflow_acceptances, {})
    return value if isinstance(value, dict) else {}


def _save_acceptances(settings, value):
    settings.workflow_acceptances = json.dumps(value, ensure_ascii=False, sort_keys=True)


def _accepted(settings, issue_id, fingerprint):
    return bool(fingerprint) and _acceptances(settings).get(issue_id) == fingerprint


def _fit_workflow_items(mesh_obj, rig_obj):
    samples = _fit_diagnostics(mesh_obj, rig_obj)
    definitions = (
        ("fit.shoulders", "双肩 / 上臂", "SHOULDER", ("arm_twist", "arm_stretch")),
        ("fit.elbows", "双肘 / 前臂", "ELBOW", ("forearm_stretch", "forearm_twist")),
        ("fit.wrists", "双腕 / 手", "WRIST", ("hand",)),
    )
    items = []
    upstream_failed = False
    for issue_id, title, joint, prefixes in definitions:
        matches = [item for item in samples if item["name"].startswith(prefixes)]
        worst = max(matches, key=lambda item: item["percent"], default=None)
        metric = worst["percent"] if worst else 0.0
        if worst is None:
            status = "WARNING"
            detail = "缺少可计算的左右权重组；需要人工检查"
        elif metric <= FIT_PASS_PERCENT:
            status = "PASSED"
            detail = f"最差 {worst['name']} {metric:.1f}% ≤ {FIT_PASS_PERCENT:.1f}%"
        elif upstream_failed:
            status = "BLOCKED"
            detail = f"被上游关节阻塞；当前最差 {worst['name']} {metric:.1f}%"
        else:
            status = "PENDING"
            upstream_failed = True
            detail = f"当前最差 {worst['name']} {metric:.1f}% > {FIT_PASS_PERCENT:.1f}%"
        if status == "WARNING" and not upstream_failed:
            upstream_failed = True
        items.append(
            {
                "id": issue_id,
                "stage": 3,
                "title": title,
                "status": status,
                "detail": detail,
                "joint": joint,
                "side": worst["name"][-2:] if worst and worst["name"].endswith((".l", ".r")) else ".l",
                "group": worst["name"] if worst else "",
                "metric": round(metric, 3),
                "manual": False,
            }
        )
    return items


def _weight_manual_definitions(mesh_obj):
    definitions = [
        (
            "weight.shoulders",
            "肩部与上臂权重",
            [name for name in ("arm_twist.l", "arm_stretch.l", "arm_twist.r", "arm_stretch.r") if mesh_obj.vertex_groups.get(name)],
        ),
        (
            "weight.elbows",
            "肘部与前臂扭转权重",
            [name for name in ("forearm_stretch.l", "forearm_twist.l", "forearm_stretch.r", "forearm_twist.r") if mesh_obj.vertex_groups.get(name)],
        ),
        (
            "weight.wrists",
            "手腕与手部权重",
            [name for name in ("hand.l", "hand.r") if mesh_obj.vertex_groups.get(name)],
        ),
    ]
    secondary = [
        group.name
        for group in mesh_obj.vertex_groups
        if group.name.startswith("cape_") or group.name.startswith("quiver")
    ]
    if secondary:
        definitions.append(("weight.secondary", "披风与刚性配饰权重", secondary))
    return definitions


def _weight_workflow_items(settings, mesh_obj, rig_obj):
    summary = _weight_data_summary(mesh_obj)
    items = []
    automatic = (
        ("weight.zero", "零权重顶点", summary["zero_weight"], "个顶点没有任何权重"),
        ("weight.normalize", "权重归一化", summary["non_normalized"], "个顶点权重和不为 1"),
    )
    upstream_failed = False
    for issue_id, title, count, suffix in automatic:
        status = "PASSED" if count == 0 else ("BLOCKED" if upstream_failed else "PENDING")
        if count:
            upstream_failed = True
        items.append(
            {
                "id": issue_id,
                "stage": 4,
                "title": title,
                "status": status,
                "detail": "通过" if count == 0 else f"{count} {suffix}",
                "manual": False,
                "count": count,
            }
        )

    for issue_id, title, groups in _weight_manual_definitions(mesh_obj):
        fingerprint = _groups_fingerprint(mesh_obj, rig_obj, groups)
        is_accepted = _accepted(settings, issue_id, fingerprint)
        if is_accepted:
            status = "PASSED"
        elif upstream_failed:
            status = "BLOCKED"
        else:
            status = "PENDING"
            upstream_failed = True
        representative = groups[0] if groups else ""
        statistics = _weight_group_statistics(mesh_obj, representative) if representative else None
        detail = "人工验收有效" if is_accepted else "需要查看真实权重并人工验收"
        if statistics and not is_accepted:
            detail += f"；{representative} 最大 {statistics['max_weight']:.3f}"
        items.append(
            {
                "id": issue_id,
                "stage": 4,
                "title": title,
                "status": status,
                "detail": detail,
                "manual": True,
                "groups": groups,
                "group": representative,
                "fingerprint": fingerprint,
            }
        )
    return items


def _deform_workflow_items(settings, mesh_obj, rig_obj):
    groups = [
        name
        for name in (
            "arm_twist.l",
            "arm_stretch.l",
            "forearm_stretch.l",
            "forearm_twist.l",
            "hand.l",
            "arm_twist.r",
            "arm_stretch.r",
            "forearm_stretch.r",
            "forearm_twist.r",
            "hand.r",
        )
        if mesh_obj.vertex_groups.get(name)
    ]
    fingerprint = _groups_fingerprint(mesh_obj, rig_obj, groups)
    issue_id = "deform.arms"
    is_accepted = _accepted(settings, issue_id, fingerprint)
    return [
        {
            "id": issue_id,
            "stage": 5,
            "title": "双臂压力测试",
            "status": "PASSED" if is_accepted else "PENDING",
            "detail": "人工验收有效" if is_accepted else "抬臂、弯肘、前臂和手腕需要人工观察",
            "manual": True,
            "groups": groups,
            "fingerprint": fingerprint,
        }
    ]


def _export_workflow_items(settings, mesh_obj, rig_obj):
    summary = _weight_data_summary(mesh_obj)
    cleanup_status = "PASSED" if summary["over_four"] == 0 else "PENDING"
    fingerprint = _export_fingerprint(mesh_obj, rig_obj)
    confirm_accepted = _accepted(settings, "export.confirm", fingerprint)
    confirm_status = "PASSED" if confirm_accepted else ("BLOCKED" if cleanup_status != "PASSED" else "PENDING")
    return [
        {
            "id": "export.influences",
            "stage": 6,
            "title": "Unity 四权重门槛",
            "status": cleanup_status,
            "detail": "通过" if cleanup_status == "PASSED" else f"{summary['over_four']} 个顶点超过 4 骨骼影响",
            "manual": False,
            "count": summary["over_four"],
        },
        {
            "id": "export.confirm",
            "stage": 6,
            "title": "最终导出确认",
            "status": confirm_status,
            "detail": "当前数据指纹已确认" if confirm_accepted else "确认当前版本可以进入导出 / Unity 验证",
            "manual": True,
            "fingerprint": fingerprint,
        },
    ]


def _workflow_scan(context):
    settings = context.scene.wgame_rigging_assistant
    mesh_obj, rig_obj = _resolve_pair(context)
    items = []

    backup_valid = bool(settings.backup_filepath and os.path.isfile(settings.backup_filepath))
    items.append(
        {
            "id": "safety.backup",
            "stage": 1,
            "title": "本次绑定安全备份",
            "status": "PASSED" if backup_valid else "PENDING",
            "detail": os.path.basename(settings.backup_filepath) if backup_valid else "开始修复前必须创建带时间戳的副本",
            "manual": False,
        }
    )

    if not mesh_obj or not rig_obj:
        items.append(
            {
                "id": "foundation.targets",
                "stage": 2,
                "title": "主体与骨架识别",
                "status": "PENDING",
                "detail": "没有识别到有效的 Mesh + Armature",
                "manual": False,
            }
        )
    else:
        modifier = _armature_modifier(mesh_obj)
        pose_count = _pose_deviation_count(rig_obj)
        items.extend(
            [
                {
                    "id": "foundation.targets",
                    "stage": 2,
                    "title": "主体与骨架识别",
                    "status": "PASSED",
                    "detail": f"{mesh_obj.name} + {rig_obj.name}",
                    "manual": False,
                },
                {
                    "id": "foundation.modifier",
                    "stage": 2,
                    "title": "Armature 修改器",
                    "status": "PASSED" if modifier and modifier.object == rig_obj else "PENDING",
                    "detail": "目标正确" if modifier and modifier.object == rig_obj else "修改器缺失或目标错误",
                    "manual": False,
                },
                {
                    "id": "foundation.pose",
                    "stage": 2,
                    "title": "基准姿势",
                    "status": "PASSED" if pose_count == 0 else "PENDING",
                    "detail": "无残留 Pose" if pose_count == 0 else f"{pose_count} 根骨骼有非零 Pose",
                    "manual": False,
                },
                {
                    "id": "foundation.scale",
                    "stage": 2,
                    "title": "对象缩放风险",
                    "status": "WARNING" if any(abs(value - 1.0) > 0.0001 for value in rig_obj.scale) else "PASSED",
                    "detail": "Rig Scale = " + ", ".join(f"{value:.4f}" for value in rig_obj.scale),
                    "manual": False,
                },
            ]
        )
        items.extend(_fit_workflow_items(mesh_obj, rig_obj))
        items.extend(_weight_workflow_items(settings, mesh_obj, rig_obj))
        items.extend(_deform_workflow_items(settings, mesh_obj, rig_obj))
        items.extend(_export_workflow_items(settings, mesh_obj, rig_obj))

    current_stage = 7
    current_issue = None
    for stage, _name in WORKFLOW_STAGES:
        stage_items = [item for item in items if item["stage"] == stage]
        pending = [item for item in stage_items if item["status"] in {"PENDING", "BLOCKED"}]
        if pending:
            current_stage = stage
            current_issue = next((item for item in pending if item["status"] == "PENDING"), pending[0])
            break

    for item in items:
        if item["stage"] > current_stage and item["status"] == "PENDING":
            item["status"] = "BLOCKED"

    payload = {
        "version": 1,
        "stage": current_stage,
        "stage_name": "绑定完成" if current_stage == 7 else dict(WORKFLOW_STAGES)[current_stage],
        "items": items,
        "current_issue_id": current_issue["id"] if current_issue else "",
        "pending_count": sum(1 for item in items if item["status"] in {"PENDING", "BLOCKED"}),
        "passed_count": sum(1 for item in items if item["status"] == "PASSED"),
        "warning_count": sum(1 for item in items if item["status"] == "WARNING"),
    }
    settings.workflow_stage = current_stage
    settings.workflow_state = json.dumps(payload, ensure_ascii=False)
    return payload


def _workflow_payload(settings):
    payload = _json_load(settings.workflow_state, {})
    return payload if isinstance(payload, dict) else {}


def _current_workflow_issue(settings):
    payload = _workflow_payload(settings)
    issue_id = payload.get("current_issue_id", "")
    return next((item for item in payload.get("items", []) if item.get("id") == issue_id), None)


def _backup_filepath():
    current = bpy.data.filepath
    if not current:
        return None
    base, extension = os.path.splitext(current)
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    return f"{base}_rig_backup_{timestamp}{extension or '.blend'}"


def _save_backup_copy():
    filepath = _backup_filepath()
    if not filepath:
        return None
    bpy.ops.wm.save_as_mainfile(filepath=filepath, copy=True, check_existing=False)
    return filepath


def _custom_chain_index_updated(settings, context):
    if context and not _CUSTOM_CHAIN_SETTINGS_SYNCING:
        _load_current_custom_chain_settings(settings, context)
        if _CHAIN_WEIGHT_VIEW and _CHAIN_WEIGHT_VIEW.get("scene") == context.scene:
            try:
                _refresh_chain_weight_view(context)
            except Exception as error:
                _CHAIN_WEIGHT_VIEW.update(batches=[], error=str(error))


def _custom_chain_setting_updated(settings, context):
    global _CUSTOM_CHAIN_SETTINGS_SYNCING
    if _CUSTOM_CHAIN_SETTINGS_SYNCING or not context:
        return
    rig_obj = _wgame_rig_object(context)
    payload = _custom_weight_chain_payload(rig_obj)
    chains = payload.get("chains", [])
    if not chains:
        return
    index = min(max(int(settings.wgame_custom_chain_index), 0), len(chains) - 1)
    chain = chains[index]
    if settings.wgame_custom_chain_id and chain.get("id") != settings.wgame_custom_chain_id:
        return
    chain["enabled"] = bool(settings.wgame_custom_chain_enabled)
    chain["influence_radius"] = max(float(settings.wgame_custom_chain_radius), 1e-5)
    chain["blend_steps_override"] = min(max(int(settings.wgame_custom_chain_blend_override), 0), 12)
    chain["coordinate_mode"] = settings.wgame_custom_chain_coordinate_mode
    chain["joint_blend"] = min(max(float(settings.wgame_custom_chain_joint_blend), 0.01), 0.5)
    if hasattr(settings, "wgame_custom_chain_semantic_key"):
        chain["semantic_key"] = _sanitize_custom_chain_semantic_key(
            settings.wgame_custom_chain_semantic_key,
            chain.get("base_parent", ""),
        )
    if hasattr(settings, "wgame_custom_chain_target_count"):
        chain["target_bone_count"] = min(max(int(settings.wgame_custom_chain_target_count), 1), 12)
    payload["chains"] = chains
    _save_custom_weight_chain_payload(rig_obj, payload)
    settings.wgame_custom_auto_weight_report = ""
    settings.wgame_custom_binding_complete = False
    settings.wgame_component_skin_complete = False


def _custom_chain_lock_updated(settings, context):
    if _CUSTOM_CHAIN_SETTINGS_SYNCING or not context:
        return
    rig_obj = _wgame_rig_object(context)
    payload = _custom_weight_chain_payload(rig_obj)
    chains = payload.get("chains", [])
    if not chains:
        return
    index = min(max(int(settings.wgame_custom_chain_index), 0), len(chains) - 1)
    chain = chains[index]
    if settings.wgame_custom_chain_id and chain.get("id") != settings.wgame_custom_chain_id:
        return
    chain["locked"] = bool(settings.wgame_custom_chain_locked)
    _save_custom_weight_chain_payload(rig_obj, payload)


def _custom_chain_global_steps_updated(settings, context):
    global _CUSTOM_CHAIN_SETTINGS_SYNCING
    if _CUSTOM_CHAIN_SETTINGS_SYNCING or not context:
        return
    rig_obj = _wgame_rig_object(context)
    payload = _custom_weight_chain_payload(rig_obj)
    if not payload:
        return
    payload["global_blend_steps"] = min(max(int(settings.wgame_custom_chain_global_blend_steps), 1), 12)
    _save_custom_weight_chain_payload(rig_obj, payload)
    settings.wgame_custom_auto_weight_report = ""
    settings.wgame_custom_binding_complete = False
    settings.wgame_component_skin_complete = False


def _custom_chain_boundary_share_updated(settings, context):
    global _CUSTOM_CHAIN_SETTINGS_SYNCING
    if _CUSTOM_CHAIN_SETTINGS_SYNCING or not context:
        return
    rig_obj = _wgame_rig_object(context)
    payload = _custom_weight_chain_payload(rig_obj)
    if not payload:
        return
    payload["boundary_custom_share"] = max(
        0.5,
        min(float(settings.wgame_custom_chain_boundary_custom_share), 0.95),
    )
    _save_custom_weight_chain_payload(rig_obj, payload)
    settings.wgame_custom_auto_weight_report = ""
    settings.wgame_custom_binding_complete = False
    settings.wgame_component_skin_complete = False


def _model_review_updated(settings, _context):
    if not all((settings.unrigged_topology_reviewed, settings.unrigged_pose_reviewed,
                settings.unrigged_hands_reviewed, settings.unrigged_regions_reviewed)):
        settings.unrigged_pose_locked = False
    report = _json_load(settings.unrigged_preflight_report, {})
    if report.get("warningCount", 0) and not settings.unrigged_review_notes.strip():
        settings.unrigged_pose_locked = False


