class WGAME_RIGGING_OT_detect_pair(Operator):
    bl_idname = "wgame_rigging.detect_pair"
    bl_label = "自动识别主体与骨架"
    bl_description = "根据当前选择和 Armature 修改器自动识别主体网格与骨架"
    bl_options = {"REGISTER"}

    def execute(self, context):
        mesh_obj, rig_obj = _resolve_pair(context)
        if not mesh_obj or not rig_obj:
            self.report({"ERROR"}, "没有找到有效的 Mesh + Armature 组合")
            return {"CANCELLED"}
        _set_report(context, "已识别", [f"主体：{mesh_obj.name}", f"骨架：{rig_obj.name}"])
        if context.scene.wgame_rigging_assistant.workflow_started:
            _workflow_scan(context)
        self.report({"INFO"}, f"已识别 {mesh_obj.name} + {rig_obj.name}")
        return {"FINISHED"}


class WGAME_RIGGING_OT_preflight(Operator):
    bl_idname = "wgame_rigging.preflight"
    bl_label = "一键绑定预检"
    bl_description = "检查绑定关系、权重、组件数量、对象缩放、姿势残留和手臂拟合偏差"
    bl_options = {"REGISTER"}

    def execute(self, context):
        mesh_obj, rig_obj = _resolve_pair(context)
        if not mesh_obj or not rig_obj:
            self.report({"ERROR"}, "请先选择主体 Mesh 或骨架，再点击自动识别")
            return {"CANCELLED"}
        status, lines = _preflight(mesh_obj, rig_obj)
        _set_report(context, status, lines)
        if status == "失败":
            self.report({"WARNING"}, lines[0] + "；点击“查看完整报告”")
        elif status == "警告":
            self.report({"WARNING"}, lines[0] + "；点击“查看完整报告”")
        else:
            self.report({"INFO"}, "绑定预检通过")
        if context.scene.wgame_rigging_assistant.workflow_started:
            _workflow_scan(context)
        return {"FINISHED"}


class WGAME_RIGGING_OT_show_report(Operator):
    bl_idname = "wgame_rigging.show_report"
    bl_label = "绑定检查报告"
    bl_options = {"INTERNAL"}

    def invoke(self, context, _event):
        return context.window_manager.invoke_props_dialog(self, width=620)

    def draw(self, context):
        layout = self.layout
        settings = context.scene.wgame_rigging_assistant
        for line in settings.last_report.splitlines():
            layout.label(text=line)

    def execute(self, _context):
        return {"FINISHED"}


class WGAME_RIGGING_OT_save_backup(Operator):
    bl_idname = "wgame_rigging.save_backup"
    bl_label = "保存带时间戳的绑定备份"
    bl_description = "在当前文件旁保存副本，不改变当前正在编辑的文件路径"
    bl_options = {"REGISTER"}

    def invoke(self, context, _event):
        return context.window_manager.invoke_confirm(self, _event)

    def execute(self, context):
        filepath = _save_backup_copy()
        if not filepath:
            self.report({"ERROR"}, "当前文件尚未命名，请先正常保存一次")
            return {"CANCELLED"}
        settings = context.scene.wgame_rigging_assistant
        settings.backup_filepath = filepath
        settings.workflow_started = True
        _workflow_scan(context)
        _set_report(context, "已备份", ["绑定备份已保存：", filepath])
        self.report({"INFO"}, f"已保存备份：{os.path.basename(filepath)}")
        return {"FINISHED"}


