class WGAME_RIGGING_OT_show_weight(Operator):
    bl_idname = "wgame_rigging.show_weight"
    bl_label = "查看当前骨骼真实权重"
    bl_description = "激活当前诊断骨的真实顶点组，进入 Blender Weight Paint 并框住受影响区域"
    bl_options = {"REGISTER"}

    def execute(self, context):
        mesh_obj, rig_obj = _resolve_pair(context)
        if not mesh_obj or not rig_obj:
            self.report({"ERROR"}, "没有找到有效的绑定对象")
            return {"CANCELLED"}

        settings = context.scene.wgame_rigging_assistant
        if _detect_character_route(context) == "WGAME_RIG":
            active_group = mesh_obj.vertex_groups.active.name if mesh_obj.vertex_groups.active else ""
            active_bone = (
                rig_obj.data.bones.active.name
                if hasattr(rig_obj.data.bones, "active") and rig_obj.data.bones.active
                else ""
            )
            candidates = (
                settings.wgame_weight_browser_bone,
                active_group,
                active_bone,
                settings.weight_group_name,
            )
            group_name = next(
                (name for name in candidates if name and mesh_obj.vertex_groups.get(name)),
                "",
            )
            if not group_name:
                group_name = next(
                    (
                        bone.name
                        for bone in rig_obj.data.bones
                        if bone.use_deform and mesh_obj.vertex_groups.get(bone.name)
                    ),
                    "",
                )
        else:
            group_name = settings.weight_group_name or _FOCUS_STATE.get("group_name", "")
            if not group_name:
                samples = _fit_diagnostics(mesh_obj, rig_obj)
                group_name = samples[0]["name"] if samples else ""
        vertex_group = mesh_obj.vertex_groups.get(group_name)
        if not vertex_group:
            self.report({"ERROR"}, f"主体 Mesh 没有顶点组：{group_name}")
            return {"CANCELLED"}
        statistics = _weight_group_statistics(mesh_obj, group_name)
        if not statistics:
            self.report({"ERROR"}, f"顶点组 {group_name} 没有有效权重")
            return {"CANCELLED"}

        _clear_focus_marker()
        if getattr(context, "object", None) and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        for candidate in context.view_layer.objects:
            candidate.select_set(False)
        rig_obj.hide_set(False)
        mesh_obj.hide_set(False)
        rig_obj.select_set(True)
        mesh_obj.select_set(True)
        context.view_layer.objects.active = mesh_obj
        mesh_obj.vertex_groups.active_index = vertex_group.index
        if hasattr(mesh_obj.data, "use_paint_mask"):
            mesh_obj.data.use_paint_mask = False
        if hasattr(mesh_obj.data, "use_paint_mask_vertex"):
            mesh_obj.data.use_paint_mask_vertex = False
        bpy.ops.object.mode_set(mode="WEIGHT_PAINT")
        _frame_weight_group(context, mesh_obj, statistics)

        settings.weight_group_name = group_name
        settings.last_focus = (
            f"权重模式：{group_name}；{statistics['count']} 顶点；"
            f"最小 {statistics['min_weight']:.3f} / 平均 {statistics['average_weight']:.3f} / "
            f"最大 {statistics['max_weight']:.3f}"
        )
        self.report(
            {"INFO"},
            f"正在查看 {group_name}：{statistics['count']} 顶点，最大权重 {statistics['max_weight']:.3f}",
        )
        return {"FINISHED"}


class WGAME_RIGGING_OT_return_focus(Operator):
    bl_idname = "wgame_rigging.return_focus"
    bl_label = "返回骨架对比定位"
    bl_description = "退出 Weight Paint，重新选择对应控制骨并显示骨骼中心与权重网格中心"
    bl_options = {"REGISTER"}

    def execute(self, context):
        mesh_obj, rig_obj = _resolve_pair(context)
        if not mesh_obj or not rig_obj:
            self.report({"ERROR"}, "没有找到有效的绑定对象")
            return {"CANCELLED"}
        settings = context.scene.wgame_rigging_assistant
        group_name = settings.weight_group_name
        if not group_name or not mesh_obj.vertex_groups.get(group_name):
            self.report({"ERROR"}, "没有记录可返回的权重组，请先定位或查看权重")
            return {"CANCELLED"}

        control_name = _diagnostic_control_name(group_name)
        if rig_obj.data.bones.get(control_name) is None:
            control_name = group_name
        if not _frame_selected_pose_bone(context, rig_obj, control_name):
            self.report({"ERROR"}, f"找不到对应控制骨：{control_name}")
            return {"CANCELLED"}

        fit = next(
            (item for item in _fit_diagnostics(mesh_obj, rig_obj) if item["name"] == group_name),
            None,
        )
        if fit:
            message = (
                f"{group_name} → {control_name}，偏移 {fit['error']:.3f}m / 高度 {fit['percent']:.1f}%"
            )
            label = f"{group_name} → {control_name}  {fit['percent']:.1f}%"
        else:
            message = f"{group_name} → {control_name}"
            label = message
        settings.last_focus = message
        _set_focus_marker(
            context,
            rig_obj,
            control_name,
            label,
            mesh_obj=mesh_obj,
            diagnostic_name=group_name,
        )
        self.report({"INFO"}, "已返回骨架对比定位：" + message)
        return {"FINISHED"}


class WGAME_RIGGING_OT_apply_source_transforms(Operator):
    bl_idname = "wgame_rigging.apply_source_transforms"
    bl_label = "应用未绑定源模型的旋转与缩放"
    bl_description = "仅允许未绑定 Mesh 使用；检测到 Armature 修改器或骨架父级时会拒绝执行"
    bl_options = {"REGISTER", "UNDO"}

    def invoke(self, context, event):
        return context.window_manager.invoke_confirm(self, event)

    def execute(self, context):
        mesh_obj, _rig_obj = _resolve_pair(context)
        if not mesh_obj:
            active = context.view_layer.objects.active
            mesh_obj = active if active and active.type == "MESH" else None
        if not mesh_obj:
            self.report({"ERROR"}, "请先选择未绑定的源 Mesh")
            return {"CANCELLED"}
        if _armature_modifier(mesh_obj) or (mesh_obj.parent and mesh_obj.parent.type == "ARMATURE"):
            self.report({"ERROR"}, "安全保护：该 Mesh 已经绑定，不能直接 Apply Scale")
            return {"CANCELLED"}
        _select_only(context, mesh_obj)
        bpy.ops.object.transform_apply(location=False, rotation=True, scale=True)
        _set_report(context, "已应用", [f"已对未绑定源模型应用旋转与缩放：{mesh_obj.name}"])
        return {"FINISHED"}


class WGAME_RIGGING_OT_weight_cleanup(Operator):
    bl_idname = "wgame_rigging.weight_cleanup"
    bl_label = "Unity 4 权重清理（先备份）"
    bl_description = "自动保存副本，然后把每个顶点限制到 4 个权重并重新归一化"
    bl_options = {"REGISTER", "UNDO"}

    def invoke(self, context, event):
        return context.window_manager.invoke_confirm(self, event)

    def execute(self, context):
        mesh_obj, rig_obj = _resolve_pair(context)
        if not mesh_obj or not rig_obj:
            self.report({"ERROR"}, "没有找到有效的绑定对象")
            return {"CANCELLED"}
        filepath = _save_backup_copy()
        if not filepath:
            self.report({"ERROR"}, "当前文件尚未命名，无法先创建安全备份")
            return {"CANCELLED"}
        _select_only(context, mesh_obj)
        bpy.ops.object.vertex_group_limit_total(group_select_mode="ALL", limit=4)
        bpy.ops.object.vertex_group_normalize_all(group_select_mode="ALL", lock_active=False)
        status, lines = _preflight(mesh_obj, rig_obj)
        lines.insert(1, f"执行前备份：{filepath}")
        _set_report(context, status, lines)
        settings = context.scene.wgame_rigging_assistant
        settings.backup_filepath = filepath
        if settings.workflow_started:
            _workflow_scan(context)
        self.report({"INFO"}, "已限制为 4 权重并归一化；请执行测试姿势验收")
        return {"FINISHED"}


class WGAME_RIGGING_OT_test_pose(Operator):
    bl_idname = "wgame_rigging.test_pose"
    bl_label = "应用双臂压力测试姿势"
    bl_description = "缓存当前姿势，切到 Auto-Rig Pro FK 手臂并抬臂、弯肘；可用恢复按钮还原"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        _mesh_obj, rig_obj = _resolve_pair(context)
        if not rig_obj:
            self.report({"ERROR"}, "没有找到骨架")
            return {"CANCELLED"}
        required = [
            "c_arm_fk.l",
            "c_forearm_fk.l",
            "c_arm_fk.r",
            "c_forearm_fk.r",
        ]
        if any(rig_obj.pose.bones.get(name) is None for name in required):
            self.report({"ERROR"}, "当前骨架不是受支持的 Auto-Rig Pro 人形骨架")
            return {"CANCELLED"}
        if POSE_BACKUP_KEY not in rig_obj:
            _capture_pose_backup(rig_obj)
        for side in (".l", ".r"):
            hand_ik = rig_obj.pose.bones.get("c_hand_ik" + side)
            if hand_ik and "ik_fk_switch" in hand_ik:
                hand_ik["ik_fk_switch"] = 1.0
            arm = rig_obj.pose.bones.get("c_arm_fk" + side)
            forearm = rig_obj.pose.bones.get("c_forearm_fk" + side)
            arm.rotation_mode = "XYZ"
            forearm.rotation_mode = "XYZ"
            arm.rotation_euler.x = math.radians(38.0)
            forearm.rotation_euler.x = math.radians(82.0)
        bpy.context.view_layer.update()
        _set_report(
            context,
            "测试姿势",
            [
                "已应用双臂压力测试姿势。",
                "重点观察：肩部塌陷、肘轴偏移、前臂扭曲和手腕绕错中心。",
                "检查完成后点击“恢复测试前姿势”。",
            ],
        )
        settings = context.scene.wgame_rigging_assistant
        if settings.workflow_started:
            issue = _current_workflow_issue(settings)
            if issue and issue.get("stage") == 5:
                settings.deform_test_seen_fingerprint = issue.get("fingerprint", "")
        self.report({"INFO"}, "已应用测试姿势；检查完成后点击恢复")
        return {"FINISHED"}


class WGAME_RIGGING_OT_restore_pose(Operator):
    bl_idname = "wgame_rigging.restore_pose"
    bl_label = "恢复测试前姿势"
