class WGAME_RIGGING_OT_workflow_focus_current(Operator):
    bl_idname = "wgame_rigging.workflow_focus_current"
    bl_label = "定位并修复下一项"
    bl_description = "按肩、肘、腕的依赖顺序定位当前待修复骨骼，而不是按最大误差跳跃"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        issue = _current_workflow_issue(settings)
        mesh_obj, rig_obj = _resolve_pair(context)
        if not issue or issue.get("stage") != 3 or not mesh_obj or not rig_obj:
            self.report({"ERROR"}, "当前阶段没有可定位的骨架拟合项")
            return {"CANCELLED"}
        group_name = issue.get("group", "")
        control_name = _diagnostic_control_name(group_name)
        if rig_obj.data.bones.get(control_name) is None:
            control_name = group_name
        if not control_name or not _frame_selected_pose_bone(context, rig_obj, control_name):
            self.report({"ERROR"}, f"找不到当前项控制骨：{control_name}")
            return {"CANCELLED"}
        settings.weight_group_name = group_name
        settings.last_focus = f"工作流当前项：{issue['title']}；{issue['detail']}"
        _set_focus_marker(
            context,
            rig_obj,
            control_name,
            f"当前项：{issue['title']}  {issue.get('metric', 0.0):.1f}%",
            mesh_obj=mesh_obj,
            diagnostic_name=group_name,
        )
        self.report({"INFO"}, f"已定位当前项：{issue['title']} → {control_name}")
        return {"FINISHED"}


class WGAME_RIGGING_OT_workflow_show_weight(Operator):
    bl_idname = "wgame_rigging.workflow_show_weight"
    bl_label = "查看当前项真实权重"
    bl_description = "进入当前权重验收项的 Blender 原生 Weight Paint"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        issue = _current_workflow_issue(settings)
        if not issue or issue.get("stage") != 4 or not issue.get("manual"):
            self.report({"ERROR"}, "当前项不是可人工验收的权重项")
            return {"CANCELLED"}
        group_name = issue.get("group", "")
        if not group_name:
            self.report({"ERROR"}, "当前权重项没有可显示的顶点组")
            return {"CANCELLED"}
        settings.weight_group_name = group_name
        result = bpy.ops.wgame_rigging.show_weight()
        if "FINISHED" in result:
            settings.last_viewed_issue_id = issue["id"]
        return result


class WGAME_RIGGING_OT_workflow_accept_current(Operator):
    bl_idname = "wgame_rigging.workflow_accept_current"
    bl_label = "验收当前项并继续"
    bl_description = "记录当前数据指纹；相关骨架或权重改变后，本次验收会自动失效"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        mesh_obj, rig_obj = _resolve_pair(context)
        if not mesh_obj or not rig_obj:
            self.report({"ERROR"}, "没有找到有效绑定对象")
            return {"CANCELLED"}
        issue = _current_workflow_issue(settings)
        if not issue or not issue.get("manual"):
            self.report({"ERROR"}, "当前项不能使用人工验收")
            return {"CANCELLED"}

        if issue.get("stage") == 4 and settings.last_viewed_issue_id != issue.get("id"):
            self.report({"ERROR"}, "请先点击“查看当前项真实权重”，完成实际检查后再验收")
            return {"CANCELLED"}
        if issue.get("stage") == 5 and settings.deform_test_seen_fingerprint != issue.get("fingerprint"):
            self.report({"ERROR"}, "请先实际运行当前压力测试，再验收变形")
            return {"CANCELLED"}

        if issue.get("stage") == 5 and POSE_BACKUP_KEY in rig_obj:
            _restore_pose_backup(rig_obj)
            _workflow_scan(context)
            issue = _current_workflow_issue(settings)
        fingerprint = issue.get("fingerprint", "") if issue else ""
        if not fingerprint:
            self.report({"ERROR"}, "当前项没有可记录的数据指纹")
            return {"CANCELLED"}

        acceptances = _acceptances(settings)
        acceptances[issue["id"]] = fingerprint
        _save_acceptances(settings, acceptances)
        settings.last_viewed_issue_id = ""
        settings.deform_test_seen_fingerprint = ""
        payload = _workflow_scan(context)
        self.report({"INFO"}, f"已验收 {issue['title']}；当前阶段：{payload['stage_name']}")
        return {"FINISHED"}


class WGAME_RIGGING_OT_workflow_deform_failed(Operator):
    bl_idname = "wgame_rigging.workflow_deform_failed"
    bl_label = "变形不通过：退回权重阶段"
    bl_description = "清除权重与变形人工验收，让相关项目重新进入待修复列表"
    bl_options = {"REGISTER"}

    def invoke(self, context, event):
        return context.window_manager.invoke_confirm(self, event)

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        _mesh_obj, rig_obj = _resolve_pair(context)
        if rig_obj and POSE_BACKUP_KEY in rig_obj:
            _restore_pose_backup(rig_obj)
        acceptances = {
            key: value
            for key, value in _acceptances(settings).items()
            if not key.startswith("weight.") and not key.startswith("deform.") and not key.startswith("export.")
        }
        _save_acceptances(settings, acceptances)
        payload = _workflow_scan(context)
        self.report({"INFO"}, f"已退回：{payload['stage_name']}")
        return {"FINISHED"}


class WGAME_RIGGING_OT_workflow_reset(Operator):
    bl_idname = "wgame_rigging.workflow_reset"
    bl_label = "重置工作流记录"
    bl_description = "清除阶段、验收和备份记录；不会删除备份文件，也不会修改骨架或权重"
    bl_options = {"REGISTER"}

    def invoke(self, context, event):
        return context.window_manager.invoke_confirm(self, event)

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        settings.workflow_started = False
        settings.workflow_stage = 1
        settings.workflow_state = ""
        settings.workflow_acceptances = "{}"
        settings.backup_filepath = ""
        settings.last_viewed_issue_id = ""
        settings.deform_test_seen_fingerprint = ""
        self.report({"INFO"}, "已重置工作流记录；场景数据未修改")
        return {"FINISHED"}


def _detect_character_route(context):
    armatures = [obj for obj in context.scene.objects if obj.type == "ARMATURE"]
    bound_meshes = [obj for obj in context.scene.objects if obj.type == "MESH" and _armature_modifier(obj)]
    if any(obj.get("wgame_rig_kind") == "deform_skeleton" for obj in armatures):
        return "WGAME_RIG"
    if bound_meshes:
        return "BOUND"
    if armatures:
        if any(bool(obj.get("wgame_reference_stage")) for obj in armatures):
            return "REFERENCE_RIG"
        generated = any(bool(obj.data.get("has_match_to_rig")) for obj in armatures)
        return "GENERATED_RIG" if generated else "REFERENCE_RIG"
    meshes = [obj for obj in context.scene.objects if _is_formal_character_mesh(obj)]
    return "UNRIGGED" if meshes else "NO_MODEL"


def _formal_binding_meshes(context):
    return sorted((obj for obj in context.scene.objects if _is_formal_character_mesh(obj)), key=lambda obj: obj.name)


def _mesh_fingerprint(context, geometry):
    digest = hashlib.sha256(b"wgame-mesh-fingerprint-v2")
    for obj in _formal_binding_meshes(context):
        obj.update_from_editmode()
        mesh = obj.data
        header = [obj.name, len(mesh.vertices), len(mesh.edges), len(mesh.polygons), len(mesh.loops)]
        digest.update(json.dumps(header, ensure_ascii=False).encode("utf-8"))
        for collection, attribute, width in ((mesh.edges, "vertices", 2), (mesh.loops, "vertex_index", 1), (mesh.polygons, "loop_total", 1)):
            values = array("i", [0]) * (len(collection) * width)
            collection.foreach_get(attribute, values)
            digest.update(values.tobytes())
        if geometry:
            values = array("f", [0.0]) * (len(mesh.vertices) * 3)
            mesh.vertices.foreach_get("co", values)
            digest.update(values.tobytes())
            digest.update(array("d", (value for row in obj.matrix_world for value in row)).tobytes())
    return digest.hexdigest()


def _unrigged_fingerprint(context):
    return _mesh_fingerprint(context, True)


def _unrigged_topology_fingerprint(context):
    return _mesh_fingerprint(context, False)


def _invalidate_model_preflight(settings):
    settings.unrigged_preflight_passed = False
    settings.unrigged_pose_locked = False
    settings.unrigged_topology_reviewed = False
    settings.unrigged_pose_reviewed = False
    settings.unrigged_hands_reviewed = False
    settings.unrigged_regions_reviewed = False
    settings.unrigged_review_notes = ""
    _invalidate_binding_results(settings)


def _current_model_preflight(context, settings):
    if not settings.unrigged_preflight_passed:
        return False
    if settings.unrigged_model_fingerprint != _unrigged_fingerprint(context):
        _invalidate_model_preflight(settings)
        return False
    return True


def _component_scan_is_current(context, settings):
    stored = settings.unrigged_component_scan_fingerprint
    if stored:
        return stored == _unrigged_topology_fingerprint(context)
    components = _unrigged_components(settings)
    expected = {}
    for component in components:
        expected[component.get("object", "")] = expected.get(component.get("object", ""), 0) + int(component.get("vertices", 0))
    for object_name, vertex_count in expected.items():
        obj = context.scene.objects.get(object_name)
        if not obj or obj.type != "MESH" or len(obj.data.vertices) != vertex_count:
            return False
    return bool(components)


def _scan_unrigged_components(context):
    result = []
    for obj in sorted((item for item in context.scene.objects if _is_formal_character_mesh(item)), key=lambda item: item.name):
        adjacency = [[] for _ in obj.data.vertices]
        for edge in obj.data.edges:
            left, right = edge.vertices
            adjacency[left].append(right)
            adjacency[right].append(left)
        seen = set()
        component_index = 0
        for start in range(len(obj.data.vertices)):
            if start in seen:
                continue
            stack = [start]
            seen.add(start)
            vertex_indices = []
            while stack:
                current = stack.pop()
                vertex_indices.append(current)
                for neighbor in adjacency[current]:
                    if neighbor not in seen:
                        seen.add(neighbor)
                        stack.append(neighbor)
            vertex_indices.sort()
            points = [obj.data.vertices[index].co for index in vertex_indices]
            minimum = [min(float(point[axis]) for point in points) for axis in range(3)]
            maximum = [max(float(point[axis]) for point in points) for axis in range(3)]
            center = [sum(float(point[axis]) for point in points) / len(points) for axis in range(3)]
            result.append(
                {
                    "id": f"{obj.name}:{component_index}",
                    "object": obj.name,
                    "vertices": len(vertex_indices),
                    "vertex_indices": vertex_indices,
                    "center": [round(value, 6) for value in center],
                    "dimensions": [round(maximum[axis] - minimum[axis], 6) for axis in range(3)],
                    "binding_scope": "",
                }
            )
            component_index += 1
    return result


def _rescan_unrigged_components_preserving_state(context, settings):
    old_components = _unrigged_components(settings)
    old_scopes_finalized = bool(old_components) and all(
        item.get("binding_scope") in VALID_COMPONENT_BINDING_SCOPES for item in old_components
    )
    old_groups = _unrigged_binding_groups(settings)
    old_current_id = ""
    if old_components:
        old_index = min(settings.unrigged_component_index, len(old_components) - 1)
        old_current_id = old_components[old_index].get("id", "")
    new_components = _scan_unrigged_components(context)

    object_diagonals = {}
    for obj in context.scene.objects:
        if obj.type == "MESH":
            object_diagonals[obj.name] = max(float(obj.dimensions.length), 0.0001)

    candidates = []
    for old in old_components:
        old_center = Vector(old.get("center") or (0.0, 0.0, 0.0))
        old_dimensions = Vector(old.get("dimensions") or (0.0, 0.0, 0.0))
        old_vertices = max(int(old.get("vertices", 0)), 1)
        diagonal = object_diagonals.get(old.get("object", ""), 1.0)
        for new in new_components:
            if new.get("object") != old.get("object"):
                continue
            new_center = Vector(new.get("center") or (0.0, 0.0, 0.0))
            new_dimensions = Vector(new.get("dimensions") or (0.0, 0.0, 0.0))
            vertex_ratio = abs(int(new.get("vertices", 0)) - old_vertices) / max(old_vertices, int(new.get("vertices", 0)), 1)
            score = (
                (new_center - old_center).length / diagonal * 4.0
                + (new_dimensions - old_dimensions).length / diagonal * 2.0
                + vertex_ratio
            )
            candidates.append((score, old.get("id", ""), new.get("id", "")))
    candidates.sort(key=lambda item: item[0])

    mapping = {}
    used_new = set()
    match_scores = {}
    for score, old_id, new_id in candidates:
        if score > 0.35 or old_id in mapping or new_id in used_new:
            continue
        mapping[old_id] = new_id
        used_new.add(new_id)
        match_scores[old_id] = score

    old_by_id = {item.get("id"): item for item in old_components}
    new_by_id = {item.get("id"): item for item in new_components}
    migrated_scopes = 0
    for old_id, new_id in mapping.items():
        old = old_by_id.get(old_id, {})
        new = new_by_id.get(new_id, {})
        scope = old.get("binding_scope")
        if scope in VALID_COMPONENT_BINDING_SCOPES:
            new["binding_scope"] = scope
            migrated_scopes += 1
            if old.get("base_region") in BASE_REGION_KEYS:
                new["base_region"] = old.get("base_region")
        elif old.get("role") in LEGACY_COMPONENT_ROLES:
            # Preserve only the legacy marker so the UI can require the user's
            # explicit metadata reset; never infer a new binding scope.
            new["role"] = old.get("role")

    # Keep legacy metadata only as a blocked marker until the user explicitly
    # resets it; it never participates in the new two-scope workflow.
    migrated_groups = list(old_groups) if any(item.get("role") in LEGACY_COMPONENT_ROLES for item in old_components) else []

    settings.unrigged_components_json = json.dumps(new_components, ensure_ascii=False, separators=(",", ":"))
    _save_unrigged_binding_groups(settings, migrated_groups)
    new_current_id = mapping.get(old_current_id, "")
    settings.unrigged_component_index = next(
        (index for index, item in enumerate(new_components) if item.get("id") == new_current_id),
        0,
    )
    settings.unrigged_component_scan_fingerprint = _unrigged_topology_fingerprint(context)
    if any(mesh_obj.vertex_groups.get(CUSTOM_BIND_MASK_GROUP) for mesh_obj in _participant_meshes(context, settings)):
        _sync_component_scopes_from_mask(context, settings, finalized=old_scopes_finalized)
    if any(
        mesh_obj.get(BASE_REGION_MASK_AUTHORITY_KEY)
        or any(mesh_obj.vertex_groups.get(_base_region_group_name(region)) for region in BASE_REGION_KEYS)
        for mesh_obj in _participant_meshes(context, settings)
    ):
        _sync_component_base_region_cache(context, settings)
    _invalidate_base_region_overlay_cache()
    return {
        "old_count": len(old_components),
        "new_count": len(new_components),
        "matched": len(mapping),
        "unmatched_old": len(old_components) - len(mapping),
        "unmatched_new": len(new_components) - len(used_new),
        "migrated_roles": migrated_scopes,
        "migrated_scopes": migrated_scopes,
        "migrated_groups": len(migrated_groups),
        "mapping": mapping,
        "scores": match_scores,
    }


def _unrigged_components(settings):
    try:
        value = json.loads(settings.unrigged_components_json or "[]")
        return value if isinstance(value, list) else []
    except ValueError:
        return []


def _wgame_rig_object(context):
    if not context or not getattr(context, "scene", None):
        return None
    settings = getattr(context.scene, "wgame_rigging_assistant", None)
    rig_obj = bpy.data.objects.get(settings.rig_name) if settings and settings.rig_name else None
    if rig_obj and rig_obj.type == "ARMATURE" and rig_obj.get("wgame_rig_kind") == "deform_skeleton":
        return rig_obj
    return next(
        (
            obj
            for obj in context.scene.objects
            if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"
        ),
        None,
    )


def _component_has_legacy_binding_data(settings):
    components = _unrigged_components(settings)
    return bool(
        any(item.get("role") in LEGACY_COMPONENT_ROLES or item.get("binding_group_id") for item in components)
        or _unrigged_binding_groups(settings)
    )


def _component_scope_ready(component):
    return component.get("binding_scope") in VALID_COMPONENT_BINDING_SCOPES


def _mesh_vertex_group_ids(mesh_obj, group_name):
    group = mesh_obj.vertex_groups.get(group_name) if mesh_obj and mesh_obj.type == "MESH" else None
    if not group:
        return set()
    if mesh_obj.mode == "EDIT":
        bm = bmesh.from_edit_mesh(mesh_obj.data)
        deform = bm.verts.layers.deform.active
        if not deform:
            return set()
        return {vert.index for vert in bm.verts if vert[deform].get(group.index, 0.0) > 0.5}
    return {
        vertex.index
        for vertex in mesh_obj.data.vertices
        if any(item.group == group.index and item.weight > 0.5 for item in vertex.groups)
    }


def _legacy_custom_vertex_ids_by_object(settings):
    result = {}
    for component in _unrigged_components(settings):
        if component.get("binding_scope") != "CUSTOM_BIND":
            continue
        result.setdefault(component.get("object", ""), set()).update(component.get("vertex_indices") or [])
    return {name: indices for name, indices in result.items() if name and indices}


def _custom_mask_vertex_ids_by_object(context, settings):
    legacy = _legacy_custom_vertex_ids_by_object(settings)
    result = {}
    for mesh_obj in _participant_meshes(context, settings):
        if mesh_obj.vertex_groups.get(CUSTOM_BIND_MASK_GROUP) and mesh_obj.get(CUSTOM_BIND_MASK_AUTHORITY_KEY):
            indices = _mesh_vertex_group_ids(mesh_obj, CUSTOM_BIND_MASK_GROUP)
        else:
            indices = _mesh_vertex_group_ids(mesh_obj, CUSTOM_BIND_MASK_GROUP) | legacy.get(mesh_obj.name, set())
        if indices:
            result[mesh_obj.name] = set(indices)
    return result


def _set_vertex_group_mask_vertices(mesh_obj, group_name, vertex_ids, enabled):
    if not mesh_obj or mesh_obj.type != "MESH":
        return 0
    valid_ids = {int(index) for index in vertex_ids if 0 <= int(index) < len(mesh_obj.data.vertices)}
    group = mesh_obj.vertex_groups.get(group_name)
    if not group:
        group = mesh_obj.vertex_groups.new(name=group_name)
    if mesh_obj.mode == "EDIT":
        bm = bmesh.from_edit_mesh(mesh_obj.data)
        bm.verts.ensure_lookup_table()
        deform = bm.verts.layers.deform.verify()
        changed = 0
        for vertex_id in valid_ids:
            weights = bm.verts[vertex_id][deform]
            present = weights.get(group.index, 0.0) > 0.5
            if enabled and not present:
                weights[group.index] = 1.0
                changed += 1
            elif not enabled and present:
                del weights[group.index]
                changed += 1
        if changed:
            bmesh.update_edit_mesh(mesh_obj.data, loop_triangles=False, destructive=False)
        return changed
    before = _mesh_vertex_group_ids(mesh_obj, group_name)
    if enabled:
        if valid_ids:
            group.add(sorted(valid_ids), 1.0, "REPLACE")
        return len(valid_ids - before)
    removable = valid_ids & before
    if removable:
        group.remove(sorted(removable))
    return len(removable)


def _set_custom_mask_vertices(mesh_obj, vertex_ids, enabled):
    changed = _set_vertex_group_mask_vertices(mesh_obj, CUSTOM_BIND_MASK_GROUP, vertex_ids, enabled)
    if changed:
        _invalidate_base_region_overlay_cache()
    return changed


def _ensure_custom_mask_groups(context, settings):
    legacy = _legacy_custom_vertex_ids_by_object(settings)
    materialized = 0
    for mesh_obj in _participant_meshes(context, settings):
        if not mesh_obj.vertex_groups.get(CUSTOM_BIND_MASK_GROUP):
            mesh_obj.vertex_groups.new(name=CUSTOM_BIND_MASK_GROUP)
        if not mesh_obj.get(CUSTOM_BIND_MASK_AUTHORITY_KEY):
            materialized += _set_custom_mask_vertices(mesh_obj, legacy.get(mesh_obj.name, set()), True)
            mesh_obj[CUSTOM_BIND_MASK_AUTHORITY_KEY] = True
    return materialized


def _clear_custom_mask_groups(context, settings):
    cleared = 0
    for mesh_obj in _participant_meshes(context, settings):
        group = mesh_obj.vertex_groups.get(CUSTOM_BIND_MASK_GROUP)
        if group:
            cleared += _set_custom_mask_vertices(mesh_obj, range(len(mesh_obj.data.vertices)), False)
            mesh_obj[CUSTOM_BIND_MASK_AUTHORITY_KEY] = True
    return cleared


def _base_region_group_name(region):
    return BASE_REGION_GROUP_PREFIX + region


def _legacy_base_region_vertex_ids_by_object(settings, region):
    result = {}
    for component in _unrigged_components(settings):
        if component.get("base_region") != region:
            continue
        result.setdefault(component.get("object", ""), set()).update(component.get("vertex_indices") or [])
    return {name: indices for name, indices in result.items() if name and indices}


def _base_region_vertex_ids_by_object(context, settings, region):
    if region not in BASE_REGION_KEYS:
        return {}
    result = {}
    for object_name, assignments in _base_region_assignments_by_object(context, settings).items():
        indices = {vertex_id for vertex_id, assigned_region in assignments.items() if assigned_region == region}
        if indices:
            result[object_name] = indices
    return result


def _base_region_assignments_by_object(context, settings):
    scene = context.scene
    signature = (
        scene.as_pointer(),
        _BASE_REGION_OVERLAY_REVISION,
        settings.unrigged_components_json,
    )
    if _BASE_REGION_ASSIGNMENTS_CACHE.get("signature") == signature:
        return _BASE_REGION_ASSIGNMENTS_CACHE["assignments"]
    result = {}
    legacy_by_region = {
        region: _legacy_base_region_vertex_ids_by_object(settings, region)
        for region in BASE_REGION_KEYS
    }
    for mesh_obj in _participant_meshes(context, settings):
        assignments = {}
        group_regions = {
            group.index: region
            for region in BASE_REGION_KEYS
            for group in [mesh_obj.vertex_groups.get(_base_region_group_name(region))]
            if group
        }
        if mesh_obj.mode == "EDIT" and context.object == mesh_obj:
            bm = bmesh.from_edit_mesh(mesh_obj.data)
            bm.verts.ensure_lookup_table()
            deform = bm.verts.layers.deform.active
            if deform:
                for vert in bm.verts:
                    for group_index, weight in vert[deform].items():
                        region = group_regions.get(group_index)
                        if region and weight > 0.5:
                            assignments.setdefault(vert.index, region)
                            break
        elif group_regions:
            for vertex in mesh_obj.data.vertices:
                for item in vertex.groups:
                    region = group_regions.get(item.group)
                    if region and item.weight > 0.5:
                        assignments.setdefault(vertex.index, region)
                        break
        if not mesh_obj.get(BASE_REGION_MASK_AUTHORITY_KEY):
            for region in BASE_REGION_KEYS:
                for vertex_id in legacy_by_region[region].get(mesh_obj.name, set()):
                    assignments.setdefault(vertex_id, region)
        if assignments:
            result[mesh_obj.name] = assignments
    _BASE_REGION_ASSIGNMENTS_CACHE.update(signature=signature, assignments=result)
    return result


def _ensure_base_region_mask_groups(context, settings):
    legacy_by_region = {
        region: _legacy_base_region_vertex_ids_by_object(settings, region)
        for region in BASE_REGION_KEYS
    }
    materialized = 0
    for mesh_obj in _participant_meshes(context, settings):
        if mesh_obj.get(BASE_REGION_MASK_AUTHORITY_KEY):
            continue
        for region in BASE_REGION_KEYS:
            group_name = _base_region_group_name(region)
            if not mesh_obj.vertex_groups.get(group_name):
                mesh_obj.vertex_groups.new(name=group_name)
            materialized += _set_vertex_group_mask_vertices(
                mesh_obj,
                group_name,
                legacy_by_region[region].get(mesh_obj.name, set()),
                True,
            )
        mesh_obj[BASE_REGION_MASK_AUTHORITY_KEY] = True
    return materialized


def _set_base_region_mask_vertices(mesh_obj, vertex_ids, region):
    if not mesh_obj or mesh_obj.type != "MESH" or region not in {*BASE_REGION_KEYS, "AUTO"}:
        return 0
    valid_ids = {int(index) for index in vertex_ids if 0 <= int(index) < len(mesh_obj.data.vertices)}
    groups = {}
    for candidate in BASE_REGION_KEYS:
        group_name = _base_region_group_name(candidate)
        groups[candidate] = mesh_obj.vertex_groups.get(group_name) or mesh_obj.vertex_groups.new(name=group_name)
    changed = 0
    if mesh_obj.mode == "EDIT" and bpy.context.object == mesh_obj:
        bm = bmesh.from_edit_mesh(mesh_obj.data)
        bm.verts.ensure_lookup_table()
        deform = bm.verts.layers.deform.verify()
        target_index = groups[region].index if region in groups else None
        region_indices = {group.index for group in groups.values()}
        for vertex_id in valid_ids:
            weights = bm.verts[vertex_id][deform]
            before = next((candidate for candidate, group in groups.items() if weights.get(group.index, 0.0) > 0.5), "AUTO")
            if before == region:
                continue
            for group_index in region_indices:
                if group_index in weights:
                    del weights[group_index]
            if target_index is not None:
                weights[target_index] = 1.0
            changed += 1
        if changed:
            bmesh.update_edit_mesh(mesh_obj.data, loop_triangles=False, destructive=False)
    else:
        current_by_region = {
            candidate: _mesh_vertex_group_ids(mesh_obj, _base_region_group_name(candidate))
            for candidate in BASE_REGION_KEYS
        }
        changed = sum(
            1
            for vertex_id in valid_ids
            if next((candidate for candidate in BASE_REGION_KEYS if vertex_id in current_by_region[candidate]), "AUTO") != region
        )
        for candidate, group in groups.items():
            removable = valid_ids & current_by_region[candidate]
            if removable:
                group.remove(sorted(removable))
        if region in groups and valid_ids:
            groups[region].add(sorted(valid_ids), 1.0, "REPLACE")
    mesh_obj[BASE_REGION_MASK_AUTHORITY_KEY] = True
    if changed:
        _invalidate_base_region_overlay_cache()
    return changed


def _clear_base_region_mask_groups(context, settings):
    cleared = 0
    for mesh_obj in _participant_meshes(context, settings):
        for region in BASE_REGION_KEYS:
            group_name = _base_region_group_name(region)
            vertex_ids = _mesh_vertex_group_ids(mesh_obj, group_name)
            if vertex_ids:
                cleared += _set_vertex_group_mask_vertices(mesh_obj, group_name, vertex_ids, False)
        if any(mesh_obj.vertex_groups.get(_base_region_group_name(region)) for region in BASE_REGION_KEYS):
            mesh_obj[BASE_REGION_MASK_AUTHORITY_KEY] = True
    if cleared:
        _invalidate_base_region_overlay_cache()
    return cleared


def _sync_component_base_region_cache(context, settings):
    components = _unrigged_components(settings)
    assignments_by_object = _base_region_assignments_by_object(context, settings)
    custom_by_object = _custom_mask_vertex_ids_by_object(context, settings)
    for component in components:
        base_ids = _component_vertex_ids_for_scope(
            context,
            settings,
            component,
            "BASE_SKIN",
            custom_by_object,
        )
        assignments = assignments_by_object.get(component.get("object", ""), {})
        regions = {assignments[vertex_id] for vertex_id in base_ids if vertex_id in assignments}
        if len(regions) == 1 and base_ids and all(vertex_id in assignments for vertex_id in base_ids):
            component["base_region"] = next(iter(regions))
        else:
            component.pop("base_region", None)
    settings.unrigged_components_json = json.dumps(components, ensure_ascii=False, separators=(",", ":"))
    _invalidate_binding_results(settings)
    return components


def _component_vertex_ids_for_scope(context, settings, component, scope, custom_by_object=None):
    object_name = component.get("object", "")
    all_ids = set(component.get("vertex_indices") or [])
    custom_by_object = custom_by_object if custom_by_object is not None else _custom_mask_vertex_ids_by_object(context, settings)
    custom_ids = all_ids & custom_by_object.get(object_name, set())
    if scope == "CUSTOM_BIND":
        return custom_ids
    if scope == "BASE_SKIN" and component.get("binding_scope") in {"BASE_SKIN", "MIXED"}:
        return all_ids - custom_ids
    return set()


def _sync_component_scopes_from_mask(context, settings, finalized):
    components = _unrigged_components(settings)
    custom_by_object = _custom_mask_vertex_ids_by_object(context, settings)
    for component in components:
        all_ids = set(component.get("vertex_indices") or [])
        custom_ids = all_ids & custom_by_object.get(component.get("object", ""), set())
        if finalized:
            component["binding_scope"] = (
                "CUSTOM_BIND" if custom_ids == all_ids and all_ids
                else "MIXED" if custom_ids
                else "BASE_SKIN"
            )
        else:
            component["binding_scope"] = "CUSTOM_BIND" if custom_ids == all_ids and all_ids else ""
    settings.unrigged_components_json = json.dumps(components, ensure_ascii=False, separators=(",", ":"))
    _invalidate_binding_results(settings)
    return components


def _component_scope_counts(settings, context=None):
    context = context or bpy.context
    signature = (
        context.scene.as_pointer(),
        _BASE_REGION_OVERLAY_REVISION,
        settings.unrigged_components_json,
    )
    if _COMPONENT_SCOPE_COUNTS_CACHE.get("signature") == signature:
        return _COMPONENT_SCOPE_COUNTS_CACHE["counts"]
    result = {
        "BASE_SKIN": {"components": 0, "vertices": 0},
        "CUSTOM_BIND": {"components": 0, "vertices": 0},
        "MIXED": {"components": 0, "vertices": 0},
        "PENDING": {"components": 0, "vertices": 0},
    }
    custom_by_object = _custom_mask_vertex_ids_by_object(context, settings)
    for component in _unrigged_components(settings):
        all_ids = set(component.get("vertex_indices") or [])
        custom_count = len(all_ids & custom_by_object.get(component.get("object", ""), set()))
        base_count = len(all_ids) - custom_count
        if custom_count:
            result["CUSTOM_BIND"]["components"] += 1
            result["CUSTOM_BIND"]["vertices"] += custom_count
        if component.get("binding_scope") in {"BASE_SKIN", "MIXED"} and base_count:
            result["BASE_SKIN"]["components"] += 1
            result["BASE_SKIN"]["vertices"] += base_count
        if component.get("binding_scope") == "MIXED":
            result["MIXED"]["components"] += 1
            result["MIXED"]["vertices"] += len(all_ids)
        if not _component_scope_ready(component):
            result["PENDING"]["components"] += 1
            result["PENDING"]["vertices"] += base_count
    _COMPONENT_SCOPE_COUNTS_CACHE.update(signature=signature, counts=result)
    return result


def _scope_vertex_ids_by_object(settings, scope, context=None):
    context = context or bpy.context
    result = {}
    custom_by_object = _custom_mask_vertex_ids_by_object(context, settings)
    for component in _unrigged_components(settings):
        indices = _component_vertex_ids_for_scope(context, settings, component, scope, custom_by_object)
        if indices:
            result.setdefault(component.get("object", ""), set()).update(indices)
    return {name: indices for name, indices in result.items() if name and indices}


def _set_mesh_elements_hidden(mesh_obj, vertex_indices, hidden):
    vertex_indices = set(vertex_indices)
    if not vertex_indices:
        return 0
    for vertex in mesh_obj.data.vertices:
        if vertex.index in vertex_indices:
            vertex.hide = bool(hidden)
            if hidden:
                vertex.select = False
    for edge in mesh_obj.data.edges:
        if all(index in vertex_indices for index in edge.vertices):
            edge.hide = bool(hidden)
            if hidden:
                edge.select = False
    for polygon in mesh_obj.data.polygons:
        if all(index in vertex_indices for index in polygon.vertices):
            polygon.hide = bool(hidden)
            if hidden:
                polygon.select = False
    mesh_obj.data.update()
    return len(vertex_indices)


def _set_component_vertices_hidden(context, component, hidden):
    obj = context.scene.objects.get(component.get("object", ""))
    indices = component.get("vertex_indices") or []
    if not obj or obj.type != "MESH":
        return 0
    if getattr(context, "object", None) and context.object.mode != "OBJECT":
        bpy.ops.object.mode_set(mode="OBJECT")
    valid_indices = [index for index in indices if 0 <= index < len(obj.data.vertices)]
    return _set_mesh_elements_hidden(obj, valid_indices, hidden)


def _enter_component_edit_mode_without_reveal(context, component):
    obj = context.scene.objects.get(component.get("object", ""))
    if not obj or obj.type != "MESH":
        return False
    if getattr(context, "object", None) and context.object.mode != "OBJECT":
        bpy.ops.object.mode_set(mode="OBJECT")
    for vertex in obj.data.vertices:
        vertex.select = False
    for edge in obj.data.edges:
        edge.select = False
    for polygon in obj.data.polygons:
        polygon.select = False
    obj.data.update()
    _select_only(context, obj)
    bpy.ops.object.mode_set(mode="EDIT")
    context.tool_settings.mesh_select_mode = (True, False, False)
    _tag_view3d_redraw()
    return True


def _set_marked_custom_hidden(context, settings, hidden):
    if getattr(context, "object", None) and context.object.mode != "OBJECT":
        bpy.ops.object.mode_set(mode="OBJECT")
    custom_by_object = _scope_vertex_ids_by_object(settings, "CUSTOM_BIND")
    changed = 0
    for object_name, indices in custom_by_object.items():
        obj = context.scene.objects.get(object_name)
        if not obj or obj.type != "MESH":
            continue
        valid_indices = [index for index in indices if 0 <= index < len(obj.data.vertices)]
        changed += _set_mesh_elements_hidden(obj, valid_indices, hidden)
    settings.unrigged_custom_selection_hidden = bool(hidden)
    _tag_view3d_redraw()
    return changed


def _toggle_picker_custom_visibility(context, settings):
    hidden = not settings.unrigged_custom_selection_hidden
    count = _set_marked_custom_hidden(context, settings, hidden)
    components = _unrigged_components(settings)
    if components:
        target_index = min(settings.unrigged_component_index, len(components) - 1)
        if hidden:
            pending_index = _next_unready_component_index(settings, components)
            if pending_index is not None:
                target_index = pending_index
        settings.unrigged_component_index = target_index
        if not _focus_unrigged_component(context, components[target_index]):
            _enter_component_edit_mode_without_reveal(context, components[target_index])
    return hidden, count


def _participant_meshes(context, settings):
    names = sorted({item.get("object", "") for item in _unrigged_components(settings) if item.get("object")})
    return [
        obj
        for name in names
        if (obj := context.scene.objects.get(name)) is not None and obj.type == "MESH"
    ]


def _invalidate_binding_results(settings, invalidate_base=True):
    if invalidate_base:
        settings.wgame_base_skin_complete = False
        settings.wgame_base_skin_report = ""
        settings.wgame_manual_binding_ui_tab = "BASE"
    settings.wgame_custom_binding_complete = False
    settings.wgame_custom_binding_report = ""
    if hasattr(settings, "wgame_custom_auto_weight_report"):
        settings.wgame_custom_auto_weight_report = ""
    settings.wgame_component_skin_complete = False
    settings.wgame_component_skin_report = ""
    settings.wgame_preview_active = False
    settings.wgame_preview_preset = ""


def _bone_snapshot_entry(bone):
    return {
        "parent": bone.parent.name if bone.parent else "",
        "head": [round(float(value), 7) for value in bone.head_local],
        "tail": [round(float(value), 7) for value in bone.tail_local],
        "matrix": [round(float(value), 7) for row in bone.matrix_local for value in row],
        "use_deform": bool(bone.use_deform),
    }


def _is_wgame_base_bone_name(name):
    body_names = {
        "root.x", "pelvis.x", "spine_01.x", "spine_02.x", "upper_chest.x", "neck.x", "head.x",
        "shoulder.l", "upper_arm.l", "forearm.l", "hand.l",
        "shoulder.r", "upper_arm.r", "forearm.r", "hand.r",
        "thigh.l", "lower_leg.l", "foot.l", "toes.l",
        "thigh.r", "lower_leg.r", "foot.r", "toes.r",
    }
    return name in body_names or any(
        name.startswith(prefix + "_")
        for prefix in ("thumb", "index", "middle", "ring", "pinky")
    )


def _capture_base_skeleton_snapshot(rig_obj):
    snapshot = {
        bone.name: _bone_snapshot_entry(bone)
        for bone in sorted(rig_obj.data.bones, key=lambda item: item.name)
        if _is_wgame_base_bone_name(bone.name)
    }
    rig_obj[BASE_SKELETON_SNAPSHOT_KEY] = json.dumps(snapshot, sort_keys=True, separators=(",", ":"))
    return snapshot


def _base_skeleton_snapshot(rig_obj):
    if not rig_obj:
        return {}
    raw = rig_obj.get(BASE_SKELETON_SNAPSHOT_KEY, "")
    try:
        value = json.loads(raw) if raw else {}
        return value if isinstance(value, dict) else {}
    except (TypeError, ValueError):
        return {}


def _base_skeleton_snapshot_status(rig_obj):
    snapshot = _base_skeleton_snapshot(rig_obj)
    if not snapshot:
        return False, "基础骨架尚未记录验收快照"
    bpy.context.view_layer.update()
    current_names = {bone.name for bone in rig_obj.data.bones}
    missing = sorted(set(snapshot) - current_names)
    if missing:
        return False, "基础骨缺失：" + ", ".join(missing[:4])
    changed = [
        name
        for name, expected in snapshot.items()
        if _bone_snapshot_entry(rig_obj.data.bones[name]) != expected
    ]
    if changed:
        return False, "基础骨结构或 Rest Pose 已变化：" + ", ".join(changed[:4])
    return True, "基础骨架快照一致"


def _custom_bone_structure_entries(rig_obj):
    if not rig_obj or rig_obj.type != "ARMATURE":
        return []
    base_names = set(_base_skeleton_snapshot(rig_obj))
    return [
        {
            "name": bone.name,
            "parent": bone.parent.name if bone.parent else "",
            "head": [round(float(value), 7) for value in bone.head_local],
            "tail": [round(float(value), 7) for value in bone.tail_local],
            "use_deform": bool(bone.use_deform),
        }
        for bone in sorted(rig_obj.data.bones, key=lambda item: item.name)
        if bone.use_deform and bone.name not in base_names
    ]


def _custom_bone_structure_fingerprint(rig_obj):
    encoded = json.dumps(
        _custom_bone_structure_entries(rig_obj),
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _custom_weight_chain_payload(rig_obj):
    if not rig_obj:
        return {}
    raw = rig_obj.get(CUSTOM_WEIGHT_CHAINS_KEY, "")
    if isinstance(raw, dict):
        value = dict(raw)
    else:
        try:
            value = json.loads(raw) if raw else {}
        except (TypeError, ValueError):
            value = {}
    if not isinstance(value, dict):
        return {}
    chains = value.get("chains", [])
    value["chains"] = chains if isinstance(chains, list) else []
    return value


def _save_custom_weight_chain_payload(rig_obj, payload):
    if not rig_obj:
        return
    rig_obj[CUSTOM_WEIGHT_CHAINS_KEY] = json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(",", ":"),
    )


def _custom_binding_topology_signature(mesh_obj):
    """Bind stored indices to connectivity, not a transient island number."""
    data = mesh_obj.data
    encoded = json.dumps(
        [len(data.vertices), [list(edge.vertices) for edge in data.edges],
         [list(face.vertices) for face in data.polygons]],
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def _custom_chain_region_summary(context, chain):
    records = chain.get("regions", [])
    count = sum(len(record.get("vertex_ids", [])) for record in records)
    roots = sum(len(record.get("roots", [])) for record in records)
    tips = sum(len(record.get("tips", [])) for record in records)
    return f"指定区域：{len(records)} 个 Mesh / {count} 顶点 · 根 {roots} / 梢 {tips}"


def _custom_region_selection(context, settings):
    mesh_obj = context.object
    if not mesh_obj or mesh_obj.type != "MESH" or mesh_obj.mode != "EDIT":
        raise ValueError("请在目标 Mesh 的编辑模式中选择顶点；不会自动扩展为整岛")
    if len(getattr(context, "objects_in_mode", [mesh_obj])) > 1:
        raise ValueError("区域指定一次处理一个 Mesh；请退出多对象编辑模式")
    bm = bmesh.from_edit_mesh(mesh_obj.data)
    bm.verts.ensure_lookup_table()
    bm.verts.index_update()
    selected = {vert.index for vert in bm.verts if vert.select and not vert.hide}
    custom_ids = _scope_vertex_ids_by_object(settings, "CUSTOM_BIND", context).get(mesh_obj.name, set())
    if not selected:
        raise ValueError("请先选择需要指定的 Custom 顶点")
    base_count = len(selected - custom_ids)
    selected = selected & custom_ids
    if not selected:
        raise ValueError("所选顶点全部属于 Base 或未标记范围；请选择属于 Custom 范围的顶点")
    if base_count > 0:
        for vert in bm.verts:
            if vert.select and vert.index not in custom_ids:
                vert.select_set(False)
        bm.select_flush_mode()
        bmesh.update_edit_mesh(mesh_obj.data, loop_triangles=False, destructive=False)
    mesh_obj.update_from_editmode()
    return mesh_obj, selected, base_count


def _custom_chain_region_action(context, settings, rig_obj, chain, action):
    payload = _custom_weight_chain_payload(rig_obj)
    chain = next((item for item in payload.get("chains", []) if item.get("id") == chain.get("id")), None)
    if not chain:
        raise ValueError("当前骨链不存在，请刷新骨链列表")
    if action == "SELECT":
        records = [item for item in chain.get("regions", []) if item.get("vertex_ids")]
        if not records:
            raise ValueError("当前链尚未指定区域")
        meshes = []
        for record in records:
            mesh = context.scene.objects.get(record.get("object", ""))
            if not mesh or mesh.type != "MESH":
                raise ValueError("指定区域的 Mesh 已删除或改名，请重新指定")
            if mesh.mode == "EDIT":
                mesh.update_from_editmode()
            if record.get("topology") != _custom_binding_topology_signature(mesh):
                raise ValueError("指定区域的拓扑已变化；请移除旧记录并重新指定")
            meshes.append((mesh, set(record["vertex_ids"])))
        if context.object and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        bpy.ops.object.select_all(action="DESELECT")
        for mesh, ids in meshes:
            mesh.hide_set(False)
            mesh.select_set(True)
            for vert in mesh.data.vertices:
                vert.select = vert.index in ids
                if vert.index in ids:
                    vert.hide = False
        context.view_layer.objects.active = meshes[0][0]
        bpy.ops.object.mode_set(mode="EDIT")
        bpy.ops.mesh.select_mode(type="VERT")
        # Mesh selection flushing can select adjacent edges/faces; reset exact vertices.
        for mesh, ids in meshes:
            bm = bmesh.from_edit_mesh(mesh.data)
            bm.verts.ensure_lookup_table()
            for face in bm.faces:
                face.select_set(False)
            for edge in bm.edges:
                edge.select_set(False)
            for vert in bm.verts:
                vert.select_set(vert.index in ids)
            bm.select_flush_mode()
            bmesh.update_edit_mesh(mesh.data, loop_triangles=False, destructive=False)
        return f"已选回当前链 {sum(len(ids) for _, ids in meshes)} 个指定顶点"
    if chain.get("locked"):
        raise ValueError("当前链已锁定；修改绑定区域前请解除锁定")
    if action == "CLEAR_REGIONS":
        chain["regions"] = []
        _save_custom_weight_chain_payload(rig_obj, payload)
        return "已清除当前链的区域记录；现有权重保留"
    if not _component_scan_is_current(context, settings):
        raise ValueError("模型拓扑已变化；请先重新扫描并确认 Base/Custom 范围")
    mesh, selected, base_count = _custom_region_selection(context, settings)
    if action in {"ASSIGN", "SHARE"}:
        rigid_ids = _mesh_vertex_group_ids(mesh, RIGID_BIND_MASK_GROUP)
        for item in _rigid_bind_payload(rig_obj).get("attachments", []):
            if item.get("object") == mesh.name:
                rigid_ids.update(item.get("vertex_indices", []))
        if selected & rigid_ids:
            raise ValueError("所选顶点属于刚性附件；请先解除其刚性指定")
    topology = _custom_binding_topology_signature(mesh)
    records = chain.setdefault("regions", [])
    record = next((item for item in records if item.get("object") == mesh.name), None)
    if record and record.get("topology") != topology:
        raise ValueError("本链保存的区域拓扑已过期；请清除本链区域记录后重新指定")
    ignored_suffix = f"（已自动忽略 {base_count} 个 Base 顶点）" if base_count > 0 else ""
    if action in {"ASSIGN", "SHARE"}:
        owners = {index: [] for index in selected}
        for other in payload.get("chains", []):
            if other.get("id") == chain.get("id"):
                continue
            for other_record in other.get("regions", []):
                if other_record.get("object") != mesh.name:
                    continue
                if other_record.get("topology") != topology:
                    raise ValueError("该 Mesh 存在过期区域记录；请先清除对应链的旧记录")
                for index in selected.intersection(other_record.get("vertex_ids", [])):
                    owners[index].append(other)
        if action == "ASSIGN" and any(owners.values()):
            raise ValueError("部分顶点已属于其他链；请先从原链移除，或明确指定为共享区")
        if action == "SHARE":
            if any(len(items) != 1 for items in owners.values()):
                raise ValueError("共享区的每个顶点须已属于另一条链，且最多允许两条链共享")
            if any(item.get("locked") or not item.get("enabled", True) for items in owners.values() for item in items):
                raise ValueError("共享区的另一条链已锁定或禁用；请先调整其状态")
        if record is None:
            record = {"object": mesh.name, "topology": topology, "vertex_ids": [], "roots": [], "tips": []}
            records.append(record)
        record["vertex_ids"] = sorted(set(record["vertex_ids"]) | selected)
        # Region assignment records ownership only. Weight cleanup belongs to the
        # prepared generation plan, where chain/group locks and budgets are checked.
        message = (f"已将 {len(selected)} 顶点指定给当前链{ignored_suffix}；现有权重保留，生成时更新" if action == "ASSIGN" else
                   f"已共享 {len(selected)} 顶点{ignored_suffix}；共享带两侧需各有独占区域，首次请生成全部")
    elif action in {"ROOT", "TIP"}:
        if not record or not selected.issubset(set(record.get("vertex_ids", []))):
            raise ValueError("根梢标记必须位于当前链已指定的区域内")
        key, opposite = ("roots", "tips") if action == "ROOT" else ("tips", "roots")
        if selected.intersection(record.get(opposite, [])):
            raise ValueError("根部和梢部标记不能重叠")
        record[key] = sorted(selected)
        message = f"已设置该 Mesh 的{'根部' if action == 'ROOT' else '梢部'}标记：{len(selected)} 顶点{ignored_suffix}"
    elif action == "REMOVE":
        if not record:
            raise ValueError("当前 Mesh 没有本链的区域记录")
        record["vertex_ids"] = sorted(set(record.get("vertex_ids", [])) - selected)
        for key in ("roots", "tips"):
            record[key] = sorted(set(record.get(key, [])) - selected)
        if not record["vertex_ids"]:
            records.remove(record)
        message = f"已从本链区域移除所选顶点{ignored_suffix}；现有权重保留"
    elif action == "CLEAR_ANCHORS":
        if not record:
            raise ValueError("当前 Mesh 没有本链的区域记录")
        record["roots"], record["tips"] = [], []
        message = "已清除当前 Mesh 的根梢标记"
    else:
        raise ValueError("未知区域操作")
    _save_custom_weight_chain_payload(rig_obj, payload)
    return message


def _custom_explicit_region_index(context, settings, chains):
    """Invalid records block their whole object; they must never become auto candidates."""
    custom_by_object = _scope_vertex_ids_by_object(settings, "CUSTOM_BIND", context)
    index, records, blocked, errors, signatures = {}, {}, set(), [], {}
    for chain in chains:
        for record in chain.get("regions", []):
            name = record.get("object", "")
            mesh = context.scene.objects.get(name)
            reason = ""
            if not mesh or mesh.type != "MESH":
                reason = "指定区域的 Mesh 已删除或改名"
            else:
                if name not in signatures:
                    signatures[name] = _custom_binding_topology_signature(mesh)
                ids = set(record.get("vertex_ids", []))
                if record.get("topology") != signatures[name]:
                    reason = "指定区域的拓扑已过期，请清除旧记录后重新指定"
                elif not ids.issubset(custom_by_object.get(name, set())):
                    reason = "指定区域不再完全属于 Custom 范围，请重新指定"
                elif (name, chain.get("id")) in records:
                    reason = "同一链存在重复 Mesh 区域记录"
            if reason:
                blocked.add(name)
                errors.append({"object": name, "chain": chain.get("root_bone", ""), "reason": reason})
                continue
            records[(name, chain.get("id"))] = record
            for vertex_id in ids:
                index.setdefault((name, vertex_id), []).append(chain)
    return index, records, blocked, errors


def _custom_shared_region_shares(island, points, owners):
    """Surface graph distance between explicitly shared bands and their exclusive sides."""
    adjacency = island["adjacency"]
    remaining = {v for v in island["vertex_ids"] if len(owners.get(v, [])) > 1}
    shares, failures = {}, {}
    while remaining:
        seed = min(remaining)
        pair = tuple(sorted(chain.get("id", "") for chain in owners[seed]))
        region, frontier = {seed}, [seed]
        remaining.remove(seed)
        while frontier:
            current = frontier.pop()
            for neighbor in adjacency[current]:
                if neighbor in remaining and tuple(sorted(c.get("id", "") for c in owners[neighbor])) == pair:
                    remaining.remove(neighbor)
                    region.add(neighbor)
                    frontier.append(neighbor)
        if len(pair) != 2:
            failures.update({v: "共享区最多允许两条骨链" for v in region})
            continue
        distances = []
        for chain_id in pair:
            distance, queue = {}, []
            for v in sorted(region):
                for neighbor in adjacency[v]:
                    adjacent_owners = owners.get(neighbor, [])
                    if neighbor in points and len(adjacent_owners) == 1 and adjacent_owners[0].get("id") == chain_id:
                        length = max((points[v] - points[neighbor]).length, 1e-9)
                        if length < distance.get(v, float("inf")):
                            distance[v] = length
                            heapq.heappush(queue, (length, v))
            while queue:
                length, v = heapq.heappop(queue)
                if length > distance[v]:
                    continue
                for neighbor in adjacency[v]:
                    if neighbor not in region:
                        continue
                    candidate = length + max((points[v] - points[neighbor]).length, 1e-9)
                    if candidate < distance.get(neighbor, float("inf")):
                        distance[neighbor] = candidate
                        heapq.heappush(queue, (candidate, neighbor))
            distances.append(distance)
        if any(len(distance) != len(region) for distance in distances):
            failures.update({v: "共享带两侧须分别连接两条链的独占区域" for v in region})
            continue
        for v in region:
            left, right = distances[0][v], distances[1][v]
            progress = left / (left + right)
            smooth = progress * progress * (3.0 - 2.0 * progress)
            shares[v] = {pair[0]: 1.0 - smooth, pair[1]: smooth}
    return shares, failures


def _rigid_bind_payload(rig_obj):
    if not rig_obj:
        return {"version": 1, "attachments": []}
    raw = rig_obj.get(RIGID_BIND_ATTACHMENTS_KEY, "")
    try:
        payload = dict(raw) if isinstance(raw, dict) else json.loads(raw) if raw else {}
    except (TypeError, ValueError):
        payload = {}
    if not isinstance(payload, dict):
        payload = {}
    attachments = payload.get("attachments", [])
    payload["version"] = 1
    payload["attachments"] = [item for item in attachments if isinstance(item, dict)] if isinstance(attachments, list) else []
    return payload


def _save_rigid_bind_payload(rig_obj, payload):
    if rig_obj:
        rig_obj[RIGID_BIND_ATTACHMENTS_KEY] = json.dumps(
            payload,
            ensure_ascii=False,
            sort_keys=True,
            separators=(",", ":"),
        )


def _rigid_bind_island_id(object_name, vertex_ids):
    encoded = (object_name + ":" + ",".join(str(index) for index in sorted(vertex_ids))).encode("utf-8")
    return hashlib.sha1(encoded).hexdigest()[:16]


def _rigid_attachment_record_for_island(rig_obj, island):
    island_id = _rigid_bind_island_id(island["object"], island["vertex_ids"])
    return next(
        (
            item
            for item in _rigid_bind_payload(rig_obj).get("attachments", [])
            if item.get("id") == island_id and item.get("object") == island["object"]
        ),
        None,
    )


def _selected_custom_subisland(context, settings):
    active = getattr(context, "object", None)
    mesh_obj = active if active and active.type == "MESH" else None
    if not mesh_obj and getattr(settings, "wgame_custom_mesh", ""):
        candidate = context.scene.objects.get(settings.wgame_custom_mesh)
        mesh_obj = candidate if candidate and candidate.type == "MESH" else None
    selected_ids = set()
    if mesh_obj:
        if mesh_obj.mode == "EDIT":
            selected_ids = {vertex.index for vertex in bmesh.from_edit_mesh(mesh_obj.data).verts if vertex.select}
        else:
            selected_ids = {vertex.index for vertex in mesh_obj.data.vertices if vertex.select}
    islands = _custom_weight_subislands(context, settings)
    matching = [
        island
        for island in islands
        if (not mesh_obj or island["object"] == mesh_obj.name)
        and selected_ids.intersection(island["vertex_set"])
    ]
    if len(matching) == 1:
        return matching[0], ""
    if len(matching) > 1:
        return None, "当前选择跨越多个 Custom 孤岛；请只保留宝石所在孤岛的一个或多个顶点"
    components = _unrigged_components(settings)
    if components:
        index = min(max(int(settings.unrigged_component_index), 0), len(components) - 1)
        component = components[index]
        matching = [
            island
            for island in islands
            if island.get("component_id") == component.get("id")
            and island["object"] == component.get("object")
        ]
        if len(matching) == 1:
            return matching[0], ""
    return None, "请在 Edit Mode 选中刚性附件孤岛中的任意顶点，或先把它设为当前组件"


def _rigid_attachment_auto_target(island, context, settings, rig_obj, chain_payload):
    mesh_obj = island["mesh"]
    transform = rig_obj.matrix_world.inverted() @ mesh_obj.matrix_world
    island_set = island["vertex_set"]
    custom_ids = _scope_vertex_ids_by_object(settings, "CUSTOM_BIND", context).get(mesh_obj.name, set())
    surface_ids = sorted(
        vertex_id
        for vertex_id in custom_ids
        if vertex_id not in island_set and 0 <= vertex_id < len(mesh_obj.data.vertices)
    )
    anchor_point = None
    surface_vertex_id = None
    attachment_distance = None
    if surface_ids:
        tree = KDTree(len(surface_ids))
        for slot, vertex_id in enumerate(surface_ids):
            tree.insert(transform @ mesh_obj.data.vertices[vertex_id].co, slot)
        tree.balance()
        best = None
        for vertex_id in island["vertex_ids"]:
            point = transform @ mesh_obj.data.vertices[vertex_id].co
            _co, slot, distance = tree.find(point)
            candidate = (float(distance), vertex_id, surface_ids[slot], point)
            if best is None or candidate[:3] < best[:3]:
                best = candidate
        if best:
            attachment_distance, _anchor_id, surface_vertex_id, anchor_point = best
    if anchor_point is None:
        anchor_point = sum(
            (transform @ mesh_obj.data.vertices[vertex_id].co for vertex_id in island["vertex_ids"]),
            Vector(),
        ) / max(len(island["vertex_ids"]), 1)

    base_names = set(_base_skeleton_snapshot(rig_obj))
    if surface_vertex_id is not None:
        existing = _normalized_existing_deform_weights(mesh_obj, rig_obj, surface_vertex_id)
        existing_custom = {
            name: weight
            for name, weight in existing.items()
            if name not in base_names and rig_obj.data.bones.get(name) and rig_obj.data.bones[name].use_deform
        }
        if existing_custom:
            target = min(existing_custom, key=lambda name: (-existing_custom[name], name))
            return target, attachment_distance, "挂接点现有主导权重"

    candidates = []
    for chain in chain_payload.get("chains", []):
        if not chain.get("enabled", True):
            continue
        for name in chain.get("bones", []):
            bone = rig_obj.data.bones.get(name)
            if bone and bone.use_deform:
                candidates.append((_rig_bone_segment_distance(anchor_point, bone), name))
    if not candidates:
        return "", attachment_distance, "没有启用的自定义 Deform 骨"
    distance, target = min(candidates, key=lambda item: (item[0], item[1]))
    return target, attachment_distance if attachment_distance is not None else distance, "最近挂接点骨骼"


def _store_rigid_attachment(context, settings, rig_obj, island, target_bone, target_source, distance=None):
    payload = _rigid_bind_payload(rig_obj)
    island_id = _rigid_bind_island_id(island["object"], island["vertex_ids"])
    payload["attachments"] = [item for item in payload["attachments"] if item.get("id") != island_id]
    payload["attachments"].append(
        {
            "id": island_id,
            "object": island["object"],
            "component_id": island.get("component_id", ""),
            "vertex_indices": list(island["vertex_ids"]),
            "target_bone": target_bone,
            "target_source": target_source,
            "anchor_distance": None if distance is None else float(distance),
        }
    )
    payload["attachments"].sort(key=lambda item: (item.get("object", ""), item.get("id", "")))
    _save_rigid_bind_payload(rig_obj, payload)
    _set_vertex_group_mask_vertices(island["mesh"], RIGID_BIND_MASK_GROUP, island["vertex_ids"], True)
    settings.wgame_custom_auto_weight_report = ""
    settings.wgame_custom_binding_complete = False
    settings.wgame_component_skin_complete = False
    return payload


def _character_height_in_rig_space(context, settings, rig_obj):
    if not rig_obj:
        return 1.0
    rig_inverse = rig_obj.matrix_world.inverted()
    z_values = []
    spans = []
    for mesh_obj in _participant_meshes(context, settings):
        transform = rig_inverse @ mesh_obj.matrix_world
        points = [transform @ Vector(corner) for corner in mesh_obj.bound_box]
        if not points:
            continue
        z_values.extend(point.z for point in points)
        spans.extend(
            max(point[axis] for point in points) - min(point[axis] for point in points)
            for axis in range(3)
        )
    height = max(z_values) - min(z_values) if z_values else 0.0
    return max(height if height > 1e-4 else max(spans, default=0.0), 1e-4)


def _default_custom_chain_semantic_key(base_parent):
    value = (base_parent or "custom").lower()
    value = re.sub(r"\.[lrx]$", "", value)
    value = re.sub(r"[^a-z0-9]+", "_", value).strip("_")
    return value or "custom"


def _sanitize_custom_chain_semantic_key(value, base_parent=""):
    normalized = re.sub(r"[^a-z0-9]+", "_", (value or "").strip().lower()).strip("_")
    return normalized or _default_custom_chain_semantic_key(base_parent)


def _custom_chain_side(base_parent):
    lowered = (base_parent or "").lower()
    if lowered.endswith(".l"):
        return "l"
    if lowered.endswith(".r"):
        return "r"
    return "x"


def _custom_chain_uid(rig_obj, root_bone, base_parent):
    payload = {
        "rig": rig_obj.name if rig_obj else "",
        "root": root_bone.name,
        "base_parent": base_parent,
        "head": [round(float(value), 6) for value in root_bone.head_local],
        "tail": [round(float(value), 6) for value in root_bone.tail_local],
    }
    return hashlib.sha1(json.dumps(payload, sort_keys=True, separators=(",", ":")).encode("utf-8")).hexdigest()[:16]


def _custom_chain_base_parent(root_bone, base_names):
    parent = root_bone.parent
    while parent:
        if parent.name in base_names:
            return parent.name
        parent = parent.parent
    return ""


def _discover_custom_weight_chains(context, settings, rig_obj):
    if not rig_obj or rig_obj.type != "ARMATURE":
        return {}
    old_payload = _custom_weight_chain_payload(rig_obj)
    # Keep unresolved records available for recovery on later refreshes.  A root
    # rename must never silently turn its explicit region into automatic scope.
    prior_chains = []
    seen_records = set()
    for chain in old_payload.get("chains", []) + old_payload.get("orphaned_regions", []):
        if not isinstance(chain, dict):
            continue
        record_key = json.dumps({key: value for key, value in chain.items() if key != "orphan_reason"}, sort_keys=True)
        if record_key not in seen_records:
            prior_chains.append(chain)
            seen_records.add(record_key)
    old_by_root, old_by_uid = {}, {}
    for index, chain in enumerate(prior_chains):
        old_by_root.setdefault(chain.get("root_bone", ""), []).append(index)
        uid = chain.get("uid") or str(chain.get("id", "")).removeprefix("custom:")
        if uid:
            old_by_uid.setdefault(uid, []).append(index)
    base_names = set(_base_skeleton_snapshot(rig_obj))
    custom_names = {
        bone.name
        for bone in rig_obj.data.bones
        if bone.use_deform
        and bone.name not in base_names
        and not bone.get("wgame_rigid_attachment_bone")
    }
    roots = sorted(
        (
            bone
            for bone in rig_obj.data.bones
            if bone.name in custom_names and (not bone.parent or bone.parent.name not in custom_names)
        ),
        key=lambda item: item.name,
    )
    root_uid_counts = {}
    for root in roots:
        stored_uid = str(root.get("wgame_custom_chain_uid", ""))
        if stored_uid:
            root_uid_counts[stored_uid] = root_uid_counts.get(stored_uid, 0) + 1
    current_root_by_bone = {}
    for name in custom_names:
        root = rig_obj.data.bones[name]
        while root.parent and root.parent.name in custom_names:
            root = root.parent
        current_root_by_bone[name] = root.name
    old_surviving_roots = [
        {current_root_by_bone[name] for name in old.get("bones", []) if name in current_root_by_bone}
        for old in prior_chains
    ]
    matched_old = set()
    structure_fingerprint = _custom_bone_structure_fingerprint(rig_obj)
    character_height = _character_height_in_rig_space(context, settings, rig_obj)
    breast_detection = _detect_breast_bone_chains(rig_obj)
    detected_breast_roots = {
        names[0]: side.upper()
        for side, names in (("L", breast_detection.get("left", [])), ("R", breast_detection.get("right", [])))
        if names
    }
    chains = []
    for root in roots:
        ordered = []
        pending = [root]
        while pending:
            bone = pending.pop(0)
            if bone.name in ordered:
                continue
            ordered.append(bone.name)
            pending.extend(
                sorted(
                    (child for child in bone.children if child.name in custom_names),
                    key=lambda item: item.name,
                )
            )
        lengths = [max(float(rig_obj.data.bones[name].length), 1e-5) for name in ordered]
        default_radius = max(
            character_height * 0.025,
            min(character_height * 0.12, statistics.median(lengths) * 0.75),
        )
        stored_uid = str(root.get("wgame_custom_chain_uid", ""))
        candidates = old_by_uid.get(stored_uid, []) if root_uid_counts.get(stored_uid) == 1 else []
        if not candidates:
            candidates = old_by_root.get(root.name, [])
        if not candidates:
            # Legacy files lack a bone UID.  Surviving child names provide a
            # safe fallback only when one old chain maps to exactly this root.
            candidates = [index for index, owners in enumerate(old_surviving_roots) if owners == {root.name}]
        candidates = [index for index in candidates if index not in matched_old]
        old_index = candidates[0] if len(candidates) == 1 else None
        old = prior_chains[old_index] if old_index is not None else {}
        if old_index is not None:
            matched_old.add(old_index)
        semantic_type = old.get("semantic_type", "")
        if root.name in detected_breast_roots:
            semantic_type = "BREAST_" + detected_breast_roots[root.name]
        elif root.name.startswith("breast_01.") and root.name.rsplit(".", 1)[-1] in {"l", "r"}:
            semantic_type = "BREAST_" + root.name.rsplit(".", 1)[-1].upper()
        semantic_key = "breast" if semantic_type.startswith("BREAST_") else _sanitize_custom_chain_semantic_key(
            old.get("semantic_key", ""),
            _custom_chain_base_parent(root, base_names),
        )
        uid = old.get("uid") or str(old.get("id", "")).removeprefix("custom:") or (
            stored_uid if stored_uid and root_uid_counts.get(stored_uid) == 1 else ""
        ) or _custom_chain_uid(
            rig_obj,
            root,
            _custom_chain_base_parent(root, base_names),
        )
        root["wgame_custom_chain_uid"] = uid
        chains.append(
            {
                "id": "custom:" + uid,
                "uid": uid,
                "root_bone": root.name,
                "bones": ordered,
                "base_parent": _custom_chain_base_parent(root, base_names),
                "semantic_type": semantic_type or "GENERIC",
                "semantic_key": semantic_key,
                "side": semantic_type[-1:].lower() if semantic_type.startswith("BREAST_") else _custom_chain_side(_custom_chain_base_parent(root, base_names)),
                "target_bone_count": min(max(int(old.get("target_bone_count", len(ordered))), 1), 12),
                "enabled": bool(old.get("enabled", True)),
                "locked": bool(old.get("locked", False)),
                "regions": old.get("regions", []),
                "coordinate_mode": old.get("coordinate_mode", "PROJECTION"),
                "joint_blend": min(max(float(old.get("joint_blend", 0.35)), 0.01), 0.5),
                "influence_radius": max(float(old.get("influence_radius", default_radius)), 1e-5),
                "blend_steps_override": min(max(int(old.get("blend_steps_override", 0)), 0), 12),
                "structure_fingerprint": structure_fingerprint,
            }
        )
    payload = {
        "version": 1,
        "structure_fingerprint": structure_fingerprint,
        "global_blend_steps": min(
            max(
                int(
                    old_payload.get(
                        "global_blend_steps",
                        getattr(settings, "wgame_custom_chain_global_blend_steps", 4),
                    )
                ),
                1,
            ),
            12,
        ),
        "boundary_custom_share": max(
            0.5,
            min(
                float(
                    old_payload.get(
                        "boundary_custom_share",
                        getattr(settings, "wgame_custom_chain_boundary_custom_share", 0.65),
                    )
                ),
                0.95,
            ),
        ),
        "character_height": character_height,
        "chains": chains,
        "orphaned_regions": [
            {**old, "orphan_reason": "原骨链已删除、分拆或身份不明确；请恢复原骨链后刷新，区域记录与权重仍保留"}
            for index, old in enumerate(prior_chains)
            if index not in matched_old and (old.get("regions") or old.get("locked"))
        ],
    }
    _save_custom_weight_chain_payload(rig_obj, payload)
    settings.wgame_custom_chain_index = min(
        max(int(getattr(settings, "wgame_custom_chain_index", 0)), 0),
        max(len(chains) - 1, 0),
    )
    settings.wgame_custom_auto_weight_report = ""
    settings.wgame_custom_binding_complete = False
    settings.wgame_component_skin_complete = False
    _load_current_custom_chain_settings(settings, context, payload)
    return payload


def _custom_weight_chain_status(rig_obj):
    payload = _custom_weight_chain_payload(rig_obj)
    fingerprint = _custom_bone_structure_fingerprint(rig_obj)
    scanned = bool(payload) and payload.get("version") == 1
    stale = scanned and payload.get("structure_fingerprint") != fingerprint
    chains = payload.get("chains", []) if scanned else []
    return {
        "payload": payload,
        "fingerprint": fingerprint,
        "scanned": scanned,
        "stale": stale,
        "chains": chains,
        "enabled": sum(1 for chain in chains if chain.get("enabled", True)),
    }


def _load_current_custom_chain_settings(settings, context, payload=None):
    global _CUSTOM_CHAIN_SETTINGS_SYNCING
    rig_obj = _wgame_rig_object(context) if context else None
    payload = payload if payload is not None else _custom_weight_chain_payload(rig_obj)
    chains = payload.get("chains", []) if payload else []
    _CUSTOM_CHAIN_SETTINGS_SYNCING = True
    try:
        settings.wgame_custom_chain_global_blend_steps = min(
            max(int(payload.get("global_blend_steps", 4)) if payload else 4, 1),
            12,
        )
        settings.wgame_custom_chain_boundary_custom_share = max(
            0.5,
            min(float(payload.get("boundary_custom_share", 0.65)) if payload else 0.65, 0.95),
        )
        if not chains:
            settings.wgame_custom_chain_index = 0
            settings.wgame_custom_chain_id = ""
            return
        index = min(max(int(settings.wgame_custom_chain_index), 0), len(chains) - 1)
        chain = chains[index]
        settings.wgame_custom_chain_index = index
        settings.wgame_custom_chain_id = chain.get("id", "")
        settings.wgame_custom_chain_enabled = bool(chain.get("enabled", True))
        settings.wgame_custom_chain_locked = bool(chain.get("locked", False))
        settings.wgame_custom_chain_radius = max(float(chain.get("influence_radius", 0.05)), 1e-5)
        coordinate_mode = chain.get("coordinate_mode", "PROJECTION")
        settings.wgame_custom_chain_coordinate_mode = coordinate_mode if coordinate_mode in {"PROJECTION", "TOPOLOGY"} else "PROJECTION"
        settings.wgame_custom_chain_joint_blend = min(max(float(chain.get("joint_blend", 0.35)), 0.01), 0.5)
        settings.wgame_custom_chain_blend_override = min(
            max(int(chain.get("blend_steps_override", 0)), 0),
            12,
        )
        settings.wgame_custom_chain_semantic_key = chain.get("semantic_key", "")
        settings.wgame_custom_chain_target_count = min(
            max(int(chain.get("target_bone_count", len(chain.get("bones", [])) or 1)), 1),
            12,
        )
    finally:
        _CUSTOM_CHAIN_SETTINGS_SYNCING = False


def _custom_chain_geometry_key(rig_obj, chain):
    root = rig_obj.data.bones.get(chain.get("root_bone", ""))
    if not root:
        return (float("inf"),) * 6
    return tuple(round(float(value), 6) for value in (*root.head_local, *root.tail_local))


def _canonical_custom_chain_plan(rig_obj, payload):
    chains = payload.get("chains", [])
    generic_groups = {}
    for chain in chains:
        if chain.get("semantic_type", "").startswith("BREAST_"):
            continue
        key = _sanitize_custom_chain_semantic_key(chain.get("semantic_key", ""), chain.get("base_parent", ""))
        side = chain.get("side") or _custom_chain_side(chain.get("base_parent", ""))
        generic_groups.setdefault((key, side), []).append(chain)
    ordinals = {}
    for group_key, items in generic_groups.items():
        for ordinal, chain in enumerate(sorted(items, key=lambda item: _custom_chain_geometry_key(rig_obj, item)), start=1):
            ordinals[chain.get("uid") or chain.get("id")] = ordinal

    rename_map = {}
    for chain in chains:
        bones = chain.get("bones", [])
        semantic_type = chain.get("semantic_type", "")
        if semantic_type in {"BREAST_L", "BREAST_R"}:
            side = semantic_type[-1].lower()
            desired = [f"breast_{index:02d}.{side}" for index in range(1, len(bones) + 1)]
            chain["semantic_key"] = "breast"
            chain["side"] = side
        else:
            key = _sanitize_custom_chain_semantic_key(chain.get("semantic_key", ""), chain.get("base_parent", ""))
            side = chain.get("side") or _custom_chain_side(chain.get("base_parent", ""))
            ordinal = ordinals.get(chain.get("uid") or chain.get("id"), 1)
            desired = [
                f"custom_{key}_{ordinal:02d}_{segment:02d}.{side}"
                for segment in range(1, len(bones) + 1)
            ]
            chain["semantic_key"] = key
            chain["side"] = side
            chain["ordinal"] = ordinal
        for old_name, new_name in zip(bones, desired):
            if old_name != new_name:
                rename_map[old_name] = new_name
    return rename_map


def _apply_custom_bone_rename(context, settings, rig_obj, rename_map):
    rename_map = {
        old: new
        for old, new in rename_map.items()
        if old != new and rig_obj.data.bones.get(old)
    }
    if not rename_map:
        return {}
    old_names = set(rename_map)
    conflicts = sorted(
        new
        for new in rename_map.values()
        if rig_obj.data.bones.get(new) and new not in old_names
    )
    if conflicts:
        raise RuntimeError("规范骨名已被其它骨骼占用：" + ", ".join(conflicts[:6]))
    for mesh_obj in (obj for obj in context.scene.objects if obj.type == "MESH"):
        for old, new in rename_map.items():
            if mesh_obj.vertex_groups.get(old) and mesh_obj.vertex_groups.get(new) and new not in old_names:
                raise RuntimeError(f"规范顶点组名已被占用：{mesh_obj.name}/{new}")

    selected_custom = settings.wgame_custom_weight_bone
    selected_browser = settings.wgame_weight_browser_bone
    temporary_names = {}
    for index, old in enumerate(sorted(rename_map)):
        temporary = f"__wgame_chain_rename_{index:03d}__"
        while rig_obj.data.bones.get(temporary):
            temporary += "_"
        temporary_names[old] = temporary
        rig_obj.data.bones[old].name = temporary
        for mesh_obj in (obj for obj in context.scene.objects if obj.type == "MESH"):
            group = mesh_obj.vertex_groups.get(old)
            if group:
                group.name = temporary
    for old, new in rename_map.items():
        temporary = temporary_names[old]
        rig_obj.data.bones[temporary].name = new
        for mesh_obj in (obj for obj in context.scene.objects if obj.type == "MESH"):
            group = mesh_obj.vertex_groups.get(temporary)
            if group:
                group.name = new
    for obj in context.scene.objects:
        for constraint in getattr(obj, "constraints", ()):
            if getattr(constraint, "target", None) == rig_obj and constraint.subtarget in rename_map:
                constraint.subtarget = rename_map[constraint.subtarget]
    for pose_bone in rig_obj.pose.bones:
        for constraint in pose_bone.constraints:
            if getattr(constraint, "target", None) == rig_obj and constraint.subtarget in rename_map:
                constraint.subtarget = rename_map[constraint.subtarget]
    rigid_payload = _rigid_bind_payload(rig_obj)
    rigid_changed = False
    for record in rigid_payload.get("attachments", []):
        target_bone = record.get("target_bone", "")
        if target_bone in rename_map:
            record["target_bone"] = rename_map[target_bone]
            rigid_changed = True
    if rigid_changed:
        _save_rigid_bind_payload(rig_obj, rigid_payload)
    _ENUM_ITEM_CACHE.clear()
    if selected_custom in rename_map:
        try:
            settings.wgame_custom_weight_bone = rename_map[selected_custom]
        except TypeError:
            pass
    if selected_browser in rename_map:
        try:
            settings.wgame_weight_browser_bone = rename_map[selected_browser]
        except TypeError:
            pass
    _clear_focus_marker()
    return rename_map


def _update_chain_payload_after_rename(rig_obj, payload, rename_map):
    for chain in payload.get("chains", []):
        chain["bones"] = [rename_map.get(name, name) for name in chain.get("bones", [])]
        chain["root_bone"] = rename_map.get(chain.get("root_bone", ""), chain.get("root_bone", ""))
        chain["target_bone_count"] = len(chain.get("bones", []))
    fingerprint = _custom_bone_structure_fingerprint(rig_obj)
    payload["structure_fingerprint"] = fingerprint
    for chain in payload.get("chains", []):
        chain["structure_fingerprint"] = fingerprint
    _save_custom_weight_chain_payload(rig_obj, payload)
    return payload


def _clear_character_cloth_for_skeleton_change(settings):
    character_id = (getattr(settings, "character_id", "") or "").strip()
    root_text = _resolve_repository_root(settings, persist=False)
    if not root_text or len(character_id) != 6 or not character_id.isdigit():
        return "", ""
    config_path = (
        pathlib.Path(root_text)
        / "Authoring"
        / "CharacterPackages"
        / f"character-{character_id}"
        / "config"
        / "character_cloth_magica.json"
    )
    if not config_path.is_file():
        return "", ""
    try:
        document = json.loads(config_path.read_text(encoding="utf-8"))
    except (OSError, ValueError):
        return "", ""
    if not document.get("enabled") and not document.get("cloths"):
        return "", ""
    backup_root = pathlib.Path(root_text) / "Temp" / "MxFrameworkAuthoring" / "CharacterCloth"
    backup_root.mkdir(parents=True, exist_ok=True)
    timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
    backup_path = backup_root / f"{character_id}_character_cloth_magica_before_skeleton_change_{timestamp}.json"
    shutil.copy2(config_path, backup_path)
    cleared = {
        "schemaVersion": document.get("schemaVersion", "1.1"),
        "backend": document.get("backend", "MagicaCloth2"),
        "enabled": False,
        "cloths": [],
    }
    temporary = config_path.with_suffix(config_path.suffix + ".tmp")
    temporary.write_text(json.dumps(cleared, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    os.replace(temporary, config_path)
    return str(config_path), str(backup_path)


def _polyline_resample(points, segment_count):
    points = [Vector(point) for point in points]
    if segment_count < 1 or len(points) < 2:
        raise ValueError("骨链重采样需要至少一个骨段和两个路径点")
    lengths = [(points[index + 1] - points[index]).length for index in range(len(points) - 1)]
    total = sum(lengths)
    if total <= 1e-8:
        raise ValueError("骨链总长度为零，无法调整数量")
    result = []
    for sample_index in range(segment_count + 1):
        distance = total * sample_index / segment_count
        consumed = 0.0
        for index, length in enumerate(lengths):
            if distance <= consumed + length or index == len(lengths) - 1:
                factor = 0.0 if length <= 1e-12 else (distance - consumed) / length
                result.append(points[index].lerp(points[index + 1], max(0.0, min(1.0, factor))))
                break
            consumed += length
    return result


def _resize_linear_custom_chain(context, rig_obj, chain, target_count):
    names = list(chain.get("bones", []))
    bones = [rig_obj.data.bones.get(name) for name in names]
    if not names or any(bone is None for bone in bones):
        raise RuntimeError("当前骨链记录包含不存在的骨骼")
    if any(
        len([child for child in bone.children if child.name in names]) > 1
        for bone in bones
    ):
        raise RuntimeError("当前骨链包含分叉，不能按单一数量重采样")
    external_children = [
        f"{bone.name}->{child.name}"
        for bone in bones
        for child in bone.children
        if child.name not in names
    ]
    if external_children:
        raise RuntimeError("骨链存在外部子骨引用：" + ", ".join(external_children[:4]))
    target_count = min(max(int(target_count), 1), 12)
    if target_count == len(names):
        return [], names
    points = [bones[0].head_local.copy()] + [bone.tail_local.copy() for bone in bones]
    sampled = _polyline_resample(points, target_count)
    root_parent = bones[0].parent.name if bones[0].parent else ""
    root_connected = bool(bones[0].use_connect)
    deleted_names = names[target_count:]
    if deleted_names:
        referenced = []
        for obj in context.scene.objects:
            for constraint in getattr(obj, "constraints", ()):
                if getattr(constraint, "target", None) == rig_obj and constraint.subtarget in deleted_names:
                    referenced.append(f"{obj.name}/{constraint.name}")
        for pose_bone in rig_obj.pose.bones:
            for constraint in pose_bone.constraints:
                if getattr(constraint, "target", None) == rig_obj and constraint.subtarget in deleted_names:
                    referenced.append(f"{pose_bone.name}/{constraint.name}")
        referenced.extend(
            f"刚性附件:{record.get('object', '')}/{record.get('id', '')}"
            for record in _rigid_bind_payload(rig_obj).get("attachments", [])
            if record.get("target_bone", "") in deleted_names
        )
        if referenced:
            raise RuntimeError("待删除骨骼仍被约束引用：" + ", ".join(referenced[:4]))
    if getattr(context, "object", None) and context.object.mode != "OBJECT":
        bpy.ops.object.mode_set(mode="OBJECT")
    _select_only(context, rig_obj)
    bpy.ops.object.mode_set(mode="EDIT")
    edit_bones = rig_obj.data.edit_bones
    rolls = [float(edit_bones[name].roll) for name in names]
    active_names = names[:target_count]
    while len(active_names) < target_count:
        temporary = f"__wgame_chain_resize_{len(active_names):02d}__"
        while edit_bones.get(temporary):
            temporary += "_"
        bone = edit_bones.new(temporary)
        bone.use_deform = True
        active_names.append(temporary)
    for name in deleted_names:
        bone = edit_bones.get(name)
        if bone:
            edit_bones.remove(bone)
    for index, name in enumerate(active_names):
        bone = edit_bones[name]
        bone.head = sampled[index]
        bone.tail = sampled[index + 1]
        bone.parent = edit_bones.get(root_parent) if index == 0 and root_parent else edit_bones[active_names[index - 1]] if index else None
        bone.use_connect = root_connected if index == 0 else True
        bone.use_deform = True
        bone.roll = rolls[min(int(index * len(rolls) / target_count), len(rolls) - 1)]
    bpy.ops.object.mode_set(mode="OBJECT")
    for mesh_obj in (obj for obj in context.scene.objects if obj.type == "MESH"):
        for name in deleted_names:
            group = mesh_obj.vertex_groups.get(name)
            if group:
                mesh_obj.vertex_groups.remove(group)
    return deleted_names, active_names


def _canonicalize_custom_weight_chains(context, settings, rig_obj, payload):
    rename_map = _canonical_custom_chain_plan(rig_obj, payload)
    applied = _apply_custom_bone_rename(context, settings, rig_obj, rename_map)
    _update_chain_payload_after_rename(rig_obj, payload, applied)
    _load_current_custom_chain_settings(settings, context, payload)
    return payload, applied


def _select_custom_chain_for_edit(context, settings, rig_obj, chain):
    names = [name for name in chain.get("bones", []) if rig_obj.data.bones.get(name)]
    if not names:
        return False
    if getattr(context, "object", None) and context.object.mode != "OBJECT":
        bpy.ops.object.mode_set(mode="OBJECT")
    _select_only(context, rig_obj)
    bpy.ops.object.mode_set(mode="EDIT")
    for bone in rig_obj.data.edit_bones:
        selected = bone.name in names
        bone.select = selected
        bone.select_head = selected
        bone.select_tail = selected
    rig_obj.data.edit_bones.active = rig_obj.data.edit_bones.get(names[0])
    settings.wgame_custom_bone_edit_active = True
    _tag_view3d_redraw()
    return True


def _sync_custom_chain_from_active_edit_bone(context, settings, rig_obj, payload=None):
    if not rig_obj or rig_obj.mode != "EDIT":
        return False
    active = rig_obj.data.edit_bones.active
    if not active or not active.select:
        return False
    payload = payload or _custom_weight_chain_payload(rig_obj)
    chains = payload.get("chains", [])
    index = next(
        (chain_index for chain_index, chain in enumerate(chains) if active.name in chain.get("bones", [])),
        None,
    )
    if index is None or index == int(settings.wgame_custom_chain_index):
        return False
    settings.wgame_custom_chain_index = index
    _load_current_custom_chain_settings(settings, context, payload)
    return True


def _declared_breast_chain_error(rig_obj, sides):
    """Validate identity and a linear hierarchy without guessing from symmetry."""
    chest = rig_obj.data.bones.get("upper_chest.x")
    if not chest or (chest.tail_local - chest.head_local).length <= 1e-8:
        return "缺少有效的 upper_chest.x 基础胸骨"
    seen = set()
    for side, label in (("left", "左"), ("right", "右")):
        names = sides.get(side, [])
        if not names:
            return f"缺少{label}侧胸部骨链"
        if not 1 <= len(names) <= 12:
            return f"{label}侧胸部骨链需要 1 至 12 根骨骼"
        if any(not isinstance(name, str) or not name for name in names):
            return f"{label}侧胸部骨链存在无效骨骼记录"
        parent = chest
        for index, name in enumerate(names):
            if not isinstance(name, str) or name in seen:
                return f"{label}侧胸部骨链存在重复或无效骨骼记录"
            seen.add(name)
            bone = rig_obj.data.bones.get(name)
            if not bone:
                return f"胸部骨骼不存在：{name}"
            if not bone.use_deform:
                return f"胸部骨骼未启用 Deform：{name}"
            if not all(math.isfinite(float(value)) for value in (*bone.head_local, *bone.tail_local)):
                return f"胸部骨骼坐标无效：{name}"
            if (bone.tail_local - bone.head_local).length <= 1e-8:
                return f"胸部骨骼长度为零：{name}"
            if not bone.parent or bone.parent.name != parent.name:
                return f"胸部骨链层级不连续：{name} 应以 {parent.name} 为父骨"
            expected_children = {names[index + 1]} if index + 1 < len(names) else set()
            actual_children = {child.name for child in bone.children
                               if child.use_deform or child.name in expected_children}
            if actual_children != expected_children:
                return f"胸部骨链存在分叉或未记录的骨段：{name}"
            parent = bone
        root = rig_obj.data.bones[names[0]]
        if (parent.tail_local - root.head_local).length <= 1e-8:
            return f"{label}侧胸部骨链首尾重合，无法定义胸部影响方向"
    return ""


def _declared_breast_detection(rig_obj, sides, error=""):
    error = error or _declared_breast_chain_error(rig_obj, sides)
    if error:
        return {"valid": False, "present": True, "left": [], "right": [], "roles": {},
                "report": "胸部骨链未就绪：" + error}
    left, right = list(sides["left"]), list(sides["right"])
    roles = {name: f"女性胸部 · {label} {index}"
             for names, label in ((left, "左"), (right, "右"))
             for index, name in enumerate(names, start=1)}
    return {"valid": True, "present": True, "left": left, "right": right, "roles": roles,
            "report": "已识别女性胸部骨链：左 " + "→".join(left) + "；右 " + "→".join(right)}


def _detect_breast_bone_chains(rig_obj):
    if not rig_obj or getattr(rig_obj, "type", "") != "ARMATURE":
        return {"valid": False, "present": False, "left": [], "right": [], "roles": {},
                "report": "没有找到可识别胸部骨链的骨架"}
    # Canonical names and saved semantic roles are explicit identities.  Their
    # chain size and slight rest-pose asymmetry must not be overridden by the
    # conservative two-bone geometric heuristic used for unlabelled imports.
    canonical = {"left": [], "right": []}
    malformed = []
    for bone in rig_obj.data.bones:
        match = re.fullmatch(r"breast_(\d+)\.([lr])", bone.name)
        if match:
            canonical["left" if match.group(2) == "l" else "right"].append((int(match.group(1)), bone.name))
        elif re.fullmatch(r"breast_\d+\.[lr]\.\d+", bone.name):
            malformed.append(bone.name)
    if any(canonical.values()) or malformed:
        sides = {}
        error = "胸部规范名称重复：" + ", ".join(malformed[:3]) if malformed else ""
        for side, label in (("left", "左"), ("right", "右")):
            entries = sorted(canonical[side])
            indices = [index for index, name in entries]
            if entries and indices != list(range(1, len(entries) + 1)):
                error = error or f"{label}侧胸部骨骼编号必须从 01 连续递增，不能缺段或重复"
            sides[side] = [name for index, name in entries]
        return _declared_breast_detection(rig_obj, sides, error)
    payload = _custom_weight_chain_payload(rig_obj)
    declared = {side: [chain for chain in payload.get("chains", [])
                       if isinstance(chain, dict) and chain.get("semantic_type") == semantic]
                for side, semantic in (("left", "BREAST_L"), ("right", "BREAST_R"))}
    if any(declared.values()):
        sides, error = {}, ""
        for side, label in (("left", "左"), ("right", "右")):
            chains = declared[side]
            if len(chains) != 1:
                error = error or f"{label}侧需要且只能声明一条胸部骨链"
                sides[side] = []
                continue
            chain = chains[0]
            names = chain.get("bones", [])
            if not isinstance(names, list):
                names = []
                error = error or f"{label}侧胸部骨链记录无效"
            sides[side] = names
            if names and chain.get("root_bone", names[0]) != names[0]:
                error = error or f"{label}侧胸部骨链根骨记录不一致，请刷新骨链"
        return _declared_breast_detection(rig_obj, sides, error)
    return _detect_legacy_breast_bone_chains(rig_obj)


def _detect_legacy_breast_bone_chains(rig_obj):
    empty = {
        "valid": False,
        "present": False,
        "left": [],
        "right": [],
        "roles": {},
        "report": "未识别到左右对称的两段女性胸部骨链",
    }
    if not rig_obj or rig_obj.type != "ARMATURE":
        return empty
    snapshot_names = set(_base_skeleton_snapshot(rig_obj))
    if not snapshot_names and rig_obj.get("wgame_rig_kind") == "deform_skeleton":
        snapshot_names = {bone.name for bone in rig_obj.data.bones if _is_wgame_base_bone_name(bone.name)}
    upper_chest = rig_obj.data.bones.get("upper_chest.x")
    if not snapshot_names or not upper_chest:
        return empty
    base_points = [
        point
        for name in snapshot_names
        for bone in [rig_obj.data.bones.get(name)]
        if bone
        for point in (bone.head_local, bone.tail_local)
    ]
    scale = max(
        (
            max(point[axis] for point in base_points) - min(point[axis] for point in base_points)
            for axis in range(3)
        ),
        default=1.0,
    )
    scale = max(scale, 1e-3)
    chest_axis = upper_chest.tail_local - upper_chest.head_local
    chest_length_squared = max(chest_axis.length_squared, 1e-12)
    candidates = []
    for root in rig_obj.data.bones:
        if (
            root.name in snapshot_names
            or not root.use_deform
            or not root.parent
            or root.parent.name != "upper_chest.x"
        ):
            continue
        chest_factor = (root.head_local - upper_chest.head_local).dot(chest_axis) / chest_length_squared
        if not -0.10 <= chest_factor <= 1.10 or abs(root.head_local.x) < scale * 0.005:
            continue
        children = [
            child
            for child in root.children
            if child.use_deform and child.name not in snapshot_names
        ]
        if len(children) != 1:
            continue
        child = children[0]
        if (child.head_local - root.tail_local).length > scale * 0.006:
            continue
        if any(grandchild.use_deform and grandchild.name not in snapshot_names for grandchild in child.children):
            continue
        chain_vector = child.tail_local - root.head_local
        chain_length = chain_vector.length
        if not scale * 0.015 <= chain_length <= scale * 0.15:
            continue
        vertical_share = abs(chain_vector.dot(chest_axis.normalized())) / max(chain_length, 1e-8)
        if vertical_share > 0.85:
            continue
        candidates.append((root, child))
    pairs = []
    for positive in (item for item in candidates if item[0].head_local.x > 0.0):
        for negative in (item for item in candidates if item[0].head_local.x < 0.0):
            positive_root, positive_child = positive
            negative_root, negative_child = negative
            root_mirror_error = Vector(
                (
                    positive_root.head_local.x + negative_root.head_local.x,
                    positive_root.head_local.y - negative_root.head_local.y,
                    positive_root.head_local.z - negative_root.head_local.z,
                )
            ).length
            tip_mirror_error = Vector(
                (
                    positive_child.tail_local.x + negative_child.tail_local.x,
                    positive_child.tail_local.y - negative_child.tail_local.y,
                    positive_child.tail_local.z - negative_child.tail_local.z,
                )
            ).length
            length_error = abs(
                (positive_child.tail_local - positive_root.head_local).length
                - (negative_child.tail_local - negative_root.head_local).length
            )
            score = root_mirror_error + tip_mirror_error + length_error
            pairs.append((score, positive, negative))
    if not pairs:
        return empty
    score, positive, negative = min(pairs, key=lambda item: item[0])
    if score > scale * 0.035:
        return empty
    left = [positive[0].name, positive[1].name]
    right = [negative[0].name, negative[1].name]
    roles = {
        left[0]: "女性胸部 · 左 1",
        left[1]: "女性胸部 · 左 2",
        right[0]: "女性胸部 · 右 1",
        right[1]: "女性胸部 · 右 2",
    }
    return {
        "valid": True,
        "present": True,
        "left": left,
        "right": right,
        "roles": roles,
        "report": f"已识别女性胸部骨链：左 {left[0]}→{left[1]}；右 {right[0]}→{right[1]}",
    }


def _store_breast_bone_detection(rig_obj):
    detection = _detect_breast_bone_chains(rig_obj)
    if rig_obj:
        rig_obj[BREAST_BONE_DETECTION_KEY] = json.dumps(
            detection,
            ensure_ascii=False,
            separators=(",", ":"),
        )
    return detection


def _canonical_breast_bone_rename_map(detection):
    if not detection or not detection.get("valid"):
        return {}
    return {name: f"breast_{index:02d}.{suffix}"
            for side, suffix in (("left", "l"), ("right", "r"))
            for index, name in enumerate(detection.get(side, []), start=1)}


def _smooth_unit(value):
    value = max(0.0, min(1.0, float(value)))
    return value * value * (3.0 - 2.0 * value)


def _breast_chain_envelopes(rig_obj, detection, character_height):
    """Rest-space envelopes for explicitly recognized linear breast chains."""
    chest = rig_obj.data.bones.get("upper_chest.x")
    if not detection.get("valid") or not chest or chest.length <= 1e-8:
        return {}
    chest_axis = (chest.tail_local - chest.head_local).normalized()
    roots = [rig_obj.data.bones.get(detection[side][0]) for side in ("left", "right")]
    if not all(roots):
        return {}
    separation = abs(roots[0].head_local.x - roots[1].head_local.x)
    mid_x = (roots[0].head_local.x + roots[1].head_local.x) * 0.5
    result = {}
    for side in ("left", "right"):
        names = detection.get(side, [])
        bones = [rig_obj.data.bones.get(name) for name in names]
        if not bones or any(not bone or not bone.use_deform or bone.length <= 1e-8 for bone in bones):
            continue
        chain_vector = bones[-1].tail_local - bones[0].head_local
        forward = chain_vector - chest_axis * chain_vector.dot(chest_axis)
        if forward.length_squared <= 1e-12:
            continue
        segments, total = [], 0.0
        for bone in bones:
            vector = bone.tail_local - bone.head_local
            segments.append({"head": bone.head_local, "vector": vector, "length": vector.length, "start": total})
            total += vector.length
        lateral_offset = sum((bone.head_local.x + bone.tail_local.x) * 0.5 for bone in bones) / len(bones) - mid_x
        side_sign = (1.0 if lateral_offset > 0.0 else -1.0) if abs(lateral_offset) > 1e-8 else (1.0 if side == "left" else -1.0)
        result[side] = {
            "names": list(names), "root": bones[0].head_local,
            "mid_x": mid_x, "side_sign": side_sign,
            "forward": forward.normalized(), "segments": segments, "length": total,
            "radius": max(character_height * 0.018, min(character_height * 0.060,
                          max(chain_vector.length * 0.70, separation * 0.58))),
        }
    return result


def _breast_point_influence(point, envelopes):
    """Return (share, side, arc coordinate), without consulting stored weights."""
    best = None
    for side, data in envelopes.items():
        if (point.x - data["mid_x"]) * data["side_sign"] <= 0.0:
            continue
        nearest = None
        for segment in data["segments"]:
            factor = max(0.0, min(1.0, (point - segment["head"]).dot(segment["vector"])
                                  / (segment["length"] ** 2)))
            distance = (point - segment["head"] - segment["vector"] * factor).length
            arc = (segment["start"] + segment["length"] * factor) / data["length"]
            if nearest is None or distance < nearest[0]:
                nearest = (distance, arc)
        radius = data["radius"]
        front_depth = (point - data["root"]).dot(data["forward"])
        if not nearest or nearest[0] > radius or front_depth < -radius * 0.10:
            continue
        share = 0.78 * _smooth_unit(1.0 - nearest[0] / radius) * _smooth_unit(
            (front_depth + radius * 0.10) / (radius * 0.45))
        if share >= 0.01 and (best is None or share > best[0]):
            best = (share, side, nearest[1])
    return best


def _breast_chain_distribution(names, coordinate):
    if not names:
        return {}
    if len(names) == 1:
        return {names[0]: 1.0}
    progress = max(0.0, min(1.0, (coordinate - 0.20) / 0.80)) * (len(names) - 1)
    index = min(int(progress), len(names) - 2)
    share = _smooth_unit(progress - index)
    return {name: weight for name, weight in ((names[index], 1.0 - share), (names[index + 1], share))
            if weight > 1e-8}


def _apply_detected_breast_weights(context, settings, rig_obj, detection=None):
    """Plan all eligible Base vertices before writing; zero coverage is failure.

    Body and clothing components use the same anatomical envelope. Existing
    weights outside the generated region, Custom scope, and protected rows
    stay unchanged. No preliminary deletion of breast groups takes place.
    """
    detection = detection or _detect_breast_bone_chains(rig_obj)
    result = {"valid": False, "left": 0, "right": 0, "total": 0, "cleared": 0,
              "max_weight": 0.0, "bone_coverage": {}, "skipped": {}, "report": ""}
    if not detection.get("valid"):
        result["report"] = detection.get("report", "未识别到有效女性乳房骨链")
        return result
    breast_names = set(detection["left"] + detection["right"])
    result["bone_coverage"] = dict.fromkeys(sorted(breast_names), 0)
    if getattr(context, "object", None) and context.object.mode != "OBJECT":
        result["report"] = "请先退出编辑/绘制模式，再生成乳房权重；现有权重保留"
        return result
    height = _character_height_in_rig_space(context, settings, rig_obj)
    envelopes = _breast_chain_envelopes(rig_obj, detection, height)
    if len(envelopes) != 2:
        result["report"] = "乳房骨链长度或前向方向无效，请检查骨骼位置；现有权重保留"
        return result
    base_by_object = _scope_vertex_ids_by_object(settings, "BASE_SKIN", context)
    explicit_regions = _base_region_assignments_by_object(context, settings)
    deform_names = {bone.name for bone in rig_obj.data.bones if bone.use_deform}
    protected_bones = {
        name for chain in _custom_weight_chain_payload(rig_obj).get("chains", [])
        if chain.get("locked") or not chain.get("enabled", True)
        for name in chain.get("bones", [])
    }
    rig_inverse = rig_obj.matrix_world.inverted()
    skipped = collections.Counter()
    geometry_counts = {"left": 0, "right": 0}
    plan = []
    scanned = 0
    for object_name, base_ids in sorted(base_by_object.items()):
        mesh_obj = context.scene.objects.get(object_name)
        if not mesh_obj or mesh_obj.type != "MESH":
            skipped["基础范围对象失效"] += len(base_ids)
            continue
        if getattr(mesh_obj, "mode", "OBJECT") != "OBJECT":
            skipped["对象仍处于编辑模式"] += len(base_ids)
            continue
        if getattr(mesh_obj.data, "users", 1) > 1:
            skipped["共享Mesh数据需先设为单用户"] += len(base_ids)
            continue
        transform = rig_inverse @ mesh_obj.matrix_world
        group_names = {group.index: group.name for group in mesh_obj.vertex_groups}
        locked_names = {group.name for group in mesh_obj.vertex_groups if group.lock_weight} | protected_bones
        for vertex_id in sorted(base_ids):
            if not 0 <= vertex_id < len(mesh_obj.data.vertices):
                skipped["顶点记录失效"] += 1
                continue
            scanned += 1
            region = explicit_regions.get(object_name, {}).get(vertex_id, "")
            if region and region != "CENTER":
                skipped["显式指定为非躯干区域"] += 1
                continue
            vertex = mesh_obj.data.vertices[vertex_id]
            point = transform @ vertex.co
            best = _breast_point_influence(point, envelopes)
            if best is None:
                skipped["不在乳房前侧包络内"] += 1
                continue
            influence, side, coordinate = best
            geometry_counts[side] += 1
            current = {group_names.get(item.group): float(item.weight) for item in vertex.groups
                       if group_names.get(item.group) in deform_names}
            if any(not math.isfinite(weight) or weight < 0.0 for weight in current.values()):
                skipped["已有权重数值无效"] += 1
                continue
            support = {name: weight for name, weight in current.items() if name not in breast_names and weight > 1e-8}
            support_total = sum(support.values())
            if support_total <= 1e-8:
                # A previously breast-only vertex still has a valid torso
                # attachment when regenerated. A genuinely unbound Base vertex
                # must first go through the Base solver.
                if sum(current.get(name, 0.0) for name in breast_names) > 1e-8:
                    support = {"upper_chest.x": 1.0}
                    support_total = 1.0
                else:
                    skipped["没有基础蒙皮支持"] += 1
                    continue
            support = {name: weight / support_total for name, weight in support.items()}
            # Repair the existing anatomical support before breast influences
            # join it. Otherwise an invalid upper-arm contribution can be
            # redistributed into breast weights and amplify the intended share.
            support = dict(_limit_base_joint_weights(point, rig_obj, list(support.items()), height))
            if sum(support.get(name, 0.0) for name in ("spine_02.x", "upper_chest.x")) < 0.10:
                skipped["胸腔骨支持不足"] += 1
                continue
            support = dict(sorted(support.items(), key=lambda item: item[1], reverse=True)[:2])
            support_total = sum(support.values())
            assignments = {name: weight / support_total * (1.0 - influence) for name, weight in support.items()}
            for name, weight in _breast_chain_distribution(detection[side], coordinate).items():
                assignments[name] = assignments.get(name, 0.0) + influence * weight
            assignments = dict(_limit_base_joint_weights(point, rig_obj, list(assignments.items()), height))
            if (not assignments or len(assignments) > 4
                    or any(name not in deform_names or not math.isfinite(weight) or weight < 0.0
                           for name, weight in assignments.items())
                    or abs(sum(assignments.values()) - 1.0) > 1e-5):
                skipped["求解结果无效"] += 1
                continue
            if any(abs(assignments.get(name, 0.0) - current.get(name, 0.0)) > 1e-8 for name in locked_names):
                skipped["骨链或顶点组已锁定/禁用"] += 1
                continue
            plan.append((mesh_obj, vertex_id, current, assignments, side, influence))
    # All geometric solving is complete before any group removal or creation.
    for mesh_obj, vertex_id, current, assignments, side, influence in plan:
        for name in current:
            group = mesh_obj.vertex_groups.get(name)
            if group and name not in assignments:
                group.remove([vertex_id])
        for name, weight in assignments.items():
            if abs(current.get(name, 0.0) - weight) <= 1e-8:
                continue
            group = mesh_obj.vertex_groups.get(name) or mesh_obj.vertex_groups.new(name=name)
            group.add([vertex_id], weight, "REPLACE")
        result[side] += 1
        actual_influence = sum(assignments.get(name, 0.0) for name in breast_names)
        result["max_weight"] = max(result["max_weight"], actual_influence)
        for name in breast_names:
            result["bone_coverage"][name] += int(assignments.get(name, 0.0) > 1e-6)
    for mesh_obj in {row[0].name: row[0] for row in plan}.values():
        mesh_obj.data.update()
    result["total"] = result["left"] + result["right"]
    result["valid"] = result["total"] > 0 and all(
        not count or result[side] > 0 for side, count in geometry_counts.items())
    result["skipped"] = dict(skipped)
    result["geometry_counts"] = geometry_counts
    result["base_vertices"] = scanned
    result["report"] = (
        f"乳房权重：左 {result['left']} / 右 {result['right']} / 总计 {result['total']} / "
        f"基础范围 {scanned} / 前侧包络 {sum(geometry_counts.values())} / 最大影响 {result['max_weight']:.3f}"
        + ("；未生成任何乳房权重" if not result["total"] else "")
        + ("；" + "，".join(f"{reason} {count}" for reason, count in skipped.items()) if skipped else "")
    )
    return result



def _deform_weight_stats(mesh_obj, rig_obj, vertex_ids):
    deform_names = {bone.name for bone in rig_obj.data.bones if bone.use_deform}
    group_names = {group.index: group.name for group in mesh_obj.vertex_groups}
    zero = over_four = bad_sum = 0
    for vertex_id in vertex_ids:
        if vertex_id < 0 or vertex_id >= len(mesh_obj.data.vertices):
            zero += 1
            continue
        assignments = [
            item.weight
            for item in mesh_obj.data.vertices[vertex_id].groups
            if item.weight > 1e-6 and group_names.get(item.group) in deform_names
        ]
        zero += not assignments
        over_four += len(assignments) > 4
        bad_sum += bool(assignments) and abs(sum(assignments) - 1.0) > 1e-4
    return {"vertices": len(vertex_ids), "zero": zero, "over_four": over_four, "bad_sum": bad_sum}


def _rig_bone_segment_distance(point, bone):
    vector = bone.tail_local - bone.head_local
    factor = max(0.0, min(1.0, (point - bone.head_local).dot(vector) / max(vector.length_squared, 1e-12)))
    return (point - (bone.head_local + vector * factor)).length


def _mesh_vertex_adjacency(mesh_obj):
    adjacency = [[] for _vertex in mesh_obj.data.vertices]
    for edge in mesh_obj.data.edges:
        first, second = edge.vertices
        adjacency[first].append(second)
        adjacency[second].append(first)
    for neighbors in adjacency:
        neighbors.sort()
    return adjacency


def _custom_weight_subislands(context, settings):
    custom_by_object = _scope_vertex_ids_by_object(settings, "CUSTOM_BIND", context)
    base_by_object = _scope_vertex_ids_by_object(settings, "BASE_SKIN", context)
    component_by_vertex = {}
    for component in _unrigged_components(settings):
        object_name = component.get("object", "")
        mapping = component_by_vertex.setdefault(object_name, {})
        for vertex_id in component.get("vertex_indices") or []:
            mapping[vertex_id] = component.get("id", "")
    islands = []
    for object_name in sorted(custom_by_object):
        mesh_obj = context.scene.objects.get(object_name)
        if not mesh_obj or mesh_obj.type != "MESH":
            continue
        custom_ids = {
            vertex_id
            for vertex_id in custom_by_object[object_name]
            if 0 <= vertex_id < len(mesh_obj.data.vertices)
        }
        base_ids = base_by_object.get(object_name, set())
        adjacency = _mesh_vertex_adjacency(mesh_obj)
        remaining = set(custom_ids)
        object_island_index = 0
        while remaining:
            seed = min(remaining)
            region = {seed}
            frontier = [seed]
            remaining.remove(seed)
            while frontier:
                current = frontier.pop()
                for neighbor in adjacency[current]:
                    if neighbor in remaining:
                        remaining.remove(neighbor)
                        region.add(neighbor)
                        frontier.append(neighbor)
            boundary_neighbors = {
                vertex_id: sorted(neighbor for neighbor in adjacency[vertex_id] if neighbor in base_ids)
                for vertex_id in sorted(region)
            }
            boundary_neighbors = {
                vertex_id: neighbors
                for vertex_id, neighbors in boundary_neighbors.items()
                if neighbors
            }
            component_ids = sorted(
                {
                    component_by_vertex.get(object_name, {}).get(vertex_id, "")
                    for vertex_id in region
                    if component_by_vertex.get(object_name, {}).get(vertex_id, "")
                }
            )
            islands.append(
                {
                    "id": f"{object_name}:{object_island_index}",
                    "object": object_name,
                    "mesh": mesh_obj,
                    "component_id": component_ids[0] if component_ids else "",
                    "vertex_ids": sorted(region),
                    "vertex_set": region,
                    "adjacency": adjacency,
                    "boundary_neighbors": boundary_neighbors,
                    "attached": bool(boundary_neighbors),
                }
            )
            object_island_index += 1
    return islands


def _chain_point_distance(point, rig_obj, chain):
    distances = [
        _rig_bone_segment_distance(point, bone)
        for name in chain.get("bones", [])
        for bone in [rig_obj.data.bones.get(name)]
        if bone and bone.use_deform
    ]
    return min(distances) if distances else float("inf")


def _match_custom_subisland_chains(points, rig_obj, chains):
    candidates = []
    for chain in chains:
        if not chain.get("enabled", True):
            continue
        distances = [_chain_point_distance(point, rig_obj, chain) for point in points]
        if not distances or not all(math.isfinite(distance) for distance in distances):
            continue
        median_distance = float(statistics.median(distances))
        candidates.append(
            {
                "chain": chain,
                "median_distance": median_distance,
                "radius": max(float(chain.get("influence_radius", 0.0)), 1e-5),
            }
        )
    candidates.sort(key=lambda item: (item["median_distance"], item["chain"].get("id", "")))
    eligible = [item for item in candidates if item["median_distance"] <= item["radius"]]
    if not eligible:
        return [], candidates[0] if candidates else None
    if len(eligible) > 1 and eligible[1]["median_distance"] <= eligible[0]["median_distance"] * 1.5 + 1e-9:
        nearest = dict(candidates[0], reason="候选链距离接近，请显式指定区域")
        return [], nearest
    return [eligible[0]], candidates[0]


def _match_custom_vertex_chains(point, rig_obj, chains):
    candidates = []
    for chain in chains:
        if not chain.get("enabled", True):
            continue
        distance = _chain_point_distance(point, rig_obj, chain)
        if not math.isfinite(distance):
            continue
        radius = max(float(chain.get("influence_radius", 0.0)), 1e-5)
        candidates.append(
            {
                "chain": chain,
                "median_distance": distance,
                "radius": radius,
            }
        )
    candidates.sort(key=lambda item: (item["median_distance"], item["chain"].get("id", "")))
    eligible = [item for item in candidates
                if item["median_distance"] <= item["radius"] + max(item["radius"] * 0.005, 1e-8)]
    nearest = candidates[0] if candidates else None
    if len(eligible) > 1 and eligible[1]["median_distance"] <= eligible[0]["median_distance"] * 1.5 + 1e-9:
        return [], dict(nearest, reason="候选链距离接近，请显式指定区域")
    return eligible[:1], nearest


def _normalized_existing_deform_weights(mesh_obj, rig_obj, vertex_id):
    if vertex_id < 0 or vertex_id >= len(mesh_obj.data.vertices):
        return {}
    deform_names = {bone.name for bone in rig_obj.data.bones if bone.use_deform}
    group_names = {group.index: group.name for group in mesh_obj.vertex_groups}
    assignments = {
        group_names[item.group]: float(item.weight)
        for item in mesh_obj.data.vertices[vertex_id].groups
        if item.weight > 1e-6 and group_names.get(item.group) in deform_names
    }
    total = sum(assignments.values())
    return {
        name: weight / total
        for name, weight in assignments.items()
    } if total > 1e-12 else {}


def _custom_boundary_samples(island, rig_obj):
    mesh_obj = island["mesh"]
    samples = {}
    for custom_id, base_neighbors in island["boundary_neighbors"].items():
        neighbor_samples = [
            sample
            for vertex_id in base_neighbors
            for sample in [_normalized_existing_deform_weights(mesh_obj, rig_obj, vertex_id)]
            if sample
        ]
        if not neighbor_samples:
            continue
        combined = {}
        for sample in neighbor_samples:
            for name, weight in sample.items():
                combined[name] = combined.get(name, 0.0) + weight / len(neighbor_samples)
        total = sum(combined.values())
        if total > 1e-12:
            samples[custom_id] = {name: weight / total for name, weight in combined.items()}
    return samples


def _propagated_boundary_profile(vertex_id, island, boundary_samples, max_steps):
    if not boundary_samples or max_steps <= 0:
        return {}, None
    visited = {vertex_id}
    frontier = {vertex_id}
    reached = []
    for distance in range(0, max_steps):
        reached.extend(
            (distance, boundary_samples[current])
            for current in sorted(frontier)
            if current in boundary_samples
        )
        next_frontier = set()
        for current in frontier:
            for neighbor in island["adjacency"][current]:
                if neighbor in island["vertex_set"] and neighbor not in visited:
                    visited.add(neighbor)
                    next_frontier.add(neighbor)
        frontier = next_frontier
        if not frontier:
            break
    if not reached:
        return {}, None
    combined = {}
    influence_total = 0.0
    for distance, sample in reached:
        influence = 1.0 / (distance + 1.0)
        influence_total += influence
        for name, weight in sample.items():
            combined[name] = combined.get(name, 0.0) + weight * influence
    total = sum(combined.values())
    if total <= 1e-12 or influence_total <= 1e-12:
        return {}, None
    return ({name: weight / total for name, weight in combined.items()}, min(item[0] for item in reached))


def _custom_chain_segments(rig_obj, chain):
    """Validate a rest-pose chain (linear or branched tree) and retain its physical arc lengths."""
    names = list(chain.get("bones", []))
    if not names or len(names) != len(set(names)):
        raise ValueError("自定义骨链为空或包含重复骨骼")
    name_set = set(names)
    bone_objs = {}
    for name in names:
        bone = rig_obj.data.bones.get(name)
        if not bone or not bone.use_deform:
            raise ValueError(f"骨链包含不存在或非 Deform 骨：{name}")
        bone_objs[name] = bone

    root_names = []
    children_map = {name: [] for name in names}
    parent_map = {}
    for name in names:
        bone = bone_objs[name]
        pname = bone.parent.name if bone.parent and bone.parent.name in name_set else None
        parent_map[name] = pname
        if pname is None:
            root_names.append(name)
        else:
            children_map[pname].append(name)

    if len(root_names) != 1:
        raise ValueError(f"骨链必须有且仅有一个根骨骼，实际发现 {len(root_names)} 个")

    segments_by_name = {}
    segments = []
    is_strictly_linear = all(len(children_map[n]) <= 1 for n in names)
    if chain.get("coordinate_mode", "PROJECTION") == "TOPOLOGY" and not is_strictly_linear:
        raise ValueError("分叉骨链暂不支持拓扑根梢坐标；请拆分为线性骨链，或改用空间投影模式")
    if is_strictly_linear:
        curr = root_names[0]
        linear_order = []
        while curr:
            linear_order.append(curr)
            curr = children_map[curr][0] if children_map[curr] else None
        if set(linear_order) == name_set and len(linear_order) == len(names):
            order = linear_order
        else:
            order = names
    else:
        order = []
        queue = [root_names[0]]
        while queue:
            curr = queue.pop(0)
            order.append(curr)
            queue.extend(children_map[curr])

    for name in order:
        bone = bone_objs[name]
        head = bone.head_local.copy()
        vector = bone.tail_local - head
        length = float(vector.length)
        if (not all(math.isfinite(float(value)) for value in (*head, *vector))
                or not math.isfinite(length) or length <= 1e-8):
            raise ValueError(f"骨链含零长度或无效坐标骨：{name}")
        pname = parent_map[name]
        start = segments_by_name[pname]["end"] if pname else 0.0
        seg = {
            "name": name,
            "head": head,
            "tail": bone.tail_local.copy(),
            "vector": vector,
            "length": length,
            "start": start,
            "end": start + length,
            "parent": pname,
            "children": children_map[name],
        }
        segments_by_name[name] = seg
        segments.append(seg)

    return segments


def _custom_project_chain_coordinate(point, segments):
    """Return normalized arc length, with deterministic ties at folded segments."""
    if not all(math.isfinite(float(value)) for value in point):
        raise ValueError("顶点坐标包含无效数值")
    closest = None
    for index, segment in enumerate(segments):
        factor = max(0.0, min(1.0, (point - segment["head"]).dot(segment["vector"])
                              / (segment["length"] ** 2)))
        distance = (point - (segment["head"] + segment["vector"] * factor)).length_squared
        candidate = (float(distance), index, segment["start"] + factor * segment["length"])
        if closest is None or candidate[:2] < closest[:2]:
            closest = candidate
    if closest is None or not math.isfinite(closest[0]):
        raise ValueError("骨链投影失败")
    total_length = max(segment["end"] for segment in segments)
    return max(0.0, min(1.0, closest[2] / total_length))


def _custom_region_coordinates(island, points_by_id, rig_obj, chain, vertex_ids, roots=(), tips=()):
    """Solve a scalar on the assigned surface; no edge leaves vertex_ids.

    TOPOLOGY uses positive inverse-edge-length conductances and fixed root/tip
    values. A bounded, diagonally preconditioned CG solve either converges or
    raises; callers must preserve existing weights on failure.
    """
    segments = _custom_chain_segments(rig_obj, chain)
    region = set(vertex_ids)
    if not region:
        return {}
    if any(vertex_id not in points_by_id for vertex_id in region):
        raise ValueError("绑定区域缺少顶点坐标")
    if any(not all(math.isfinite(float(value)) for value in points_by_id[vertex_id])
           for vertex_id in region):
        raise ValueError("绑定区域包含无效顶点坐标")
    mode = chain.get("coordinate_mode", "PROJECTION")
    if mode == "PROJECTION":
        return {vertex_id: _custom_project_chain_coordinate(points_by_id[vertex_id], segments)
                for vertex_id in sorted(region)}
    if mode != "TOPOLOGY":
        raise ValueError(f"未知骨链纵向坐标模式：{mode}")
    root_ids, tip_ids = set(roots) & region, set(tips) & region
    if root_ids & tip_ids:
        raise ValueError("根部与末端锚点不能重叠")
    adjacency = island.get("adjacency", [])
    neighbors = {vertex_id: set() for vertex_id in region}
    for vertex_id in sorted(region):
        if vertex_id < 0 or vertex_id >= len(adjacency):
            raise ValueError("绑定区域的网格邻接数据已失效")
        for neighbor in adjacency[vertex_id]:
            if neighbor in region and neighbor != vertex_id:
                neighbors[vertex_id].add(neighbor)
                neighbors[neighbor].add(vertex_id)
    edge_floor = max(max(s["end"] for s in segments) * 1e-7, 1e-10)
    graph = {}
    for vertex_id in sorted(region):
        graph[vertex_id] = []
        for neighbor in sorted(neighbors[vertex_id]):
            length = float((points_by_id[vertex_id] - points_by_id[neighbor]).length)
            if not math.isfinite(length):
                raise ValueError("绑定区域包含无效边长度")
            graph[vertex_id].append((neighbor, max(length, edge_floor)))

    def distances(component, seeds):
        result = {vertex_id: 0.0 for vertex_id in seeds}
        queue = [(0.0, vertex_id) for vertex_id in sorted(seeds)]
        heapq.heapify(queue)
        while queue:
            distance, current = heapq.heappop(queue)
            if distance != result[current]:
                continue
            for neighbor, length in graph[current]:
                candidate = distance + length
                if neighbor in component and candidate < result.get(neighbor, float("inf")):
                    result[neighbor] = candidate
                    heapq.heappush(queue, (candidate, neighbor))
        return result

    result = {}
    remaining = set(region)
    while remaining:
        seed = min(remaining)
        component, frontier = {seed}, [seed]
        remaining.remove(seed)
        while frontier:
            current = frontier.pop()
            for neighbor, _length in graph[current]:
                if neighbor in remaining:
                    remaining.remove(neighbor)
                    component.add(neighbor)
                    frontier.append(neighbor)
        component_roots, component_tips = root_ids & component, tip_ids & component
        if not component_roots or not component_tips:
            raise ValueError(f"拓扑区域的每个连通块都需要根部和末端锚点（缺失块 {len(component)} 顶点）")
        result.update({vertex_id: 0.0 for vertex_id in component_roots})
        result.update({vertex_id: 1.0 for vertex_id in component_tips})
        unknown = sorted(component - component_roots - component_tips)
        if not unknown:
            continue
        root_distance = distances(component, component_roots)
        tip_distance = distances(component, component_tips)
        index_by_id = {vertex_id: index for index, vertex_id in enumerate(unknown)}
        diagonal, links, rhs, values = [], [], [], []
        for vertex_id in unknown:
            row, degree, boundary = [], 0.0, 0.0
            for neighbor, length in graph[vertex_id]:
                conductance = 1.0 / length
                degree += conductance
                if neighbor in index_by_id:
                    row.append((index_by_id[neighbor], conductance))
                elif neighbor in component_tips:
                    boundary += conductance
            if degree <= 0.0:
                raise ValueError("拓扑区域存在无法求解的孤立顶点")
            diagonal.append(degree)
            links.append(row)
            rhs.append(boundary)
            values.append(root_distance[vertex_id] / (root_distance[vertex_id] + tip_distance[vertex_id]))

        def product(vector):
            return [diagonal[index] * vector[index]
                    - sum(weight * vector[neighbor] for neighbor, weight in links[index])
                    for index in range(len(unknown))]

        residual = [target - actual for target, actual in zip(rhs, product(values))]
        tolerance = max(1e-10, math.sqrt(sum(value * value for value in rhs)) * 1e-8)
        preconditioned = [value / degree for value, degree in zip(residual, diagonal)]
        direction = list(preconditioned)
        rho = sum(a * b for a, b in zip(residual, preconditioned))
        edge_work = max(len(unknown) + sum(len(row) for row in links), 1)
        max_iterations = min(len(unknown) * 4 + 32, 2048, max(8, 12000000 // edge_work))
        converged = math.sqrt(sum(value * value for value in residual)) <= tolerance
        for _iteration in range(max_iterations):
            if converged:
                break
            projected = product(direction)
            denominator = sum(a * b for a, b in zip(direction, projected))
            if denominator <= 0.0 or not math.isfinite(denominator) or not math.isfinite(rho):
                break
            step = rho / denominator
            values = [value + step * delta for value, delta in zip(values, direction)]
            residual = [value - step * delta for value, delta in zip(residual, projected)]
            converged = math.sqrt(sum(value * value for value in residual)) <= tolerance
            if converged:
                break
            preconditioned = [value / degree for value, degree in zip(residual, diagonal)]
            next_rho = sum(a * b for a, b in zip(residual, preconditioned))
            if rho <= 0.0:
                break
            direction = [value + (next_rho / rho) * old
                         for value, old in zip(preconditioned, direction)]
            rho = next_rho
        true_residual = math.sqrt(sum((target - actual) ** 2 for target, actual in zip(rhs, product(values))))
        if (not converged or not math.isfinite(true_residual) or true_residual > tolerance * 4.0
                or any(not math.isfinite(value) or value < -1e-6 or value > 1.0 + 1e-6 for value in values)):
            raise ValueError("拓扑纵向坐标在求解预算内未收敛；请拆分区域或补充根梢锚点")
        result.update({vertex_id: max(0.0, min(1.0, value)) for vertex_id, value in zip(unknown, values)})
    return result


def _custom_bone_distribution(point, rig_obj, matched_chains, character_height, coordinates=None):
    """Distribute explicit chain shares, blending only adjacent rest-pose bones."""
    del character_height  # Kept in the signature for existing callers.
    coordinates = coordinates or {}
    combined = {}
    total_share = 0.0
    for match in matched_chains:
        chain = match["chain"]
        share = float(match.get("share", 1.0))
        if not math.isfinite(share) or share < 0.0:
            raise ValueError("骨链份额必须是有限非负数")
        if share == 0.0:
            continue
        segments = _custom_chain_segments(rig_obj, chain)
        seg_by_name = {s["name"]: s for s in segments}
        is_linear = all(len(s.get("children", [])) <= 1 for s in segments)
        chain_id = chain.get("id", "")
        coordinate_mode = chain.get("coordinate_mode", "PROJECTION")
        if coordinate_mode not in {"PROJECTION", "TOPOLOGY"}:
            raise ValueError(f"未知骨链纵向坐标模式：{coordinate_mode}")
        if coordinate_mode == "TOPOLOGY" and chain_id not in coordinates:
            raise ValueError("拓扑模式缺少已求解的纵向坐标；请指定区域并为每个连通块设置根部和末端锚点")
        blend = float(chain.get("joint_blend", 0.35))
        if not math.isfinite(blend):
            raise ValueError("关节过渡宽度包含无效数值")
        blend = max(0.0, min(0.5, blend))

        local = None
        if is_linear and chain_id in coordinates:
            coordinate = float(coordinates[chain_id])
            if not math.isfinite(coordinate) or coordinate < -1e-8 or coordinate > 1.0 + 1e-8:
                raise ValueError("骨链纵向坐标必须位于 0 到 1")
            coordinate = max(0.0, min(1.0, coordinate))
            arc = coordinate * segments[-1]["end"]
            for previous, following in zip(segments, segments[1:]):
                half_width = blend * min(previous["length"], following["length"])
                joint = previous["end"]
                if half_width > 0.0 and joint - half_width <= arc <= joint + half_width:
                    factor = (arc - joint + half_width) / (2.0 * half_width)
                    smooth = factor * factor * (3.0 - 2.0 * factor)
                    local = {previous["name"]: 1.0 - smooth, following["name"]: smooth}
                    break
            if local is None:
                segment = next((segment for segment in segments if arc <= segment["end"]), segments[-1])
                local = {segment["name"]: 1.0}
        else:
            if not all(math.isfinite(float(value)) for value in point):
                raise ValueError("顶点坐标包含无效数值")
            closest_seg = None
            closest_dist_sq = float("inf")
            closest_factor = 0.0

            for seg in segments:
                factor = max(0.0, min(1.0, (point - seg["head"]).dot(seg["vector"]) / (seg["length"] ** 2)))
                proj = seg["head"] + seg["vector"] * factor
                d_sq = (point - proj).length_squared
                if d_sq < closest_dist_sq:
                    closest_dist_sq = d_sq
                    closest_seg = seg
                    closest_factor = factor

            dist_along = closest_factor * closest_seg["length"]

            pname = closest_seg.get("parent")
            if pname and pname in seg_by_name:
                pseg = seg_by_name[pname]
                half_width = blend * min(pseg["length"], closest_seg["length"])
                if half_width > 0.0 and dist_along <= half_width:
                    t = (half_width + dist_along) / (2.0 * half_width)
                    smooth = t * t * (3.0 - 2.0 * t)
                    local = {pname: 1.0 - smooth, closest_seg["name"]: smooth}

            if local is None:
                cnames = closest_seg.get("children", [])
                if cnames:
                    best_child = None
                    best_child_d_sq = float("inf")
                    for cname in cnames:
                        if cname in seg_by_name:
                            cseg = seg_by_name[cname]
                            cfactor = max(0.0, min(1.0, (point - cseg["head"]).dot(cseg["vector"]) / (cseg["length"] ** 2)))
                            cproj = cseg["head"] + cseg["vector"] * cfactor
                            cd_sq = (point - cproj).length_squared
                            if cd_sq < best_child_d_sq:
                                best_child_d_sq = cd_sq
                                best_child = cseg

                    if best_child is not None:
                        dist_from_tail = closest_seg["length"] - dist_along
                        half_width = blend * min(closest_seg["length"], best_child["length"])
                        if half_width > 0.0 and dist_from_tail <= half_width:
                            pos = half_width - dist_from_tail
                            t = pos / (2.0 * half_width)
                            smooth = t * t * (3.0 - 2.0 * t)
                            local = {closest_seg["name"]: 1.0 - smooth, best_child["name"]: smooth}

            if local is None:
                local = {closest_seg["name"]: 1.0}

        for name, weight in local.items():
            if weight > 0.0:
                combined[name] = combined.get(name, 0.0) + share * weight
        total_share += share
    if not math.isfinite(total_share) or any(not math.isfinite(weight) for weight in combined.values()):
        raise ValueError("骨链份额数值超出可计算范围")
    return {name: weight / total_share for name, weight in combined.items()} if total_share > 0.0 else {}


def _normalized_strongest(weights, limit):
    strongest = sorted(
        ((name, float(weight)) for name, weight in weights.items() if weight > 1e-12),
        key=lambda item: (-item[1], item[0]),
    )[:limit]
    total = sum(weight for _name, weight in strongest)
    return {name: weight / total for name, weight in strongest} if total > 1e-12 else {}


def _combine_base_custom_distribution(base_weights, custom_weights, custom_share):
    custom_share = max(0.0, min(1.0, float(custom_share)))
    base = _normalized_strongest(base_weights, max(len(base_weights), 1))
    custom = _normalized_strongest(custom_weights, max(len(custom_weights), 1))
    if not base or custom_share >= 1.0 - 1e-9:
        return _normalized_strongest(custom, 4)
    if not custom or custom_share <= 1e-9:
        return _normalized_strongest(base, 4)
    if custom_share < 1.0 / 3.0:
        base_slots, custom_slots = 3, 1
    elif custom_share <= 2.0 / 3.0:
        base_slots, custom_slots = 2, 2
    else:
        base_slots, custom_slots = 1, 3
    scaled_base = {name: weight * (1.0 - custom_share) for name, weight in base.items()}
    scaled_custom = {name: weight * custom_share for name, weight in custom.items()}
    selected_names = []
    for source, slot_count in ((scaled_base, base_slots), (scaled_custom, custom_slots)):
        for name, _weight in sorted(source.items(), key=lambda item: (-item[1], item[0]))[:slot_count]:
            if name not in selected_names:
                selected_names.append(name)
    remaining = sorted(
        (
            (name, weight)
            for source in (scaled_base, scaled_custom)
            for name, weight in source.items()
            if name not in selected_names
        ),
        key=lambda item: (-item[1], item[0]),
    )
    for name, _weight in remaining:
        if len(selected_names) >= 4:
            break
        if name not in selected_names:
            selected_names.append(name)
    selected_names = set(selected_names[:4])
    retained_base = _normalized_strongest({name: weight for name, weight in base.items()
                                           if name in selected_names}, 4)
    retained_custom = _normalized_strongest({name: weight for name, weight in custom.items()
                                             if name in selected_names}, 4)
    combined = {}
    for source, share in ((retained_base, 1.0 - custom_share), (retained_custom, custom_share)):
        for name, weight in source.items():
            combined[name] = combined.get(name, 0.0) + share * weight
    return combined


def _custom_chain_effective_blend_steps(settings, matched_chains):
    global_steps = min(max(int(settings.wgame_custom_chain_global_blend_steps), 1), 12)
    return max(
        (
            min(max(int(match["chain"].get("blend_steps_override", 0)), 0), 12) or global_steps
            for match in matched_chains
        ),
        default=global_steps,
    )


def _custom_connection_share(settings, depth, blend_steps):
    minimum = max(
        0.5,
        min(float(settings.wgame_custom_chain_boundary_custom_share), 0.95),
    )
    blend_steps = max(int(blend_steps), 1)
    if depth >= blend_steps:
        return 1.0
    progress = _smooth_unit(max(0.0, float(depth)) / blend_steps)
    return minimum + (1.0 - minimum) * progress


def _build_custom_auto_weight_plan(context, settings, rig_obj, payload=None, only_chain_id=None):
    # References _match_custom_subisland_chains for subisland candidate matching.
    payload = payload or _custom_weight_chain_payload(rig_obj)
    chains = payload.get("chains", [])
    if payload.get("orphaned_regions"):
        raise ValueError("存在无法关联骨链的旧区域记录；请恢复原骨骼名称或 UID 后刷新骨链")
    explicit_index, region_records, blocked_objects, region_errors = _custom_explicit_region_index(context, settings, chains)
    if any(not context.scene.objects.get(error["object"]) for error in region_errors):
        raise ValueError("指定区域的 Mesh 已删除或改名；请先清除对应链的旧区域记录，避免错误自动接管")
    automatic_chains = [chain for chain in chains if not chain.get("regions") and not chain.get("locked")]
    invalid_chains = {}
    for chain in chains:
        try:
            _custom_chain_segments(rig_obj, chain)
        except ValueError as error:
            invalid_chains[chain.get("id")] = str(error)
    automatic_chains = [chain for chain in automatic_chains if chain.get("id") not in invalid_chains]
    character_height = _character_height_in_rig_space(context, settings, rig_obj)
    rig_inverse = rig_obj.matrix_world.inverted()
    plan = []
    unmatched = []
    matched_components = set()
    matched_vertices = 0
    detached_count = 0
    attached_count = 0
    dual_chain_count = 0
    dual_chain_vertices = 0
    multi_chain_subislands = 0
    max_chains_per_subisland = 0
    local_match_vertices = 0
    island_fallback_vertices = 0
    partially_matched_subislands = 0
    shared_vertices = 0
    missing_boundary_samples = 0
    rigid_subislands = 0
    rigid_vertices = 0
    invalid_rigid_subislands = 0
    rigid_assignments = []
    explicit_vertices = 0
    ambiguous_vertices = 0
    locked_skipped_vertices = 0
    scope_skipped_vertices = 0
    reasons = {}
    generic_custom_names = {name for chain in chains
                            if not chain.get("semantic_type", "").startswith("BREAST_")
                            for name in chain.get("bones", [])}
    coverage = {
        chain.get("id", ""): {
            "root_bone": chain.get("root_bone", ""),
            "island_ids": set(),
            "vertices": 0,
        }
        for chain in chains
    }
    islands = _custom_weight_subislands(context, settings)
    for island in islands:
        mesh_obj = island["mesh"]
        if island["object"] in blocked_objects:
            blocked_count = (sum(any(c.get("id") == only_chain_id for c in explicit_index.get((island["object"], v), []))
                                 for v in island["vertex_ids"]) if only_chain_id else len(island["vertex_ids"]))
            # Invalid records were deliberately excluded from the index; use their
            # stored count only for reporting, never as authorization to write.
            if only_chain_id and not blocked_count:
                blocked_count = len(set(island["vertex_ids"]).intersection(
                    v for c in chains if c.get("id") == only_chain_id for r in c.get("regions", [])
                    if r.get("object") == island["object"] for v in r.get("vertex_ids", [])))
            if not blocked_count:
                continue
            unmatched.append({"island": island["id"], "component": island["component_id"],
                              "object": island["object"], "vertices": blocked_count,
                              "reason": "该 Mesh 的显式区域记录已失效；现有权重保留"})
            continue
        rigid_record = _rigid_attachment_record_for_island(rig_obj, island)
        if rigid_record:
            if only_chain_id:
                scope_skipped_vertices += len(island["vertex_ids"])
                continue
            target_bone = rigid_record.get("target_bone", "")
            target = rig_obj.data.bones.get(target_bone)
            if not target or not target.use_deform:
                invalid_rigid_subislands += 1
                unmatched.append(
                    {
                        "island": island["id"],
                        "component": island["component_id"],
                        "object": island["object"],
                        "vertices": len(island["vertex_ids"]),
                        "rigid": True,
                        "reason": "刚性附件目标骨不存在或不是 Deform 骨",
                        "nearest_chain": target_bone,
                        "nearest_distance": None,
                        "nearest_radius": None,
                    }
                )
                continue
            for vertex_id in island["vertex_ids"]:
                plan.append((island["object"], vertex_id, [(target_bone, 1.0)]))
            vertex_count = len(island["vertex_ids"])
            rigid_subislands += 1
            rigid_vertices += vertex_count
            matched_vertices += vertex_count
            detached_count += not island["attached"]
            attached_count += bool(island["attached"])
            if island["component_id"]:
                matched_components.add(island["component_id"])
            rigid_assignments.append(
                {
                    "island": island["id"],
                    "component": island["component_id"],
                    "object": island["object"],
                    "vertices": vertex_count,
                    "target_bone": target_bone,
                }
            )
            continue
        transform = rig_inverse @ mesh_obj.matrix_world
        points = [transform @ mesh_obj.data.vertices[vertex_id].co for vertex_id in island["vertex_ids"]]
        points_by_id = dict(zip(island["vertex_ids"], points))
        owners = {v: explicit_index.get((island["object"], v), []) for v in island["vertex_ids"]}
        shares, share_errors = _custom_shared_region_shares(island, points_by_id, owners)
        coordinates, coordinate_errors = {}, {}
        explicit_chains = {chain.get("id"): chain for items in owners.values() for chain in items}
        for chain_id, chain in explicit_chains.items():
            if only_chain_id and chain_id != only_chain_id:
                continue
            if chain.get("locked") or not chain.get("enabled", True):
                continue
            record = region_records[(island["object"], chain_id)]
            region_ids = set(record["vertex_ids"]) & island["vertex_set"]
            try:
                coordinates[chain_id] = _custom_region_coordinates(
                    island, points_by_id, rig_obj, chain, region_ids,
                    roots=record.get("roots", []), tips=record.get("tips", []),
                )
            except ValueError as error:
                coordinate_errors[chain_id] = str(error)
        nearest = None
        boundary_samples = _custom_boundary_samples(island, rig_obj) if island["attached"] else {}
        # Base neighbours can include dedicated breast bones, but must not reintroduce
        # a neighbouring hair/skirt chain outside its declared region.
        boundary_samples = {
            v: filtered for v, sample in boundary_samples.items()
            for filtered in [_normalized_strongest({name: weight for name, weight in sample.items()
                                                     if name not in generic_custom_names}, 4)] if filtered
        }
        island_planned_vertices = 0
        island_unmatched_vertices = []
        island_reasons = collections.Counter()
        island_chain_ids = set()
        for vertex_id, point in zip(island["vertex_ids"], points):
            assigned = owners[vertex_id]
            if only_chain_id and not any(chain.get("id") == only_chain_id for chain in assigned):
                scope_skipped_vertices += 1
                continue
            if any(chain.get("locked") for chain in assigned
                   if not only_chain_id or chain.get("id") == only_chain_id):
                locked_skipped_vertices += 1
                continue
            reason = ""
            vertex_coordinates = {}
            local_matched = []
            if assigned:
                solving = [chain for chain in assigned if not only_chain_id or chain.get("id") == only_chain_id]
                if any(not chain.get("enabled", True) for chain in solving):
                    reason = "指定区域包含禁用链；不会改用其他链接管"
                elif vertex_id in share_errors:
                    reason = share_errors[vertex_id]
                else:
                    reason = next((coordinate_errors[c.get("id")] for c in solving
                                   if c.get("id") in coordinate_errors), "")
                if only_chain_id and len(assigned) > 1 and not reason:
                    existing = _normalized_existing_deform_weights(mesh_obj, rig_obj, vertex_id)
                    if any(not any(existing.get(name, 0.0) > 1e-8 for name in chain.get("bones", []))
                           for chain in assigned if chain.get("id") != only_chain_id):
                        reason = "共享区尚未建立另一条链的权重；请先生成全部"
                matched = [{"chain": chain, "share": shares.get(vertex_id, {}).get(chain.get("id"), 1.0)}
                           for chain in solving] if not reason else []
                if not reason:
                    vertex_coordinates = {c.get("id"): coordinates[c.get("id")][vertex_id] for c in solving}
            else:
                local_matched, nearest = _match_custom_vertex_chains(point, rig_obj, automatic_chains)
                matched = local_matched
                if not matched:
                    reason = nearest.get("reason", "超出自动候选半径，请显式指定区域") if nearest else "没有可自动匹配的有效骨链，请显式指定区域"
                    ambiguous_vertices += bool(nearest and nearest.get("reason"))
            if not matched:
                island_unmatched_vertices.append(vertex_id)
                island_reasons[reason] += 1
                continue
            local_match_vertices += bool(local_matched)
            blend_steps = _custom_chain_effective_blend_steps(settings, matched)
            try:
                custom_weights = _custom_bone_distribution(point, rig_obj, matched, character_height,
                                                           coordinates=vertex_coordinates or None)
            except ValueError as error:
                island_unmatched_vertices.append(vertex_id)
                island_reasons[str(error)] += 1
                continue
            if not custom_weights:
                island_unmatched_vertices.append(vertex_id)
                island_reasons["链内权重求解没有有效结果"] += 1
                continue
            if only_chain_id and len(assigned) > 1:
                # The writer freezes the other chain's absolute budget. Keep this
                # chain's intended ratio to Base before rescaling that remainder.
                own_share = shares[vertex_id][only_chain_id]
                custom_weights = {name: weight * own_share for name, weight in custom_weights.items()}
            assignments = custom_weights
            if island["attached"] and boundary_samples:
                base_weights, depth = _propagated_boundary_profile(
                    vertex_id,
                    island,
                    boundary_samples,
                    blend_steps,
                )
                if base_weights and depth is not None and depth < blend_steps:
                    custom_share = _custom_connection_share(settings, depth, blend_steps)
                    if len(assigned) > 1:
                        # Preserve both explicit chain shares and all adjacent-bone blends.
                        # A four-influence budget cannot always fit two chains plus Base.
                        assignments = {name: weight * custom_share for name, weight in custom_weights.items()}
                        for name, weight in base_weights.items():
                            assignments[name] = assignments.get(name, 0.0) + weight * (1.0 - custom_share)
                        assignments = {name: weight for name, weight in assignments.items() if weight > 1e-12}
                        if len(assignments) > 4:
                            island_unmatched_vertices.append(vertex_id)
                            island_reasons["共享链与基础衔接超过4骨容量；请缩窄关节过渡或调整共享带"] += 1
                            continue
                    else:
                        assignments = _combine_base_custom_distribution(base_weights, custom_weights, custom_share)
                    shared_vertices += bool(base_weights and custom_weights and 1e-9 < custom_share < 1.0 - 1e-9)
            if not assignments:
                island_unmatched_vertices.append(vertex_id)
                continue
            plan.append((island["object"], vertex_id, sorted(assignments.items())))
            island_planned_vertices += 1
            matched_vertices += 1
            explicit_vertices += bool(assigned)
            active_chain_ids = set()
            for match in matched:
                chain = match["chain"]
                chain_id = chain.get("id", "")
                if not any(assignments.get(name, 0.0) > 1e-8 for name in chain.get("bones", [])):
                    continue
                active_chain_ids.add(chain_id)
                island_chain_ids.add(chain_id)
                chain_coverage = coverage.setdefault(
                    chain_id,
                    {"root_bone": chain.get("root_bone", ""), "island_ids": set(), "vertices": 0},
                )
                chain_coverage["island_ids"].add(island["id"])
                chain_coverage["vertices"] += 1
            dual_chain_vertices += len(active_chain_ids) == 2
        reasons.update({island["id"] + ":" + key: value for key, value in island_reasons.items()})
        reason_text = "；".join(f"{reason}（{count}顶点）" for reason, count in island_reasons.items())
        if not island_planned_vertices and island_unmatched_vertices:
            unmatched.append(
                {
                    "island": island["id"],
                    "component": island["component_id"],
                    "object": island["object"],
                    "vertices": len(island_unmatched_vertices),
                    "reason": reason_text,
                    "nearest_chain": nearest["chain"].get("root_bone", "") if nearest else "",
                    "nearest_distance": nearest["median_distance"] if nearest else None,
                    "nearest_radius": nearest["radius"] if nearest else None,
                }
            )
            continue
        if not island_planned_vertices:
            continue
        attached_count += bool(island["attached"])
        detached_count += not island["attached"]
        dual_chain_count += len(island_chain_ids) >= 2
        multi_chain_subislands += len(island_chain_ids) > 2
        max_chains_per_subisland = max(max_chains_per_subisland, len(island_chain_ids))
        partially_matched_subislands += bool(island_unmatched_vertices)
        if island["component_id"]:
            matched_components.add(island["component_id"])
        if island["attached"] and not boundary_samples:
            missing_boundary_samples += 1
        if island_unmatched_vertices:
            unmatched.append(
                {
                    "island": island["id"],
                    "component": island["component_id"],
                    "object": island["object"],
                    "vertices": len(island_unmatched_vertices),
                    "partial": True,
                    "reason": reason_text,
                    "nearest_chain": nearest["chain"].get("root_bone", "") if nearest else "",
                    "nearest_distance": nearest["median_distance"] if nearest else None,
                    "nearest_radius": nearest["radius"] if nearest else None,
                }
            )
    unmatched_vertices = sum(item["vertices"] for item in unmatched)
    unmatched_component_ids = sorted({item["component"] for item in unmatched if item["component"]})
    serialized_coverage = []
    for key in sorted(coverage):
        item = coverage[key]
        serialized_coverage.append(
            {
                "root_bone": item["root_bone"],
                "islands": len(item["island_ids"]),
                "vertices": item["vertices"],
            }
        )
    unmatched_subislands = sum(1 for item in unmatched if not item.get("partial"))
    return plan, {
        "matching_mode": "EXPLICIT_REGIONS_ARC_LENGTH_V2",
        "scope": "CURRENT" if only_chain_id else "ALL",
        "explicit_vertices": explicit_vertices,
        "ambiguous_vertices": ambiguous_vertices,
        "locked_skipped_vertices": locked_skipped_vertices,
        "scope_skipped_vertices": scope_skipped_vertices,
        "invalid_regions": region_errors,
        "invalid_chains": invalid_chains,
        "boundary_custom_share": float(settings.wgame_custom_chain_boundary_custom_share),
        "discovered_chains": len(chains),
        "enabled_chains": sum(1 for chain in chains if chain.get("enabled", True)),
        "custom_subislands": len(islands),
        "detached_subislands": detached_count,
        "attached_subislands": attached_count,
        "dual_chain_subislands": dual_chain_count,
        "dual_chain_vertices": dual_chain_vertices,
        "multi_chain_subislands": multi_chain_subislands,
        "max_chains_per_subisland": max_chains_per_subisland,
        "local_match_vertices": local_match_vertices,
        "island_fallback_vertices": island_fallback_vertices,
        "partially_matched_subislands": partially_matched_subislands,
        "matched_subislands": attached_count + detached_count,
        "matched_components": len(matched_components),
        "matched_component_ids": sorted(matched_components),
        "matched_vertices": matched_vertices,
        "unmatched_subislands": unmatched_subislands,
        "unmatched_components": len(unmatched_component_ids),
        "unmatched_component_ids": unmatched_component_ids,
        "unmatched_vertices": unmatched_vertices,
        "shared_vertices": shared_vertices,
        "missing_boundary_samples": missing_boundary_samples,
        "rigid_subislands": rigid_subislands,
        "rigid_vertices": rigid_vertices,
        "invalid_rigid_subislands": invalid_rigid_subislands,
        "rigid_assignments": rigid_assignments,
        "unmatched": unmatched,
        "chain_coverage": serialized_coverage,
    }


def _base_anatomical_regions(rig_obj, snapshot):
    available = {
        name
        for name, entry in snapshot.items()
        if entry.get("use_deform") and name != "root.x" and rig_obj.data.bones.get(name)
    }

    def existing(names):
        return [name for name in names if name in available]

    return {
        "CENTER": existing(("pelvis.x", "spine_01.x", "spine_02.x", "upper_chest.x")),
        "NECK": existing(("upper_chest.x", "neck.x")),
        "HEAD": existing(("neck.x", "head.x")),
        "SHOULDER_L": existing(("upper_chest.x", "shoulder.l", "upper_arm.l")),
        "SHOULDER_R": existing(("upper_chest.x", "shoulder.r", "upper_arm.r")),
        "ARM_L": existing(("shoulder.l", "upper_arm.l", "forearm.l", "hand.l")),
        "ARM_R": existing(("shoulder.r", "upper_arm.r", "forearm.r", "hand.r")),
        "LEG_L": existing(("thigh.l", "lower_leg.l", "foot.l", "toes.l")),
        "LEG_R": existing(("thigh.r", "lower_leg.r", "foot.r", "toes.r")),
    }


def _closest_anatomical_region(point, rig_obj, regions):
    candidates = []
    for region_name, names in regions.items():
        if names:
            candidates.append(
                (
                    min(_rig_bone_segment_distance(point, rig_obj.data.bones[name]) for name in names),
                    region_name,
                )
            )
    return min(candidates)[1] if candidates else "CENTER"


def _arm_lateral_projection(point, rig_obj, side):
    shoulder = rig_obj.data.bones.get("shoulder" + side)
    upper_arm = rig_obj.data.bones.get("upper_arm" + side)
    if not upper_arm:
        return float("-inf")
    lateral_axis = None
    if shoulder:
        shoulder_axis = shoulder.tail_local - shoulder.head_local
        if shoulder_axis.length_squared > 1e-12:
            lateral_axis = shoulder_axis.normalized()
    if lateral_axis is None:
        arm_axis = upper_arm.tail_local - upper_arm.head_local
        arm_axis.z = 0.0
        if arm_axis.length_squared <= 1e-12:
            return float("-inf")
        lateral_axis = arm_axis.normalized()
    return (point - upper_arm.head_local).dot(lateral_axis)


def _upper_arm_root_transition_length(rig_obj, side, character_height):
    shoulder = rig_obj.data.bones.get("shoulder" + side)
    preferred = shoulder.length * 0.65 if shoulder else character_height * 0.03
    return max(character_height * 0.015, min(character_height * 0.04, preferred))


def _finalize_joint_limited_weights(weights, protected_names=(), preferred_names=()):
    protected_names = set(protected_names)
    # Joint-boundary limiting can intentionally create a sub-1% parent support
    # weight. Dropping it and renormalizing the protected child back to 1.0
    # would immediately violate the limit we just calculated.
    retained = {name: weight for name, weight in weights.items() if weight > 1e-8}
    if len(retained) > 4:
        retained = dict(sorted(retained.items(), key=lambda item: item[1], reverse=True)[:4])
    discarded = sum(weight for name, weight in weights.items() if name not in retained)
    if not retained and weights:
        name, weight = max(weights.items(), key=lambda item: item[1])
        retained[name] = weight
        discarded = sum(value for other_name, value in weights.items() if other_name != name)
    if discarded > 1e-8 and retained:
        target_name = next(
            (
                name
                for name in preferred_names
                if name in retained and name not in protected_names
            ),
            None,
        )
        if target_name is None:
            support_names = [name for name in retained if name not in protected_names]
            target_name = max(support_names or list(retained), key=lambda name: retained[name])
        retained[target_name] += discarded
    total = sum(retained.values())
    return [(name, weight / total) for name, weight in retained.items()] if total > 1e-8 else []


def _limit_upper_arm_root_weights(point, rig_obj, assignments, character_height):
    weights = {name: float(weight) for name, weight in assignments if weight > 1e-8}
    for side in (".l", ".r"):
        upper_arm_name = "upper_arm" + side
        current_weight = weights.get(upper_arm_name, 0.0)
        if current_weight <= 0.0:
            continue
        lateral_projection = _arm_lateral_projection(point, rig_obj, side)
        transition = _upper_arm_root_transition_length(rig_obj, side, character_height)
        factor = max(0.0, min(1.0, lateral_projection / max(transition, 1e-6)))
        maximum_weight = factor * factor * (3.0 - 2.0 * factor)
        if current_weight <= maximum_weight + 1e-8:
            continue
        remaining_names = [name for name in weights if name != upper_arm_name]
        remaining_total = sum(weights[name] for name in remaining_names)
        weights[upper_arm_name] = maximum_weight
        if remaining_total > 1e-8:
            scale = (1.0 - maximum_weight) / remaining_total
            for name in remaining_names:
                weights[name] *= scale
        else:
            support_names = [
                name
                for name in ("upper_chest.x", "shoulder" + side)
                if rig_obj.data.bones.get(name)
            ]
            support = _normalized_anatomical_weights(point, rig_obj, support_names)
            for name, weight in support:
                weights[name] = weights.get(name, 0.0) + weight * (1.0 - maximum_weight)
    return _finalize_joint_limited_weights(
        weights,
        protected_names={"upper_arm.l", "upper_arm.r"},
        preferred_names=("shoulder.l", "shoulder.r", "upper_chest.x"),
    )


def _child_joint_projection(point, rig_obj, child_name, parent_name):
    child = rig_obj.data.bones.get(child_name)
    parent = rig_obj.data.bones.get(parent_name)
    if not child or not parent:
        return float("-inf")
    parent_axis = parent.tail_local - parent.head_local
    if parent_axis.length_squared <= 1e-12:
        return float("-inf")
    return (point - child.head_local).dot(parent_axis.normalized())


def _child_joint_transition_length(rig_obj, parent_name, character_height):
    parent = rig_obj.data.bones.get(parent_name)
    preferred = parent.length * 0.15 if parent else character_height * 0.02
    return max(character_height * 0.012, min(character_height * 0.03, preferred))


def _joint_axis_projection(point, rig_obj, child_name, parent_name, axis_source="PARENT"):
    child = rig_obj.data.bones.get(child_name)
    parent = rig_obj.data.bones.get(parent_name)
    if not child or not parent:
        return float("-inf")
    axis_bone = child if axis_source == "CHILD" else parent
    axis = axis_bone.tail_local - axis_bone.head_local
    if axis.length_squared <= 1e-12:
        return float("-inf")
    return (point - child.head_local).dot(axis.normalized())


def _distal_joint_transition_length(rig_obj, child_name, character_height, kind):
    child = rig_obj.data.bones.get(child_name)
    child_length = child.length if child else character_height * 0.01
    if kind == "FINGER":
        return max(character_height * 0.0015, min(character_height * 0.006, child_length * 0.25))
    if kind == "TOES":
        return max(character_height * 0.005, min(character_height * 0.012, child_length * 0.20))
    if kind == "HAND":
        return max(character_height * 0.005, min(character_height * 0.012, child_length * 0.25))
    if kind == "FOOT":
        return max(character_height * 0.008, min(character_height * 0.020, child_length * 0.25))
    if kind == "SHOULDER":
        return max(character_height * 0.006, min(character_height * 0.015, child_length * 0.25))
    return max(character_height * 0.005, min(character_height * 0.015, child_length * 0.25))


def _joint_band_maximum_weight(projection, transition):
    factor = max(
        0.0,
        min(1.0, (projection + transition) / max(transition * 2.0, 1e-6)),
    )
    return factor * factor * (3.0 - 2.0 * factor)


def _distal_joint_specs():
    specs = []
    for segment in (3, 2, 1):
        for prefix in ("thumb", "index", "middle", "ring", "pinky"):
            for side in (".l", ".r"):
                child_name = f"{prefix}_{segment:02d}{side}"
                parent_name = (
                    "hand" + side
                    if segment == 1
                    else f"{prefix}_{segment - 1:02d}{side}"
                )
                specs.append(
                    (child_name, parent_name, "CHILD" if segment == 1 else "PARENT", "FINGER")
                )
    for side in (".l", ".r"):
        specs.extend(
            (
                ("toes" + side, "foot" + side, "PARENT", "TOES"),
                ("hand" + side, "forearm" + side, "PARENT", "HAND"),
                ("foot" + side, "lower_leg" + side, "PARENT", "FOOT"),
            )
        )
    return specs


def _limit_distal_joint_weights(point, rig_obj, assignments, character_height):
    weights = {name: float(weight) for name, weight in assignments if weight > 1e-8}
    protected_names = set()
    preferred_names = []
    for child_name, parent_name, axis_source, kind in _distal_joint_specs():
        current_weight = weights.get(child_name, 0.0)
        if current_weight <= 0.0 or not rig_obj.data.bones.get(parent_name):
            continue
        projection = _joint_axis_projection(
            point,
            rig_obj,
            child_name,
            parent_name,
            axis_source,
        )
        transition = _distal_joint_transition_length(
            rig_obj,
            child_name,
            character_height,
            kind,
        )
        maximum_weight = _joint_band_maximum_weight(projection, transition)
        if current_weight > maximum_weight + 1e-8:
            removed = current_weight - maximum_weight
            weights[child_name] = maximum_weight
            weights[parent_name] = weights.get(parent_name, 0.0) + removed
        protected_names.add(child_name)
        preferred_names.append(parent_name)
    return _finalize_joint_limited_weights(
        weights,
        protected_names=protected_names,
        preferred_names=preferred_names,
    )


def _limit_shoulder_root_weights(point, rig_obj, assignments, character_height):
    weights = {name: float(weight) for name, weight in assignments if weight > 1e-8}
    protected_names = set()
    for side in (".l", ".r"):
        child_name = "shoulder" + side
        parent_name = "upper_chest.x"
        current_weight = weights.get(child_name, 0.0)
        if current_weight <= 0.0 or not rig_obj.data.bones.get(parent_name):
            continue
        projection = _joint_axis_projection(point, rig_obj, child_name, parent_name, "CHILD")
        transition = _distal_joint_transition_length(
            rig_obj,
            child_name,
            character_height,
            "SHOULDER",
        )
        maximum_weight = _joint_band_maximum_weight(projection, transition)
        if current_weight > maximum_weight + 1e-8:
            removed = current_weight - maximum_weight
            weights[child_name] = maximum_weight
            weights[parent_name] = weights.get(parent_name, 0.0) + removed
        protected_names.add(child_name)
    return _finalize_joint_limited_weights(
        weights,
        protected_names=protected_names,
        preferred_names=("upper_chest.x",),
    )


def _limit_limb_child_root_weights(point, rig_obj, assignments, character_height):
    weights = {name: float(weight) for name, weight in assignments if weight > 1e-8}
    protected_names = set()
    preferred_names = []
    for child_base, parent_base in (("forearm", "upper_arm"), ("lower_leg", "thigh")):
        for side in (".l", ".r"):
            child_name = child_base + side
            parent_name = parent_base + side
            current_weight = weights.get(child_name, 0.0)
            if current_weight <= 0.0:
                continue
            projection = _child_joint_projection(point, rig_obj, child_name, parent_name)
            transition = _child_joint_transition_length(rig_obj, parent_name, character_height)
            maximum_weight = _joint_band_maximum_weight(projection, transition)
            if current_weight > maximum_weight + 1e-8:
                removed = current_weight - maximum_weight
                weights[child_name] = maximum_weight
                if rig_obj.data.bones.get(parent_name):
                    weights[parent_name] = weights.get(parent_name, 0.0) + removed
            protected_names.add(child_name)
            preferred_names.append(parent_name)
    return _finalize_joint_limited_weights(
        weights,
        protected_names=protected_names,
        preferred_names=preferred_names,
    )


def _limit_base_joint_weights(point, rig_obj, assignments, character_height):
    assignments = _limit_distal_joint_weights(
        point,
        rig_obj,
        assignments,
        character_height,
    )
    assignments = _limit_limb_child_root_weights(
        point,
        rig_obj,
        assignments,
        character_height,
    )
    assignments = _limit_upper_arm_root_weights(
        point,
        rig_obj,
        assignments,
        character_height,
    )
    return _limit_shoulder_root_weights(
        point,
        rig_obj,
        assignments,
        character_height,
    )


def _anatomical_region_for_point(point, rig_obj, regions, character_height):
    neck = rig_obj.data.bones.get("neck.x")
    head = rig_obj.data.bones.get("head.x")
    upper_left = rig_obj.data.bones.get("upper_arm.l")
    upper_right = rig_obj.data.bones.get("upper_arm.r")
    if head and point.z >= head.head_local.z:
        return "HEAD"
    pelvis = rig_obj.data.bones.get("pelvis.x")
    if pelvis and point.z < pelvis.head_local.z - character_height * 0.02:
        selected = "LEG_L" if point.x >= 0.0 else "LEG_R"
        return selected if regions.get(selected) else _closest_anatomical_region(point, rig_obj, regions)
    shoulder_extent = max(
        abs(upper_left.head_local.x) if upper_left else 0.0,
        abs(upper_right.head_local.x) if upper_right else 0.0,
        character_height * 0.04,
    )
    side = ".l" if point.x >= 0.0 else ".r"
    shoulder = rig_obj.data.bones.get("shoulder" + side)
    upper_arm = rig_obj.data.bones.get("upper_arm" + side)
    upper_chest = rig_obj.data.bones.get("upper_chest.x")
    if shoulder and upper_arm and upper_chest:
        shoulder_projection = _arm_lateral_projection(point, rig_obj, side)
        inner_extent = abs(shoulder.head_local.x) * 0.7
        in_shoulder_height = (
            point.z >= upper_chest.head_local.z - character_height * 0.01
            and point.z < head.head_local.z if head else point.z <= upper_chest.tail_local.z
        )
        if in_shoulder_height and abs(point.x) >= inner_extent and shoulder_projection <= character_height * 0.025:
            return "SHOULDER_L" if point.x >= 0.0 else "SHOULDER_R"
    if neck and point.z >= neck.head_local.z:
        return "NECK"
    if abs(point.x) <= shoulder_extent * 1.1:
        return "CENTER"
    side_suffix = "L" if point.x >= 0.0 else "R"
    arm_region = "ARM_" + side_suffix
    leg_region = "LEG_" + side_suffix
    arm_distance = min(
        (_rig_bone_segment_distance(point, rig_obj.data.bones[name]) for name in regions.get(arm_region, ())),
        default=float("inf"),
    )
    leg_distance = min(
        (_rig_bone_segment_distance(point, rig_obj.data.bones[name]) for name in regions.get(leg_region, ())),
        default=float("inf"),
    )
    selected = arm_region if arm_distance <= leg_distance else leg_region
    return selected if regions.get(selected) else _closest_anatomical_region(point, rig_obj, regions)


def _base_authority_component_ids(context, settings, rig_obj, regions, character_height):
    best_by_region = {}
    best_bilateral_by_zone = {}
    largest = None
    source_regions = {"CENTER", "HEAD", "ARM_L", "ARM_R", "LEG_L", "LEG_R"}
    custom_by_object = _custom_mask_vertex_ids_by_object(context, settings)
    base_region_assignments = _base_region_assignments_by_object(context, settings)
    lateral_threshold = character_height * 0.04

    pelvis_bone = rig_obj.data.bones.get("pelvis.x")
    neck_bone = rig_obj.data.bones.get("neck.x")
    p_z = pelvis_bone.head_local.z if pelvis_bone else character_height * 0.55
    n_z = neck_bone.head_local.z if neck_bone else character_height * 0.85

    for component in _unrigged_components(settings):
        obj = context.scene.objects.get(component.get("object", ""))
        if not obj or obj.type != "MESH":
            continue
        base_ids = _component_vertex_ids_for_scope(
            context,
            settings,
            component,
            "BASE_SKIN",
            custom_by_object,
        )
        if not base_ids:
            continue
        transform = rig_obj.matrix_world.inverted() @ obj.matrix_world
        points = [
            transform @ obj.data.vertices[vertex_id].co
            for vertex_id in base_ids
            if 0 <= vertex_id < len(obj.data.vertices)
        ]
        if not points:
            continue
        center = sum(points, Vector()) / len(points)
        min_x = min(p.x for p in points)
        max_x = max(p.x for p in points)
        is_bilateral = min_x < -lateral_threshold and max_x > lateral_threshold

        explicit_regions = {
            base_region_assignments.get(obj.name, {}).get(vertex_id)
            for vertex_id in base_ids
        }
        explicit_regions.discard(None)
        full_component_region = (
            next(iter(explicit_regions))
            if len(explicit_regions) == 1
            and all(vertex_id in base_region_assignments.get(obj.name, {}) for vertex_id in base_ids)
            else ""
        )
        region_name = full_component_region or _anatomical_region_for_point(center, rig_obj, regions, character_height)
        vertex_count = len(base_ids)
        candidate = (vertex_count, component.get("id", ""))

        if is_bilateral:
            if center.z >= n_z:
                zone = "HEAD"
            elif center.z >= p_z - character_height * 0.05:
                zone = "TORSO"
            else:
                zone = "LOWER_BODY"
            if zone not in best_bilateral_by_zone or candidate > best_bilateral_by_zone[zone]:
                best_bilateral_by_zone[zone] = candidate
            if region_name in {"CENTER", "HEAD"} and (region_name not in best_by_region or candidate > best_by_region[region_name]):
                best_by_region[region_name] = candidate
        else:
            if region_name in source_regions and (region_name not in best_by_region or candidate > best_by_region[region_name]):
                best_by_region[region_name] = candidate

        if largest is None or candidate > largest:
            largest = candidate

    result = {component_id for _count, component_id in best_by_region.values() if component_id}
    if largest and largest[1]:
        result.add(largest[1])
    for _count, component_id in best_bilateral_by_zone.values():
        if component_id:
            result.add(component_id)

    authority_by_region = {
        region: component_id for region, (_count, component_id) in best_by_region.items()
    }
    authority_by_region.update({
        "BILATERAL_" + zone: component_id
        for zone, (_count, component_id) in best_bilateral_by_zone.items()
    })
    if largest and largest[1] not in authority_by_region.values():
        authority_by_region["LARGEST"] = largest[1]
    return result, authority_by_region



def _base_triangle_coordinates(point, triangle):
    """Barycentric coordinates on a non-degenerate rest-space triangle."""
    a, b, c = triangle
    first, second, offset = b - a, c - a, point - a
    aa, ab, bb = first.dot(first), first.dot(second), second.dot(second)
    determinant = aa * bb - ab * ab
    # Relative degeneracy check is invariant under a uniform geometry scale.
    if aa <= 0.0 or bb <= 0.0 or determinant <= aa * bb * 1e-12:
        return None
    x = (bb * offset.dot(first) - ab * offset.dot(second)) / determinant
    y = (aa * offset.dot(second) - ab * offset.dot(first)) / determinant
    result = (1.0 - x - y, x, y)
    if any(not math.isfinite(value) or value < -1e-5 or value > 1.0 + 1e-5 for value in result):
        return None
    result = tuple(max(0.0, min(1.0, value)) for value in result)
    total = sum(result)
    return tuple(value / total for value in result) if total > 0.0 else None


def _base_build_transfer_surfaces(context, rig_obj, authority_vertices, plan, vertex_regions):
    """Only complete, same-region authority triangles can provide weights.

    Rest mesh loop triangles preserve original vertex indices, including n-gon
    tessellation. Loose points/edges, masked faces and anatomical boundaries
    intentionally have no surface source; their targets use the direct solver.
    """
    batches = {}
    rig_inverse = rig_obj.matrix_world.inverted()
    for object_name, vertex_ids in authority_vertices.items():
        mesh_obj = context.scene.objects.get(object_name)
        if not mesh_obj or mesh_obj.type != "MESH":
            continue
        mesh_obj.data.calc_loop_triangles()
        transform = rig_inverse @ mesh_obj.matrix_world
        object_plan = plan.get(object_name, {})
        object_regions = vertex_regions.get(object_name, {})
        points = {
            vertex_id: transform @ mesh_obj.data.vertices[vertex_id].co
            for vertex_id in vertex_ids
        }
        for loop_triangle in mesh_obj.data.loop_triangles:
            ids = tuple(loop_triangle.vertices)
            if len(ids) != 3 or any(index not in object_plan or index not in points for index in ids):
                continue
            names = {object_regions.get(index, "") for index in ids}
            if len(names) != 1 or not next(iter(names)):
                continue
            triangle = tuple(points[index] for index in ids)
            if _base_triangle_coordinates(triangle[0], triangle) is None:
                continue
            region_name = next(iter(names))
            batch = batches.setdefault(region_name, {"points": [], "polygons": [], "triangles": [], "weights": []})
            offset = len(batch["points"])
            batch["points"].extend(triangle)
            batch["polygons"].append((offset, offset + 1, offset + 2))
            batch["triangles"].append(triangle)
            batch["weights"].append(tuple(object_plan[index] for index in ids))
    result = {}
    for region_name, batch in batches.items():
        tree = BVHTree.FromPolygons(batch["points"], batch["polygons"], all_triangles=True)
        if tree is not None:
            result[region_name] = {
                "tree": tree, "triangles": batch["triangles"], "weights": batch["weights"],
            }
    return result


def _base_transfer_is_compatible(point, rig_obj, assignments, direct_assignments, character_height, region_name):
    """Nearby cloth must agree with the target's own anatomical support."""
    weights = dict(assignments)
    direct = dict(direct_assignments)
    if not weights or not direct:
        return False
    if any(not math.isfinite(value) or value < 0.0 for value in weights.values()):
        return False
    # This compares distributions, so a LEG_R label alone cannot let a calf
    # surface claim a toe. A transfer may still smooth a legitimate joint blend.
    overlap = sum(min(weight, direct.get(name, 0.0)) for name, weight in weights.items())
    if overlap < 0.5 - 1e-8:
        return False
    expected = _base_expected_distal_support(point, rig_obj, character_height, region_name)
    return all(
        _base_distal_support_weight(assignments, name) + 1e-8 >= minimum
        for name, minimum in expected.items()
    )


def _base_surface_transfer_weights(point, surface, rig_obj, direct_assignments, character_height, region_name):
    """Nearest triangle interpolation with bounded, continuous distance fade."""
    if not surface or not direct_assignments:
        return []
    maximum_distance = character_height * 0.05
    if maximum_distance <= 0.0:
        return []
    hit = surface["tree"].find_nearest(point, maximum_distance)
    if not hit or hit[0] is None or hit[2] is None or hit[3] is None:
        return []
    nearest_point, _normal, triangle_index, distance = hit
    if not math.isfinite(distance) or distance < 0.0 or distance >= maximum_distance:
        return []
    if triangle_index < 0 or triangle_index >= len(surface["triangles"]):
        return []
    factors = _base_triangle_coordinates(nearest_point, surface["triangles"][triangle_index])
    if factors is None:
        return []
    weights = {}
    for factor, assignments in zip(factors, surface["weights"][triangle_index]):
        for name, weight in assignments:
            weights[name] = weights.get(name, 0.0) + factor * weight
    transferred = _limit_base_joint_weights(point, rig_obj, list(weights.items()), character_height)
    if not _base_transfer_is_compatible(
        point, rig_obj, transferred, direct_assignments, character_height, region_name,
    ):
        return []
    factor = max(0.0, min(1.0, distance / maximum_distance))
    source_share = 1.0 - factor * factor * (3.0 - 2.0 * factor)
    if source_share <= 1e-8:
        return []
    weights = {name: weight * source_share for name, weight in transferred}
    for name, weight in direct_assignments:
        weights[name] = weights.get(name, 0.0) + (1.0 - source_share) * weight
    blended = _limit_base_joint_weights(point, rig_obj, list(weights.items()), character_height)
    return blended if _base_transfer_is_compatible(
        point, rig_obj, blended, direct_assignments, character_height, region_name,
    ) else []


def _base_direct_assignments(point, rig_obj, snapshot, regions, character_height, forced_region=""):
    if forced_region == "HEAD" and rig_obj.data.bones.get("head.x"):
        return [("head.x", 1.0)]
    candidates = _base_anatomical_candidate_names(
        point, rig_obj, snapshot, regions, character_height, forced_region=forced_region,
    )
    return _limit_base_joint_weights(
        point, rig_obj, _normalized_anatomical_weights(point, rig_obj, candidates), character_height,
    )


def _base_weight_plan_error(context, base_by_object, plan, deform_names):
    """Validate the complete result before the first old weight is removed."""
    data_owners = {}
    for object_name, raw_ids in base_by_object.items():
        mesh_obj = context.scene.objects.get(object_name)
        if not mesh_obj or mesh_obj.type != "MESH":
            return f"组件记录中的 Mesh 已丢失：{object_name}"
        vertex_ids = set(raw_ids)
        rows = plan.get(object_name, {})
        if set(rows) != vertex_ids:
            return f"{object_name} 的求解结果未覆盖全部基础顶点；原权重未修改"
        for vertex_id, assignments in rows.items():
            if vertex_id < 0 or vertex_id >= len(mesh_obj.data.vertices):
                return f"{object_name} 的组件顶点记录已失效"
            names = [name for name, _weight in assignments]
            if (
                not assignments or len(assignments) > 4 or len(set(names)) != len(names)
                or any(name not in deform_names for name in names)
                or any(not math.isfinite(weight) or weight < 0.0 for _name, weight in assignments)
                or abs(sum(weight for _name, weight in assignments) - 1.0) > 1e-5
            ):
                return f"{object_name} 顶点 {vertex_id} 的基础权重求解无效；原权重未修改"
        # Mesh deform data is shared while vertex-group names are object data.
        # Writing it through one object could alter a different binding scope.
        data_key = mesh_obj.data.as_pointer() if hasattr(mesh_obj.data, "as_pointer") else id(mesh_obj.data)
        owner = data_owners.get(data_key)
        if owner is not None and owner != object_name:
            return f"{owner} 与 {object_name} 共享 Mesh 数据；请先将参与蒙皮的 Mesh 设为单用户"
        data_owners[data_key] = object_name
        if getattr(mesh_obj.data, "users", 1) > 1:
            return f"{object_name} 的 Mesh 数据被多个对象共享；请先设为单用户后生成基础权重"
    return ""


def _component_locked_transfer_region(
    context,
    settings,
    component,
    rig_obj,
    regions,
    character_height,
    base_region_assignments=None,
):
    obj = context.scene.objects.get(component.get("object", ""))
    if not obj or obj.type != "MESH":
        return ""
    transform = rig_obj.matrix_world.inverted() @ obj.matrix_world
    base_region_assignments = base_region_assignments or _base_region_assignments_by_object(context, settings)
    explicit_assignments = base_region_assignments.get(obj.name, {})
    points = [
        transform @ obj.data.vertices[vertex_id].co
        for vertex_id in _component_vertex_ids_for_scope(context, settings, component, "BASE_SKIN")
        if 0 <= vertex_id < len(obj.data.vertices) and vertex_id not in explicit_assignments
    ]
    if not points:
        return ""
    votes = {}
    for point in points:
        region_name = _anatomical_region_for_point(point, rig_obj, regions, character_height)
        votes[region_name] = votes.get(region_name, 0) + 1
    dominant_region, dominant_count = max(votes.items(), key=lambda item: item[1])
    total = len(points)
    top_count = max(4, int(math.ceil(total * 0.20)))
    top_points = sorted(points, key=lambda point: point.z, reverse=True)[:top_count]
    top_votes = {}
    for point in top_points:
        region_name = _anatomical_region_for_point(point, rig_obj, regions, character_height)
        top_votes[region_name] = top_votes.get(region_name, 0) + 1
    head_top_share = top_votes.get("HEAD", 0) / max(len(top_points), 1)
    if votes.get("HEAD", 0) and (head_top_share >= 0.50 or votes.get("HEAD", 0) / total >= 0.40):
        return "HEAD"
    if dominant_count / total >= 0.75:
        return dominant_region
    return ""


def _automatic_locked_region_applies(point, rig_obj, component, locked_region):
    # A cached component-level value exists only when every Base Skin vertex
    # carries the same explicit per-vertex region, preserving the old rigid
    # whole-component semantics without promoting partial brush overrides.
    if component.get("base_region"):
        return True
    head = rig_obj.data.bones.get("head.x")
    if locked_region == "HEAD" and head and point.z < head.head_local.z:
        return False
    return True


def _chain_window_candidates(point, rig_obj, names, radius=1):
    names = [name for name in names if rig_obj.data.bones.get(name)]
    if not names:
        return []
    closest_index = min(
        range(len(names)),
        key=lambda index: _rig_bone_segment_distance(point, rig_obj.data.bones[names[index]]),
    )
    return names[max(0, closest_index - radius) : min(len(names), closest_index + radius + 1)]


def _base_anatomical_candidate_names(
    point,
    rig_obj,
    snapshot,
    regions,
    character_height,
    forced_region="",
):
    available = {
        name
        for name, entry in snapshot.items()
        if entry.get("use_deform") and name != "root.x" and rig_obj.data.bones.get(name)
    }
    region_name = (
        forced_region
        if forced_region in regions
        else _anatomical_region_for_point(point, rig_obj, regions, character_height)
    )
    if region_name == "HEAD":
        return _chain_window_candidates(
            point,
            rig_obj,
            [name for name in ("neck.x", "head.x") if name in available],
        )
    if region_name == "NECK":
        return [name for name in ("upper_chest.x", "neck.x") if name in available]
    if region_name in {"SHOULDER_L", "SHOULDER_R"}:
        side = ".l" if region_name.endswith("_L") else ".r"
        upper_arm = rig_obj.data.bones.get("upper_arm" + side)
        names = [name for name in ("upper_chest.x", "shoulder" + side) if name in available]
        if upper_arm:
            if _arm_lateral_projection(point, rig_obj, side) > 0.0 and "upper_arm" + side in available:
                names.append("upper_arm" + side)
        return names
    if region_name in {"ARM_L", "ARM_R"}:
        side = ".l" if region_name.endswith("_L") else ".r"
        hand_name = "hand" + side
        hand = rig_obj.data.bones.get(hand_name)
        upper_arm_name = "upper_arm" + side
        upper_arm = rig_obj.data.bones.get(upper_arm_name)
        shoulder_name = "shoulder" + side
        arm_chain = [name for name in ("upper_chest.x", "shoulder" + side, "upper_arm" + side, "forearm" + side, hand_name) if name in available]
        if upper_arm:
            shoulder_projection = _arm_lateral_projection(point, rig_obj, side)
            if shoulder_projection <= 0.0:
                return [name for name in ("upper_chest.x", shoulder_name) if name in available]
            if shoulder_projection < _upper_arm_root_transition_length(rig_obj, side, character_height):
                return [
                    name
                    for name in ("upper_chest.x", shoulder_name, upper_arm_name)
                    if name in available
                ]
        if hand:
            hand_axis = (hand.tail_local - hand.head_local).normalized()
            wrist_projection = (point - hand.head_local).dot(hand_axis)
            finger_projection = (point - hand.tail_local).dot(hand_axis)
            wrist_blend = character_height * 0.015
            if wrist_projection < -wrist_blend:
                arm_chain = [name for name in arm_chain if name != hand_name]
            if finger_projection >= -character_height * 0.004:
                finger_chains = []
                for prefix in ("thumb", "index", "middle", "ring", "pinky"):
                    chain = [f"{prefix}_{segment:02d}{side}" for segment in range(1, 4)]
                    chain = [name for name in chain if name in available]
                    if chain:
                        finger_chains.append(chain)
                if finger_chains:
                    closest_chain = min(
                        finger_chains,
                        key=lambda chain: min(
                            _rig_bone_segment_distance(point, rig_obj.data.bones[name]) for name in chain
                        ),
                    )
                    return [name for name in ("forearm" + side, hand_name, *closest_chain) if name in available]
        return _chain_window_candidates(point, rig_obj, arm_chain)
    if region_name in {"LEG_L", "LEG_R"}:
        side = ".l" if region_name.endswith("_L") else ".r"
        foot_name = "foot" + side
        toes_name = "toes" + side
        foot = rig_obj.data.bones.get(foot_name)
        leg_chain = [name for name in ("pelvis.x", "thigh" + side, "lower_leg" + side, foot_name, toes_name) if name in available]
        if foot:
            foot_axis = (foot.tail_local - foot.head_local).normalized()
            ankle_projection = (point - foot.head_local).dot(foot_axis)
            if ankle_projection < -character_height * 0.02:
                leg_chain = [name for name in leg_chain if name not in {foot_name, toes_name}]
        return _chain_window_candidates(point, rig_obj, leg_chain)
    center_chain = [name for name in ("pelvis.x", "spine_01.x", "spine_02.x", "upper_chest.x") if name in available]
    return _chain_window_candidates(point, rig_obj, center_chain)


def _normalized_anatomical_weights(point, rig_obj, bone_names):
    distances = sorted(
        (_rig_bone_segment_distance(point, rig_obj.data.bones[name]), name)
        for name in bone_names
        if rig_obj.data.bones.get(name)
    )[:4]
    if not distances:
        return []
    raw = [(name, 1.0 / max(distance, 0.003) ** 3) for distance, name in distances]
    total = sum(weight for _name, weight in raw)
    normalized = [(name, weight / total) for name, weight in raw]
    retained = [(name, weight) for name, weight in normalized if weight >= 0.01]
    if not retained:
        retained = [max(normalized, key=lambda item: item[1])]
    retained_total = sum(weight for _name, weight in retained)
    return [(name, weight / retained_total) for name, weight in retained]


def _rigid_attachment_validation_stats(context, rig_obj, issues=None):
    deform_names = {bone.name for bone in rig_obj.data.bones if bone.use_deform}
    stats = {"records": 0, "vertices": 0, "invalid_records": 0, "mismatches": 0}
    for record in _rigid_bind_payload(rig_obj).get("attachments", []):
        stats["records"] += 1
        mesh_obj = context.scene.objects.get(record.get("object", ""))
        vertex_ids = sorted(set(int(index) for index in record.get("vertex_indices", []) if isinstance(index, int)))
        target_bone = record.get("target_bone", "")
        if (
            not mesh_obj
            or mesh_obj.type != "MESH"
            or not vertex_ids
            or any(index < 0 or index >= len(mesh_obj.data.vertices) for index in vertex_ids)
            or target_bone not in deform_names
        ):
            stats["invalid_records"] += 1
            stats["mismatches"] += len(vertex_ids) or 1
            if issues is not None:
                issues.append({"object": record.get("object", ""), "bone": target_bone,
                               "vertex": None, "reason": "附件记录失效：对象、顶点编号或目标骨骼无效", "actual": "请检查附件记录并重新绑定"})
            continue
        rigid_mask = _mesh_vertex_group_ids(mesh_obj, RIGID_BIND_MASK_GROUP)
        group_names = {group.index: group.name for group in mesh_obj.vertex_groups}
        for vertex_id in vertex_ids:
            stats["vertices"] += 1
            assignments = {
                group_names[item.group]: float(item.weight)
                for item in mesh_obj.data.vertices[vertex_id].groups
                if item.weight > 1e-6 and group_names.get(item.group) in deform_names
            }
            if (
                vertex_id not in rigid_mask
                or set(assignments) != {target_bone}
                or abs(assignments.get(target_bone, 0.0) - 1.0) > 1e-4
            ):
                stats["mismatches"] += 1
                if issues is not None:
                    reasons = []
                    if vertex_id not in rigid_mask:
                        reasons.append("不在刚性附件蒙版中")
                    if set(assignments) != {target_bone}:
                        reasons.append("骨骼绑定不符")
                    if abs(assignments.get(target_bone, 0.0) - 1.0) > 1e-4:
                        reasons.append("目标骨骼权重不是1")
                    issues.append({"object": mesh_obj.name, "bone": target_bone, "vertex": vertex_id,
                                   "reason": "、".join(reasons),
                                   "actual": ", ".join(f"{name}={weight:.6g}" for name, weight in sorted(assignments.items())) or "无有效骨骼权重"})
    return stats


def _repair_rigid_weight_errors(context, rig):
    issues = []
    _rigid_attachment_validation_stats(context, rig, issues)
    claims = {}
    for record in _rigid_bind_payload(rig).get("attachments", []):
        for index in record.get("vertex_indices", []):
            if isinstance(index, int):
                claims.setdefault((record.get("object", ""), index), set()).add(record.get("target_bone", ""))
    plan = {}
    skipped = []
    for item in issues:
        key = (item["object"], item["vertex"])
        if item["vertex"] is None:
            skipped.append(f"{item['object']}：{item['reason']}")
        elif len(claims.get(key, set())) != 1:
            skipped.append(f"{item['object']} 顶点 {item['vertex']}：附件目标骨骼冲突")
        else:
            plan[key] = item["bone"]
    deform_names = {bone.name for bone in rig.data.bones if bone.use_deform}
    saved = {}
    initial_groups = {}
    try:
        for (name, index), bone in plan.items():
            obj = context.scene.objects[name]
            initial_groups.setdefault(name, {group.name for group in obj.vertex_groups})
            names = {group.index: group.name for group in obj.vertex_groups}
            saved[(name, index)] = [(names[item.group], float(item.weight)) for item in obj.data.vertices[index].groups]
            for group in obj.vertex_groups:
                if group.name in deform_names:
                    group.remove([index])
            group = obj.vertex_groups.get(bone) or obj.vertex_groups.new(name=bone)
            group.add([index], 1.0, "REPLACE")
            mask = obj.vertex_groups.get(RIGID_BIND_MASK_GROUP) or obj.vertex_groups.new(name=RIGID_BIND_MASK_GROUP)
            mask.add([index], 1.0, "REPLACE")
            obj.data.update()
        remaining = []
        _rigid_attachment_validation_stats(context, rig, remaining)
        if any((item["object"], item["vertex"]) in plan for item in remaining):
            raise RuntimeError("修复后刚性附件复查失败")
    except Exception:
        for (name, index), assignments in saved.items():
            obj = context.scene.objects[name]
            for group in obj.vertex_groups:
                group.remove([index])
            for group_name, weight in assignments:
                obj.vertex_groups[group_name].add([index], weight, "REPLACE")
        for name, names in initial_groups.items():
            obj = context.scene.objects[name]
            for group in list(obj.vertex_groups):
                if group.name not in names:
                    obj.vertex_groups.remove(group)
            obj.data.update()
        raise
    return len(plan), skipped


class WGAME_RIGGING_OT_repair_rigid_weight_errors(Operator):
    bl_idname = "wgame_rigging.repair_rigid_weight_errors"
    bl_label = "自动修复刚性附件错误顶点"
    bl_description = "按已记录的目标骨骼恢复错误顶点的单骨权重1及刚性蒙版；保留其它顶点和非骨骼组，跳过失效或冲突记录"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig = _wgame_rig_object(context)
        if not rig or settings.wgame_custom_weight_edit_active:
            self.report({"ERROR"}, "请先退出自定义权重绘制，并确认 WGame 骨架存在")
            return {"CANCELLED"}
        if context.object and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        if not _component_scan_is_current(context, settings):
            self.report({"ERROR"}, "组件拓扑已变化，请先修复组件记录并确认附件范围")
            return {"CANCELLED"}
        try:
            count, skipped = _repair_rigid_weight_errors(context, rig)
        except Exception as error:
            self.report({"ERROR"}, f"修复失败，已恢复修复前权重：{error}")
            return {"CANCELLED"}
        _WEIGHTED_CENTROID_CACHE.clear()
        _validate_complete_binding(context, settings, rig)
        remaining = []
        _rigid_attachment_validation_stats(context, rig, remaining)
        settings.wgame_rigid_validation_details = json.dumps(remaining, ensure_ascii=False)
        summary = f"刚性附件自动修复 {count} 个顶点；跳过 {len(skipped)} 项"
        settings.wgame_custom_binding_report = summary + "；" + "；".join(skipped) + "；" + settings.wgame_custom_binding_report
        self.report({"WARNING" if skipped else "INFO"}, summary)
        return {"FINISHED"}


class WGAME_RIGGING_OT_focus_rigid_weight_errors(Operator):
    bl_idname = "wgame_rigging.focus_rigid_weight_errors"
    bl_label = "选中错误顶点"
    bl_description = "重新检查并选中该对象、目标骨骼对应的刚性附件错误顶点；不修改权重"
    bl_options = {"REGISTER"}

    object_name: StringProperty()
    target_bone: StringProperty()

    def execute(self, context):
        rig = _wgame_rig_object(context)
        if not rig:
            self.report({"ERROR"}, "没有找到 WGame 骨架")
            return {"CANCELLED"}
        if context.object and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        issues = []
        _rigid_attachment_validation_stats(context, rig, issues)
        context.scene.wgame_rigging_assistant.wgame_rigid_validation_details = json.dumps(issues, ensure_ascii=False)
        indices = sorted({item["vertex"] for item in issues if item["object"] == self.object_name
                          and item["bone"] == self.target_bone and item["vertex"] is not None})
        if not indices or not _focus_unrigged_component(context, {"object": self.object_name, "vertex_indices": indices}):
            self.report({"WARNING"}, "当前没有可选中的错误顶点；请重新检查绑定报告")
            return {"CANCELLED"}
        mesh = context.scene.objects[self.object_name].data
        editable = bmesh.from_edit_mesh(mesh)
        editable.verts.ensure_lookup_table()
        for index in indices:
            editable.verts[index].hide_set(False)
            editable.verts[index].select_set(True)
        bmesh.update_edit_mesh(mesh, loop_triangles=False, destructive=False)
        self.report({"INFO"}, f"已选中 {self.object_name} 的 {len(indices)} 个错误顶点；应仅绑定 {self.target_bone}=1")
        return {"FINISHED"}


def _validate_scope_weights(context, settings, rig_obj, scope):
    by_object = _scope_vertex_ids_by_object(settings, scope)
    totals = {"vertices": 0, "zero": 0, "over_four": 0, "bad_sum": 0, "modifier_errors": 0, "missing_objects": 0}
    for object_name, vertex_ids in by_object.items():
        mesh_obj = context.scene.objects.get(object_name)
        if not mesh_obj or mesh_obj.type != "MESH":
            totals["missing_objects"] += 1
            continue
        modifier = _armature_modifier(mesh_obj)
        totals["modifier_errors"] += not modifier or modifier.object != rig_obj
        stats = _deform_weight_stats(mesh_obj, rig_obj, vertex_ids)
        for key in ("vertices", "zero", "over_four", "bad_sum"):
            totals[key] += stats[key]
    if scope == "CUSTOM_BIND":
        rigid = _rigid_attachment_validation_stats(context, rig_obj)
        totals.update({"rigid_" + key: value for key, value in rigid.items()})
    return totals


def _required_torso_weight_coverage(context, settings, rig_obj):
    required = (
        "pelvis.x",
        "spine_01.x",
        "spine_02.x",
        "upper_chest.x",
        "neck.x",
        "head.x",
    )
    full_torso = all(rig_obj.data.bones.get(name) for name in required)
    base_by_object = _scope_vertex_ids_by_object(settings, "BASE_SKIN")
    coverage = {name: 0 for name in required if rig_obj.data.bones.get(name)}
    for object_name, vertex_ids in base_by_object.items():
        mesh_obj = context.scene.objects.get(object_name)
        if not mesh_obj or mesh_obj.type != "MESH":
            continue
        for name in coverage:
            group = mesh_obj.vertex_groups.get(name)
            if not group:
                continue
            for vertex_id in vertex_ids:
                if vertex_id < 0 or vertex_id >= len(mesh_obj.data.vertices):
                    continue
                vertex = mesh_obj.data.vertices[vertex_id]
                if any(item.group == group.index and item.weight > 1e-6 for item in vertex.groups):
                    coverage[name] += 1
    missing = [name for name, count in coverage.items() if count == 0] if full_torso else []
    return coverage, missing


def _base_expected_distal_support(point, rig_obj, character_height, region=None):
    """Conservative foot/toe core coverage, independent of existing weights.

    A foot requirement includes its toe descendant. Only nearby vertices whose
    closest leg segment is distal and which lie beyond the ankle transition
    are checked. Joint bands, missing bones and absent geometry create no
    blanket requirement for a vertex group to exist. Explicit non-leg regions
    remain authoritative. All distances are in the rig's rest space.
    """
    if region and region not in {"LEG_L", "LEG_R"}:
        return {}
    side = (".l" if region == "LEG_L" else ".r") if region else (".l" if point.x >= 0.0 else ".r")
    foot_name, toes_name = "foot" + side, "toes" + side
    foot = rig_obj.data.bones.get(foot_name)
    lower_leg = rig_obj.data.bones.get("lower_leg" + side)
    if not foot or not lower_leg or not foot.use_deform:
        return {}
    if foot.length <= 1e-8 or lower_leg.length <= 1e-8:
        return {}
    candidates = [
        bone for name in ("thigh" + side, "lower_leg" + side, foot_name, toes_name)
        if (bone := rig_obj.data.bones.get(name)) and bone.use_deform and bone.length > 1e-8
    ]
    distances = {bone.name: _rig_bone_segment_distance(point, bone) for bone in candidates}
    nearest = min(distances, key=distances.get)
    radius = max(character_height * 0.025, min(character_height * 0.06, foot.length * 0.5))
    if nearest not in {foot_name, toes_name} or distances[nearest] > radius:
        return {}
    ankle_projection = _joint_axis_projection(point, rig_obj, foot_name, lower_leg.name)
    ankle_band = _distal_joint_transition_length(rig_obj, foot_name, character_height, "FOOT")
    if ankle_projection < ankle_band:
        return {}
    expected = {foot_name: 0.05}
    toes = rig_obj.data.bones.get(toes_name)
    if toes and toes.use_deform and toes.length > 1e-8:
        toe_projection = _joint_axis_projection(point, rig_obj, toes_name, foot_name)
        toe_band = _distal_joint_transition_length(rig_obj, toes_name, character_height, "TOES")
        along_toes = (point - toes.head_local).dot((toes.tail_local - toes.head_local).normalized())
        if (nearest == toes_name and toe_projection >= toe_band
                and 0.0 <= along_toes <= toes.length + radius):
            expected[toes_name] = 0.05
    return expected


def _base_distal_support_weight(assignments, bone_name):
    """Foot core can be driven by foot, toes, or their blend."""
    names = {bone_name}
    if bone_name.startswith("foot."):
        names.add("toes" + bone_name[len("foot"):])
    items = assignments.items() if isinstance(assignments, dict) else assignments
    return sum(float(weight) for name, weight in items if name in names and math.isfinite(float(weight)))


def _required_distal_weight_coverage(context, settings, rig_obj, character_height):
    result = {"checked": 0, "mismatches": 0, "bones": {}, "examples": []}
    overrides = _base_region_assignments_by_object(context, settings)
    rig_inverse = rig_obj.matrix_world.inverted()
    for object_name, vertex_ids in _scope_vertex_ids_by_object(settings, "BASE_SKIN").items():
        obj = context.scene.objects.get(object_name)
        if not obj or obj.type != "MESH":
            continue
        transform = rig_inverse @ obj.matrix_world
        group_names = {group.index: group.name for group in obj.vertex_groups}
        for vertex_id in sorted(vertex_ids):
            if not 0 <= vertex_id < len(obj.data.vertices):
                continue
            vertex = obj.data.vertices[vertex_id]
            expected = _base_expected_distal_support(
                transform @ vertex.co, rig_obj, character_height,
                overrides.get(object_name, {}).get(vertex_id),
            )
            if not expected:
                continue
            result["checked"] += 1
            assignments = {group_names.get(item.group): float(item.weight) for item in vertex.groups}
            missing = []
            for name, minimum in expected.items():
                counts = result["bones"].setdefault(name, {"expected": 0, "covered": 0, "missing": 0})
                counts["expected"] += 1
                covered = _base_distal_support_weight(assignments, name) >= minimum - 1e-6
                counts["covered"] += int(covered)
                counts["missing"] += int(not covered)
                if not covered:
                    missing.append(name)
            if missing:
                result["mismatches"] += 1
                if len(result["examples"]) < 20:
                    result["examples"].append({"object": object_name, "vertex": vertex_id, "bones": missing})
    return result


def _head_override_mismatch_count(context, settings, rig_obj):
    deform_names = {bone.name for bone in rig_obj.data.bones if bone.use_deform}
    mismatch_count = 0
    checked_count = 0
    assignments_by_object = _base_region_assignments_by_object(context, settings)
    custom_by_object = _custom_mask_vertex_ids_by_object(context, settings)
    for component in _unrigged_components(settings):
        base_ids = _component_vertex_ids_for_scope(context, settings, component, "BASE_SKIN", custom_by_object)
        assignments = assignments_by_object.get(component.get("object", ""), {})
        head_ids = {vertex_id for vertex_id in base_ids if assignments.get(vertex_id) == "HEAD"}
        if not head_ids:
            continue
        mesh_obj = context.scene.objects.get(component.get("object", ""))
        if not mesh_obj or mesh_obj.type != "MESH":
            mismatch_count += len(head_ids)
            continue
        group_names = {group.index: group.name for group in mesh_obj.vertex_groups}
        for vertex_id in head_ids:
            checked_count += 1
            if vertex_id < 0 or vertex_id >= len(mesh_obj.data.vertices):
                mismatch_count += 1
                continue
            assignments = {
                group_names.get(item.group): item.weight
                for item in mesh_obj.data.vertices[vertex_id].groups
                if item.weight > 1e-6 and group_names.get(item.group) in deform_names
            }
            if set(assignments) != {"head.x"} or abs(assignments.get("head.x", 0.0) - 1.0) > 1e-4:
                mismatch_count += 1
    return checked_count, mismatch_count


def _automatic_head_boundary_stats(context, settings, rig_obj):
    head = rig_obj.data.bones.get("head.x")
    if not head:
        return 0, 0
    checked_count = 0
    outside_count = 0
    assignments_by_object = _base_region_assignments_by_object(context, settings)
    custom_by_object = _custom_mask_vertex_ids_by_object(context, settings)
    for component in _unrigged_components(settings):
        base_ids = _component_vertex_ids_for_scope(context, settings, component, "BASE_SKIN", custom_by_object)
        assignments = assignments_by_object.get(component.get("object", ""), {})
        base_ids = {vertex_id for vertex_id in base_ids if assignments.get(vertex_id) != "HEAD"}
        if not base_ids:
            continue
        mesh_obj = context.scene.objects.get(component.get("object", ""))
        group = mesh_obj.vertex_groups.get("head.x") if mesh_obj and mesh_obj.type == "MESH" else None
        if not group:
            continue
        transform = rig_obj.matrix_world.inverted() @ mesh_obj.matrix_world
        for vertex_id in base_ids:
            if vertex_id < 0 or vertex_id >= len(mesh_obj.data.vertices):
                continue
            vertex = mesh_obj.data.vertices[vertex_id]
            weight = next((item.weight for item in vertex.groups if item.group == group.index), 0.0)
            if weight <= 1e-6:
                continue
            checked_count += 1
            outside_count += (transform @ vertex.co).z < head.head_local.z - 1e-6
    return checked_count, outside_count


def _upper_arm_boundary_stats(context, settings, rig_obj, character_height):
    checked_count = 0
    medial_influence_count = 0
    over_limit_count = 0
    for object_name, vertex_ids in _scope_vertex_ids_by_object(settings, "BASE_SKIN").items():
        mesh_obj = context.scene.objects.get(object_name)
        if not mesh_obj or mesh_obj.type != "MESH":
            continue
        transform = rig_obj.matrix_world.inverted() @ mesh_obj.matrix_world
        for side in (".l", ".r"):
            group = mesh_obj.vertex_groups.get("upper_arm" + side)
            if not group:
                continue
            transition = _upper_arm_root_transition_length(rig_obj, side, character_height)
            for vertex_id in vertex_ids:
                if vertex_id < 0 or vertex_id >= len(mesh_obj.data.vertices):
                    continue
                vertex = mesh_obj.data.vertices[vertex_id]
                weight = next(
                    (item.weight for item in vertex.groups if item.group == group.index),
                    0.0,
                )
                if weight <= 1e-6:
                    continue
                checked_count += 1
                point = transform @ vertex.co
                lateral_projection = _arm_lateral_projection(point, rig_obj, side)
                factor = max(0.0, min(1.0, lateral_projection / max(transition, 1e-6)))
                maximum_weight = factor * factor * (3.0 - 2.0 * factor)
                medial_influence_count += lateral_projection <= 0.0
                over_limit_count += weight > maximum_weight + 1e-3
    return checked_count, medial_influence_count, over_limit_count


def _limb_child_boundary_stats(
    context,
    settings,
    rig_obj,
    character_height,
    child_base,
    parent_base,
):
    checked_count = 0
    parent_side_influence_count = 0
    over_limit_count = 0
    for object_name, vertex_ids in _scope_vertex_ids_by_object(settings, "BASE_SKIN").items():
        mesh_obj = context.scene.objects.get(object_name)
        if not mesh_obj or mesh_obj.type != "MESH":
            continue
        transform = rig_obj.matrix_world.inverted() @ mesh_obj.matrix_world
        for side in (".l", ".r"):
            child_name = child_base + side
            parent_name = parent_base + side
            group = mesh_obj.vertex_groups.get(child_name)
            if not group:
                continue
            transition = _child_joint_transition_length(rig_obj, parent_name, character_height)
            for vertex_id in vertex_ids:
                if vertex_id < 0 or vertex_id >= len(mesh_obj.data.vertices):
                    continue
                vertex = mesh_obj.data.vertices[vertex_id]
                weight = next(
                    (item.weight for item in vertex.groups if item.group == group.index),
                    0.0,
                )
                if weight <= 1e-6:
                    continue
                checked_count += 1
                point = transform @ vertex.co
                projection = _child_joint_projection(point, rig_obj, child_name, parent_name)
                maximum_weight = _joint_band_maximum_weight(projection, transition)
                parent_side_influence_count += projection <= -transition
                over_limit_count += weight > maximum_weight + 1e-3
    return checked_count, parent_side_influence_count, over_limit_count


def _distal_hierarchy_boundary_stats(context, settings, rig_obj, character_height):
    results = {
        "SHOULDER": {"checked": 0, "outside": 0, "over_limit": 0},
        "HAND": {"checked": 0, "outside": 0, "over_limit": 0},
        "FINGER": {"checked": 0, "outside": 0, "over_limit": 0},
        "FOOT": {"checked": 0, "outside": 0, "over_limit": 0},
        "TOES": {"checked": 0, "outside": 0, "over_limit": 0},
    }
    specs = list(_distal_joint_specs())
    for side in (".l", ".r"):
        specs.append(("shoulder" + side, "upper_chest.x", "CHILD", "SHOULDER"))
    base_by_object = _scope_vertex_ids_by_object(settings, "BASE_SKIN")
    weighted_by_object = {}
    for object_name, vertex_ids in base_by_object.items():
        obj = context.scene.objects.get(object_name)
        if not obj or obj.type != "MESH":
            continue
        by_group = {}
        for vertex_id in vertex_ids:
            if not 0 <= vertex_id < len(obj.data.vertices):
                continue
            for entry in obj.data.vertices[vertex_id].groups:
                if entry.weight > 1e-6:
                    by_group.setdefault(entry.group, []).append((vertex_id, entry.weight))
        weighted_by_object[object_name] = by_group
    for child_name, parent_name, axis_source, kind in specs:
        if not rig_obj.data.bones.get(child_name) or not rig_obj.data.bones.get(parent_name):
            continue
        transition = _distal_joint_transition_length(
            rig_obj,
            child_name,
            character_height,
            kind,
        )
        category = results[kind]
        for object_name, vertex_ids in base_by_object.items():
            mesh_obj = context.scene.objects.get(object_name)
            if not mesh_obj or mesh_obj.type != "MESH":
                continue
            group = mesh_obj.vertex_groups.get(child_name)
            if not group:
                continue
            transform = rig_obj.matrix_world.inverted() @ mesh_obj.matrix_world
            for vertex_id, weight in weighted_by_object.get(object_name, {}).get(group.index, []):
                vertex = mesh_obj.data.vertices[vertex_id]
                point = transform @ vertex.co
                projection = _joint_axis_projection(
                    point,
                    rig_obj,
                    child_name,
                    parent_name,
                    axis_source,
                )
                maximum_weight = _joint_band_maximum_weight(projection, transition)
                category["checked"] += 1
                category["outside"] += projection <= -transition
                category["over_limit"] += weight > maximum_weight + 1e-3
    return results


def _unrigged_binding_groups(settings):
    try:
        value = json.loads(settings.unrigged_binding_groups_json or "[]")
        return value if isinstance(value, list) else []
    except ValueError:
        return []


def _save_unrigged_binding_groups(settings, groups):
    settings.unrigged_binding_groups_json = json.dumps(groups, ensure_ascii=False, separators=(",", ":"))


def _binding_group(settings, group_id):
    return next((item for item in _unrigged_binding_groups(settings) if item.get("id") == group_id), None)


def _component_use_ready(settings, component):
    return _component_scope_ready(component)


def _component_binding_group_ready(settings, component):
    return _component_scope_ready(component)


def _unrigged_component_uses_complete(settings):
    components = _unrigged_components(settings)
    return bool(components) and all(_component_use_ready(settings, item) for item in components)


def _unrigged_single_bone_groups_complete(settings):
    return _unrigged_component_uses_complete(settings)


def _unrigged_components_complete(settings):
    return _unrigged_component_uses_complete(settings) and _unrigged_single_bone_groups_complete(settings)


def _next_unready_component_index(settings, components):
    return next((index for index, item in enumerate(components) if not _component_use_ready(settings, item)), None)


def _next_ungrouped_single_bone_index(settings, components):
    return None


def _component_has_any_binding_group(settings, component):
    group = _binding_group(settings, component.get("binding_group_id", ""))
    return bool(group and component.get("id") in group.get("component_ids", []))


def _aabb_gap(left, right):
    left_center = Vector(left.get("center") or (0.0, 0.0, 0.0))
    right_center = Vector(right.get("center") or (0.0, 0.0, 0.0))
    left_half = Vector(left.get("dimensions") or (0.0, 0.0, 0.0)) * 0.5
    right_half = Vector(right.get("dimensions") or (0.0, 0.0, 0.0)) * 0.5
    left_min, left_max = left_center - left_half, left_center + left_half
    right_min, right_max = right_center - right_half, right_center + right_half
    gap = Vector(
        tuple(
            max(0.0, float(right_min[axis] - left_max[axis]), float(left_min[axis] - right_max[axis]))
            for axis in range(3)
        )
    )
    return gap.length


def _rigid_group_suggestions(settings):
    components = _unrigged_components(settings)
    candidates = [
        item
        for item in components
        if item.get("role") == "RIGID" and not _component_has_any_binding_group(settings, item)
    ]
    tolerance = max(0.0, float(settings.unrigged_rigid_cluster_distance))
    adjacency = {item.get("id"): [] for item in candidates}
    by_id = {item.get("id"): item for item in candidates}
    for left_index, left in enumerate(candidates):
        for right in candidates[left_index + 1 :]:
            if left.get("object") != right.get("object"):
                continue
            if _aabb_gap(left, right) <= tolerance:
                adjacency[left.get("id")].append(right.get("id"))
                adjacency[right.get("id")].append(left.get("id"))
    seen = set()
    suggestions = []
    component_order = {item.get("id"): index for index, item in enumerate(components)}
    for candidate in candidates:
        start = candidate.get("id")
        if start in seen:
            continue
        stack = [start]
        seen.add(start)
        ids = []
        while stack:
            current = stack.pop()
            ids.append(current)
            for neighbor in adjacency.get(current, []):
                if neighbor not in seen:
                    seen.add(neighbor)
                    stack.append(neighbor)
        ids.sort(key=lambda item: component_order.get(item, 999999))
        items = [by_id[item] for item in ids]
        centers = [Vector(item.get("center") or (0.0, 0.0, 0.0)) for item in items]
        dimensions = [Vector(item.get("dimensions") or (0.0, 0.0, 0.0)) for item in items]
        minimum = Vector(tuple(min((center - size * 0.5)[axis] for center, size in zip(centers, dimensions)) for axis in range(3)))
        maximum = Vector(tuple(max((center + size * 0.5)[axis] for center, size in zip(centers, dimensions)) for axis in range(3)))
        suggestions.append(
            {
                "component_ids": ids,
                "vertices": sum(int(item.get("vertices", 0)) for item in items),
                "center": list((minimum + maximum) * 0.5),
                "dimensions": list(maximum - minimum),
                "first_index": min(component_order.get(item, 999999) for item in ids),
            }
        )
    suggestions.sort(key=lambda item: item["first_index"])
    return suggestions


def _remove_components_from_binding_groups(settings, component_ids, keep_group_id=""):
    component_ids = set(component_ids)
    groups = _unrigged_binding_groups(settings)
    retained = []
    for group in groups:
        if group.get("id") != keep_group_id:
            group["component_ids"] = [item for item in group.get("component_ids", []) if item not in component_ids]
        if group.get("component_ids") or group.get("id") == keep_group_id:
            retained.append(group)
    _save_unrigged_binding_groups(settings, retained)


def _selected_unrigged_component_ids(context, components):
    selected = {}
    for obj in context.scene.objects:
        if obj.type != "MESH":
            continue
        if obj.mode == "EDIT":
            obj.update_from_editmode()
        selected[obj.name] = {vertex.index for vertex in obj.data.vertices if vertex.select}
    result = []
    for component in components:
        object_selection = selected.get(component.get("object", ""), set())
        if object_selection.intersection(component.get("vertex_indices") or []):
            result.append(component.get("id"))
    return result


def _focus_unrigged_component_ids(context, components, component_ids):
    component_ids = set(component_ids)
    selected = [item for item in components if item.get("id") in component_ids]
    if not selected:
        return False
    object_name = selected[0].get("object", "")
    selected = [item for item in selected if item.get("object") == object_name]
    merged_indices = sorted({index for item in selected for index in (item.get("vertex_indices") or [])})
    return _focus_unrigged_component(
        context,
        {"object": object_name, "vertex_indices": merged_indices},
    )


def _assign_components_to_binding_group(context, settings, group_id, component_ids):
    components = _unrigged_components(settings)
    valid_ids = {item.get("id") for item in components}
    component_ids = [item for item in dict.fromkeys(component_ids) if item in valid_ids]
    if not component_ids:
        return 0

    groups = _unrigged_binding_groups(settings)
    target = next((item for item in groups if item.get("id") == group_id), None)
    if not target:
        return 0
    component_id_set = set(component_ids)
    for group in groups:
        group["component_ids"] = [
            item for item in group.get("component_ids", []) if item not in component_id_set
        ]
    target["component_ids"] = list(dict.fromkeys(target.get("component_ids", []) + component_ids))
    groups = [item for item in groups if item.get("component_ids") or item.get("id") == group_id]
    _save_unrigged_binding_groups(settings, groups)

    for component in components:
        if component.get("id") in component_id_set:
            component["role"] = "RIGID"
            component["binding_group_id"] = group_id
    settings.unrigged_components_json = json.dumps(components, ensure_ascii=False, separators=(",", ":"))
    _focus_unrigged_component_ids(context, components, target.get("component_ids", []))
    return len(component_ids)


def _rigid_vertex_indices_by_object(settings):
    result = {}
    for component in _unrigged_components(settings):
        if component.get("role") == "RIGID":
            result.setdefault(component.get("object", ""), set()).update(component.get("vertex_indices") or [])
    return result


def _set_rigid_component_isolation(context, settings, enabled):
    if context.object and context.object.mode != "OBJECT":
        bpy.ops.object.mode_set(mode="OBJECT")
    rigid_by_object = _rigid_vertex_indices_by_object(settings)
    target = None
    for object_name, rigid_indices in rigid_by_object.items():
        obj = context.scene.objects.get(object_name)
        if not obj or obj.type != "MESH":
            continue
        target = target or obj
        for vertex in obj.data.vertices:
            vertex.hide = bool(enabled and vertex.index not in rigid_indices)
            if vertex.hide:
                vertex.select = False
        obj.data.update()
    settings.unrigged_rigid_isolation_active = bool(enabled)
    if target:
        _select_only(context, target)
        bpy.ops.object.mode_set(mode="EDIT")
        context.tool_settings.mesh_select_mode = (True, False, False)
    _tag_view3d_redraw()
    return sum(len(indices) for indices in rigid_by_object.values())


def _focus_unrigged_component(context, component):
    obj = context.scene.objects.get(component.get("object", ""))
    indices = component.get("vertex_indices") or []
    if not obj or obj.type != "MESH" or not indices:
        return False
    if any(index < 0 or index >= len(obj.data.vertices) for index in indices):
        return False

    _select_only(context, obj)
    bpy.ops.object.mode_set(mode="EDIT")
    settings = context.scene.wgame_rigging_assistant
    if not settings.unrigged_custom_selection_hidden:
        bpy.ops.mesh.reveal()
    bpy.ops.mesh.select_all(action="DESELECT")
    bpy.ops.object.mode_set(mode="OBJECT")
    if settings.unrigged_rigid_isolation_active:
        visible = _rigid_vertex_indices_by_object(settings).get(obj.name, set())
        for vertex in obj.data.vertices:
            vertex.hide = vertex.index not in visible
    for index in indices:
        if not obj.data.vertices[index].hide:
            obj.data.vertices[index].select = True
    obj.data.update()
    bpy.ops.object.mode_set(mode="EDIT")
    context.tool_settings.mesh_select_mode = (True, False, False)

    # Component navigation should only update the mesh selection. Framing a
    # small connected component makes Blender zoom in aggressively and causes
    # the user's working view to jump on every navigation or assignment step.
    _tag_view3d_redraw()
    return True


def _view3d_window_region_from_event(context, event):
    screen = getattr(context, "screen", None)
    if not screen:
        return None, None
    for area in screen.areas:
        if area.type != "VIEW_3D":
            continue
        for region in area.regions:
            if region.type != "WINDOW":
                continue
            if (
                region.x <= event.mouse_x < region.x + region.width
                and region.y <= event.mouse_y < region.y + region.height
            ):
                return area, region
    return None, None


def _raycast_unrigged_component(context, settings, area, region, mouse_region):
    space = area.spaces.active
    origin_world = view3d_utils.region_2d_to_origin_3d(region, space.region_3d, mouse_region)
    direction_world = view3d_utils.region_2d_to_vector_3d(region, space.region_3d, mouse_region).normalized()
    components = _unrigged_components(settings)
    vertex_lookup = {}
    for component_index, component in enumerate(components):
        object_lookup = vertex_lookup.setdefault(component.get("object", ""), {})
        for vertex_index in component.get("vertex_indices") or []:
            object_lookup[vertex_index] = component_index

    best = None
    for mesh_obj in _participant_meshes(context, settings):
        if mesh_obj.hide_get() or not mesh_obj.visible_get():
            continue
        vertices = [vertex.co.copy() for vertex in mesh_obj.data.vertices]
        visible_polygons = []
        source_polygons = []
        for polygon in mesh_obj.data.polygons:
            indices = tuple(polygon.vertices)
            if not indices or any(mesh_obj.data.vertices[index].hide for index in indices):
                continue
            visible_polygons.append(indices)
            source_polygons.append(polygon)
        if not visible_polygons:
            continue
        tree = BVHTree.FromPolygons(vertices, visible_polygons, all_triangles=False)
        inverse = mesh_obj.matrix_world.inverted()
        local_origin = inverse @ origin_world
        local_direction = (inverse.to_3x3() @ direction_world).normalized()
        location, _normal, polygon_index, _distance = tree.ray_cast(local_origin, local_direction)
        if location is None or polygon_index is None or polygon_index >= len(source_polygons):
            continue
        world_location = mesh_obj.matrix_world @ location
        world_distance = (world_location - origin_world).length
        polygon = source_polygons[polygon_index]
        component_index = next(
            (
                vertex_lookup.get(mesh_obj.name, {}).get(vertex_index)
                for vertex_index in polygon.vertices
                if vertex_lookup.get(mesh_obj.name, {}).get(vertex_index) is not None
            ),
            None,
        )
        if component_index is None:
            continue
        if best is None or world_distance < best[0]:
            best = (world_distance, component_index)
    return best[1] if best else None


def _distance_to_screen_segment(point, start, end):
    vector = end - start
    factor = max(0.0, min(1.0, (point - start).dot(vector) / max(vector.length_squared, 1e-12)))
    return (point - (start + vector * factor)).length


def _pick_weight_bone_from_view(rig_obj, area, region, mouse_region, pixel_radius=24.0):
    space = area.spaces.active
    mouse = Vector(mouse_region)
    candidates = []
    for pose_bone in rig_obj.pose.bones:
        bone = pose_bone.bone
        if not bone.use_deform or bone.hide:
            continue
        collections = tuple(getattr(bone, "collections", ()))
        if collections and not any(
            bool(getattr(collection, "is_visible_effectively", getattr(collection, "is_visible", True)))
            for collection in collections
        ):
            continue
        head_world = rig_obj.matrix_world @ pose_bone.head
        tail_world = rig_obj.matrix_world @ pose_bone.tail
        head_screen = view3d_utils.location_3d_to_region_2d(region, space.region_3d, head_world)
        tail_screen = view3d_utils.location_3d_to_region_2d(region, space.region_3d, tail_world)
        if head_screen is None or tail_screen is None:
            continue
        screen_distance = _distance_to_screen_segment(mouse, head_screen, tail_screen)
        if screen_distance > pixel_radius:
            continue
        midpoint_world = (head_world + tail_world) * 0.5
        view_origin = view3d_utils.region_2d_to_origin_3d(region, space.region_3d, mouse_region)
        candidates.append((screen_distance, (midpoint_world - view_origin).length, pose_bone.name))
    return min(candidates)[2] if candidates else ""


def _activate_custom_weight_bone(context, settings, rig_obj, mesh_obj, bone_name):
    bone = rig_obj.data.bones.get(bone_name)
    pose_bone = rig_obj.pose.bones.get(bone_name)
    if not bone or not pose_bone or not bone.use_deform:
        return False
    for candidate_pose_bone in rig_obj.pose.bones:
        candidate_pose_bone.select = False
    bone.hide = False
    pose_bone.select = True
    _show_bone_collections(bone)
    rig_obj.data.bones.active = bone
    vertex_group = mesh_obj.vertex_groups.get(bone_name) or mesh_obj.vertex_groups.new(name=bone_name)
    mesh_obj.vertex_groups.active_index = vertex_group.index
    try:
        settings.wgame_custom_weight_bone = bone_name
    except TypeError:
        pass
    _set_focus_marker(
        context,
        rig_obj,
        bone_name,
        f"当前自定义权重骨骼：{bone_name}",
        mesh_obj=mesh_obj,
        diagnostic_name=bone_name,
        kind="WEIGHT_BROWSER",
        frame_view=False,
    )
    _tag_view3d_redraw()
    return True


def _toggle_custom_component_from_view(context, settings, component_index):
    components = _unrigged_components(settings)
    if component_index < 0 or component_index >= len(components):
        return False, "组件索引无效"
    component = components[component_index]
    if any(item.get("binding_scope") in {"BASE_SKIN", "MIXED"} for item in components):
        return False, "范围已经确认；请先点击“继续调整自定义选择”"
    _ensure_custom_mask_groups(context, settings)
    mesh_obj = context.scene.objects.get(component.get("object", ""))
    component_ids = set(component.get("vertex_indices") or [])
    current_ids = _mesh_vertex_group_ids(mesh_obj, CUSTOM_BIND_MASK_GROUP) if mesh_obj else set()
    marking_custom = not component_ids.issubset(current_ids)
    if not marking_custom and settings.unrigged_custom_selection_hidden:
        _set_component_vertices_hidden(context, component, False)
    _set_custom_mask_vertices(mesh_obj, component_ids, marking_custom)
    components = _sync_component_scopes_from_mask(context, settings, finalized=False)
    component = components[component_index]
    component.pop("role", None)
    component.pop("binding_group_id", None)
    settings.unrigged_components_json = json.dumps(components, ensure_ascii=False, separators=(",", ":"))
    settings.unrigged_component_index = component_index
    if marking_custom and settings.unrigged_custom_selection_hidden:
        # The component disappears immediately, so do not enter Edit Mode just
        # to highlight it first. Avoiding that transition also guarantees that
        # Blender cannot resync an older BMesh visibility state over the
        # already-hidden custom components.
        _set_component_vertices_hidden(context, component, True)
        _enter_component_edit_mode_without_reveal(context, component)
        _tag_view3d_redraw()
    else:
        _focus_unrigged_component(context, component)
    return True, "整岛已加入自定义绑定" if marking_custom else "整岛已移出自定义绑定"


def _set_component_base_region_override(context, settings, component_index, region):
    components = _unrigged_components(settings)
    if component_index < 0 or component_index >= len(components):
        return False, "组件索引无效"
    component = components[component_index]
    base_ids = _component_vertex_ids_for_scope(context, settings, component, "BASE_SKIN")
    if not base_ids:
        return False, "只能给基础蒙皮组件设置解剖语义"
    _ensure_base_region_mask_groups(context, settings)
    mesh_obj = context.scene.objects.get(component.get("object", ""))
    if region == "AUTO":
        changed = _set_base_region_mask_vertices(mesh_obj, base_ids, "AUTO")
        message = "已恢复自动语义"
    elif region in BASE_REGION_KEYS:
        changed = _set_base_region_mask_vertices(mesh_obj, base_ids, region)
        message = f"已锁定基础语义：{region}"
    else:
        return False, "未知基础组件语义"
    _sync_component_base_region_cache(context, settings)
    settings.unrigged_component_index = component_index
    _focus_unrigged_component(context, component)
    return bool(changed), message if changed else "当前顶点已经是该语义"


def _diagnostic_text_lines(value, limit=8):
    lines = [line.strip() for line in str(value or "").splitlines() if line.strip()]
    important = [
        line
        for line in lines
        if any(token in line.lower() for token in ("error", "fail", "exception", "invalid", "missing", "required", "conflict"))
    ]
    selected = important[-limit:] if important else lines[-limit:]
    return selected


def _authoring_response_failure(stage, response):
    response = response if isinstance(response, dict) else {"message": str(response or "")}
    report = response.get("report") if isinstance(response.get("report"), dict) else {}
    details = []

    def append(label, value):
        text = str(value or "").strip()
        entry = f"{label}：{text}" if text else ""
        if entry and entry not in details:
            details.append(entry)

    for key, label in (("message", "消息"), ("error", "错误"), ("code", "错误码"), ("errorCode", "错误码")):
        append(label, response.get(key))
    if "exitCode" in response:
        append("进程退出码", response.get("exitCode"))
    if response.get("timedOut"):
        append("超时", "是")
    append("报告目录", response.get("reportOut"))
    append("报告状态", report.get("status"))

    for owner in (response, report):
        for item in owner.get("issues") or []:
            if isinstance(item, dict):
                code = item.get("code") or item.get("errorCode") or ""
                message = item.get("message") or item.get("detail") or json.dumps(item, ensure_ascii=False)
                append("问题" + (f"[{code}]" if code else ""), message)
            else:
                append("问题", item)
        for item in owner.get("diagnostics") or []:
            if isinstance(item, dict):
                code = item.get("code") or item.get("errorCode") or ""
                message = item.get("message") or item.get("detail") or json.dumps(item, ensure_ascii=False)
                append("诊断" + (f"[{code}]" if code else ""), message)
            else:
                append("诊断", item)

    for label, key in (("stderr", "stderr"), ("stdout", "stdout")):
        for line in _diagnostic_text_lines(response.get(key)):
            append(label, line)

    summary = next(
        (
            line.split("：", 1)[1]
            for line in details
            if line.startswith(("错误码：", "错误：", "消息：", "问题", "诊断", "stderr：", "stdout："))
            and "：" in line
        ),
        "服务端未返回错误详情",
    )
    return "\n".join([f"{stage}失败：{summary}", *details])


def _http_json(base_url, path, method="GET", payload=None, timeout=15):
    url = (base_url or "").rstrip("/") + path
    body = None if payload is None else json.dumps(payload, ensure_ascii=False).encode("utf-8")
    request = urllib.request.Request(url, data=body, method=method)
    request.add_header("Accept", "application/json")
    if body is not None:
        request.add_header("Content-Type", "application/json; charset=utf-8")
    try:
        with urllib.request.urlopen(request, timeout=timeout) as response:
            return json.loads(response.read().decode("utf-8"))
    except urllib.error.HTTPError as error:
        message = error.read().decode("utf-8", errors="replace")
        try:
            detail = json.loads(message)
            message = _authoring_response_failure(f"Authoring HTTP {error.code}", detail)
        except ValueError:
            pass
        raise RuntimeError(message) from error


def _call_arp_in_view3d(context, operator, _active_object=None, **kwargs):
    window = context.window
    screen = context.screen
    area = context.area if context.area and context.area.type == "VIEW_3D" else None
    if not area:
        for candidate_window in context.window_manager.windows:
            candidate_screen = candidate_window.screen
            candidate_area = next((item for item in candidate_screen.areas if item.type == "VIEW_3D"), None)
            if candidate_area:
                window, screen, area = candidate_window, candidate_screen, candidate_area
                break
    region = next((item for item in area.regions if item.type == "WINDOW"), None) if area else None
    if not area or not region:
        raise RuntimeError("Auto-Rig Pro requires an active 3D View")
    active_object = _active_object
    override = {
        "window": window,
        "screen": screen,
        "area": area,
        "region": region,
        "space_data": area.spaces.active,
    }
    if active_object:
        override.update(
            {
                "active_object": active_object,
                "object": active_object,
                "selected_objects": [obj for obj in context.view_layer.objects if obj.select_get()],
                "selected_editable_objects": [obj for obj in context.view_layer.objects if obj.select_get() and not obj.hide_get()],
            }
        )
    with context.temp_override(**override):
        return operator(**kwargs)


def _initialize_arp_reference_for_mesh(context, rig_obj, mesh_obj):
    if not rig_obj or rig_obj.type != "ARMATURE" or not mesh_obj or mesh_obj.type != "MESH":
        raise RuntimeError("Reference Rig 或角色 Mesh 无效")
    source_height = max(float(rig_obj.dimensions.z), 0.0001)
    target_height = max(float(mesh_obj.dimensions.z), 0.0001)
    scale_factor = target_height / source_height

    _select_only(context, rig_obj)
    _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="EDIT")
    edit_bones = rig_obj.data.edit_bones
    snapshot = {
        bone.name: {
            "head": bone.head.copy(),
            "tail": bone.tail.copy(),
            "connected": bool(bone.use_connect),
        }
        for bone in edit_bones
    }
    for bone in edit_bones:
        bone.use_connect = False
    for bone in edit_bones:
        bone.head = snapshot[bone.name]["head"] * scale_factor
        bone.tail = snapshot[bone.name]["tail"] * scale_factor
        bone.head_radius *= scale_factor
        bone.tail_radius *= scale_factor
        bone.envelope_distance *= scale_factor

    def hierarchy_depth(bone):
        depth = 0
        parent = bone.parent
        while parent:
            depth += 1
            parent = parent.parent
        return depth

    for bone in sorted(list(edit_bones), key=hierarchy_depth):
        if snapshot[bone.name]["connected"] and bone.parent:
            scaled_vector = (snapshot[bone.name]["tail"] - snapshot[bone.name]["head"]) * scale_factor
            bone.head = bone.parent.tail.copy()
            bone.tail = bone.head + scaled_vector
            bone.use_connect = True
    _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="OBJECT")
    bpy.context.view_layer.update()

    for collection in rig_obj.data.collections:
        collection.is_visible = collection.name == "Reference"
    rig_obj.show_in_front = True
    rig_obj.display_type = "WIRE"
    rig_obj["wgame_reference_stage"] = True

    for collection in bpy.data.collections:
        if collection.name.startswith("character") and collection.name.endswith("_cs"):
            collection.hide_viewport = True
            collection.hide_render = True
    for obj in bpy.data.objects:
        if obj.name.startswith("cs_"):
            obj.hide_set(True)

    _select_only(context, rig_obj)
    if hasattr(bpy.ops, "arp") and bpy.ops.arp.edit_ref.poll():
        _call_arp_in_view3d(context, bpy.ops.arp.edit_ref)
    elif rig_obj.mode != "EDIT":
        _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="EDIT")

    for collection in rig_obj.data.collections:
        collection.is_visible = collection.name == "Reference"
    if rig_obj.mode == "EDIT":
        for bone in rig_obj.data.edit_bones:
            bone.select = any(collection.name == "Reference" for collection in bone.collections)
            bone.select_head = bone.select
            bone.select_tail = bone.select
    window = context.window
    screen = context.screen
    area = context.area if context.area and context.area.type == "VIEW_3D" else None
    if not area:
        for candidate_window in context.window_manager.windows:
            candidate_screen = candidate_window.screen
            candidate_area = next((item for item in candidate_screen.areas if item.type == "VIEW_3D"), None)
            if candidate_area:
                window, screen, area = candidate_window, candidate_screen, candidate_area
                break
    region = next((item for item in area.regions if item.type == "WINDOW"), None) if area else None
    if area and region:
        with context.temp_override(window=window, screen=screen, area=area, region=region, space_data=area.spaces.active):
            try:
                bpy.ops.view3d.view_selected(use_all_regions=False)
            except RuntimeError:
                pass
    return scale_factor


def _fit_arp_reference_from_joint_guides(context, settings, rig_obj):
    if not _joint_guides_complete(settings):
        raise RuntimeError("主要关节定位尚未全部确认")
    inverse_rig = rig_obj.matrix_world.inverted()

    def position(guide_id):
        obj = _joint_guide_object(guide_id)
        if not obj:
            raise RuntimeError(f"缺少关节定位点：{guide_id}")
        return inverse_rig @ obj.matrix_world.translation

    if getattr(context, "object", None) != rig_obj or rig_obj.mode != "EDIT":
        _select_only(context, rig_obj)
        _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="EDIT")
    edit_bones = rig_obj.data.edit_bones
    snapshot = {
        bone.name: {
            "head": bone.head.copy(),
            "tail": bone.tail.copy(),
            "connected": bool(bone.use_connect),
        }
        for bone in edit_bones
    }
    for bone in edit_bones:
        bone.use_connect = False

    pelvis, chest, neck, head_top = (position(item) for item in ("pelvis.x", "chest.x", "neck.x", "head_top.x"))
    spine_a = pelvis.lerp(chest, 0.34)
    spine_b = pelvis.lerp(chest, 0.67)
    center_targets = {
        "root_ref.x": (pelvis, spine_a),
        "spine_01_ref.x": (spine_a, spine_b),
        "spine_02_ref.x": (spine_b, chest),
        "neck_ref.x": (chest, neck),
        "head_ref.x": (neck, head_top),
    }
    for name, (head, tail) in center_targets.items():
        bone = edit_bones.get(name)
        if bone:
            bone.head, bone.tail = head, tail

    jaw = edit_bones.get("jaw_ref.x")
    if jaw:
        vector = snapshot[jaw.name]["tail"] - snapshot[jaw.name]["head"]
        jaw.head = position("jaw.x")
        jaw.tail = jaw.head + vector

    def descendants(root):
        result = []
        stack = list(root.children)
        while stack:
            current = stack.pop()
            result.append(current)
            stack.extend(current.children)
        return result

    for side in ("l", "r"):
        shoulder = position(f"shoulder.{side}")
        elbow = position(f"elbow.{side}")
        wrist = position(f"wrist.{side}")
        hand_end = position(f"hand_end.{side}")
        hand_bone = edit_bones.get(f"hand_ref.{side}")
        if hand_bone:
            delta = wrist - hand_bone.head
            for child in descendants(hand_bone):
                child.head += delta
                child.tail += delta
        arm_targets = {
            f"shoulder_ref.{side}": (chest, shoulder),
            f"arm_ref.{side}": (shoulder, elbow),
            f"forearm_ref.{side}": (elbow, wrist),
            f"hand_ref.{side}": (wrist, hand_end),
        }
        for name, (head, tail) in arm_targets.items():
            bone = edit_bones.get(name)
            if bone:
                bone.head, bone.tail = head, tail

        hip = position(f"hip.{side}")
        knee = position(f"knee.{side}")
        ankle = position(f"ankle.{side}")
        ball = position(f"ball.{side}")
        toe = position(f"toe.{side}")
        leg_targets = {
            f"thigh_ref.{side}": (hip, knee),
            f"leg_ref.{side}": (knee, ankle),
            f"foot_ref.{side}": (ankle, ball),
            f"toes_ref.{side}": (ball, toe),
        }
        for name, (head, tail) in leg_targets.items():
            bone = edit_bones.get(name)
            if bone:
                bone.head, bone.tail = head, tail

    def hierarchy_depth(bone):
        depth = 0
        parent = bone.parent
        while parent:
            depth += 1
            parent = parent.parent
        return depth

    for bone in sorted(list(edit_bones), key=hierarchy_depth):
        if snapshot[bone.name]["connected"] and bone.parent:
            vector = bone.tail - bone.head
            bone.head = bone.parent.tail.copy()
            bone.tail = bone.head + vector
            bone.use_connect = True

    collection = bpy.data.collections.get("WGame_RigGuides")
    if collection:
        collection.hide_viewport = True
    return True


def _resolve_repository_root(settings, persist=True):
    configured = (settings.repository_root or os.environ.get("WGAME_PROJECT_ROOT", "")).strip()
    if configured and os.path.isdir(configured):
        return os.path.abspath(configured)
    current = bpy.data.filepath
    if current:
        candidate = pathlib.Path(current).resolve().parent
        for parent in (candidate, *candidate.parents):
            if (parent / "ArtSource" / "Characters").is_dir() and (parent / ".gitattributes").is_file():
                if persist:
                    settings.repository_root = str(parent)
                return str(parent)
    deployment_path = pathlib.Path(__file__).with_name("wgame_rigging_assistant.deployment.json")
    if deployment_path.is_file():
        try:
            deployed = pathlib.Path(json.loads(deployment_path.read_text(encoding="utf-8-sig")).get("repositoryRoot", "")).resolve()
            if (deployed / "ArtSource" / "Characters").is_dir() and (deployed / ".gitattributes").is_file():
                if persist:
                    settings.repository_root = str(deployed)
                return str(deployed)
        except (OSError, ValueError, TypeError):
            pass
    return ""


def _adopt_optional_source(settings, item_id, kind, role, relative_path):
    character_id = (settings.character_id or "").strip()
    package = f"Authoring/CharacterPackages/character-{character_id}"
    state = _http_json(
        settings.authoring_server_url,
        "/api/character/authoring-sources?package=" + urllib.parse.quote(package),
    )
    return _http_json(
        settings.authoring_server_url,
        "/api/character/authoring-sources/apply",
        method="POST",
        payload={
            "package": package,
            "expectedRevision": int((state.get("manifest") or {}).get("revision") or 0),
            "action": "adopt",
            "id": item_id,
            "kind": kind,
            "role": role,
            "path": relative_path,
        },
    )


class WGAME_RIGGING_OT_create_numeric_character(Operator):
    bl_idname = "wgame_rigging.create_numeric_character"
    bl_label = "从编号池创建新角色"
    bl_description = "通过 Authoring Server 分配六位编号并原子创建 Character package 与 ArtSource"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        display_name = (settings.character_display_name or "").strip()
        if not display_name:
            self.report({"ERROR"}, "请先填写角色显示名称")
            return {"CANCELLED"}
        try:
            catalog = _http_json(settings.authoring_server_url, "/api/character/id-catalog")
            result = _http_json(
                settings.authoring_server_url,
                "/api/character/create",
                method="POST",
                payload={
                    "displayName": display_name,
                    "template": settings.numeric_template,
                    "idCatalogRevision": int(catalog.get("revision") or 0),
                },
            )
        except Exception as error:
            self.report({"ERROR"}, "创建角色失败：" + str(error))
            return {"CANCELLED"}
        character_id = str(result.get("allocatedCharacterId") or "")
        if len(character_id) != 6 or not character_id.isdigit():
            self.report({"ERROR"}, "Authoring Server 未返回有效六位编号")
            return {"CANCELLED"}
        settings.character_id = character_id
        settings.last_status = "数字角色已创建"
        settings.last_report = f"角色编号：{character_id}\n显示名称：{display_name}\nArtSource：{result.get('artSourceRelative', '')}"
        self.report({"INFO"}, f"已创建 {character_id} · {display_name}")
        return {"FINISHED"}


class WGAME_RIGGING_OT_bootstrap_current_character_source(Operator):
    bl_idname = "wgame_rigging.bootstrap_current_character_source"
    bl_label = "申请 ID 并纳入原材料"
    bl_description = "为当前外部 Blend 申请六位角色 ID、创建 ArtSource/Authoring 包，并把当前文件保存为版本化 Work Blend"
    bl_options = {"REGISTER"}

    def invoke(self, context, event):
        return context.window_manager.invoke_confirm(self, event)

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        display_name = (settings.character_display_name or "").strip()
        if not display_name:
            self.report({"ERROR"}, "请先填写角色显示名称")
            return {"CANCELLED"}
        root_text = _resolve_repository_root(settings)
        if not root_text:
            self.report({"ERROR"}, "无法定位仓库根；请重新安装插件或手动选择仓库根")
            return {"CANCELLED"}
        root = pathlib.Path(root_text).resolve()
        character_id = (settings.character_id or "").strip()
        created = False
        try:
            _ensure_authoring_server(
                settings,
                root,
                "Tools/MxFramework.Authoring/samples/character-codex-flow-test",
            )
            if len(character_id) != 6 or not character_id.isdigit() or character_id == "000000":
                catalog = _http_json(settings.authoring_server_url, "/api/character/id-catalog")
                result = _http_json(
                    settings.authoring_server_url,
                    "/api/character/create",
                    method="POST",
                    payload={
                        "displayName": display_name,
                        "template": settings.numeric_template,
                        "idCatalogRevision": int(catalog.get("revision") or 0),
                    },
                    timeout=120,
                )
                character_id = str(result.get("allocatedCharacterId") or "")
                if len(character_id) != 6 or not character_id.isdigit():
                    raise RuntimeError("Authoring Server 未返回有效六位角色编号")
                created = True
            package_relative = f"Authoring/CharacterPackages/character-{character_id}"
            package_root = root / pathlib.Path(*package_relative.split("/"))
            character_root = root / "ArtSource" / "Characters" / character_id
            if not package_root.is_dir() or not character_root.is_dir():
                raise RuntimeError("角色 ID 已设置，但对应 ArtSource/Authoring 目录不存在")

            settings.character_id = character_id
            settings.character_display_name = display_name
            settings.repository_root = str(root)
            settings.versioned_sources = True
            work_path = character_root / "Blender_Work" / f"{character_id}_work.blend"
            work_path.parent.mkdir(parents=True, exist_ok=True)
            current_path = pathlib.Path(bpy.data.filepath).resolve() if bpy.data.filepath else None
            if work_path.exists() and current_path != work_path:
                raise RuntimeError("目标 Work Blend 已存在，拒绝覆盖：" + str(work_path))
            save_result = bpy.ops.wm.save_as_mainfile(filepath=str(work_path), check_existing=False)
            if "FINISHED" not in save_result:
                raise RuntimeError("无法把当前 Blender 文件保存到版本化 Work 目录")

            adopted = _adopt_optional_source(
                settings,
                "blender-work",
                "BlenderWork",
                "active-work",
                f"Blender_Work/{character_id}_work.blend",
            )
            if not adopted.get("success"):
                raise RuntimeError("Work Blend 已保存，但制作清单采用失败")
            if hasattr(context.scene, "wgame_palette_package_root"):
                context.scene.wgame_palette_package_root = str(package_root)
                context.scene.wgame_palette_exported_model_path = str(
                    character_root / "Final_Source" / f"{character_id}_LOD0.fbx"
                )
                palette_addon = _loaded_palette_tools()
                palette_addon.load_catalog(context, prefer_server=True)
                context.scene.wgame_character_color_profile_path = str(
                    package_root / "config" / "character_color_profile.json"
                )
                palette_addon.save_character_color_profile(context.scene)
                # Palette tokens and color profiles remain authoring inputs. Registration
                # must not create a legacy runtime binding for a new baked character.
                # Existing package bindings are left untouched.
                for mesh_obj in (obj for obj in context.scene.objects if obj.type == "MESH"):
                    for attribute in list(mesh_obj.data.attributes):
                        if attribute.name == "PaletteSlot" or attribute.name == "MaterialClass" or attribute.name.startswith("MaterialClass."):
                            mesh_obj.data.attributes.remove(attribute)
                    mesh_obj.data.update()
                save_result = bpy.ops.wm.save_as_mainfile(filepath=str(work_path), check_existing=False)
                if "FINISHED" not in save_result:
                    raise RuntimeError("Palette Profile 已建立，但版本化 Work Blend 保存失败")
            _set_report(
                context,
                "当前角色已纳入原材料",
                [
                    "角色编号：" + character_id,
                    "显示名称：" + display_name,
                    "Work Blend：" + str(work_path),
                    "ArtSource：" + str(character_root),
                    "Authoring Package：" + str(package_root),
                    "下一步：完成绑定与材质设置后点击“发布到 Unity”",
                ],
            )
            if settings.wgame_component_skin_complete:
                self.report({"INFO"}, f"{character_id} 原材料已建立；继续发布 FBX 与 Unity")
                return bpy.ops.wgame_rigging.publish_fbx_and_update_unity("EXEC_DEFAULT")
            self.report(
                {"INFO"},
                ("已申请并创建 " if created else "已采用 ") + character_id + " · " + display_name,
            )
            return {"FINISHED"}
        except Exception as error:
            _set_report(context, "首次纳入原材料失败", [str(error)])
            self.report({"ERROR"}, str(error).splitlines()[0])
            return {"CANCELLED"}


def _scan_model_preflight(context):
    """Read-only topology evidence. IDs locate issues; topology observations are not auto-repairs."""
    objects = []
    for obj in _formal_binding_meshes(context):
        obj.update_from_editmode()
        mesh = obj.data
        issues = []
        def issue(key, label, severity, domain, indices):
            if indices:
                issues.append({"key": key, "label": label, "severity": severity, "domain": domain,
                               "count": len(indices), "indices": list(indices)})
        invalid = [v.index for v in mesh.vertices if not all(math.isfinite(x) for x in v.co)]
        issue("invalid_coordinates", "无效顶点坐标", "BLOCK", "VERT", invalid)
        if not mesh.vertices or not mesh.polygons:
            issue("empty_mesh", "空网格或没有表面", "BLOCK", "OBJECT", [0])
        if _armature_modifier(obj):
            issue("old_binding", "仍有 Armature Modifier", "BLOCK", "OBJECT", [0])
        if obj.parent and obj.parent.type == "ARMATURE":
            issue("armature_parent", "仍以 Armature 为父级", "BLOCK", "OBJECT", [0])
        if any(abs(value - 1.0) > 0.0001 for value in obj.scale) or any(abs(value) > 0.0001 for value in obj.rotation_euler):
            issue("transforms", "旋转或缩放未应用", "BLOCK", "OBJECT", [0])
        valid_world = all(math.isfinite(value) for row in obj.matrix_world for value in row) and abs(obj.matrix_world.determinant()) >= 1e-12
        if not valid_world:
            issue("world_transform", "世界变换无效或不可逆", "BLOCK", "OBJECT", [0])
        reserved = lambda name: name.startswith("WGame.")
        groups = [group.index for group in obj.vertex_groups if not reserved(group.name)]
        issue("vertex_groups", "已有顶点组，需确认是否为旧权重", "WARN", "OBJECT", groups)
        if not mesh.uv_layers:
            issue("uv", "没有 UV", "WARN", "OBJECT", [0])
        if not obj.material_slots or any(slot.material is None for slot in obj.material_slots):
            issue("materials", "材质槽缺失或为空", "WARN", "OBJECT", [0])
        components = 0
        dimension = max((value for value in obj.dimensions if math.isfinite(value)), default=0.0)
        tolerance = max(dimension * 1e-6, 1e-8)
        if mesh.vertices and not invalid:
            bm = bmesh.new()
            try:
                bm.from_mesh(mesh)
                bm.verts.ensure_lookup_table(); bm.edges.ensure_lookup_table(); bm.faces.ensure_lookup_table()
                bm.normal_update()
                issue("loose_vertices", "孤立顶点", "WARN", "VERT", [v.index for v in bm.verts if not v.link_edges])
                issue("loose_edges", "松散边", "WARN", "EDGE", [e.index for e in bm.edges if not e.link_faces])
                issue("zero_edges", "零长度边", "BLOCK", "EDGE", [e.index for e in bm.edges if e.calc_length() <= 1e-10])
                issue("degenerate_faces", "零面积或退化面", "BLOCK", "FACE", [f.index for f in bm.faces if f.calc_area() <= 1e-14])
                issue("boundary", "开口边（袖口/裙摆等允许保留，需确认）", "WARN", "EDGE", [e.index for e in bm.edges if len(e.link_faces) == 1])
                issue("nonmanifold", "超过两面共用的边", "WARN", "EDGE", [e.index for e in bm.edges if len(e.link_faces) > 2])
                issue("winding", "相邻面绕向不一致", "WARN", "EDGE", [e.index for e in bm.edges if len(e.link_faces) == 2 and not e.is_contiguous])
                seen_faces = {}
                duplicates = []
                for face in mesh.polygons:
                    key = tuple(sorted(face.vertices))
                    if key in seen_faces:
                        duplicates.append(face.index)
                    else:
                        seen_faces[key] = face.index
                issue("duplicate_faces", "重复顶点集合的面", "BLOCK", "FACE", duplicates)
                components = _connected_component_count(mesh)
                if components > 1:
                    issue("components", "独立连通岛（不等于语义部件）", "WARN", "OBJECT", list(range(components)))
                if valid_world:
                    tree = KDTree(len(mesh.vertices))
                    for vertex in mesh.vertices:
                        tree.insert(obj.matrix_world @ vertex.co, vertex.index)
                    tree.balance()
                    nearby = []
                    for vertex in mesh.vertices:
                        if any(index < vertex.index for _point, index, _distance in tree.find_range(obj.matrix_world @ vertex.co, tolerance)):
                            nearby.append(vertex.index)
                    issue("near_vertices", "近重合顶点（不自动焊接）", "WARN", "VERT", nearby)
            finally:
                bm.free()
        objects.append({"name": obj.name, "vertices": len(mesh.vertices), "edges": len(mesh.edges),
                        "polygons": len(mesh.polygons), "components": components,
                        "nearVertexToleranceWorld": tolerance, "issues": issues})
    excluded = [obj.name for obj in context.scene.objects if obj.type == "MESH" and not _is_formal_character_mesh(obj)]
    blockers = sum(item["severity"] == "BLOCK" for obj in objects for item in obj["issues"])
    return {"version": 1, "fingerprint": _unrigged_fingerprint(context), "objects": objects, "excluded": excluded,
            "blockerCount": blockers + (not objects),
            "warningCount": sum(item["severity"] == "WARN" for obj in objects for item in obj["issues"])}


def _repair_degenerate_mesh(mesh):
    """Work on a detached mesh copy. Weld only endpoints connected by near-zero edges."""
    bm = bmesh.new()
    try:
        bm.from_mesh(mesh)
        bm.verts.ensure_lookup_table()
        parents = {v: v for v in bm.verts}
        def root(v):
            while parents[v] != v:
                parents[v] = parents[parents[v]]
                v = parents[v]
            return v
        for edge in bm.edges:
            if edge.calc_length() <= 1e-10:
                first, second = (root(v) for v in edge.verts)
                if first != second:
                    keep, remove = sorted((first, second), key=lambda v: v.index)
                    parents[remove] = keep
        targets = {v: root(v) for v in bm.verts if root(v) != v}
        deform = bm.verts.layers.deform.active
        if deform:
            for vertex, target in targets.items():
                if dict(vertex[deform]) != dict(target[deform]):
                    raise RuntimeError("零长度边端点的顶点组/蒙版不同，需人工确认后合并")
        merged = len(targets)
        faces_before = len(bm.faces)
        if targets:
            bmesh.ops.weld_verts(bm, targetmap=targets)
        degenerate = [face for face in bm.faces if face.calc_area() <= 1e-14]
        if degenerate:
            bmesh.ops.delete(bm, geom=degenerate, context="FACES_ONLY")
        bm.normal_update()
        removed_faces = faces_before - len(bm.faces)
        if any(edge.calc_length() <= 1e-10 for edge in bm.edges):
            raise RuntimeError("局部合并后仍存在零长度边，未应用修改")
        bm.to_mesh(mesh)
        mesh.update()
        return merged, removed_faces
    finally:
        bm.free()


def _merge_same_island_vertices(mesh, matrix_world, tolerance):
    """Use original edge connectivity and bounded representative distances; never join islands."""
    if not math.isfinite(tolerance) or tolerance <= 0:
        raise RuntimeError("近重合容差无效")
    bm = bmesh.new()
    try:
        bm.from_mesh(mesh)
        bm.verts.ensure_lookup_table()
        labels = {}
        for vertex in bm.verts:
            if vertex in labels:
                continue
            label = vertex.index
            labels[vertex] = label
            pending = [vertex]
            while pending:
                current = pending.pop()
                for edge in current.link_edges:
                    other = edge.other_vert(current)
                    if other not in labels:
                        labels[other] = label
                        pending.append(other)
        points = [matrix_world @ vertex.co for vertex in bm.verts]
        if any(not math.isfinite(value) for point in points for value in point):
            raise RuntimeError("网格世界坐标无效")
        tree = KDTree(len(points))
        for index, point in enumerate(points):
            tree.insert(point, index)
        tree.balance()
        targets = {}
        skipped = 0
        deform = bm.verts.layers.deform.active
        for vertex in bm.verts:
            candidates = sorted(index for _point, index, _distance in tree.find_range(points[vertex.index], tolerance)
                                if index < vertex.index and labels[bm.verts[index]] == labels[vertex])
            conflict = False
            for index in candidates:
                target = bm.verts[index]
                # Do not chain A-B-C beyond the specified merge distance from A.
                if target in targets:
                    continue
                if deform and dict(vertex[deform]) != dict(target[deform]):
                    conflict = True
                    continue
                targets[vertex] = target
                break
            if vertex not in targets and conflict:
                skipped += 1
        # Reject only candidate groups that would create an edge shared by too many faces.
        # Predict connectivity before welding, retaining unrelated safe groups.
        original_edges = {tuple(sorted(v.index for v in edge.verts)): len(edge.link_faces) for edge in bm.edges}
        while targets:
            incidence = {}
            for face in bm.faces:
                ids = [targets.get(v, v).index for v in face.verts]
                compact = [value for i, value in enumerate(ids) if value != ids[i-1]]
                if len(set(compact)) < 3:
                    continue
                face_key = tuple(sorted(set(compact)))
                for i, first in enumerate(compact):
                    second = compact[(i + 1) % len(compact)]
                    if first != second:
                        incidence.setdefault(tuple(sorted((first, second))), set()).add(face_key)
            bad_vertices = {index for edge, faces in incidence.items()
                            if len(faces) > max(2, original_edges.get(edge, 0)) for index in edge}
            rejected = [vertex for vertex, target in targets.items() if target.index in bad_vertices]
            if not rejected:
                break
            skipped += len(rejected)
            for vertex in rejected:
                del targets[vertex]
        if not targets:
            return 0, 0, skipped
        affected_faces = {face for vertex in set(targets) | set(targets.values()) for face in vertex.link_faces}
        before_faces = len(bm.faces)
        nonmanifold_before = sum(len(edge.link_faces) > 2 for edge in bm.edges)
        bmesh.ops.weld_verts(bm, targetmap=targets)
        collapsed = [face for face in affected_faces if face.is_valid and face.calc_area() <= 1e-14]
        if collapsed:
            bmesh.ops.delete(bm, geom=collapsed, context="FACES_ONLY")
        if sum(len(edge.link_faces) > 2 for edge in bm.edges) > nonmanifold_before:
            raise RuntimeError("同岛合并会增加异常共边，已保留原网格，请局部处理")
        bm.normal_update()
        bm.to_mesh(mesh)
        mesh.update()
        return len(targets), before_faces - len(bm.faces), skipped
    finally:
        bm.free()


class WGAME_RIGGING_OT_repair_preflight_degenerates(Operator):
    bl_idname = "wgame_rigging.repair_preflight_degenerates"
    bl_label = "修复零长度边与退化面"
    bl_description = "先备份，只合并零长度边的相连端点并删除退化面；不全模型按距离焊接，不补洞；完成后重新预检，可撤销"
    bl_options = {"REGISTER", "UNDO"}

    same_island: BoolProperty(default=False, options={"HIDDEN"})

    @classmethod
    def description(cls, context, properties):
        if properties.same_island:
            return "先备份，按预检世界空间容差仅合并原始同一连通岛内的近重合顶点；跳过权重/蒙版冲突，不跨岛；自动重新预检，可撤销"
        return cls.bl_description

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        if context.object and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        report = _scan_model_preflight(context)
        repair_keys = {"near_vertices"} if self.same_island else {"zero_edges", "degenerate_faces"}
        names = [entry["name"] for entry in report["objects"]
                 if any(item["key"] in repair_keys for item in entry["issues"])]
        if not names:
            self.report({"INFO"}, "没有命中当前修复范围的问题")
            return {"FINISHED"}
        if not bpy.data.filepath:
            self.report({"ERROR"}, "请先保存 Blend，以便创建修复前备份")
            return {"CANCELLED"}
        staged = []
        applied = False
        try:
            for name in names:
                obj = context.scene.objects[name]
                if obj.data.shape_keys or _armature_modifier(obj):
                    raise RuntimeError(name + " 存在 Shape Keys 或 Armature 绑定，需专门处理拓扑变更")
                if any(not math.isfinite(value) for vertex in obj.data.vertices for value in vertex.co):
                    raise RuntimeError(name + " 有无效坐标，请先处理")
                candidate = obj.data.copy()
                staged.append((obj, obj.data, candidate))
            if self.same_island:
                tolerances = {entry["name"]: entry["nearVertexToleranceWorld"] for entry in report["objects"]}
                counts = [_merge_same_island_vertices(candidate, obj.matrix_world, tolerances[obj.name])
                          for obj, _old, candidate in staged]
            else:
                counts = [(*_repair_degenerate_mesh(candidate), 0) for _obj, _old, candidate in staged]
            skipped = sum(count[2] for count in counts)
            if not any(count[0] or count[1] for count in counts):
                self.report({"INFO"}, f"没有可合并的同岛顶点；属性或拓扑冲突跳过 {skipped} 个；不同岛保持分离")
                return {"FINISHED"}
            # Verify the backup write before committing any staged geometry.
            source = pathlib.Path(bpy.data.filepath)
            stamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S_%f")
            backup = source.with_name(source.stem + ("_same_island_merge_backup_" if self.same_island else "_preflight_repair_backup_") + stamp + ".blend")
            result = bpy.ops.wm.save_as_mainfile(filepath=str(backup), copy=True, check_existing=False)
            if "FINISHED" not in result or not backup.is_file() or backup.stat().st_size == 0:
                raise RuntimeError("备份未成功写入，未应用修复")
            for obj, _old, candidate in staged:
                obj.data = candidate
            applied = True
            settings.backup_filepath = str(backup)
            _invalidate_model_preflight(settings)
            bpy.ops.wgame_rigging.unrigged_preflight()
            merged = sum(count[0] for count in counts)
            removed = sum(count[1] for count in counts)
            self.report({"INFO"}, f"已合并 {merged} 个顶点，移除 {removed} 个退化面；属性或拓扑冲突跳过 {skipped} 个；已备份并重新预检，可 Ctrl+Z 撤销")
            return {"FINISHED"}
        except Exception as error:
            for obj, old, _candidate in staged:
                if obj.data != old:
                    obj.data = old
            applied = False
            _invalidate_model_preflight(settings)
            self.report({"ERROR"}, str(error))
            return {"CANCELLED"}
        finally:
            if not applied:
                for _obj, _old, candidate in staged:
                    if candidate.users == 0:
                        bpy.data.meshes.remove(candidate)


def _draw_model_review(layout, settings):
    report = _json_load(settings.unrigged_preflight_report, {})
    if report:
        layout.label(text=f"正式 Mesh {len(report.get('objects', []))} / 排除 {len(report.get('excluded', []))}")
        layout.label(text=f"阻塞 {report.get('blockerCount', 0)} / 待确认 {report.get('warningCount', 0)}")
        layout.operator("wgame_rigging.show_report", text="查看完整预检报告", icon="TEXT")
        if any(item["key"] in {"zero_edges", "degenerate_faces"} for obj in report.get("objects", []) for item in obj["issues"]):
            layout.operator("wgame_rigging.repair_preflight_degenerates", icon="AUTOMERGE_ON")
        if any(item["key"] == "near_vertices" for obj in report.get("objects", []) for item in obj["issues"]):
            op = layout.operator("wgame_rigging.repair_preflight_degenerates", text="合并同岛近重合顶点", icon="AUTOMERGE_ON")
            op.same_island = True
        for obj in report.get("objects", []):
            layout.label(text=obj["name"])
            for item in obj["issues"]:
                row = layout.row()
                row.label(text=f"{item['label'].split('（')[0]}：{item['count']}", icon="ERROR" if item["severity"] == "BLOCK" else "INFO")
                if item["domain"] != "OBJECT":
                    op = row.operator("wgame_rigging.focus_preflight_issue", text="定位")
                    op.object_name = obj["name"]
                    op.issue_key = item["key"]
        for name in report.get("excluded", []):
            layout.label(text="已排除：" + name)
    layout.operator("wgame_rigging.toggle_binding_participant", text="切换所选 Mesh 是否参与绑定")
    if settings.unrigged_preflight_passed:
        layout.label(text="进入下一步前逐项确认：")
        for name in ("unrigged_topology_reviewed", "unrigged_pose_reviewed", "unrigged_hands_reviewed", "unrigged_regions_reviewed", "unrigged_review_notes"):
            layout.prop(settings, name)


class WGAME_RIGGING_OT_toggle_binding_participant(Operator):
    bl_idname = "wgame_rigging.toggle_binding_participant"
    bl_label = "切换网格参与绑定"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        obj = context.view_layer.objects.active
        if not obj or obj.type != "MESH":
            self.report({"ERROR"}, "请先选择一个 Mesh")
            return {"CANCELLED"}
        obj["wgame_rig_exclude_from_binding"] = not bool(obj.get("wgame_rig_exclude_from_binding", False))
        _invalidate_model_preflight(context.scene.wgame_rigging_assistant)
        self.report({"INFO"}, obj.name + (" 已排除" if not _is_formal_character_mesh(obj) else " 已纳入") + "；请重新预检")
        return {"FINISHED"}


class WGAME_RIGGING_OT_focus_preflight_issue(Operator):
    bl_idname = "wgame_rigging.focus_preflight_issue"
    bl_label = "定位预检问题"
    bl_options = {"REGISTER"}
    object_name: StringProperty()
    issue_key: StringProperty()

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        report = _json_load(settings.unrigged_preflight_report, {})
        if report.get("fingerprint") != _unrigged_fingerprint(context):
            _invalidate_model_preflight(settings)
            self.report({"ERROR"}, "几何已变化，请重新预检后定位")
            return {"CANCELLED"}
        obj = context.scene.objects.get(self.object_name)
        entry = next((entry for entry in report.get("objects", []) if entry["name"] == self.object_name), {})
        issue = next((item for item in entry.get("issues", []) if item["key"] == self.issue_key), None)
        if not obj or not issue:
            return {"CANCELLED"}
        if context.object and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        _select_only(context, obj)
        for vertex in obj.data.vertices: vertex.select = False
        for edge in obj.data.edges: edge.select = False
        for face in obj.data.polygons: face.select = False
        collection = {"VERT": obj.data.vertices, "EDGE": obj.data.edges, "FACE": obj.data.polygons}.get(issue["domain"])
        if collection is not None:
            for index in issue["indices"]:
                collection[index].select = True
            context.tool_settings.mesh_select_mode = tuple(issue["domain"] == name for name in ("VERT", "EDGE", "FACE"))
            bpy.ops.object.mode_set(mode="EDIT")
        self.report({"INFO"}, f"已选择 {issue['count']} 个问题元素；可按小键盘 . 聚焦")
        return {"FINISHED"}


class WGAME_RIGGING_OT_unrigged_preflight(Operator):
    bl_idname = "wgame_rigging.unrigged_preflight"
    bl_label = "无骨骼模型预检"
    bl_description = "检查全部正式 Mesh 的数据和拓扑；开口等例外需人工确认，不自动修补"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        report = _scan_model_preflight(context)
        changed = settings.unrigged_model_fingerprint != report["fingerprint"]
        if changed or report["blockerCount"]:
            _invalidate_model_preflight(settings)
        settings.unrigged_preflight_report = json.dumps(report, ensure_ascii=False, separators=(",", ":"))
        settings.unrigged_model_fingerprint = report["fingerprint"]
        settings.unrigged_preflight_passed = report["blockerCount"] == 0
        lines = ["正式 Mesh：" + ", ".join(obj["name"] for obj in report["objects"]),
                 "排除：" + ", ".join(report["excluded"]),
                 f"阻塞项 {report['blockerCount']} / 待确认项 {report['warningCount']}"]
        if not report["objects"]: lines.append("没有正式 Mesh")
        for obj in report["objects"]:
            lines.append(f"{obj['name']}：{obj['vertices']} 顶点 / {obj['polygons']} 面 / {obj['components']} 岛")
            lines.extend(f"  {item['label']}：{item['count']}；{item['domain']} IDs {item['indices'][:20]}" for item in obj["issues"])
        lines.append("待人工确认：允许的开口/重叠、姿势与朝向、双手五指、身体与衣物混合区域。自相交与语义误连未自动判定。")
        _set_report(context, "预检阻塞" if report["blockerCount"] else "数据检查通过，待姿势与区域确认", lines)
        self.report({"WARNING" if report["blockerCount"] else "INFO"}, lines[2])
        return {"FINISHED"}


class WGAME_RIGGING_OT_create_joint_guides(Operator):
    bl_idname = "wgame_rigging.create_joint_guides"
    bl_label = "创建主要关节定位点"
    bl_description = "根据身体截面估算主要关节；刷新未调整的默认点，保留手动调整和已确认点；不会创建骨架或权重"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        if not _current_model_preflight(context, settings) or not settings.unrigged_pose_locked:
            self.report({"ERROR"}, "请先完成当前正式模型预检与姿势/区域确认")
            return {"CANCELLED"}
        meshes = [obj for obj in context.scene.objects if _is_formal_character_mesh(obj)]
        mesh_obj = max(meshes, key=lambda item: len(item.data.vertices), default=None)
        if not mesh_obj:
            return {"CANCELLED"}
        collection = bpy.data.collections.get("WGame_RigGuides")
        if not collection:
            collection = bpy.data.collections.new("WGame_RigGuides")
            context.scene.collection.children.link(collection)
        base_ids = _scope_vertex_ids_by_object(settings, "BASE_SKIN", context)
        body_points = [obj.matrix_world @ obj.data.vertices[index].co for obj in meshes
                       for index in base_ids.get(obj.name, []) if 0 <= index < len(obj.data.vertices)]
        defaults = _default_joint_guide_positions(mesh_obj, body_points)
        legacy = _legacy_joint_guide_positions(mesh_obj)
        height = max(float(mesh_obj.dimensions.z), 0.0001)
        state = _joint_guide_state(settings)
        for guide_id, _label, _description in JOINT_GUIDE_DEFINITIONS:
            ids = [guide_id]
            mirrored_id = _mirrored_guide_id(guide_id)
            if mirrored_id:
                ids.append(mirrored_id)
            preserve = bool(state.get(guide_id, {}).get("accepted"))
            for current_id in ids:
                old_position = legacy[guide_id].copy()
                if current_id.endswith(".r"):
                    old_position.x *= -1
                preserve |= not _joint_guide_default_is_untouched(_joint_guide_object(current_id), old_position, height * 1e-5)
            for current_id in ids:
                obj = _joint_guide_object(current_id)
                if obj is not None and preserve:
                    continue
                if not obj:
                    obj = bpy.data.objects.new(_joint_guide_object_name(current_id), None)
                    collection.objects.link(obj)
                base_position = (_joint_guide_object(guide_id).location.copy()
                                 if preserve and _joint_guide_object(guide_id) and current_id != guide_id
                                 else defaults[guide_id])
                obj.location = Vector((-base_position.x, base_position.y, base_position.z)) if current_id.endswith(".r") else base_position
                obj["wgame_joint_default_position"] = list(obj.location)
                obj.empty_display_type = "SPHERE"
                obj.empty_display_size = height * 0.007
                obj.show_in_front = True
                obj.color = (0.2, 0.55, 1.0, 1.0) if current_id.endswith(".r") else (1.0, 0.35, 0.08, 1.0) if current_id.endswith(".l") else (0.1, 0.9, 0.9, 1.0)
            if not preserve:
                state[guide_id] = {"accepted": False}
        settings.unrigged_joint_guide_index = 0
        _save_joint_guide_state(settings, state)
        _sync_all_joint_guide_mirrors(settings)
        bpy.ops.wgame_rigging.focus_joint_guide()
        self.report({"INFO"}, f"已创建 {len(JOINT_GUIDE_DEFINITIONS)} 个主要关节定位项")
        return {"FINISHED"}


class WGAME_RIGGING_OT_pick_joint_guide(Operator):
    bl_idname = "wgame_rigging.pick_joint_guide"
    bl_label = "点选关节定位点"
    bl_description = "点击关节圆圈或名称选中；镜像开启时右侧对应左侧控制点"
    bl_options = {"INTERNAL"}

    @classmethod
    def poll(cls, context):
        collection = bpy.data.collections.get("WGame_RigGuides")
        return bool(context.mode == "OBJECT" and context.area and context.area.type == "VIEW_3D"
                    and context.region and context.region.type == "WINDOW"
                    and collection and not collection.hide_viewport and not collection.hide_select
                    and getattr(context.scene, "wgame_rigging_assistant", None))

    def invoke(self, context, event):
        hit = _joint_guide_hit_test(context, (event.mouse_region_x, event.mouse_region_y))
        if hit is None:
            return {"PASS_THROUGH"}
        settings = context.scene.wgame_rigging_assistant
        source_id = hit[:-2] + ".l" if hit.endswith(".r") else hit
        target_id = source_id if settings.unrigged_joint_mirror else hit
        target = _joint_guide_object(target_id)
        if target is None or target.hide_select or target.hide_get():
            return {"PASS_THROUGH"}
        _select_only(context, target)
        settings.unrigged_joint_guide_index = next(i for i, entry in enumerate(JOINT_GUIDE_DEFINITIONS) if entry[0] == source_id)
        _tag_view3d_redraw()
        return {"FINISHED"}


class WGAME_RIGGING_OT_focus_joint_guide(Operator):
    bl_idname = "wgame_rigging.focus_joint_guide"
    bl_label = "定位当前关节标记"
    bl_description = "选中当前关节标记并在 3D 视图中聚焦"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        index = min(settings.unrigged_joint_guide_index, len(JOINT_GUIDE_DEFINITIONS) - 1)
        guide_id = JOINT_GUIDE_DEFINITIONS[index][0]
        obj = _joint_guide_object(guide_id)
        if not obj:
            return {"CANCELLED"}
        _select_only(context, obj)
        _sync_joint_guide_view_centers(context, guide_id)
        return {"FINISHED"}


class WGAME_RIGGING_OT_joint_guide_from_selection(Operator):
    bl_idname = "wgame_rigging.joint_guide_from_selection"
    bl_label = "从当前选择记录位置"
    bl_description = "使用当前选中 Mesh 顶点的世界坐标中心更新关节标记"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        points = []
        for obj in context.scene.objects:
            if obj.type != "MESH" or obj.name.startswith("cs_"):
                continue
            if obj.mode == "EDIT":
                obj.update_from_editmode()
            points.extend(obj.matrix_world @ vertex.co for vertex in obj.data.vertices if vertex.select)
        if not points:
            self.report({"ERROR"}, "请先在 Edit Mode 中选择关节周围的顶点")
            return {"CANCELLED"}
        position = sum(points, Vector((0.0, 0.0, 0.0))) / len(points)
        index = min(settings.unrigged_joint_guide_index, len(JOINT_GUIDE_DEFINITIONS) - 1)
        guide_id = JOINT_GUIDE_DEFINITIONS[index][0]
        _set_joint_guide_position(settings, guide_id, position)
        self.report({"INFO"}, f"已从 {len(points)} 个顶点更新 {JOINT_GUIDE_DEFINITIONS[index][1]}")
        return {"FINISHED"}


class WGAME_RIGGING_OT_joint_guide_view_mode(Operator):
    bl_idname = "wgame_rigging.joint_guide_view_mode"
    bl_label = "关节定位视图模式"
    bl_options = {"REGISTER"}

    mode: EnumProperty(
        items=(
            ("FRONT", "正面 X/Z", "切到正视图并锁定前后 Y"),
            ("SIDE", "侧面 Y/Z", "切到侧视图并锁定左右 X"),
            ("FREE", "自由 XYZ", "解除定位点轴锁定"),
        ),
        default="FRONT",
    )

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        index = min(settings.unrigged_joint_guide_index, len(JOINT_GUIDE_DEFINITIONS) - 1)
        guide_id = JOINT_GUIDE_DEFINITIONS[index][0]
        obj = _joint_guide_object(guide_id)
        if not obj:
            return {"CANCELLED"}
        _select_only(context, obj)
        obj.lock_location = (False, True, False) if self.mode == "FRONT" else (True, False, False) if self.mode == "SIDE" else (False, False, False)
        if self.mode in {"FRONT", "SIDE"} and not settings.unrigged_joint_dual_view:
            _call_arp_in_view3d(
                context,
                bpy.ops.view3d.view_axis,
                type="FRONT" if self.mode == "FRONT" else "LEFT",
                align_active=False,
            )
        self.report({"INFO"}, "正面只调整 X/Z" if self.mode == "FRONT" else "侧面只调整 Y/Z" if self.mode == "SIDE" else "已解除轴锁定")
        return {"FINISHED"}


class WGAME_RIGGING_OT_enable_joint_dual_view(Operator):
    bl_idname = "wgame_rigging.enable_joint_dual_view"
    bl_label = "开启正侧双视图"
    bl_description = "将主 3D View 左右分屏：左侧正面、右侧侧面，并同步关节中心和缩放"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        window, screen = _joint_guide_window_screen(context)
        if not window or not screen:
            return {"CANCELLED"}
        areas = [area for area in screen.areas if area.type == "VIEW_3D"]
        if len(areas) == 1:
            area = areas[0]
            with context.temp_override(window=window, screen=screen, area=area):
                bpy.ops.screen.area_split(direction="VERTICAL", factor=0.5)
            areas = [item for item in screen.areas if item.type == "VIEW_3D"]
        if len(areas) < 2:
            self.report({"ERROR"}, "无法创建第二个 3D View")
            return {"CANCELLED"}
        areas = sorted(areas, key=lambda area: area.x)[:2]
        for index, area in enumerate(areas):
            region = next((item for item in area.regions if item.type == "WINDOW"), None)
            if not region:
                continue
            area.spaces.active.show_region_ui = index == 1
            with context.temp_override(window=window, screen=screen, area=area, region=region, space_data=area.spaces.active):
                bpy.ops.view3d.view_axis(type="FRONT" if index == 0 else "LEFT", align_active=False)
        settings.unrigged_joint_dual_view = True
        guide_id = JOINT_GUIDE_DEFINITIONS[min(settings.unrigged_joint_guide_index, len(JOINT_GUIDE_DEFINITIONS) - 1)][0]
        _sync_joint_guide_view_centers(context, guide_id)
        self.report({"INFO"}, "双视图已开启：左侧正面 X/Z，右侧侧面 Y/Z")
        return {"FINISHED"}


class WGAME_RIGGING_OT_disable_joint_dual_view(Operator):
    bl_idname = "wgame_rigging.disable_joint_dual_view"
    bl_label = "恢复单视图"
    bl_description = "合并由关节定位创建的正侧双 3D View"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        window, screen = _joint_guide_window_screen(context)
        if not window or not screen:
            return {"CANCELLED"}
        areas = sorted((area for area in screen.areas if area.type == "VIEW_3D"), key=lambda area: area.x)
        if len(areas) == 2:
            left, right = areas
            source_xy = (right.x + right.width // 2, right.y + right.height // 2)
            target_xy = (left.x + left.width // 2, left.y + left.height // 2)
            try:
                with context.temp_override(window=window, screen=screen, area=left):
                    bpy.ops.screen.area_join(source_xy=source_xy, target_xy=target_xy)
            except RuntimeError:
                self.report({"ERROR"}, "自动合并失败；可在两视图边界右键选择 Join Areas")
                return {"CANCELLED"}
        settings.unrigged_joint_dual_view = False
        remaining = next((area for area in screen.areas if area.type == "VIEW_3D"), None)
        if remaining:
            remaining.spaces.active.show_region_ui = True
        self.report({"INFO"}, "已恢复单 3D View")
        return {"FINISHED"}


class WGAME_RIGGING_OT_joint_guide_from_cursor(Operator):
    bl_idname = "wgame_rigging.joint_guide_from_cursor"
    bl_label = "使用 3D Cursor"
    bl_description = "将当前关节标记移动到 3D Cursor"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        index = min(settings.unrigged_joint_guide_index, len(JOINT_GUIDE_DEFINITIONS) - 1)
        guide_id = JOINT_GUIDE_DEFINITIONS[index][0]
        _set_joint_guide_position(settings, guide_id, context.scene.cursor.location.copy())
        return {"FINISHED"}


class WGAME_RIGGING_OT_accept_joint_guide(Operator):
    bl_idname = "wgame_rigging.accept_joint_guide"
    bl_label = "确认当前关节并继续"
    bl_description = "记录当前标记位置，应用左右镜像，并进入下一个未确认关节"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        index = min(settings.unrigged_joint_guide_index, len(JOINT_GUIDE_DEFINITIONS) - 1)
        guide_id = JOINT_GUIDE_DEFINITIONS[index][0]
        obj = _joint_guide_object(guide_id)
        if not obj:
            return {"CANCELLED"}
        _set_joint_guide_position(settings, guide_id, obj.location.copy())
        state = _joint_guide_state(settings)
        state.setdefault(guide_id, {})["accepted"] = True
        _save_joint_guide_state(settings, state)
        next_index = next(
            (i for i, (item_id, _label, _description) in enumerate(JOINT_GUIDE_DEFINITIONS) if not state.get(item_id, {}).get("accepted")),
            None,
        )
        if next_index is not None:
            settings.unrigged_joint_guide_index = next_index
            bpy.ops.wgame_rigging.focus_joint_guide()
        self.report({"INFO"}, f"已确认 {JOINT_GUIDE_DEFINITIONS[index][1]}")
        return {"FINISHED"}


class WGAME_RIGGING_OT_accept_all_joint_guides(Operator):
    bl_idname = "wgame_rigging.accept_all_joint_guides"
    bl_label = "一键确认全部关节"
    bl_description = "以当前标记位置确认全部主要关节；只解锁骨架生成，不会立即创建 Armature"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        missing = [guide_id for guide_id, _label, _description in JOINT_GUIDE_DEFINITIONS if not _joint_guide_object(guide_id)]
        if missing:
            self.report({"ERROR"}, "缺少关节标记：" + ", ".join(missing))
            return {"CANCELLED"}
        _sync_all_joint_guide_mirrors(settings)
        state = _joint_guide_state(settings)
        for guide_id, _label, _description in JOINT_GUIDE_DEFINITIONS:
            state.setdefault(guide_id, {})["accepted"] = True
        _save_joint_guide_state(settings, state)
        _tag_view3d_redraw()
        self.report({"INFO"}, f"已确认全部 {len(JOINT_GUIDE_DEFINITIONS)} 个主要关节定位项")
        return {"FINISHED"}


class WGAME_RIGGING_OT_navigate_joint_guide(Operator):
    bl_idname = "wgame_rigging.navigate_joint_guide"
    bl_label = "切换关节定位"
    bl_options = {"REGISTER"}

    step: bpy.props.IntProperty(default=1, min=-1, max=1, options={"HIDDEN"})

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        settings.unrigged_joint_guide_index = max(0, min(len(JOINT_GUIDE_DEFINITIONS) - 1, settings.unrigged_joint_guide_index + self.step))
        return bpy.ops.wgame_rigging.focus_joint_guide()


class WGAME_RIGGING_OT_generate_wgame_skeleton(Operator):
    bl_idname = "wgame_rigging.generate_wgame_skeleton"
    bl_label = "生成 WGame 基础骨架"
    bl_description = "根据已确认关节定位直接创建 WGame Deform Skeleton，不依赖 ARP"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        if not _current_model_preflight(context, settings) or not settings.unrigged_pose_locked:
            self.report({"ERROR"}, "请先完成当前正式模型预检与姿势/区域确认")
            return {"CANCELLED"}
        if any(obj.type == "ARMATURE" for obj in context.scene.objects):
            self.report({"ERROR"}, "场景中已经存在 Armature")
            return {"CANCELLED"}
        if not _joint_guides_complete(settings):
            self.report({"ERROR"}, "请先完成全部主要关节定位")
            return {"CANCELLED"}
        meshes = [obj for obj in context.scene.objects if _is_formal_character_mesh(obj)]
        mesh_obj = max(meshes, key=lambda item: len(item.data.vertices), default=None)
        if not mesh_obj:
            return {"CANCELLED"}
        backup = _save_backup_copy()
        if backup:
            settings.backup_filepath = backup

        armature = bpy.data.armatures.new("rig")
        rig_obj = bpy.data.objects.new("rig", armature)
        context.scene.collection.objects.link(rig_obj)
        rig_obj.show_in_front = True
        rig_obj.display_type = "WIRE"
        rig_obj["wgame_rig_kind"] = "deform_skeleton"
        rig_obj["wgame_schema_version"] = "2.2"
        _select_only(context, rig_obj)
        _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="EDIT")

        inverse_rig = rig_obj.matrix_world.inverted()

        def guide(guide_id):
            return inverse_rig @ _joint_guide_object(guide_id).matrix_world.translation

        model_points = [mesh_obj.matrix_world @ vertex.co for vertex in mesh_obj.data.vertices]
        ground = min(point.z for point in model_points)
        height = max(point.z for point in model_points) - ground
        pelvis, chest, neck, head_top = (guide(item) for item in ("pelvis.x", "chest.x", "neck.x", "head_top.x"))
        shoulder_guides = {side: guide(f"shoulder.{side}") for side in ("l", "r")}
        shoulder_center = (shoulder_guides["l"] + shoulder_guides["r"]) * 0.5
        spine_a = pelvis.lerp(chest, 0.34)
        spine_b = pelvis.lerp(chest, 0.67)
        head_center = neck.lerp(head_top, 0.55)
        head_base = neck.lerp(head_center, 0.32)
        definitions = [
            ("root.x", Vector((0.0, 0.0, ground)), Vector((0.0, 0.0, ground + height * 0.08)), None, False, "CENTER"),
            ("pelvis.x", pelvis, spine_a, "root.x", True, "CENTER"),
            ("spine_01.x", spine_a, spine_b, "pelvis.x", True, "CENTER"),
            ("spine_02.x", spine_b, chest, "spine_01.x", True, "CENTER"),
            ("upper_chest.x", chest, neck, "spine_02.x", True, "CENTER"),
            ("neck.x", neck, head_base, "upper_chest.x", True, "CENTER"),
            ("head.x", head_base, head_center, "neck.x", True, "CENTER"),
        ]
        for side in ("l", "r"):
            shoulder = shoulder_guides[side]
            shoulder_root = shoulder_center.lerp(shoulder, 0.35)
            elbow, wrist, hand_end = (guide(f"{item}.{side}") for item in ("elbow", "wrist", "hand_end"))
            hip, knee, ankle, ball, toe = (guide(f"{item}.{side}") for item in ("hip", "knee", "ankle", "ball", "toe"))
            definitions.extend(
                [
                    (f"shoulder.{side}", shoulder_root, shoulder, "upper_chest.x", True, "ARM"),
                    (f"upper_arm.{side}", shoulder, elbow, f"shoulder.{side}", True, "ARM"),
                    (f"forearm.{side}", elbow, wrist, f"upper_arm.{side}", True, "ARM"),
                    (f"hand.{side}", wrist, hand_end, f"forearm.{side}", True, "ARM"),
                    (f"thigh.{side}", hip, knee, "pelvis.x", True, "LEG"),
                    (f"lower_leg.{side}", knee, ankle, f"thigh.{side}", True, "LEG"),
                    (f"foot.{side}", ankle, ball, f"lower_leg.{side}", True, "FOOT"),
                    (f"toes.{side}", ball, toe, f"foot.{side}", True, "FOOT"),
                ]
            )

        edit_bones = armature.edit_bones
        bone_specs = {}
        for bone_name, head, tail, parent_name, deform, roll_kind in definitions:
            if (tail - head).length < 0.0001:
                tail = head + Vector((0.0, 0.0, max(height * 0.02, 0.01)))
            bone = edit_bones.new(bone_name)
            bone.head, bone.tail = head, tail
            bone.use_deform = deform
            bone_specs[bone_name] = (bone, parent_name, roll_kind)
        for bone_name, (bone, parent_name, roll_kind) in bone_specs.items():
            if parent_name and edit_bones.get(parent_name):
                bone.parent = edit_bones[parent_name]
                bone.use_connect = False
            try:
                bone.align_roll(Vector((0.0, 0.0, 1.0)) if roll_kind in {"ARM", "FOOT"} else Vector((0.0, 1.0, 0.0)))
            except ValueError:
                pass

        component_by_id = {item.get("id"): item for item in _unrigged_components(settings)}
        parent_aliases = {
            "pelvis": "pelvis.x",
            "chest": "upper_chest.x",
            "head": "head.x",
            "hand.l": "hand.l",
            "hand.r": "hand.r",
            "thigh.l": "thigh.l",
            "thigh.r": "thigh.r",
        }
        accessory_names = []
        for group in _unrigged_binding_groups(settings):
            if group.get("status") != "COMPLETE" or not group.get("component_ids"):
                continue
            points = []
            for component_id in group.get("component_ids", []):
                component = component_by_id.get(component_id)
                obj = context.scene.objects.get(component.get("object", "")) if component else None
                if obj:
                    transform = inverse_rig @ obj.matrix_world
                    points.extend(transform @ obj.data.vertices[index].co for index in component.get("vertex_indices", []))
            if not points:
                continue
            minimum = Vector(tuple(min(point[axis] for point in points) for axis in range(3)))
            maximum = Vector(tuple(max(point[axis] for point in points) for axis in range(3)))
            center = (minimum + maximum) * 0.5
            bone_name = group.get("target_bone", "")
            if not bone_name or edit_bones.get(bone_name):
                continue
            bone = edit_bones.new(bone_name)
            bone.head = center
            bone.tail = center + Vector((0.0, 0.0, max(0.02, min(0.12, (maximum - minimum).length * 0.3))))
            bone.use_deform = True
            parent_name = parent_aliases.get(group.get("parent_bone", ""), group.get("parent_bone", ""))
            if edit_bones.get(parent_name):
                bone.parent = edit_bones[parent_name]
            accessory_names.append(bone_name)

        _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="OBJECT")
        deform_collection = armature.collections.new("WGame Deform")
        root_collection = armature.collections.new("WGame Root")
        for bone in armature.bones:
            (root_collection if bone.name == "root.x" else deform_collection).assign(bone)
        for group in _unrigged_binding_groups(settings):
            pose_bone = rig_obj.pose.bones.get(group.get("target_bone", ""))
            if pose_bone:
                pose_bone["wgame_binding_group"] = group.get("id", "")

        mapping = {
            "Hips": "pelvis.x",
            "Spine": "spine_01.x",
            "Chest": "spine_02.x",
            "UpperChest": "upper_chest.x",
            "Neck": "neck.x",
            "Head": "head.x",
            "LeftShoulder": "shoulder.l",
            "LeftUpperArm": "upper_arm.l",
            "LeftLowerArm": "forearm.l",
            "LeftHand": "hand.l",
            "RightShoulder": "shoulder.r",
            "RightUpperArm": "upper_arm.r",
            "RightLowerArm": "forearm.r",
            "RightHand": "hand.r",
            "LeftUpperLeg": "thigh.l",
            "LeftLowerLeg": "lower_leg.l",
            "LeftFoot": "foot.l",
            "LeftToes": "toes.l",
            "RightUpperLeg": "thigh.r",
            "RightLowerLeg": "lower_leg.r",
            "RightFoot": "foot.r",
            "RightToes": "toes.r",
        }
        settings.wgame_humanoid_mapping_json = json.dumps(mapping, ensure_ascii=False, separators=(",", ":"))
        settings.wgame_skeleton_accepted = False
        settings.wgame_finger_rig_complete = False
        settings.wgame_head_detail_complete = False
        _invalidate_binding_results(settings)
        settings.rig_name = rig_obj.name
        guide_collection = bpy.data.collections.get("WGame_RigGuides")
        if guide_collection:
            guide_collection.hide_viewport = True
        _select_only(context, rig_obj)
        _set_report(
            context,
            "WGame 基础骨架已生成",
            [
                f"基础骨骼：{len(definitions)}",
                f"附件骨骼：{len(accessory_names)}",
                f"Unity Humanoid 映射：{len(mapping)}",
                *( ["生成前备份：", backup] if backup else [] ),
            ],
        )
        self.report({"INFO"}, f"已生成 WGame 基础骨架：{len(armature.bones)} 根骨")
        return {"FINISHED"}


class WGAME_RIGGING_OT_edit_wgame_skeleton(Operator):
    bl_idname = "wgame_rigging.edit_wgame_skeleton"
    bl_label = "进入 WGame 骨架编辑"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        rig_obj = next((obj for obj in context.scene.objects if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"), None)
        if not rig_obj:
            return {"CANCELLED"}
        _select_only(context, rig_obj)
        _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="EDIT")
        return {"FINISHED"}


def _finger_authoring_mesh(context, rig_obj=None):
    """Resolve the authored body mesh without silently selecting a topology backup."""
    settings = context.scene.wgame_rigging_assistant
    configured = bpy.data.objects.get(settings.mesh_name) if settings.mesh_name else None
    if _is_formal_character_mesh(configured):
        return configured

    candidates = [obj for obj in context.scene.objects if _is_formal_character_mesh(obj)]
    if rig_obj:
        bound = [
            obj
            for obj in candidates
            if (modifier := _armature_modifier(obj)) is not None and modifier.object == rig_obj
        ]
        if bound:
            candidates = bound
    mesh_obj = max(candidates, key=lambda obj: (len(obj.data.vertices), len(obj.data.polygons)), default=None)
    if mesh_obj:
        settings.mesh_name = mesh_obj.name
    return mesh_obj


def _hand_local_frame(rig_obj, mesh_obj, side):
    bone = rig_obj.data.bones.get(f"hand.{side}")
    if not bone:
        raise ValueError(f"缺少 hand.{side}")
    forward = (bone.tail_local - bone.head_local).normalized()
    world_up = Vector((0.0, 0.0, 1.0))
    up = world_up - forward * world_up.dot(forward)
    if up.length < 0.0001:
        up = Vector((0.0, 1.0, 0.0))
        up -= forward * up.dot(forward)
    up.normalize()
    normal = forward.cross(up).normalized()
    transform = rig_obj.matrix_world.inverted() @ mesh_obj.matrix_world
    return bone, forward, up, normal, transform


class _HandBranchError(ValueError):
    def __init__(self, message, candidates):
        super().__init__(message)
        self.candidates = list(candidates)


def _hand_hint_fingerprint(mesh_obj):
    digest = hashlib.sha256()
    mesh = mesh_obj.data
    for collection, attribute, width, kind in ((mesh.vertices, "co", 3, "f"), (mesh.edges, "vertices", 2, "i"), (mesh.loops, "vertex_index", 1, "i")):
        values = array(kind, [0]) * (len(collection) * width)
        collection.foreach_get(attribute, values)
        digest.update(values.tobytes())
    return digest.hexdigest()


def _hand_thumb_hint(mesh_obj, side):
    raw = mesh_obj.get("wgame_thumb_hint_" + side)
    if not raw:
        return None
    try:
        data = json.loads(raw)
        if data["fingerprint"] != _hand_hint_fingerprint(mesh_obj):
            raise ValueError(f"{side.upper()} 手动拇指尖记录已失效；网格发生变化，请重新指定或清除")
        index = int(data["vertex"])
        if not 0 <= index < len(mesh_obj.data.vertices):
            raise ValueError("手动拇指尖顶点索引无效")
        return index
    except (KeyError, TypeError, json.JSONDecodeError) as error:
        raise ValueError("手动拇指尖记录无效，请清除并重新指定") from error


def _separate_hand_tip_candidates(points, adjacency, first, second, minimum):
    """Deduplicate a tip cap without merging close fingers across their gap."""
    if (points[first] - points[second]).length >= minimum:
        return True
    # Adjacent digits can be close in space but connect only through the palm.
    # Require a finite surface path; disconnected candidates are not evidence.
    distances = {first: 0.0}
    queue = [(0.0, first)]
    while queue:
        distance, index = heapq.heappop(queue)
        if distance != distances[index]:
            continue
        if index == second:
            return distance >= minimum * 2.0
        for neighbor, length in adjacency.get(index, ()):
            candidate = distance + length
            if candidate < distances.get(neighbor, math.inf):
                distances[neighbor] = candidate
                heapq.heappush(queue, (candidate, neighbor))
    return False


def _hand_geodesic_analysis(mesh_obj, rig_obj, side):
    """Find five fingertip branches by surface distance, independent of finger curl."""
    bone, forward, up, normal, transform = _hand_local_frame(rig_obj, mesh_obj, side)
    height = max(float(mesh_obj.dimensions.z), 0.0001)
    palm_length = max((bone.tail_local - bone.head_local).length, 1e-6)
    points = [transform @ vertex.co for vertex in mesh_obj.data.vertices]
    along = [(point - bone.tail_local).dot(forward) for point in points]
    radial = [
        (point - (bone.tail_local + forward * along[index])).length
        for index, point in enumerate(points)
    ]
    max_radial = max(palm_length * 3.5, height * 0.16)
    along_min = -palm_length * 1.5
    along_max = palm_length * 4.5
    roi = {
        index
        for index in range(len(points))
        if along_min <= along[index] <= along_max and radial[index] <= max_radial
    }
    hint = _hand_thumb_hint(mesh_obj, side)
    if hint is not None:
        roi.add(hint)
    if len(roi) < 80:
        raise ValueError(f"{side.upper()} 手部区域顶点不足：{len(roi)}/80")

    def _dijkstra(current_roi):
        adj = {index: [] for index in current_roi}
        for edge in mesh_obj.data.edges:
            first, second = edge.vertices
            if first not in current_roi or second not in current_roi:
                continue
            length = (points[first] - points[second]).length
            adj[first].append((second, length))
            adj[second].append((first, length))

        min_roi_along = min(along[index] for index in current_roi)
        wrist_cutoff = min(min_roi_along + palm_length * 0.35, -palm_length * 0.4)
        seeds = [index for index in current_roi if along[index] <= wrist_cutoff]
        if not seeds:
            seeds = sorted(current_roi, key=lambda index: along[index])[: max(4, len(current_roi) // 20)]
        dists = {index: math.inf for index in current_roi}
        prev = {}
        q = []
        for index in seeds:
            dists[index] = 0.0
            heapq.heappush(q, (0.0, index))
        while q:
            distance, index = heapq.heappop(q)
            if distance != dists[index]:
                continue
            for neighbor, edge_length in adj[index]:
                candidate = distance + edge_length
                if candidate >= dists[neighbor]:
                    continue
                dists[neighbor] = candidate
                prev[neighbor] = index
                heapq.heappush(q, (candidate, neighbor))

        reach = [i for i in current_roi if math.isfinite(dists[i])]
        return adj, seeds, dists, prev, reach

    adjacency, wrist_seeds, distances, previous, reachable = _dijkstra(roi)
    if not reachable:
        raise ValueError(f"{side.upper()} 手部候选无法连接到掌根，请检查网格连通性")

    if hint is not None and (hint not in reachable or not math.isfinite(distances.get(hint, math.inf))):
        full_adj = {}
        for edge in mesh_obj.data.edges:
            u, v = edge.vertices
            full_adj.setdefault(u, []).append(v)
            full_adj.setdefault(v, []).append(u)
        bfs_queue = collections.deque([hint])
        visited = {hint: None}
        found_target = None
        reachable_set = set(reachable)
        while bfs_queue:
            curr = bfs_queue.popleft()
            if curr in reachable_set:
                found_target = curr
                break
            if (points[curr] - points[hint]).length > palm_length * 4.0:
                continue
            for nbr in full_adj.get(curr, ()):
                if nbr not in visited:
                    visited[nbr] = curr
                    bfs_queue.append(nbr)
        if found_target is not None:
            curr = found_target
            while curr is not None:
                roi.add(curr)
                for nbr in full_adj.get(curr, ()):
                    roi.add(nbr)
                curr = visited[curr]
            adjacency, wrist_seeds, distances, previous, reachable = _dijkstra(roi)

    reach = max(along[i] for i in reachable)
    surface_length = max(distances[i] for i in reachable)
    minimum_separation = max(reach * .18, palm_length * .25)
    local_maxima = sorted(
        (i for i in reachable if distances[i] > surface_length * .30
         and all(distances[i] >= distances[j] - 1e-8 for j, _ in adjacency[i])),
        key=lambda i: (-distances[i], i),
    )
    main_tips = []
    for i in local_maxima:
        if along[i] < reach * .48 or distances[i] < surface_length * .65:
            continue
        if all(_separate_hand_tip_candidates(points, adjacency, i, j, minimum_separation) for j in main_tips):
            main_tips.append(i)
    extra_thumb = None
    if len(main_tips) == 5:
        if hint is not None and hint in main_tips:
            extra_thumb = hint
            main_tips = [t for t in main_tips if t != hint]
        else:
            sorted_by_along = sorted(main_tips, key=lambda t: along[t])
            extra_thumb = sorted_by_along[0]
            main_tips = sorted_by_along[1:]
    if len(main_tips) != 4:
        raise _HandBranchError(f"{side.upper()} 已识别主指 {len(main_tips)}/4；点 {side.upper()} 显示候选核对食指、中指、无名指、小指；若仍缺失，检查指缝连接与手掌定位后重新分析；指定拇指尖不能补齐主指", local_maxima)
    lateral = [(points[i] - bone.tail_local).dot(normal) for i in main_tips]
    lateral_center = (min(lateral) + max(lateral)) * .5
    lateral_margin = max((max(lateral) - min(lateral)) * .65, minimum_separation)
    thumb_candidates = []
    if extra_thumb is not None and all((points[extra_thumb] - points[j]).length >= minimum_separation for j in main_tips):
        thumb_candidates.append(extra_thumb)
    for i in local_maxima:
        if i in main_tips or i == extra_thumb or any((points[i] - points[j]).length < minimum_separation for j in main_tips):
            continue
        side_offset = abs((points[i] - bone.tail_local).dot(normal) - lateral_center)
        if side_offset < lateral_margin:
            continue
        if all((points[i] - points[j]).length >= minimum_separation for j in thumb_candidates):
            thumb_candidates.append(i)
    if hint is not None:
        if hint not in reachable or distances[hint] < surface_length * .05:
            raise _HandBranchError(f"{side.upper()} 指定的拇指尖不在可达手部末端，请重新选择", local_maxima)
        if any((points[hint] - points[j]).length < minimum_separation for j in main_tips):
            raise _HandBranchError(f"{side.upper()} 指定的拇指尖与主指候选重合，请重新选择", local_maxima)
        thumb_tip = hint
    elif len(thumb_candidates) >= 1:
        thumb_tip = max(thumb_candidates, key=lambda i: abs((points[i] - bone.tail_local).dot(normal) - lateral_center))
    else:
        raise _HandBranchError(f"{side.upper()} 已识别主指 4/4，拇指候选 0；点 {side.upper()} 显示候选，在顶点模式只选拇指尖一个顶点，再点 {side.upper()} 指定拇指尖，然后重新生成", local_maxima)
    tips = main_tips + [thumb_tip]

    def path_to_wrist(tip):
        path = [tip]
        seen = {tip}
        while path[-1] not in wrist_seeds and path[-1] in previous:
            next_index = previous[path[-1]]
            if next_index in seen:
                break
            path.append(next_index)
            seen.add(next_index)
        path.reverse()
        return path

    paths = {tip: path_to_wrist(tip) for tip in tips}
    if any(len(path) < 4 for path in paths.values()):
        raise ValueError(f"{side.upper()} 手指中心路径过短")

    return {
        "side": side,
        "height": height,
        "bone": bone,
        "forward": forward,
        "up": up,
        "normal": normal,
        "transform": transform,
        "points": points,
        "along": along,
        "roi": roi,
        "adjacency": adjacency,
        "distances": distances,
        "tips": tips,
        "main_tips": main_tips,
        "thumb_tip": thumb_tip,
        "paths": paths,
    }


def _resample_hand_path(path_points, sample_count=17):
    if len(path_points) < 2:
        return list(path_points), [0.0] * len(path_points)
    lengths = [0.0]
    for first, second in zip(path_points, path_points[1:]):
        lengths.append(lengths[-1] + (second - first).length)
    total = lengths[-1]
    if total <= 1e-8:
        return [path_points[0].copy() for _index in range(sample_count)], [0.0] * sample_count
    samples = []
    sample_lengths = []
    segment = 0
    for sample_index in range(sample_count):
        target = total * sample_index / (sample_count - 1)
        while segment + 1 < len(lengths) - 1 and lengths[segment + 1] < target:
            segment += 1
        segment_length = max(lengths[segment + 1] - lengths[segment], 1e-8)
        factor = (target - lengths[segment]) / segment_length
        samples.append(path_points[segment].lerp(path_points[segment + 1], factor))
        sample_lengths.append(target)
    for _pass in range(2):
        samples = [
            samples[0],
            *[
                (samples[index - 1] + samples[index] * 2.0 + samples[index + 1]) * 0.25
                for index in range(1, len(samples) - 1)
            ],
            samples[-1],
        ]
    return samples, sample_lengths


def _prepare_hand_neutralization(analysis):
    height = analysis["height"]
    points = analysis["points"]
    distances = analysis["distances"]
    forward = analysis["forward"]
    chains = []
    for tip in analysis["main_tips"]:
        source_indices = analysis["paths"][tip]
        root_distance = min(height * 0.027, distances[tip] * 0.48)
        root_position = next(
            (index for index, vertex_index in enumerate(source_indices) if distances[vertex_index] >= root_distance),
            max(0, len(source_indices) - 2),
        )
        source_indices = source_indices[root_position:]
        source_points = [points[index] for index in source_indices]
        samples, sample_lengths = _resample_hand_path(source_points)
        total_length = max(sample_lengths[-1], 1e-8)
        current_delta = samples[-1] - samples[0]
        lateral = current_delta - forward * current_delta.dot(forward)
        # Preserve the authored finger fan. Neutralization removes curvature
        # along each branch; it must not collapse the four tips onto the hand
        # axis, especially for broad stylized claws.
        lateral_ratio = min(lateral.length / total_length, 0.80)
        target_direction = forward.copy()
        if lateral.length > 1e-8:
            target_direction += lateral.normalized() * lateral_ratio
        target_direction.normalize()
        target_samples = [samples[0] + target_direction * length for length in sample_lengths]
        chains.append(
            {
                "tip": tip,
                "root_distance": distances[source_indices[0]],
                "samples": samples,
                "target_samples": target_samples,
                "target_direction": target_direction,
                "length": total_length,
            }
        )
    return chains


def _nearest_tip_labels(analysis):
    distances = {index: math.inf for index in analysis["roi"]}
    labels = {}
    queue = []
    for label, tip in enumerate(analysis["tips"]):
        distances[tip] = 0.0
        labels[tip] = label
        heapq.heappush(queue, (0.0, label, tip))
    while queue:
        distance, label, index = heapq.heappop(queue)
        if distance != distances[index] or labels.get(index) != label:
            continue
        for neighbor, edge_length in analysis["adjacency"][index]:
            candidate = distance + edge_length
            if candidate >= distances[neighbor]:
                continue
            distances[neighbor] = candidate
            labels[neighbor] = label
            heapq.heappush(queue, (candidate, label, neighbor))
    return labels


def _apply_hand_neutralization(mesh_obj, analysis):
    chains = _prepare_hand_neutralization(analysis)
    labels = _nearest_tip_labels(analysis)
    points = analysis["points"]
    height = analysis["height"]
    inverse_transform = analysis["transform"].inverted()
    displacements = {}
    blend_factors = {}
    for vertex_index in analysis["roi"]:
        label = labels.get(vertex_index)
        if label is None or label >= 4:
            continue
        chain = chains[label]
        wrist_distance = analysis["distances"][vertex_index]
        blend_width = height * 0.014
        factor = (wrist_distance - chain["root_distance"]) / max(blend_width, 1e-8)
        factor = max(0.0, min(1.0, factor))
        factor = factor * factor * (3.0 - 2.0 * factor)
        if factor <= 0.0:
            continue
        source_samples = chain["samples"]
        target_samples = chain["target_samples"]
        best = None
        for segment_index in range(len(source_samples) - 1):
            start = source_samples[segment_index]
            segment = source_samples[segment_index + 1] - start
            segment_factor = max(
                0.0,
                min(
                    1.0,
                    (points[vertex_index] - start).dot(segment) / max(segment.length_squared, 1e-12),
                ),
            )
            closest = start + segment * segment_factor
            squared_distance = (points[vertex_index] - closest).length_squared
            if best is None or squared_distance < best[0]:
                best = (squared_distance, segment_index, segment_factor, closest)
        _distance, sample_index, sample_factor, source_center = best
        target_center = target_samples[sample_index].lerp(target_samples[sample_index + 1], sample_factor)
        source_tangent = source_samples[sample_index + 1] - source_samples[sample_index]
        if source_tangent.length < 1e-8:
            source_tangent = analysis["forward"]
        else:
            source_tangent.normalize()
        rotation = source_tangent.rotation_difference(chain["target_direction"])
        offset = points[vertex_index] - source_center
        target = target_center + rotation @ offset
        corrected = points[vertex_index].lerp(target, factor)
        displacements[vertex_index] = corrected - points[vertex_index]
        blend_factors[vertex_index] = factor

    # Smooth the deformation field inside each topological finger partition.
    # This keeps low-poly cross sections coherent and avoids a path sample or
    # a single surface edge becoming a visible crease after straightening.
    for _pass in range(4):
        smoothed = {}
        for vertex_index, displacement in displacements.items():
            neighbors = [
                neighbor
                for neighbor, _length in analysis["adjacency"][vertex_index]
                if labels.get(neighbor) == labels.get(vertex_index)
            ]
            neighbor_displacements = [displacements.get(neighbor, Vector((0.0, 0.0, 0.0))) for neighbor in neighbors]
            if not neighbor_displacements:
                smoothed[vertex_index] = displacement
                continue
            average = sum(neighbor_displacements, Vector((0.0, 0.0, 0.0))) / len(neighbor_displacements)
            smoothing = 0.28 * (1.0 - 0.35 * blend_factors[vertex_index])
            smoothed[vertex_index] = displacement.lerp(average, smoothing)
        displacements = smoothed

    moved = 0
    maximum_displacement = 0.0
    for vertex_index, displacement in displacements.items():
        if displacement.length <= 1e-8:
            continue
        corrected = points[vertex_index] + displacement
        mesh_obj.data.vertices[vertex_index].co = inverse_transform @ corrected
        moved += 1
        maximum_displacement = max(maximum_displacement, displacement.length)
    mesh_obj.data.update()
    return moved, maximum_displacement, chains


def _hand_neutralization_summary(analysis):
    distances = analysis["distances"]
    return (
        f"{analysis['side'].upper()}：5/5 分支，"
        f"主指测地长度 "
        + ", ".join(f"{distances[tip]:.4f}" for tip in analysis["main_tips"])
        + f"，拇指 {distances[analysis['thumb_tip']]:.4f}"
    )


class WGAME_RIGGING_OT_hand_tip_assist(Operator):
    bl_idname = "wgame_rigging.hand_tip_assist"
    bl_label = "手指识别辅助"
    bl_options = {"REGISTER", "UNDO"}
    side: EnumProperty(items=(("l", "L", "角色左手"), ("r", "R", "角色右手")))
    action: EnumProperty(items=(("SHOW", "显示候选", "进入顶点选择模式并高亮候选"),
                                ("SET", "指定拇指尖", "用当前唯一选中的顶点指定拇指尖"),
                                ("CLEAR", "清除指定", "恢复自动识别拇指")))

    def execute(self, context):
        rig = _wgame_rig_object(context)
        mesh = _finger_authoring_mesh(context, rig)
        if not rig or not mesh:
            self.report({"ERROR"}, "缺少正式角色 Mesh 或 WGame 骨架")
            return {"CANCELLED"}
        key = "wgame_thumb_hint_" + self.side
        if self.action == "CLEAR":
            mesh.pop(key, None)
            self.report({"INFO"}, f"{self.side.upper()} 已恢复自动识别拇指")
            return {"FINISHED"}
        if mesh.mode == "EDIT":
            mesh.update_from_editmode()
        if self.action == "SET":
            if context.object != mesh or mesh.mode != "EDIT":
                self.report({"ERROR"}, "请在正式角色的编辑模式中只选中一个拇指尖顶点")
                return {"CANCELLED"}
            selected = [v.index for v in mesh.data.vertices if v.select and not v.hide]
            if len(selected) != 1:
                self.report({"ERROR"}, "请只选中一个拇指尖顶点")
                return {"CANCELLED"}
            previous = mesh.get(key)
            mesh[key] = json.dumps({"vertex": selected[0], "fingerprint": _hand_hint_fingerprint(mesh)})
            try:
                _hand_geodesic_analysis(mesh, rig, self.side)
            except ValueError as error:
                if previous is None:
                    mesh.pop(key, None)
                else:
                    mesh[key] = previous
                self.report({"ERROR"}, str(error))
                return {"CANCELLED"}
            self.report({"INFO"}, f"{self.side.upper()} 拇指尖已指定，五指路径检查通过")
            return {"FINISHED"}
        guidance = "可只选拇指尖后点指定拇指尖"
        try:
            analysis = _hand_geodesic_analysis(mesh, rig, self.side)
            candidates = analysis["tips"]
        except _HandBranchError as error:
            candidates = error.candidates
            guidance = str(error)
            context.scene.wgame_rigging_assistant.wgame_finger_detection_report = guidance
            self.report({"WARNING"}, guidance)
        except ValueError as error:
            self.report({"ERROR"}, str(error))
            return {"CANCELLED"}
        _select_only(context, mesh)
        bpy.ops.object.mode_set(mode="EDIT")
        context.tool_settings.mesh_select_mode = (True, False, False)
        bpy.ops.mesh.select_all(action="DESELECT")
        bm = bmesh.from_edit_mesh(mesh.data)
        bm.verts.ensure_lookup_table()
        for index in candidates:
            bm.verts[index].hide_set(False)
            bm.verts[index].select_set(True)
        bmesh.update_edit_mesh(mesh.data, loop_triangles=False, destructive=False)
        self.report({"INFO"}, f"{self.side.upper()} 已高亮 {len(candidates)} 个候选；{guidance}")
        return {"FINISHED"}


def _draw_hand_detection_report(layout, report):
    # Account for sidebar width, UI scale, nested boxes and the leading icon.
    region = bpy.context.region
    if not region or region.type != "UI":
        area = bpy.context.area
        region = next((r for r in area.regions if r.type == "UI"), None) if area else None
    scale = max(float(bpy.context.preferences.system.ui_scale), 0.5)
    columns = max(6, min(16, int((region.width / scale - 80) / 14))) if region else 16
    for paragraph in str(report or "").splitlines():
        for sentence in paragraph.split("；"):
            for offset in range(0, len(sentence), columns):
                layout.label(text=sentence[offset:offset + columns], icon="INFO" if offset == 0 else "NONE")


def _draw_hand_tip_assistance(layout):
    for side in ("l", "r"):
        row = layout.row(align=True)
        row.label(text=side.upper())
        for action, label in (("SHOW", "显示候选"), ("SET", "指定拇指尖"), ("CLEAR", "清除指定")):
            button = row.operator("wgame_rigging.hand_tip_assist", text=label)
            button.side, button.action = side, action


class WGAME_RIGGING_OT_analyze_hand_neutralization(Operator):
    bl_idname = "wgame_rigging.analyze_hand_neutralization"
    bl_label = "分析手部中立位"
    bl_description = "按网格表面拓扑识别双手五指，只分析并报告，不修改模型"
    bl_options = {"REGISTER"}

    def execute(self, context):
        rig_obj = next(
            (obj for obj in context.scene.objects if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"),
            None,
        )
        mesh_obj = _finger_authoring_mesh(context, rig_obj)
        if not rig_obj or not mesh_obj:
            self.report({"ERROR"}, "缺少正式角色 Mesh 或 WGame 骨架")
            return {"CANCELLED"}
        if mesh_obj.mode == "EDIT":
            mesh_obj.update_from_editmode()
        lines = [f"正式网格：{mesh_obj.name}"]
        errors = []
        for side in ("l", "r"):
            try:
                lines.append(_hand_neutralization_summary(_hand_geodesic_analysis(mesh_obj, rig_obj, side)))
            except ValueError as error:
                errors.append(str(error))
                lines.append(str(error))
        context.scene.wgame_rigging_assistant.wgame_hand_neutral_report = "；".join(lines)
        if errors:
            _set_report(context, "手指候选识别需要处理", lines)
            self.report({"ERROR"}, "；".join(errors))
            return {"CANCELLED"}
        _set_report(context, "手部中立位分析完成", lines)
        self.report({"INFO"}, "双手五指拓扑分支识别通过，可执行回正")
        return {"FINISHED"}


class WGAME_RIGGING_OT_apply_hand_neutralization(Operator):
    bl_idname = "wgame_rigging.apply_hand_neutralization"
    bl_label = "自动回正双手中立位"
    bl_description = "备份后按五指表面路径回正四根主指；保持手掌和拇指，不生成正式蒙皮权重"
    bl_options = {"REGISTER", "UNDO"}

    skip_backup: BoolProperty(default=False, options={"HIDDEN"})

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        if settings.wgame_finger_bones_generated or settings.wgame_skeleton_accepted:
            self.report({"ERROR"}, "请在生成手指骨和验收基础骨架之前回正手部")
            return {"CANCELLED"}
        rig_obj = next(
            (obj for obj in context.scene.objects if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"),
            None,
        )
        mesh_obj = _finger_authoring_mesh(context, rig_obj)
        if not rig_obj or not mesh_obj:
            self.report({"ERROR"}, "缺少正式角色 Mesh 或 WGame 骨架")
            return {"CANCELLED"}
        if rig_obj.mode != "OBJECT":
            _select_only(context, rig_obj)
            _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="OBJECT")
        try:
            analyses = [_hand_geodesic_analysis(mesh_obj, rig_obj, side) for side in ("l", "r")]
        except ValueError as error:
            self.report({"ERROR"}, str(error))
            return {"CANCELLED"}
        original_coordinates = [vertex.co.copy() for vertex in mesh_obj.data.vertices]
        original_edge_lengths = [
            (original_coordinates[edge.vertices[0]] - original_coordinates[edge.vertices[1]]).length
            for edge in mesh_obj.data.edges
        ]
        backup = None if self.skip_backup else _save_backup_copy()
        if backup:
            settings.backup_filepath = backup
        results = [_apply_hand_neutralization(mesh_obj, analysis) for analysis in analyses]
        changed_vertices = {
            index
            for index, (before, vertex) in enumerate(zip(original_coordinates, mesh_obj.data.vertices))
            if (vertex.co - before).length > 1e-8
        }
        edge_ratios = []
        for edge, original_length in zip(mesh_obj.data.edges, original_edge_lengths):
            if original_length <= 1e-8 or not any(index in changed_vertices for index in edge.vertices):
                continue
            current_length = (mesh_obj.data.vertices[edge.vertices[0]].co - mesh_obj.data.vertices[edge.vertices[1]].co).length
            edge_ratios.append(current_length / original_length)
        coordinates_finite = all(
            math.isfinite(component)
            for vertex in mesh_obj.data.vertices
            for component in vertex.co
        )
        minimum_edge_ratio = min(edge_ratios, default=1.0)
        maximum_edge_ratio = max(edge_ratios, default=1.0)
        if not coordinates_finite or minimum_edge_ratio < 0.5 or maximum_edge_ratio > 2.0:
            for vertex, coordinate in zip(mesh_obj.data.vertices, original_coordinates):
                vertex.co = coordinate
            mesh_obj.data.update()
            self.report(
                {"ERROR"},
                f"手部回正已回滚：边长倍率 {minimum_edge_ratio:.2f}–{maximum_edge_ratio:.2f}",
            )
            return {"CANCELLED"}
        settings.wgame_hand_neutralized = True
        settings.wgame_finger_bones_generated = False
        settings.wgame_finger_rig_complete = False
        settings.wgame_skeleton_accepted = False
        _invalidate_binding_results(settings)
        lines = [
            f"正式网格：{mesh_obj.name}",
            *[
                f"{side.upper()}：移动 {result[0]} 点，最大位移 {result[1]:.4f}"
                for side, result in zip(("l", "r"), results)
            ],
            f"变形边长倍率：{minimum_edge_ratio:.2f}–{maximum_edge_ratio:.2f}",
            *( ["回正前备份：", backup] if backup else [] ),
        ]
        settings.wgame_hand_neutral_report = "；".join(lines)
        _set_report(context, "双手中立位已回正", lines)
        _select_only(context, mesh_obj)
        self.report({"INFO"}, "双手四根主指已回正；请检查轮廓后生成手指骨")
        return {"FINISHED"}


def _fit_finger_chains(analysis):
    points, graph, wrist_dist = analysis['points'], analysis['adjacency'], analysis['distances']
    thumb = analysis['thumb_tip']; main = analysis['main_tips']; normal = analysis['normal']
    middle = sum((points[t].dot(normal) for t in main)) / 4
    thumb_positive = points[thumb].dot(normal) > middle
    ordered = sorted(main, key=lambda t: points[t].dot(normal), reverse=thumb_positive)
    named = dict(zip(('index','middle','ring','pinky'), ordered));named['thumb']=thumb
    routes = {}
    for name, tip in named.items():
        distances = {tip:0.0};queue=[(0.0,tip)]
        while queue:
            distance, index=heapq.heappop(queue)
            if distance!=distances[index]:continue
            for neighbor,length in graph[index]:
                value=distance+length
                if value < distances.get(neighbor,math.inf):
                    distances[neighbor]=value;heapq.heappush(queue,(value,neighbor))
        routes[name]=distances
    owners={i:min(named,key=lambda n: routes[n].get(i,math.inf)/wrist_dist[named[n]]) for i in graph if math.isfinite(wrist_dist[i])}
    chains={};counts={}
    def q(values,t):
        values=sorted(values);x=(len(values)-1)*t;j=int(x)
        return values[j]+(values[min(j+1,len(values)-1)]-values[j])*(x-j)
    for name,tip in named.items():
        total=wrist_dist[tip];root=total*(.25 if name=='thumb' else .40)
        targets=[root,root+(total*.96-root)*.38,root+(total*.96-root)*.72,total*.96]
        candidates=[i for i in owners if owners[i]==name];nodes=[];sizes=[]
        for target in targets:
            window = total * .065
            ids = [i for i in candidates if abs(wrist_dist[i] - target) < window]
            while len(ids) < 3 and window < total * 0.25:
                window *= 1.5
                ids = [i for i in candidates if abs(wrist_dist[i] - target) < window]
            if len(ids) < 3 and len(candidates) >= 3:
                ids = sorted(candidates, key=lambda i: abs(wrist_dist[i] - target))[:3]
            if len(ids) < 3:
                raise ValueError(f'{analysis["side"].upper()} {name} 指节截面样本不足（{len(ids)}/3），未修改骨架')
            nodes.append(Vector(tuple((q([points[i][axis] for i in ids],.15)+q([points[i][axis] for i in ids],.85))*.5 for axis in range(3))))
            sizes.append(len(ids))
        # A sparse palm section can select dorsal/knuckle vertices instead of
        # the finger shaft. Extend the two reliable distal centers back to the
        # first target when that sparse estimate forms an outlier.
        if sizes[0] <= 3:
            ratio = (targets[1] - targets[0]) / max(targets[2] - targets[1], 1e-8)
            shaft_root = nodes[1] - (nodes[2] - nodes[1]) * ratio
            palm_len = (analysis['bone'].tail_local - analysis['bone'].head_local).length
            if (nodes[0] - shaft_root).length > palm_len * 0.30:
                nodes[0] = shaft_root
        chains[name]=nodes;counts[name]=sizes
    return chains,owners,counts



def _validate_finger_chain_fit(mesh_obj, analysis, chains, owners):
    bvh = BVHTree.FromPolygons(analysis["points"], [list(p.vertices) for p in mesh_obj.data.polygons], all_triangles=False)
    palm_len = (analysis["bone"].tail_local - analysis["bone"].head_local).length
    tolerance = max(palm_len * 0.25, 0.015)
    branch_bvhs = {}
    for name, nodes in chains.items():
        for segment in range(3):
            if (nodes[segment + 1] - nodes[segment]).length <= 1e-5:
                raise ValueError(f"{analysis['side'].upper()} {name} 第{segment+1}节长度无效")
            for fraction in (0, .25, .5, .75, 1):
                point = nodes[segment].lerp(nodes[segment + 1], fraction)
                nearest, normal, face_index, _distance = bvh.find_nearest(point)
                if nearest is None or (point - nearest).dot(normal) > tolerance:
                    raise ValueError(f"{analysis['side'].upper()} {name} 第{segment+1}节超出手指表面；请检查候选和网格")
                votes = [owners.get(i) for i in mesh_obj.data.polygons[face_index].vertices]
                if votes.count(name) < len(votes) / 2:
                    # The proximal bone crosses the palm-to-finger transition.
                    # A nearest palm face may belong to a neighboring tip's
                    # geodesic partition even when the chain enters its own
                    # finger. Bound proximal samples by the local surface;
                    # the proximal endpoint and distal bones stay strict.
                    if segment == 0 and fraction < 1:
                        if name not in branch_bvhs:
                            faces = [
                                list(face.vertices)
                                for face in mesh_obj.data.polygons
                                if sum(owners.get(i) == name for i in face.vertices) > len(face.vertices) / 2
                            ]
                            branch_bvhs[name] = (
                                BVHTree.FromPolygons(analysis["points"], faces, all_triangles=False)
                                if faces else None
                            )
                        branch_bvh = branch_bvhs[name]
                        branch_nearest = branch_bvh.find_nearest(point) if branch_bvh else None
                        limit = max(palm_len * 0.35, tolerance) if fraction == 0 else palm_len * 0.35
                        if branch_nearest and branch_nearest[0] is not None and branch_nearest[3] <= limit:
                            continue
                    raise ValueError(f"{analysis['side'].upper()} {name} 第{segment+1}节接近其它手指，拒绝跨指生成")


class WGAME_RIGGING_OT_generate_finger_bones(Operator):
    bl_idname = "wgame_rigging.generate_finger_bones"
    bl_label = "自动识别并生成手指骨"
    bl_description = "复用五指拓扑分支，分别拟合双手指节；校验通过并备份后替换手指骨"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = _wgame_rig_object(context)
        mesh_obj = _finger_authoring_mesh(context, rig_obj)
        if not rig_obj or not mesh_obj:
            return {"CANCELLED"}
        previous_mode = context.object.mode if context.object else "OBJECT"
        previous_object = context.object
        if previous_mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        try:
            plans = {}
            analyses = {}
            for side in ("l", "r"):
                analysis = _hand_geodesic_analysis(mesh_obj, rig_obj, side)
                chains, owners, _counts = _fit_finger_chains(analysis)
                _validate_finger_chain_fit(mesh_obj, analysis, chains, owners)
                plans[side], analyses[side] = chains, analysis
            expected = {f"{finger}_{segment:02d}.{side}" for side in plans for finger in plans[side] for segment in range(1, 4)}
            existing = {b.name for b in rig_obj.data.bones if any(b.name.startswith(f + "_") for f in ("thumb", "index", "middle", "ring", "pinky"))}
            if existing - expected:
                raise ValueError("存在非标准手指骨名称，请先处理；未删除任何骨骼")
            if any(b.parent and b.parent.name in existing and b.name not in existing for b in rig_obj.data.bones):
                raise ValueError("手指骨挂有其它子骨，请先处理其依赖；未删除任何骨骼")
            mapping = json.loads(settings.wgame_humanoid_mapping_json or "{}")
            if not isinstance(mapping, dict):
                raise ValueError("Humanoid 映射必须是对象")
            backup = _save_backup_copy()
            if not backup or not pathlib.Path(backup).is_file():
                raise ValueError("生成前必须先保存 Blend 并成功写入备份")
            settings.backup_filepath = backup
        except Exception as error:
            if previous_mode != "OBJECT" and previous_object:
                _select_only(context, previous_object)
                bpy.ops.object.mode_set(mode=previous_mode)
            settings.wgame_finger_detection_report = str(error)
            self.report({"ERROR"}, str(error))
            return {"CANCELLED"}

        untouched = {b.name: _bone_snapshot_entry(b) for b in rig_obj.data.bones if b.name not in existing}
        rollback = rig_obj.data.copy()
        _select_only(context, rig_obj)
        try:
            bpy.ops.object.mode_set(mode="EDIT")
            bones = rig_obj.data.edit_bones
            for name in existing:
                bones.remove(bones[name])
            unity_names = {"thumb": "Thumb", "index": "Index", "middle": "Middle", "ring": "Ring", "pinky": "Little"}
            for side, chains in plans.items():
                for finger, nodes in chains.items():
                    parent = f"hand.{side}"
                    for segment in range(3):
                        name = f"{finger}_{segment+1:02d}.{side}"
                        bone = bones.new(name)
                        bone.head, bone.tail = nodes[segment], nodes[segment+1]
                        bone.parent = bones[parent]
                        bone.use_connect = segment > 0
                        bone.use_deform = True
                        bone.align_roll(analyses[side]["up"])
                        parent = name
                        unity_side = "Left" if side == "l" else "Right"
                        unity_segment = ("Proximal", "Intermediate", "Distal")[segment]
                        mapping[unity_side + unity_names[finger] + unity_segment] = name
            bpy.ops.object.mode_set(mode="OBJECT")
            mapping_raw = json.dumps(mapping, ensure_ascii=False, separators=(",", ":"))
            errors = _finger_structure_errors(rig_obj, mapping_raw)
            if errors or any(_bone_snapshot_entry(rig_obj.data.bones[n]) != v for n, v in untouched.items()):
                raise ValueError("生成后骨架校验失败：" + "；".join(errors))
        except Exception as error:
            if rig_obj.mode != "OBJECT":
                bpy.ops.object.mode_set(mode="OBJECT")
            failed = rig_obj.data
            rig_obj.data = rollback
            if failed.users == 0:
                bpy.data.armatures.remove(failed)
            self.report({"ERROR"}, f"手指生成失败，已恢复原骨架：{error}")
            return {"CANCELLED"}
        if rollback.users == 0:
            bpy.data.armatures.remove(rollback)
        settings.wgame_humanoid_mapping_json = mapping_raw
        settings.wgame_finger_bones_generated = True
        settings.wgame_finger_rig_complete = False
        settings.wgame_skeleton_accepted = False
        _invalidate_binding_results(settings)
        settings.wgame_finger_detection_report = "已生成30根手指骨：左右独立分支拟合，指节与骨段表面/分支检查通过；请目视检查后验收"
        self.report({"INFO"}, settings.wgame_finger_detection_report)
        return {"FINISHED"}



def _finger_structure_errors(rig_obj, mapping_raw):
    """Validate the exact Humanoid finger contract independently of acceptance flags."""
    if not rig_obj:
        return ["缺少 WGame 骨架"]
    try:
        mapping = json.loads(mapping_raw or "{}")
    except (ValueError, TypeError):
        return ["Humanoid 映射不是有效 JSON"]
    if not isinstance(mapping, dict):
        return ["Humanoid 映射必须是对象"]
    fingers = {"thumb": "Thumb", "index": "Index", "middle": "Middle", "ring": "Ring", "pinky": "Little"}
    expected = {f"{finger}_{segment:02d}.{side}" for finger in fingers for segment in range(1, 4) for side in ("l", "r")}
    actual = {bone.name for bone in rig_obj.data.bones if any(bone.name.startswith(name + "_") for name in fingers)}
    errors = []
    if expected != actual:
        errors.append("手指骨名称集合错误；缺少 " + ",".join(sorted(expected - actual)) + "；额外 " + ",".join(sorted(actual - expected)))
    for side, unity_side in (("l", "Left"), ("r", "Right")):
        if not rig_obj.data.bones.get(f"hand.{side}"):
            errors.append(f"缺少 hand.{side}")
        for finger, unity_finger in fingers.items():
            for segment, unity_segment in enumerate(("Proximal", "Intermediate", "Distal"), 1):
                name = f"{finger}_{segment:02d}.{side}"
                bone = rig_obj.data.bones.get(name)
                if not bone:
                    continue
                parent = f"hand.{side}" if segment == 1 else f"{finger}_{segment-1:02d}.{side}"
                if not bone.parent or bone.parent.name != parent:
                    errors.append(name + " 父级必须为 " + parent)
                if not bone.use_deform:
                    errors.append(name + " 未启用 Deform")
                if not all(math.isfinite(value) for point in (bone.head_local, bone.tail_local) for value in point) or bone.length <= 1e-6:
                    errors.append(name + " 长度或坐标无效")
                if segment > 1 and (not bone.use_connect or not bone.parent or (bone.head_local - bone.parent.tail_local).length > 1e-5):
                    errors.append(name + " 骨链未连续连接")
                if mapping.get(unity_side + unity_finger + unity_segment) != name:
                    errors.append(name + " Humanoid 映射不一致")
    return errors


def _reject_invalid_fingers(context, settings, rig_obj):
    errors = _finger_structure_errors(rig_obj, settings.wgame_humanoid_mapping_json)
    if errors:
        settings.wgame_finger_rig_complete = False
        settings.wgame_skeleton_accepted = False
        if rig_obj:
            rig_obj["wgame_skeleton_accepted"] = False
        _invalidate_binding_results(settings)
        settings.wgame_finger_detection_report = "手指结构验收失败：" + "；".join(errors)
    return errors


class WGAME_RIGGING_OT_accept_finger_bones(Operator):
    bl_idname = "wgame_rigging.accept_finger_bones"
    bl_label = "确认手指骨"
    bl_description = "确认自动生成的左右30根手指骨位置可以进入下一阶段"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = next((obj for obj in context.scene.objects if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"), None)
        if rig_obj and rig_obj.mode == "EDIT":
            _select_only(context, rig_obj)
            bpy.ops.object.mode_set(mode="OBJECT")
        errors = _reject_invalid_fingers(context, settings, rig_obj)
        if errors:
            self.report({"ERROR"}, settings.wgame_finger_detection_report)
            return {"CANCELLED"}
        settings.wgame_finger_rig_complete = True
        self.report({"INFO"}, "手指骨已确认：30/30")
        return {"FINISHED"}


class WGAME_RIGGING_OT_focus_finger_bones(Operator):
    bl_idname = "wgame_rigging.focus_finger_bones"
    bl_label = "检查手指骨"
    bl_options = {"REGISTER"}

    side: EnumProperty(items=(("L", "左手", "检查左手"), ("R", "右手", "检查右手")), default="L")

    def execute(self, context):
        rig_obj = next((obj for obj in context.scene.objects if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"), None)
        if not rig_obj:
            return {"CANCELLED"}
        _select_only(context, rig_obj)
        if rig_obj.mode != "EDIT":
            _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="EDIT")
        suffix = ".l" if self.side == "L" else ".r"
        selected = []
        for bone in rig_obj.data.edit_bones:
            is_finger = bone.name.endswith(suffix) and any(bone.name.startswith(prefix + "_") for prefix in ("thumb", "index", "middle", "ring", "pinky"))
            bone.select = is_finger
            bone.select_head = is_finger
            bone.select_tail = is_finger
            if is_finger:
                selected.extend((bone.head.copy(), bone.tail.copy()))
        if selected:
            center = sum(selected, Vector((0.0, 0.0, 0.0))) / len(selected)
            window, screen = _joint_guide_window_screen(context)
            for area in (item for item in screen.areas if item.type == "VIEW_3D"):
                area.spaces.active.region_3d.view_location = rig_obj.matrix_world @ center
                area.spaces.active.region_3d.view_distance = 0.11
                area.tag_redraw()
        return {"FINISHED"}


