class WGAME_RIGGING_OT_confirm_head_plan(Operator):
    bl_idname = "wgame_rigging.confirm_head_plan"
    bl_label = "确认头面方案"
    bl_description = "按当前眼球与下颌方案创建、移除或跳过对应骨骼"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        if settings.wgame_eye_mode == "UNSET" or settings.wgame_jaw_mode == "UNSET":
            self.report({"ERROR"}, "请先选择眼球和下颌方案")
            return {"CANCELLED"}
        rig_obj = next((obj for obj in context.scene.objects if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"), None)
        mesh_obj = next((obj for obj in context.scene.objects if _is_formal_character_mesh(obj)), None)
        if not rig_obj or not mesh_obj:
            return {"CANCELLED"}
        if rig_obj.mode != "EDIT":
            _select_only(context, rig_obj)
            _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="EDIT")
        edit_bones = rig_obj.data.edit_bones
        for name in ("eye.l", "eye.r", "jaw.x"):
            bone = edit_bones.get(name)
            if bone:
                edit_bones.remove(bone)
        mapping = json.loads(settings.wgame_humanoid_mapping_json or "{}")
        for key in ("LeftEye", "RightEye", "Jaw"):
            mapping.pop(key, None)
        created = []
        if settings.wgame_eye_mode == "BONES":
            components = [item for item in _unrigged_components(settings) if item.get("role") == "HEAD_RIGID" and 50 <= int(item.get("vertices", 0)) <= 500 and abs(float((item.get("center") or [0.0])[0])) > 0.005]
            pairs = []
            for left in components:
                for right in components:
                    if float(left["center"][0]) <= 0.0 or float(right["center"][0]) >= 0.0:
                        continue
                    score = abs(float(left["center"][0]) + float(right["center"][0])) + abs(float(left["center"][1]) - float(right["center"][1])) + abs(float(left["center"][2]) - float(right["center"][2])) + abs(int(left["vertices"]) - int(right["vertices"])) * 0.001
                    pairs.append((score, left, right))
            if not pairs:
                self.report({"ERROR"}, "没有找到可靠的左右眼球组件对")
                return {"CANCELLED"}
            _score, left_component, right_component = min(pairs, key=lambda item: item[0])
            for side, component in (("l", left_component), ("r", right_component)):
                center_world = mesh_obj.matrix_world @ Vector(component["center"])
                center = rig_obj.matrix_world.inverted() @ center_world
                bone = edit_bones.new(f"eye.{side}")
                bone.head = center
                bone.tail = center + Vector((0.0, -0.02, 0.0))
                bone.parent = edit_bones.get("head.x")
                bone.use_deform = True
                created.append(bone.name)
            mapping["LeftEye"] = "eye.l"
            mapping["RightEye"] = "eye.r"
        if settings.wgame_jaw_mode == "BONE":
            pivot = _joint_guide_object("jaw.x")
            end = bpy.data.objects.get("WGameGuide_jaw_end_x")
            if not pivot or not end:
                self.report({"ERROR"}, "生成下颌骨前需要创建并定位下颌末端")
                return {"CANCELLED"}
            head = rig_obj.matrix_world.inverted() @ pivot.matrix_world.translation
            tail = rig_obj.matrix_world.inverted() @ end.matrix_world.translation
            if (tail - head).length < 0.01:
                self.report({"ERROR"}, "下颌骨长度过短")
                return {"CANCELLED"}
            bone = edit_bones.new("jaw.x")
            bone.head, bone.tail = head, tail
            bone.parent = edit_bones.get("head.x")
            bone.use_deform = True
            created.append("jaw.x")
            mapping["Jaw"] = "jaw.x"
        _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="OBJECT")
        settings.wgame_humanoid_mapping_json = json.dumps(mapping, ensure_ascii=False, separators=(",", ":"))
        settings.wgame_head_detail_complete = True
        rig_obj["wgame_eye_mode"] = settings.wgame_eye_mode
        rig_obj["wgame_jaw_mode"] = settings.wgame_jaw_mode
        self.report({"INFO"}, "头面方案已确认" + ("；创建 " + ", ".join(created) if created else "；未创建可选头面骨"))
        return {"FINISHED"}


class WGAME_RIGGING_OT_generate_secondary_bones(Operator):
    bl_idname = "wgame_rigging.generate_secondary_bones"
    bl_label = "生成披风与摆动次级骨"
    bl_description = "根据摆动骨链组件的真实顶点分布生成披风三列骨链和小型摆动链"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = next((obj for obj in context.scene.objects if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"), None)
        mesh_obj = next((obj for obj in context.scene.objects if _is_formal_character_mesh(obj)), None)
        components = [item for item in _unrigged_components(settings) if item.get("role") == "CAPE"]
        if not rig_obj or not mesh_obj or not components:
            return {"CANCELLED"}
        if rig_obj.mode != "EDIT":
            _select_only(context, rig_obj)
            _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="EDIT")
        edit_bones = rig_obj.data.edit_bones
        for bone in list(edit_bones):
            if bone.name.startswith("cape.") or bone.name.startswith("swing_"):
                edit_bones.remove(bone)
        transform = rig_obj.matrix_world.inverted() @ mesh_obj.matrix_world

        def component_points(component):
            return [transform @ mesh_obj.data.vertices[index].co for index in component.get("vertex_indices", [])]

        def sample_point(points, x_target, z_target):
            ordered = sorted(points, key=lambda point: abs(point.z - z_target) + abs(point.x - x_target) * 0.7)
            chosen = ordered[: max(8, min(40, len(ordered) // 8))]
            return sum(chosen, Vector((0.0, 0.0, 0.0))) / len(chosen)

        def create_chain(prefix, nodes, parent_name):
            parent = edit_bones.get(parent_name)
            names = []
            for index in range(len(nodes) - 1):
                bone = edit_bones.new(f"{prefix}_{index + 1:02d}")
                bone.head, bone.tail = nodes[index], nodes[index + 1]
                bone.parent = parent
                bone.use_connect = index > 0
                bone.use_deform = True
                parent = bone
                names.append(bone.name)
            return names

        largest = max(components, key=lambda item: int(item.get("vertices", 0)))
        created = []
        points = component_points(largest)
        xs = sorted(point.x for point in points)
        zs = sorted(point.z for point in points)
        x_targets = {
            "r": xs[int((len(xs) - 1) * 0.18)],
            "x": xs[int((len(xs) - 1) * 0.50)],
            "l": xs[int((len(xs) - 1) * 0.82)],
        }
        top = zs[int((len(zs) - 1) * 0.94)]
        bottom = zs[int((len(zs) - 1) * 0.06)]
        for side, bone_count in (("r", 4), ("x", 3), ("l", 4)):
            nodes = [sample_point(points, x_targets[side], top + (bottom - top) * index / bone_count) for index in range(bone_count + 1)]
            created.extend(create_chain(f"cape.{side}", nodes, "spine_02.x"))
        small_components = [item for item in components if item is not largest]
        for component_index, component in enumerate(small_components, start=1):
            small_points = component_points(component)
            small_z = sorted(point.z for point in small_points)
            x_center = sum(point.x for point in small_points) / len(small_points)
            top_z = small_z[int((len(small_z) - 1) * 0.92)]
            bottom_z = small_z[int((len(small_z) - 1) * 0.08)]
            nodes = [sample_point(small_points, x_center, top_z + (bottom_z - top_z) * index / 2) for index in range(3)]
            created.extend(create_chain(f"swing_{component_index:02d}.x", nodes, "pelvis.x"))
        _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="OBJECT")
        collection = rig_obj.data.collections.get("WGame Secondary") or rig_obj.data.collections.new("WGame Secondary")
        for name in created:
            if rig_obj.data.bones.get(name):
                collection.assign(rig_obj.data.bones[name])
        settings.wgame_secondary_bones_complete = True
        settings.wgame_component_skin_complete = False
        self.report({"INFO"}, f"次级骨已生成：{len(created)} 根（披风11，小型摆动{len(created)-11}）")
        return {"FINISHED"}


def _secondary_edit_bone_names(settings, rig_obj, scope=None):
    scope = scope or settings.wgame_secondary_edit_scope
    cape = [bone.name for bone in rig_obj.data.bones if bone.name.startswith("cape.")]
    swing = [bone.name for bone in rig_obj.data.bones if bone.name.startswith("swing_")]
    attachment_targets = {
        group.get("target_bone", "")
        for group in _unrigged_binding_groups(settings)
        if group.get("status") == "COMPLETE"
    }
    attachments = [bone.name for bone in rig_obj.data.bones if bone.name in attachment_targets]
    if scope == "CAPE":
        return cape
    if scope == "SWING":
        return swing
    if scope == "ATTACHMENT":
        return attachments
    return list(dict.fromkeys(cape + swing + attachments))


def _secondary_edit_vertex_ids(settings, scope):
    components = _unrigged_components(settings)
    cape_components = [item for item in components if item.get("role") == "CAPE"]
    largest = max(cape_components, key=lambda item: int(item.get("vertices", 0)), default=None)
    if scope == "CAPE":
        selected_components = [largest] if largest else []
    elif scope == "SWING":
        selected_components = [item for item in cape_components if item is not largest]
    elif scope == "ATTACHMENT":
        attachment_ids = {
            component_id
            for group in _unrigged_binding_groups(settings)
            if group.get("status") == "COMPLETE"
            for component_id in group.get("component_ids", [])
        }
        selected_components = [item for item in components if item.get("id") in attachment_ids]
    else:
        attachment_ids = {
            component_id
            for group in _unrigged_binding_groups(settings)
            if group.get("status") == "COMPLETE"
            for component_id in group.get("component_ids", [])
        }
        selected_components = cape_components + [
            item for item in components if item.get("id") in attachment_ids
        ]
    return {
        index
        for component in selected_components
        if component
        for index in component.get("vertex_indices", [])
    }


class WGAME_RIGGING_OT_edit_secondary_bones(Operator):
    bl_idname = "wgame_rigging.edit_secondary_bones"
    bl_label = "编辑所选次级骨"
    bl_description = "恢复绑定姿势，自动选中指定类型的次级骨并进入正侧双视图；不会清除现有权重"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = next(
            (
                obj
                for obj in context.scene.objects
                if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"
            ),
            None,
        )
        if not rig_obj:
            self.report({"ERROR"}, "没有找到 WGame 骨架")
            return {"CANCELLED"}
        selected_names = _secondary_edit_bone_names(settings, rig_obj)
        if not selected_names:
            self.report({"ERROR"}, "当前类型没有可编辑的次级骨")
            return {"CANCELLED"}
        if SLIDER_PREVIEW_BACKUP_KEY in rig_obj:
            _restore_slider_preview_base(rig_obj, clear=True)
            _reset_slider_properties(settings)
        if POSE_BACKUP_KEY in rig_obj:
            _restore_pose_backup(rig_obj)
        settings.wgame_preview_active = False
        settings.wgame_preview_preset = ""
        _select_only(context, rig_obj)
        if rig_obj.mode != "EDIT":
            _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="EDIT")
        edit_bones = rig_obj.data.edit_bones
        if not settings.wgame_secondary_edit_active:
            backup = {
                name: {
                    "head": list(edit_bones[name].head),
                    "tail": list(edit_bones[name].tail),
                    "roll": float(edit_bones[name].roll),
                }
                for name in selected_names
                if edit_bones.get(name)
            }
            rig_obj[SECONDARY_EDIT_BACKUP_KEY] = json.dumps(
                {"scope": settings.wgame_secondary_edit_scope, "bones": backup},
                separators=(",", ":"),
            )
        selected_points = []
        for bone in edit_bones:
            selected = bone.name in selected_names
            if selected:
                bone.hide = False
                selected_points.extend((bone.head.copy(), bone.tail.copy()))
            bone.select = selected
            bone.select_head = selected
            bone.select_tail = selected
        edit_bones.active = edit_bones.get("cape.x_01") if "cape.x_01" in selected_names else next(
            (bone for bone in edit_bones if bone.name in selected_names),
            None,
        )
        rig_obj.show_in_front = True
        settings.wgame_secondary_edit_active = True

        if not settings.unrigged_joint_dual_view:
            try:
                bpy.ops.wgame_rigging.enable_joint_dual_view()
            except RuntimeError:
                pass
        if selected_points:
            center_local = sum(selected_points, Vector((0.0, 0.0, 0.0))) / len(selected_points)
            center_world = rig_obj.matrix_world @ center_local
            extent = max((point - center_local).length for point in selected_points)
            window, screen = _joint_guide_window_screen(context)
            areas = sorted((area for area in screen.areas if area.type == "VIEW_3D"), key=lambda area: area.x) if screen else []
            for index, area in enumerate(areas[:2]):
                region = next((item for item in area.regions if item.type == "WINDOW"), None)
                if not region:
                    continue
                with context.temp_override(
                    window=window,
                    screen=screen,
                    area=area,
                    region=region,
                    space_data=area.spaces.active,
                ):
                    bpy.ops.view3d.view_axis(type="FRONT" if index == 0 else "LEFT", align_active=False)
                area.spaces.active.region_3d.view_location = center_world
                area.spaces.active.region_3d.view_distance = max(0.24, extent * 1.25)
                area.tag_redraw()
        self.report({"INFO"}, f"已选中 {len(selected_names)} 根次级骨；正面调宽度，侧面调深度")
        return {"FINISHED"}


class WGAME_RIGGING_OT_finish_secondary_bones(Operator):
    bl_idname = "wgame_rigging.finish_secondary_bones"
    bl_label = "完成并检查次级骨"
    bl_description = "退出编辑并检查所选次级骨数量、长度和到对应网格的距离；现有顶点组权重保持不变"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = next(
            (
                obj
                for obj in context.scene.objects
                if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"
            ),
            None,
        )
        mesh_obj = bpy.data.objects.get(settings.mesh_name)
        if not rig_obj or not mesh_obj or mesh_obj.type != "MESH":
            self.report({"ERROR"}, "没有找到绑定主体与 WGame 骨架")
            return {"CANCELLED"}
        if rig_obj.mode == "EDIT":
            _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="OBJECT")
        target_bones = [
            rig_obj.data.bones[name]
            for name in _secondary_edit_bone_names(settings, rig_obj)
            if rig_obj.data.bones.get(name)
        ]
        height = max(float(mesh_obj.dimensions.z), 0.0001)
        short_bones = [bone.name for bone in target_bones if bone.length < height * 0.005]
        target_vertex_ids = _secondary_edit_vertex_ids(settings, settings.wgame_secondary_edit_scope)
        worst_distance = 0.0
        if target_vertex_ids:
            transform = rig_obj.matrix_world.inverted() @ mesh_obj.matrix_world
            kd = KDTree(len(target_vertex_ids))
            for kd_index, vertex_id in enumerate(sorted(target_vertex_ids)):
                kd.insert(transform @ mesh_obj.data.vertices[vertex_id].co, kd_index)
            kd.balance()
            for bone in target_bones:
                for point in (bone.head_local, bone.tail_local):
                    _co, _index, distance = kd.find(point)
                    worst_distance = max(worst_distance, distance)
        settings.wgame_secondary_edit_active = False
        context.view_layer.update()
        if not target_bones or short_bones:
            self.report(
                {"ERROR"},
                f"次级骨检查失败：数量 {len(target_bones)}，过短 {len(short_bones)} 根",
            )
            return {"CANCELLED"}
        if worst_distance > height * 0.04:
            self.report({"WARNING"}, f"次级骨已保存，但有节点离对应组件较远：最大 {worst_distance:.3f}m")
        else:
            self.report({"INFO"}, f"次级骨位置检查通过；最大表面距离 {worst_distance:.3f}m，权重无需重做")
        return {"FINISHED"}


class WGAME_RIGGING_OT_restore_secondary_bones(Operator):
    bl_idname = "wgame_rigging.restore_secondary_bones"
    bl_label = "恢复调整前位置"
    bl_description = "恢复点击“编辑所选次级骨”之前保存的次级骨静止位置"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = next(
            (
                obj
                for obj in context.scene.objects
                if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"
            ),
            None,
        )
        if not rig_obj or SECONDARY_EDIT_BACKUP_KEY not in rig_obj:
            self.report({"WARNING"}, "没有可恢复的次级骨位置")
            return {"CANCELLED"}
        try:
            backup = json.loads(rig_obj[SECONDARY_EDIT_BACKUP_KEY])
        except (TypeError, ValueError):
            self.report({"ERROR"}, "次级骨恢复记录损坏")
            return {"CANCELLED"}
        bone_states = backup.get("bones", backup)
        _select_only(context, rig_obj)
        if rig_obj.mode != "EDIT":
            _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="EDIT")
        restored = 0
        for name, state in bone_states.items():
            bone = rig_obj.data.edit_bones.get(name)
            if not bone:
                continue
            bone.head = Vector(state["head"])
            bone.tail = Vector(state["tail"])
            bone.roll = float(state.get("roll", bone.roll))
            restored += 1
        _call_arp_in_view3d(context, bpy.ops.object.mode_set, _active_object=rig_obj, mode="OBJECT")
        del rig_obj[SECONDARY_EDIT_BACKUP_KEY]
        settings.wgame_secondary_edit_active = False
        context.view_layer.update()
        self.report({"INFO"}, f"已恢复 {restored} 根次级骨到调整前位置")
        return {"FINISHED"}


def _current_secondary_weight_bone(context, settings, rig_obj):
    names = _secondary_edit_bone_names(settings, rig_obj)
    current = settings.wgame_secondary_weight_bone
    if current not in names:
        current = names[0] if names else ""
        if current:
            try:
                settings.wgame_secondary_weight_bone = current
            except TypeError:
                pass
    return current


class WGAME_RIGGING_OT_edit_secondary_weight(Operator):
    bl_idname = "wgame_rigging.edit_secondary_weight"
    bl_label = "进入当前骨骼权重绘制"
    bl_description = "只允许绘制当前次级骨类型对应的组件顶点，并激活所选骨骼的真实顶点组"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = bpy.data.objects.get(settings.rig_name)
        mesh_obj = bpy.data.objects.get(settings.mesh_name)
        if not rig_obj or rig_obj.type != "ARMATURE" or not mesh_obj or mesh_obj.type != "MESH":
            self.report({"ERROR"}, "没有找到绑定主体与 WGame 骨架")
            return {"CANCELLED"}
        group_name = _current_secondary_weight_bone(context, settings, rig_obj)
        vertex_group = mesh_obj.vertex_groups.get(group_name)
        if not group_name or not vertex_group:
            self.report({"ERROR"}, f"没有找到次级骨顶点组：{group_name or '未选择'}")
            return {"CANCELLED"}
        target_vertex_ids = _secondary_edit_vertex_ids(settings, settings.wgame_secondary_edit_scope)
        if not target_vertex_ids:
            self.report({"ERROR"}, "当前类型没有可编辑的组件顶点")
            return {"CANCELLED"}
        if SLIDER_PREVIEW_BACKUP_KEY in rig_obj:
            _restore_slider_preview_base(rig_obj, clear=True)
            _reset_slider_properties(settings)
        if POSE_BACKUP_KEY in rig_obj:
            _restore_pose_backup(rig_obj)
        settings.wgame_preview_active = False
        settings.wgame_preview_preset = ""
        if getattr(context, "object", None) and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        for vertex in mesh_obj.data.vertices:
            vertex.select = vertex.index in target_vertex_ids
        if hasattr(mesh_obj.data, "use_paint_mask"):
            mesh_obj.data.use_paint_mask = False
        if hasattr(mesh_obj.data, "use_paint_mask_vertex"):
            mesh_obj.data.use_paint_mask_vertex = True
        for candidate in context.view_layer.objects:
            candidate.select_set(False)
        rig_obj.hide_set(False)
        mesh_obj.hide_set(False)
        rig_obj.select_set(True)
        mesh_obj.select_set(True)
        context.view_layer.objects.active = mesh_obj
        mesh_obj.vertex_groups.active_index = vertex_group.index
        if hasattr(rig_obj.data.bones, "active") and rig_obj.data.bones.get(group_name):
            rig_obj.data.bones.active = rig_obj.data.bones[group_name]
        bpy.ops.object.mode_set(mode="WEIGHT_PAINT")
        statistics = _weight_group_statistics(mesh_obj, group_name)
        if statistics:
            _frame_weight_group(context, mesh_obj, statistics)
        settings.weight_group_name = group_name
        display_name = next(
            (label for identifier, label, _description in _secondary_weight_bone_items(settings, context) if identifier == group_name),
            group_name,
        )
        _set_focus_marker(
            context,
            rig_obj,
            group_name,
            f"当前权重：{display_name}（{group_name}）",
            mesh_obj=mesh_obj,
            diagnostic_name=group_name,
            kind="WEIGHT_BROWSER",
        )
        settings.wgame_secondary_weight_report = (
            f"正在编辑 {group_name}；仅 {len(target_vertex_ids)} 个当前组件顶点可绘制"
        )
        self.report({"INFO"}, settings.wgame_secondary_weight_report)
        return {"FINISHED"}


class WGAME_RIGGING_OT_navigate_secondary_weight(Operator):
    bl_idname = "wgame_rigging.navigate_secondary_weight"
    bl_label = "切换次级骨权重"
    bl_description = "切换到同一类型的上一根或下一根次级骨，并继续权重绘制"
    bl_options = {"REGISTER", "UNDO"}

    step: bpy.props.IntProperty(default=1)

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = bpy.data.objects.get(settings.rig_name)
        if not rig_obj or rig_obj.type != "ARMATURE":
            return {"CANCELLED"}
        names = _secondary_edit_bone_names(settings, rig_obj)
        if not names:
            return {"CANCELLED"}
        current = settings.wgame_secondary_weight_bone
        index = names.index(current) if current in names else 0
        settings.wgame_secondary_weight_bone = names[(index + self.step) % len(names)]
        return bpy.ops.wgame_rigging.edit_secondary_weight()


class WGAME_RIGGING_OT_finish_secondary_weight(Operator):
    bl_idname = "wgame_rigging.finish_secondary_weight"
    bl_label = "完成并检查次级骨权重"
    bl_description = "退出权重绘制，检查当前类型组件的零权重、四权重上限、归一化和次级骨覆盖"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = bpy.data.objects.get(settings.rig_name)
        mesh_obj = bpy.data.objects.get(settings.mesh_name)
        if not rig_obj or not mesh_obj:
            return {"CANCELLED"}
        if getattr(context, "object", None) and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        if hasattr(mesh_obj.data, "use_paint_mask_vertex"):
            mesh_obj.data.use_paint_mask_vertex = False
        target_vertex_ids = _secondary_edit_vertex_ids(settings, settings.wgame_secondary_edit_scope)
        target_names = set(_secondary_edit_bone_names(settings, rig_obj))
        target_group_indices = {
            group.index for group in mesh_obj.vertex_groups if group.name in target_names
        }
        zero = over_four = bad_sum = missing_secondary = 0
        for vertex_id in target_vertex_ids:
            vertex = mesh_obj.data.vertices[vertex_id]
            assignments = [item for item in vertex.groups if item.weight > 1e-6]
            total = sum(item.weight for item in assignments)
            zero += not assignments
            over_four += len(assignments) > 4
            bad_sum += bool(assignments) and abs(total - 1.0) > 1e-4
            missing_secondary += not any(item.group in target_group_indices for item in assignments)
        settings.wgame_secondary_weight_report = (
            f"检查 {len(target_vertex_ids)} 顶点：零权重 {zero} / 超4骨 {over_four} / "
            f"未归一 {bad_sum} / 无次级骨 {missing_secondary}"
        )
        severity = {"INFO"} if zero == over_four == bad_sum == missing_secondary == 0 else {"WARNING"}
        self.report(severity, settings.wgame_secondary_weight_report)
        return {"FINISHED"}


class WGAME_RIGGING_OT_recalculate_secondary_weights(Operator):
    bl_idname = "wgame_rigging.recalculate_secondary_weights"
    bl_label = "按当前位置重算当前组件权重"
    bl_description = "先备份，再按当前次级骨位置重算当前组件；不修改身体、手指或其它组件"
    bl_options = {"REGISTER", "UNDO"}

    def invoke(self, context, event):
        return context.window_manager.invoke_confirm(self, event)

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = bpy.data.objects.get(settings.rig_name)
        mesh_obj = bpy.data.objects.get(settings.mesh_name)
        if not rig_obj or rig_obj.type != "ARMATURE" or not mesh_obj or mesh_obj.type != "MESH":
            self.report({"ERROR"}, "没有找到绑定主体与 WGame 骨架")
            return {"CANCELLED"}
        if SLIDER_PREVIEW_BACKUP_KEY in rig_obj:
            _restore_slider_preview_base(rig_obj, clear=True)
            _reset_slider_properties(settings)
        if POSE_BACKUP_KEY in rig_obj:
            _restore_pose_backup(rig_obj)
        settings.wgame_preview_active = False
        settings.wgame_preview_preset = ""
        if getattr(context, "object", None) and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        backup = _save_backup_copy()
        if backup:
            settings.backup_filepath = backup

        components = _unrigged_components(settings)
        cape_components = [item for item in components if item.get("role") == "CAPE"]
        largest = max(cape_components, key=lambda item: int(item.get("vertices", 0)), default=None)
        small_components = [item for item in cape_components if item is not largest]
        scope = settings.wgame_secondary_edit_scope
        worksets = []
        if scope in {"CAPE", "ALL"} and largest:
            names = [bone.name for bone in rig_obj.data.bones if bone.name.startswith("cape.")]
            worksets.append((set(largest.get("vertex_indices", [])), names))
        if scope in {"SWING", "ALL"}:
            for component_index, component in enumerate(small_components, start=1):
                prefix = f"swing_{component_index:02d}.x_"
                names = [bone.name for bone in rig_obj.data.bones if bone.name.startswith(prefix)]
                worksets.append((set(component.get("vertex_indices", [])), names))
        if scope in {"ATTACHMENT", "ALL"}:
            component_by_id = {item.get("id"): item for item in components}
            for binding_group in _unrigged_binding_groups(settings):
                if binding_group.get("status") != "COMPLETE":
                    continue
                vertex_ids = {
                    vertex_id
                    for component_id in binding_group.get("component_ids", [])
                    for vertex_id in component_by_id.get(component_id, {}).get("vertex_indices", [])
                }
                worksets.append((vertex_ids, [binding_group.get("target_bone", "")]))
        worksets = [
            (vertex_ids, [name for name in names if name and rig_obj.data.bones.get(name)])
            for vertex_ids, names in worksets
            if vertex_ids and names
        ]
        worksets = [(vertex_ids, names) for vertex_ids, names in worksets if names]
        if not worksets:
            self.report({"ERROR"}, "当前类型没有可以重算的组件与骨骼")
            return {"CANCELLED"}

        all_vertex_ids = sorted({vertex_id for vertex_ids, _names in worksets for vertex_id in vertex_ids})
        deform_names = {bone.name for bone in rig_obj.data.bones if bone.use_deform}
        scope_group_names = set()
        if scope in {"CAPE", "ALL"}:
            scope_group_names.update(group.name for group in mesh_obj.vertex_groups if group.name.startswith("cape."))
        if scope in {"SWING", "ALL"}:
            scope_group_names.update(group.name for group in mesh_obj.vertex_groups if group.name.startswith("swing_"))
        if scope in {"ATTACHMENT", "ALL"}:
            scope_group_names.update(
                binding_group.get("target_bone", "")
                for binding_group in _unrigged_binding_groups(settings)
            )
        orphan_scope_names = {
            name for name in scope_group_names if name and not rig_obj.data.bones.get(name)
        }
        for group in mesh_obj.vertex_groups:
            if group.name in deform_names or group.name in scope_group_names:
                group.remove(all_vertex_ids)

        inverse_mesh = mesh_obj.matrix_world.inverted()
        bone_to_mesh = inverse_mesh @ rig_obj.matrix_world

        def group(name):
            return mesh_obj.vertex_groups.get(name) or mesh_obj.vertex_groups.new(name=name)

        def segment_distance(point, bone):
            head = bone_to_mesh @ bone.head_local
            tail = bone_to_mesh @ bone.tail_local
            vector = tail - head
            factor = max(0.0, min(1.0, (point - head).dot(vector) / max(vector.length_squared, 1e-12)))
            return (point - (head + vector * factor)).length

        for vertex_ids, names in worksets:
            if len(names) == 1:
                group(names[0]).add(sorted(vertex_ids), 1.0, "REPLACE")
                continue
            bones = [rig_obj.data.bones[name] for name in names]
            for vertex_id in vertex_ids:
                point = mesh_obj.data.vertices[vertex_id].co
                nearest = sorted((segment_distance(point, bone), bone.name) for bone in bones)[:2]
                values = [1.0 / max(distance, 0.003) ** 3 for distance, _name in nearest]
                total = sum(values)
                for value, (_distance, name) in zip(values, nearest):
                    group(name).add([vertex_id], value / total, "REPLACE")

        removed_orphan_groups = 0
        for name in sorted(orphan_scope_names):
            orphan_group = mesh_obj.vertex_groups.get(name)
            if orphan_group and not any(
                assignment.group == orphan_group.index and assignment.weight > 1e-6
                for vertex in mesh_obj.data.vertices
                for assignment in vertex.groups
            ):
                mesh_obj.vertex_groups.remove(orphan_group)
                removed_orphan_groups += 1

        zero = over_four = bad_sum = missing_scope = 0
        target_names = {name for _vertex_ids, names in worksets for name in names}
        target_indices = {
            mesh_obj.vertex_groups[name].index
            for name in target_names
            if mesh_obj.vertex_groups.get(name)
        }
        for vertex_id in all_vertex_ids:
            assignments = [item for item in mesh_obj.data.vertices[vertex_id].groups if item.weight > 1e-6]
            total = sum(item.weight for item in assignments)
            zero += not assignments
            over_four += len(assignments) > 4
            bad_sum += bool(assignments) and abs(total - 1.0) > 1e-4
            missing_scope += not any(item.group in target_indices for item in assignments)
        context.view_layer.update()
        recalculation_report = (
            f"已按骨骼当前位置重算 {len(all_vertex_ids)} 顶点：零权重 {zero} / 超4骨 {over_four} / "
            f"未归一 {bad_sum} / 无目标骨 {missing_scope} / 清理孤儿组 {removed_orphan_groups}"
        )
        settings.wgame_secondary_weight_report = recalculation_report
        _clear_focus_marker()
        current = settings.wgame_secondary_weight_bone
        available = _secondary_edit_bone_names(settings, rig_obj)
        if current not in available and available:
            settings.wgame_secondary_weight_bone = available[0]
        result = bpy.ops.wgame_rigging.edit_secondary_weight()
        settings.wgame_secondary_weight_report = recalculation_report
        self.report(
            {"INFO" if zero == over_four == bad_sum == missing_scope == 0 else "WARNING"},
            recalculation_report + (f"；备份 {backup}" if backup else ""),
        )
        return result


def _current_weight_browser_bone(context, settings, rig_obj):
    names = _weight_browser_bones(settings, context)
    current = settings.wgame_weight_browser_bone
    if current not in names:
        current = names[0] if names else ""
        if current:
            try:
                settings.wgame_weight_browser_bone = current
            except TypeError:
                pass
    return current


def _current_custom_weight_chain(settings, rig_obj):
    payload = _custom_weight_chain_payload(rig_obj)
    chains = payload.get("chains", [])
    if not chains:
        return None
    index = min(max(int(settings.wgame_custom_chain_index), 0), len(chains) - 1)
    return chains[index]


def _best_weight_preview_mesh(context, settings, group_name):
    candidates = []
    participant_names = {
        component.get("object", "")
        for component in _unrigged_components(settings)
        if component.get("object")
    }
    meshes = [
        obj
        for obj in context.scene.objects
        if obj.type == "MESH"
        and (
            obj.name in participant_names
            or any(modifier.type == "ARMATURE" for modifier in obj.modifiers)
        )
    ]
    for mesh_obj in meshes:
        statistics = _weight_group_statistics(mesh_obj, group_name)
        if statistics:
            candidates.append((statistics["count"], mesh_obj.name, mesh_obj, statistics))
    if not candidates:
        return None, None
    _count, _name, mesh_obj, statistics = max(candidates, key=lambda item: (item[0], item[1]))
    return mesh_obj, statistics


class WGAME_RIGGING_OT_view_weight_browser_bone(Operator):
    bl_idname = "wgame_rigging.view_weight_browser_bone"
    bl_label = "查看当前骨骼热力图"
    bl_description = "进入标准 Weight Paint 热力图，显示当前骨骼对整个角色的真实影响范围"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
