class WGAME_RIGGING_OT_scan_all_weights(Operator):
    bl_idname = "wgame_rigging.scan_all_weights"
    bl_label = "检查全部骨骼权重"
    bl_description = "扫描全部变形骨与顶点，检查缺失组、空组、零权重、四权重上限和归一化"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = bpy.data.objects.get(settings.rig_name)
        mesh_obj = bpy.data.objects.get(settings.mesh_name)
        if not rig_obj or not mesh_obj:
            return {"CANCELLED"}
        deform_names = [bone.name for bone in rig_obj.data.bones if bone.use_deform]
        missing = [name for name in deform_names if not mesh_obj.vertex_groups.get(name)]
        empty = []
        for name in deform_names:
            group = mesh_obj.vertex_groups.get(name)
            if group and not any(
                assignment.group == group.index and assignment.weight > 1e-6
                for vertex in mesh_obj.data.vertices
                for assignment in vertex.groups
            ):
                empty.append(name)
        wgame_group_prefixes = (
            "cape.",
            "swing_",
            "pouch_",
            "quiver_",
            "thumb_",
            "index_",
            "middle_",
            "ring_",
            "pinky_",
            "eye.",
            "jaw.",
        )
        orphan = [
            group.name
            for group in mesh_obj.vertex_groups
            if group.name.startswith(wgame_group_prefixes)
            and not rig_obj.data.bones.get(group.name)
            and any(
                assignment.group == group.index and assignment.weight > 1e-6
                for vertex in mesh_obj.data.vertices
                for assignment in vertex.groups
            )
        ]
        zero = over_four = bad_sum = 0
        for vertex in mesh_obj.data.vertices:
            weights = [assignment.weight for assignment in vertex.groups if assignment.weight > 1e-6]
            zero += not weights
            over_four += len(weights) > 4
            bad_sum += bool(weights) and abs(sum(weights) - 1.0) > 1e-4
        settings.wgame_weight_browser_report = (
            f"{len(deform_names)} 骨：缺组 {len(missing)} / 空组 {len(empty)} / 孤儿组 {len(orphan)} / "
            f"零权重 {zero} / 超4骨 {over_four} / 未归一 {bad_sum}"
        )
        severity = (
            {"INFO"}
            if not missing and not empty and not orphan and zero == over_four == bad_sum == 0
            else {"WARNING"}
        )
        self.report(severity, settings.wgame_weight_browser_report)
        return {"FINISHED"}


class WGAME_RIGGING_OT_exit_weight_browser(Operator):
    bl_idname = "wgame_rigging.exit_weight_browser"
    bl_label = "退出权重浏览"
    bl_description = "退出 Weight Paint 并恢复选择 WGame 骨架；不会修改任何权重"
