_BONE_EDIT_RETURN = {}


def _bone_edit_return_key(context):
    return (context.scene.as_pointer(), context.view_layer.name)


def _capture_bone_edit_return(context, rig):
    active = context.object
    selected = list(context.selected_objects)
    settings = context.scene.wgame_rigging_assistant
    mesh_selection = {}
    for obj in selected:
        if obj.type == "MESH" and obj.mode == "EDIT":
            bm = bmesh.from_edit_mesh(obj.data)
            mesh_selection[obj.name] = [[(item.select, item.hide) for item in collection] for collection in (bm.verts, bm.edges, bm.faces)]
    return {
        "mesh_selection": mesh_selection, "mesh_select_mode": tuple(context.tool_settings.mesh_select_mode),
        "active": active, "selected": selected, "mode": active.mode if active else "OBJECT",
        "pose_objects": [obj for obj in selected if obj.mode == "POSE"],
        "vertex_group": active.vertex_groups.active.name if active and active.type == "MESH" and active.vertex_groups.active else None,
        "rig": rig, "rig_hidden": rig.hide_get(), "rig_hide_select": rig.hide_select,
        "active_bone": rig.data.bones.active.name if rig.data.bones.active else None,
        "selected_bones": [bone.name for bone in rig.pose.bones if bone.select],
        "bones": {bone.name: _bone_snapshot_entry(bone) for bone in rig.data.bones},
        "flags": {name: getattr(settings, name) for name in ("wgame_custom_bone_edit_active", "wgame_custom_weight_edit_active")},
    }


def _restore_bone_edit_return(context, state):
    if not state:
        return
    rig = state.get("rig")
    if rig:
        try:
            if "rig_hidden" in state:
                rig.hide_set(state["rig_hidden"])
            if "rig_hide_select" in state:
                rig.hide_select = state["rig_hide_select"]
        except Exception:
            pass

    active = state.get("active")
    if active is not None and context.view_layer.objects.get(active.name) != active:
        raise ValueError("原编辑对象已不在当前视图层，无法自动返回")

    if context.object and context.object.mode != "OBJECT":
        try:
            bpy.ops.object.mode_set(mode="OBJECT")
        except Exception:
            pass

    for obj in context.view_layer.objects:
        try:
            obj.select_set(False)
        except Exception:
            pass

    for obj in state.get("selected", []):
        if context.view_layer.objects.get(obj.name) == obj:
            try:
                obj.select_set(True)
            except Exception:
                pass

    for obj in state.get("pose_objects", []):
        if (
            context.view_layer.objects.get(obj.name) == obj
            and obj.type == "ARMATURE"
            and not obj.hide_get()
            and not getattr(obj, "hide_viewport", False)
        ):
            context.view_layer.objects.active = obj
            if context.active_object == obj and obj.mode != "POSE":
                try:
                    bpy.ops.object.mode_set(mode="POSE")
                except Exception:
                    pass

    if active and context.view_layer.objects.get(active.name) == active and not active.hide_get():
        context.view_layer.objects.active = active
        if context.active_object == active and active.mode != state.get("mode", "OBJECT"):
            try:
                bpy.ops.object.mode_set(mode=state["mode"])
            except Exception:
                pass

    if active and state.get("vertex_group"):
        group = active.vertex_groups.get(state["vertex_group"])
        if group:
            try:
                active.vertex_groups.active_index = group.index
            except Exception:
                pass

    if rig and getattr(rig, "pose", None):
        selected_bones = set(state.get("selected_bones", []))
        for bone in rig.pose.bones:
            bone.select = bone.name in selected_bones
        active_bone = state.get("active_bone")
        if active_bone and getattr(rig, "data", None):
            rig.data.bones.active = rig.data.bones.get(active_bone)

    settings = getattr(context.scene, "wgame_rigging_assistant", None)
    if settings:
        for name, value in state.get("flags", {}).items():
            if hasattr(settings, name):
                setattr(settings, name, value)

    if hasattr(context, "tool_settings") and "mesh_select_mode" in state:
        context.tool_settings.mesh_select_mode = state["mesh_select_mode"]
    for name, selections in state["mesh_selection"].items():
        obj = context.view_layer.objects.get(name)
        if obj and obj.mode == "EDIT":
            bm = bmesh.from_edit_mesh(obj.data)
            for collection, values in zip((bm.verts, bm.edges, bm.faces), selections):
                if len(collection) != len(values):
                    raise ValueError("原网格拓扑已变化，无法恢复原选择")
                for item, (selected, hidden) in zip(collection, values):
                    item.hide = hidden
            for collection, values in reversed(list(zip((bm.verts, bm.edges, bm.faces), selections))):
                for item, (selected, _hidden) in zip(collection, values):
                    item.select = selected
            bmesh.update_edit_mesh(obj.data, loop_triangles=False, destructive=False)


class WGAME_RIGGING_OT_toggle_bone_edit(Operator):
    bl_idname = "wgame_rigging.toggle_bone_edit"
    bl_label = "临时编辑骨骼 / 返回原编辑状态"
    bl_description = "记住当前对象、模式、选择和活动权重组；临时进入骨骼编辑，再次点击返回"
    bl_options = {"REGISTER"}

    @classmethod
    def poll(cls, context):
        return bool(_bone_edit_return_key(context) in _BONE_EDIT_RETURN or _wgame_rig_object(context))

    def execute(self, context):
        key = _bone_edit_return_key(context)
        settings = context.scene.wgame_rigging_assistant
        state = _BONE_EDIT_RETURN.get(key)
        if state:
            try:
                rig = state["rig"]
                if context.object and context.object.mode != "OBJECT":
                    bpy.ops.object.mode_set(mode="OBJECT")
                current = {bone.name: _bone_snapshot_entry(bone) for bone in rig.data.bones}
                base_changed = ({name: value for name, value in current.items() if _is_wgame_base_bone_name(name)}
                                != {name: value for name, value in state["bones"].items() if _is_wgame_base_bone_name(name)})
                changed = current != state["bones"]
                _restore_bone_edit_return(context, state)
                if base_changed:
                    settings.wgame_skeleton_accepted = False
                    rig["wgame_skeleton_accepted"] = False
                    _invalidate_binding_results(settings)
                elif changed:
                    settings.wgame_custom_binding_complete = False
                    settings.wgame_component_skin_complete = False
                    settings.wgame_custom_auto_weight_report = ""
            except (ReferenceError, RuntimeError, ValueError) as error:
                self.report({"ERROR"}, f"返回失败，已保留返回记录：{error}")
                return {"CANCELLED"}
            _BONE_EDIT_RETURN.pop(key, None)
            self.report({"INFO"}, "已返回原编辑状态" + ("；基础骨位已变化，需要重新验收" if base_changed else "；骨链有修改，生成权重前请刷新骨链" if changed else ""))
        else:
            rig = _wgame_rig_object(context)
            if context.mode == "EDIT_ARMATURE" and context.object == rig:
                self.report({"INFO"}, "当前已经是骨骼编辑模式；请从需要返回的模式启动临时编辑")
                return {"CANCELLED"}
            state = _capture_bone_edit_return(context, rig)
            try:
                rig.hide_select = False
                _select_only(context, rig)
                bpy.ops.object.mode_set(mode="EDIT")
            except RuntimeError as error:
                _restore_bone_edit_return(context, state)
                self.report({"ERROR"}, str(error))
                return {"CANCELLED"}
            _BONE_EDIT_RETURN[key] = state
            settings.wgame_custom_bone_edit_active = True
            settings.wgame_custom_weight_edit_active = False
            self.report({"INFO"}, "已进入临时骨骼编辑；修改完成后点击“返回原编辑状态”")
        _tag_view3d_redraw()
        return {"FINISHED"}


class WGAME_RIGGING_OT_add_detached_child(Operator):
    bl_idname = "wgame_rigging.add_detached_child"
    bl_label = "从当前骨创建分离子骨"
    bl_description = "以活动骨为父级创建不相连的附加 Deform 骨，选中新骨后按 G 移动"
    bl_options = {"REGISTER", "UNDO"}

    @classmethod
    def poll(cls, context):
        obj = context.object
        return bool(context.mode == "EDIT_ARMATURE" and obj
                    and obj == _wgame_rig_object(context)
                    and obj.data.edit_bones.active
                    and not obj.data.edit_bones.active.hide
                    and obj.data.edit_bones.active.select)

    def execute(self, context):
        rig = context.object
        bones = rig.data.edit_bones
        parent = bones.active
        if parent.length <= 1e-6:
            self.report({"ERROR"}, "当前父骨长度无效，请先修正")
            return {"CANCELLED"}
        length = parent.length * .5
        direction = (parent.tail - parent.head).normalized()
        offset = parent.matrix.to_3x3() @ Vector((length * .5, 0, 0))
        bone = bones.new("extra_" + parent.name)
        bone.head = parent.tail + offset
        bone.tail = bone.head + direction * length
        bone.roll = parent.roll
        bone.parent = parent
        bone.use_connect = False
        bone.use_deform = True
        # Keep it visible when the parent belongs to an isolated bone collection.
        for collection in parent.collections:
            collection.assign(bone)
        for item in bones:
            item.select = item.select_head = item.select_tail = False
        bone.select = bone.select_head = bone.select_tail = True
        bones.active = bone
        settings = context.scene.wgame_rigging_assistant
        settings.wgame_custom_binding_complete = False
        settings.wgame_component_skin_complete = False
        settings.wgame_custom_auto_weight_report = ""
        _tag_view3d_redraw()
        self.report({"INFO"}, f"已创建 {bone.name}，父级 {parent.name}；按 G 移动，F2 改名")
        return {"FINISHED"}


