class WGAME_RIGGING_OT_finish_custom_bones(Operator):
    bl_idname = "wgame_rigging.finish_custom_bones"
    bl_label = "完成自定义骨骼编辑"
    bl_description = "退出 Edit Mode 并确认基础骨骼未被改名、删除或改变 Rest Pose"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = _wgame_rig_object(context)
        if not rig_obj:
            return {"CANCELLED"}
        if getattr(context, "object", None) and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        settings.wgame_custom_bone_edit_active = False
        snapshot_ok, snapshot_message = _base_skeleton_snapshot_status(rig_obj)
        if not snapshot_ok:
            settings.wgame_skeleton_accepted = False
            rig_obj["wgame_skeleton_accepted"] = False
            _invalidate_binding_results(settings)
            self.report({"ERROR"}, snapshot_message + "；基础蒙皮已失效，请重新验收骨架并执行基础蒙皮")
            return {"CANCELLED"}
        custom_count = sum(
            1
            for bone in rig_obj.data.bones
            if bone.use_deform and bone.name not in _base_skeleton_snapshot(rig_obj)
        )
        breast_detection = _store_breast_bone_detection(rig_obj)
        settings.wgame_custom_binding_complete = False
        settings.wgame_component_skin_complete = False
        message = f"自定义骨骼编辑完成：当前 {custom_count} 根自定义Deform骨；基础骨架未变化"
        if breast_detection["valid"]:
            settings.wgame_breast_weight_report = "乳房骨骼编辑已完成；权重尚未复核，请生成/修复女性乳房权重或验收现有权重"
            message += "；" + breast_detection["report"] + "；请单独生成/修复乳房权重"
        elif breast_detection.get("present"):
            settings.wgame_breast_weight_report = breast_detection["report"]
            message += "；" + breast_detection["report"]
        chain_status = _custom_weight_chain_status(rig_obj)
        if chain_status["scanned"] and chain_status["stale"]:
            message += "；骨链结构已变化，请刷新自定义骨链后再生成初始权重"
        settings.wgame_custom_auto_weight_report = ""
        self.report({"INFO"}, message)
        return {"FINISHED"}


class WGAME_RIGGING_OT_refresh_custom_weight_chains(Operator):
    bl_idname = "wgame_rigging.refresh_custom_weight_chains"
    bl_label = "扫描/刷新自定义骨链"
    bl_description = "按自定义 Deform 骨父子关系刷新骨链，保留区域、锁定和参数；失联记录保留并提示处理"
    bl_options = {"REGISTER", "UNDO"}

    def invoke(self, context, event):
        return context.window_manager.invoke_confirm(self, event)

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = _wgame_rig_object(context)
        snapshot_ok, snapshot_message = _base_skeleton_snapshot_status(rig_obj)
        if not rig_obj or not snapshot_ok:
            self.report({"ERROR"}, snapshot_message if rig_obj else "没有找到 WGame 骨架")
            return {"CANCELLED"}
        if settings.wgame_custom_bone_edit_active or (getattr(context, "object", None) and context.object.mode == "EDIT"):
            self.report({"ERROR"}, "请先完成并退出自定义骨骼编辑")
            return {"CANCELLED"}
        payload = _discover_custom_weight_chains(context, settings, rig_obj)
        rename_plan = _canonical_custom_chain_plan(rig_obj, payload)
        backup = _save_backup_copy() if rename_plan else None
        if backup:
            settings.backup_filepath = backup
        payload, renamed = _canonicalize_custom_weight_chains(context, settings, rig_obj, payload)
        cloth_path = cloth_backup = ""
        if renamed:
            cloth_path, cloth_backup = _clear_character_cloth_for_skeleton_change(settings)
            _invalidate_binding_results(settings, invalidate_base=False)
        chains = payload.get("chains", [])
        enabled = sum(1 for chain in chains if chain.get("enabled", True))
        message = f"已记录 {len(chains)} 条自定义骨链，其中启用 {enabled} 条；规范重命名 {len(renamed)} 根"
        orphan_count = len(payload.get("orphaned_regions", []))
        if orphan_count:
            message += f"；{orphan_count} 条原骨链身份待恢复，区域记录与现有权重保留；恢复原骨链后刷新，当前禁止生成"
        if not chains:
            message += "；当前没有基础快照之外的 Deform 骨"
        if cloth_path:
            message += "；骨路径已变化，旧角色布料已清空"
        if backup:
            message += f"；备份 {backup}"
        if cloth_backup:
            message += f"；布料备份 {cloth_backup}"
        self.report({"INFO" if chains and not orphan_count else "WARNING"}, message)
        return {"FINISHED"}


def _focus_custom_chain_in_view(context, rig_obj, chain):
    bones = [
        rig_obj.data.bones.get(name)
        for name in chain.get("bones", [])
        if rig_obj.data.bones.get(name)
    ]
    if not bones:
        return False
    head_points = [rig_obj.matrix_world @ b.head_local for b in bones]
    tail_points = [rig_obj.matrix_world @ b.tail_local for b in bones]
    all_points = head_points + tail_points
    settings = getattr(context.scene, "wgame_rigging_assistant", None)
    ex_pts, sh_pts, _, _ = _custom_chain_active_vertices_data(context.scene, settings, rig_obj, chain) if settings else ((), (), (), ())
    if ex_pts:
        all_points.extend(ex_pts[::max(1, len(ex_pts) // 40)])
    if sh_pts:
        all_points.extend(sh_pts[::max(1, len(sh_pts) // 20)])
    center = sum(all_points, Vector((0.0, 0.0, 0.0))) / len(all_points)
    span = max((p - center).length for p in all_points) * 2.0
    character_size = max(float(rig_obj.dimensions.z), 1.0)
    focus_distance = max(span * 1.8, character_size * 0.18, 0.25)
    if rig_obj and context.mode == "POSE":
        for pb in rig_obj.pose.bones:
            pb.select = (pb.name in chain.get("bones", []))
        if bones:
            rig_obj.data.bones.active = bones[0]
    if context.screen:
        for area in context.screen.areas:
            if area.type != "VIEW_3D":
                continue
            try:
                r3d = area.spaces.active.region_3d
                r3d.view_location = center
                r3d.view_distance = focus_distance
                area.tag_redraw()
            except Exception:
                pass
    _tag_view3d_redraw()
    return True


class WGAME_RIGGING_OT_navigate_custom_weight_chain(Operator):
    bl_idname = "wgame_rigging.navigate_custom_weight_chain"
    bl_label = "切换自定义骨链"
    bl_options = {"REGISTER"}

    step: IntProperty(default=1)

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = _wgame_rig_object(context)
        payload = _custom_weight_chain_payload(rig_obj)
        chains = payload.get("chains", [])
        if not chains:
            self.report({"WARNING"}, "请先扫描自定义骨链")
            return {"CANCELLED"}
        settings.wgame_custom_chain_index = (
            int(settings.wgame_custom_chain_index) + int(self.step)
        ) % len(chains)
        _load_current_custom_chain_settings(settings, context, payload)
        chain = chains[settings.wgame_custom_chain_index]
        if rig_obj and context.mode == "POSE":
            for pb in rig_obj.pose.bones:
                pb.select = (pb.name in chain.get("bones", []))
            if chain.get("bones") and chain["bones"][0] in rig_obj.pose.bones:
                rig_obj.data.bones.active = rig_obj.data.bones[chain["bones"][0]]
        _tag_view3d_redraw()
        if settings.wgame_custom_chain_weight_preview_active:
            return bpy.ops.wgame_rigging.preview_custom_chain_weight(step=0)
        self.report({"INFO"}, f"当前骨链：{chain.get('root_bone', '')}")
        return {"FINISHED"}


class WGAME_RIGGING_OT_focus_custom_weight_chain(Operator):
    bl_idname = "wgame_rigging.focus_custom_weight_chain"
    bl_label = "在 3D 视图中定位骨链"
    bl_description = "将 3D 视图镜头平滑对准当前自定义骨链，并在姿态模式下选中对应骨骼"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = _wgame_rig_object(context)
        if not rig_obj:
            self.report({"ERROR"}, "没有找到 WGame 骨架")
            return {"CANCELLED"}
        chain = _current_custom_weight_chain(settings, rig_obj)
        if not chain:
            self.report({"ERROR"}, "当前没有可用的骨链")
