    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = next((obj for obj in context.scene.objects if obj.type == "ARMATURE" and obj.get("wgame_rig_kind") == "deform_skeleton"), None)
        slider_restored = False
