class WGAME_RIGGING_OT_accept_wgame_skeleton(Operator):
    bl_idname = "wgame_rigging.accept_wgame_skeleton"
    bl_label = "验收 WGame 基础骨架"
    bl_description = "确认基础骨架位置、方向和层级，可以进入蒙皮阶段"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = _wgame_rig_object(context)
        if not rig_obj:
            return {"CANCELLED"}
        if not settings.wgame_finger_rig_complete:
            self.report({"ERROR"}, "手指骨尚未完成，不能验收基础骨架")
            return {"CANCELLED"}
        if rig_obj.mode == "EDIT":
            _select_only(context, rig_obj)
            bpy.ops.object.mode_set(mode="OBJECT")
        if _reject_invalid_fingers(context, settings, rig_obj):
            self.report({"ERROR"}, settings.wgame_finger_detection_report)
            return {"CANCELLED"}
        snapshot = _capture_base_skeleton_snapshot(rig_obj)
        settings.wgame_skeleton_accepted = True
        rig_obj["wgame_skeleton_accepted"] = True
        _invalidate_binding_results(settings)
        self.report({"INFO"}, f"WGame 基础骨架已验收：记录 {len(snapshot)} 根基础骨；下一步执行基础蒙皮")
        return {"FINISHED"}


class WGAME_RIGGING_OT_upgrade_upper_chest(Operator):
    bl_idname = "wgame_rigging.upgrade_upper_chest"
    bl_label = "一键升级正式胸颈肩骨架"
    bl_description = "备份后创建 UpperChest，迁移 Neck/Shoulder 并更新 Humanoid 映射；骨架验收和蒙皮在后续步骤单独执行"
    bl_options = {"REGISTER", "UNDO"}

    def invoke(self, context, event):
        return context.window_manager.invoke_confirm(self, event)

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = _wgame_rig_object(context)
        if not rig_obj:
            self.report({"ERROR"}, "没有找到 WGame 基础骨架")
            return {"CANCELLED"}
        current_schema = str(rig_obj.get("wgame_schema_version", ""))
        if rig_obj.data.bones.get("upper_chest.x") and current_schema == "2.2":
            self.report({"INFO"}, "当前骨架已经是正确的胸颈肩 2.2 布局")
            return {"CANCELLED"}
        required = ("spine_02.x", "neck.x", "head.x", "shoulder.l", "shoulder.r")
        missing = [name for name in required if not rig_obj.data.bones.get(name)]
        if missing:
            self.report({"ERROR"}, "胸颈肩迁移缺少基础骨：" + ", ".join(missing))
            return {"CANCELLED"}
        backup = _save_backup_copy()
        if backup:
            settings.backup_filepath = backup
        if SLIDER_PREVIEW_BACKUP_KEY in rig_obj:
            _restore_slider_preview_base(rig_obj, clear=True)
        if POSE_BACKUP_KEY in rig_obj:
            _restore_pose_backup(rig_obj)
        settings.wgame_preview_active = False
        settings.wgame_preview_preset = ""
        if getattr(context, "object", None) and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        _select_only(context, rig_obj)
        bpy.ops.object.mode_set(mode="EDIT")
        edit_bones = rig_obj.data.edit_bones
        spine = edit_bones.get("spine_02.x")
        neck = edit_bones.get("neck.x")
        head = edit_bones.get("head.x")
        shoulder_left = edit_bones.get("shoulder.l")
        shoulder_right = edit_bones.get("shoulder.r")
        chest_center = spine.tail.copy()
        neck_root = neck.head.copy() if current_schema == "2.1" else neck.tail.copy()
        head_center = head.tail.copy()
        head_base = neck_root.lerp(head_center, 0.32)
        shoulder_center = (shoulder_left.tail + shoulder_right.tail) * 0.5
        if (
            (neck_root - chest_center).length < 0.01
            or (head_base - neck_root).length < 0.01
            or (head_center - head_base).length < 0.01
        ):
            bpy.ops.object.mode_set(mode="OBJECT")
            self.report({"ERROR"}, "现有 Chest、颈根与头部中心距离不足，无法安全迁移胸颈肩骨架")
            return {"CANCELLED"}
        upper_chest = edit_bones.get("upper_chest.x") or edit_bones.new("upper_chest.x")
        upper_chest.head = chest_center
        upper_chest.tail = neck_root
        upper_chest.parent = spine
        upper_chest.use_connect = False
        upper_chest.use_deform = True
        try:
            upper_chest.align_roll(Vector((0.0, 1.0, 0.0)))
        except ValueError:
            pass
        neck.head = neck_root
        neck.tail = head_base
        neck.parent = upper_chest
        neck.use_connect = False
        try:
            neck.align_roll(Vector((0.0, 1.0, 0.0)))
        except ValueError:
            pass
        head.head = head_base
        head.tail = head_center
        head.parent = neck
        head.use_connect = False
        try:
            head.align_roll(Vector((0.0, 1.0, 0.0)))
        except ValueError:
            pass
        for shoulder in (shoulder_left, shoulder_right):
            shoulder.head = shoulder_center.lerp(shoulder.tail, 0.35)
            shoulder.parent = upper_chest
            shoulder.use_connect = False
            try:
                shoulder.align_roll(Vector((0.0, 0.0, 1.0)))
            except ValueError:
                pass
        bpy.ops.object.mode_set(mode="OBJECT")
        deform_collection = rig_obj.data.collections.get("WGame Deform") or rig_obj.data.collections.new("WGame Deform")
        deform_collection.assign(rig_obj.data.bones["upper_chest.x"])
        mapping = _json_load(settings.wgame_humanoid_mapping_json, {})
        mapping["Chest"] = "spine_02.x"
        mapping["UpperChest"] = "upper_chest.x"
        mapping["Neck"] = "neck.x"
        mapping["LeftShoulder"] = "shoulder.l"
        mapping["RightShoulder"] = "shoulder.r"
        settings.wgame_humanoid_mapping_json = json.dumps(mapping, ensure_ascii=False, separators=(",", ":"))
        rig_obj["wgame_schema_version"] = "2.2"
        settings.wgame_skeleton_accepted = False
        rig_obj["wgame_skeleton_accepted"] = False
        _invalidate_binding_results(settings)
        _set_report(
            context,
            "UpperChest 骨架升级完成",
            [
                "Humanoid：Chest=spine_02.x / UpperChest=upper_chest.x",
                "本步骤没有生成或修改蒙皮权重",
                "下一步：检查胸、颈、头和肩部骨骼位置，然后单独验收基础骨架",
                *( ["迁移前备份：", backup] if backup else [] ),
            ],
        )
        self.report(
            {"INFO"},
            "UpperChest、Neck 和左右 Shoulder 迁移完成；请检查并单独验收基础骨架",
        )
        return {"FINISHED"}


class WGAME_RIGGING_OT_arp_create_reference(Operator):
    bl_idname = "wgame_rigging.arp_create_reference"
    bl_label = "创建 ARP Reference Bones"
    bl_description = "调用已验证的 Auto-Rig Pro append_arp 操作；创建后进入参考骨架拟合"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        existing_armatures = [obj for obj in context.scene.objects if obj.type == "ARMATURE"]
        if existing_armatures:
            self.report({"ERROR"}, "场景中已经存在 Armature，拒绝重复创建 Reference Bones")
            return {"CANCELLED"}
        if settings.versioned_sources and len((settings.character_id or "").strip()) != 6:
            self.report({"ERROR"}, "版本化模式必须先从编号池创建或选择六位数字角色")
            return {"CANCELLED"}
        if not _current_model_preflight(context, settings):
            settings.unrigged_preflight_passed = False
            self.report({"ERROR"}, "无骨骼模型预检未通过或模型已变化，请重新预检")
            return {"CANCELLED"}
        if not settings.unrigged_pose_locked:
            self.report({"ERROR"}, "请先确认并锁定绑定姿势")
            return {"CANCELLED"}
        if not _unrigged_components_complete(settings):
            self.report({"ERROR"}, "请先为全部连通组件分配绑定用途")
            return {"CANCELLED"}
        if not _joint_guides_complete(settings):
            self.report({"ERROR"}, "请先完成全部主要关节定位")
            return {"CANCELLED"}
        if not hasattr(bpy.ops, "arp") or not bpy.ops.arp.append_arp.poll():
            self.report({"ERROR"}, "Auto-Rig Pro append_arp 当前不可用")
            return {"CANCELLED"}
        meshes = [
            obj
            for obj in context.scene.objects
            if _is_formal_character_mesh(obj)
        ]
        mesh_obj = max(meshes, key=lambda item: len(item.data.vertices), default=None)
        if not mesh_obj:
            self.report({"ERROR"}, "没有找到角色主体 Mesh")
            return {"CANCELLED"}
        backup = _save_backup_copy()
        if backup:
            settings.backup_filepath = backup
        result = _call_arp_in_view3d(context, bpy.ops.arp.append_arp, rig_preset="human")
        rig_obj = next((obj for obj in context.scene.objects if obj.type == "ARMATURE"), None)
        if "FINISHED" not in result or not rig_obj:
            self.report({"ERROR"}, "ARP 未能创建有效 Reference Rig；可以打开创建前备份恢复")
            return {"CANCELLED"}
        scale_factor = _initialize_arp_reference_for_mesh(context, rig_obj, mesh_obj)
        _fit_arp_reference_from_joint_guides(context, settings, rig_obj)
        settings.rig_name = rig_obj.name
        _set_report(
            context,
            "Reference Bones 已创建",
            [
                f"主体：{mesh_obj.name}",
                f"骨架：{rig_obj.name}",
                f"初始比例：{scale_factor * 100.0:.1f}%",
                "已根据主要关节定位拟合骨盆、脊柱、头颈、四肢和脚部",
                "已隐藏 Main / Secondary 控制器与 Custom Shapes",
                "已进入 Reference Bones 编辑模式",
                *( ["创建前备份：", backup] if backup else [] ),
            ],
        )
        self.report({"INFO"}, f"Reference Bones 已创建并缩放至角色高度的 {scale_factor * 100.0:.1f}%")
        return result


class WGAME_RIGGING_OT_lock_bind_pose(Operator):
    bl_idname = "wgame_rigging.lock_bind_pose"
    bl_label = "锁定当前绑定姿势"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        if not _current_model_preflight(context, settings):
            self.report({"ERROR"}, "请先完成当前模型预检")
            return {"CANCELLED"}
        if not all((settings.unrigged_topology_reviewed, settings.unrigged_pose_reviewed,
                    settings.unrigged_hands_reviewed, settings.unrigged_regions_reviewed)):
            self.report({"ERROR"}, "请完成拓扑、姿势、双手与混合区域的人工确认")
            return {"CANCELLED"}
        report = _json_load(settings.unrigged_preflight_report, {})
        if report.get("warningCount", 0) and not settings.unrigged_review_notes.strip():
            self.report({"ERROR"}, "预检存在警告，请记录允许保留的原因或例外")
            return {"CANCELLED"}
        settings.unrigged_pose_locked = True
        self.report({"INFO"}, "已锁定 " + settings.unrigged_bind_pose + " 作为绑定基准")
        return {"FINISHED"}


class WGAME_RIGGING_OT_pick_weight_bone_in_view(Operator):
    bl_idname = "wgame_rigging.pick_weight_bone_in_view"
    bl_label = "3D 点选要绘制的骨骼"
    bl_description = "在 Weight Paint 中左键点击可见 Deform Bone，同步切换骨骼、顶点组和 WGame 定位标记"
    bl_options = {"REGISTER"}

    def _set_header(self, context, text):
        screen = getattr(context, "screen", None)
        if not screen:
            return
        for area in screen.areas:
            if area.type == "VIEW_3D":
                area.header_text_set(text)

    def _finish(self, context):
        self._set_header(context, None)
        if getattr(context, "window", None):
            try:
                context.window.cursor_modal_restore()
            except RuntimeError:
                pass

    def invoke(self, context, _event):
        settings = context.scene.wgame_rigging_assistant
        rig_obj = _wgame_rig_object(context)
        mesh_obj = context.scene.objects.get(settings.wgame_custom_mesh) if settings.wgame_custom_mesh else None
        if not settings.wgame_custom_weight_edit_active or not rig_obj or not mesh_obj or mesh_obj.mode != "WEIGHT_PAINT":
            self.report({"ERROR"}, "请先进入自定义权重绘制")
            return {"CANCELLED"}
        if rig_obj.mode != "POSE":
            self.report({"ERROR"}, "当前 Armature 未保持 Pose Mode；请退出后重新进入自定义权重绘制")
            return {"CANCELLED"}
        screen = getattr(context, "screen", None)
        if screen:
            for area in screen.areas:
                if area.type == "VIEW_3D":
                    area.spaces.active.overlay.show_bones = True
                    area.spaces.active.show_object_select_armature = True
        self._picked = False
        context.window_manager.modal_handler_add(self)
        if getattr(context, "window", None):
            context.window.cursor_modal_set("EYEDROPPER")
        self._set_header(context, "WGame 权重骨骼点选：左键点击骨骼 · 中键/滚轮浏览 · Esc/右键取消")
        self.report({"INFO"}, "请在 3D 视图中左键点击要绘制的骨骼")
        return {"RUNNING_MODAL"}

    def modal(self, context, event):
        if event.type in {"ESC", "RIGHTMOUSE"} and event.value == "PRESS":
            self._finish(context)
            return {"CANCELLED"}
        if event.type == "LEFTMOUSE" and event.value == "PRESS":
            area, region = _view3d_window_region_from_event(context, event)
            if not area or not region:
                return {"PASS_THROUGH"}
            mouse_region = (event.mouse_x - region.x, event.mouse_y - region.y)
            settings = context.scene.wgame_rigging_assistant
            rig_obj = _wgame_rig_object(context)
            mesh_obj = context.scene.objects.get(settings.wgame_custom_mesh) if settings.wgame_custom_mesh else None
            bone_name = _pick_weight_bone_from_view(rig_obj, area, region, mouse_region) if rig_obj else ""
            if not bone_name or not mesh_obj:
                self.report({"WARNING"}, "点击位置没有命中可见的 Deform Bone；请点粗橙线或骨骼主体附近")
                return {"RUNNING_MODAL"}
            if not _activate_custom_weight_bone(context, settings, rig_obj, mesh_obj, bone_name):
                self.report({"WARNING"}, f"无法激活骨骼：{bone_name}")
                return {"RUNNING_MODAL"}
            self._picked = True
            self.report({"INFO"}, f"当前权重骨骼已切换为 {bone_name}；活动顶点组已同步")
            return {"RUNNING_MODAL"}
        if event.type == "LEFTMOUSE" and event.value == "RELEASE" and self._picked:
            self._finish(context)
            return {"FINISHED"}
        if event.type in {"MIDDLEMOUSE", "WHEELUPMOUSE", "WHEELDOWNMOUSE", "TRACKPADPAN", "TRACKPADZOOM"}:
            return {"PASS_THROUGH"}
        return {"RUNNING_MODAL"}

    def cancel(self, context):
        self._finish(context)


class WGAME_RIGGING_OT_pick_base_region_in_view(Operator):
    bl_idname = "wgame_rigging.pick_base_region_in_view"
    bl_label = "3D 点选并标记基础组件语义"
    bl_description = "连续点击基础连通岛，锁定为当前选择的 Head/Neck/Shoulder/Arm/Leg/Center 语义"
    bl_options = {"REGISTER", "UNDO"}

    forced_region: StringProperty(default="", options={"HIDDEN"})

    def _set_header(self, context, text):
        screen = getattr(context, "screen", None)
        if screen:
            for area in screen.areas:
                if area.type == "VIEW_3D":
                    area.header_text_set(text)

    def _finish(self, context):
        self._set_header(context, None)
        if getattr(context, "window", None):
            try:
                context.window.cursor_modal_restore()
            except RuntimeError:
                pass

    def invoke(self, context, _event):
        settings = context.scene.wgame_rigging_assistant
        if not _unrigged_components(settings) or not _component_scan_is_current(context, settings):
            self.report({"ERROR"}, "请先完成有效的连通组件扫描")
            return {"CANCELLED"}
        context.window_manager.modal_handler_add(self)
        if getattr(context, "window", None):
            context.window.cursor_modal_set("EYEDROPPER")
        region = self.forced_region or settings.wgame_base_region_override
        self._target_region = region
        self._marked_count = 0
        self._set_header(context, f"WGame 基础组件语义：左键=写入 {region} 并选中 · 回车/Esc/右键=结束")
        self.report({"INFO"}, f"请在 3D 视图点击要标记为 {region} 的基础组件")
        return {"RUNNING_MODAL"}

    def modal(self, context, event):
        if event.type in {"ESC", "RIGHTMOUSE", "RET", "NUMPAD_ENTER"} and event.value == "PRESS":
            self._finish(context)
            return {"FINISHED" if self._marked_count else "CANCELLED"}
        if event.type == "LEFTMOUSE" and event.value == "PRESS":
            area, region = _view3d_window_region_from_event(context, event)
            if not area or not region:
                return {"PASS_THROUGH"}
            mouse_region = (event.mouse_x - region.x, event.mouse_y - region.y)
            settings = context.scene.wgame_rigging_assistant
            component_index = _raycast_unrigged_component(context, settings, area, region, mouse_region)
            if component_index is None:
                self.report({"WARNING"}, "点击位置没有命中可见的已扫描组件")
                return {"RUNNING_MODAL"}
            changed, message = _set_component_base_region_override(
                context,
                settings,
                component_index,
                self._target_region,
            )
            if changed:
                self._marked_count += 1
                self._set_header(
                    context,
                    f"✓ 组件 {component_index + 1} 已写入 {self._target_region} · "
                    f"本次 {self._marked_count} 个 · 继续左键或回车结束",
                )
            self.report({"INFO" if changed else "WARNING"}, f"组件 {component_index + 1}：{message}")
            return {"RUNNING_MODAL"}
        if event.type == "LEFTMOUSE" and event.value == "RELEASE":
            return {"RUNNING_MODAL"}
        if event.type in {"MIDDLEMOUSE", "WHEELUPMOUSE", "WHEELDOWNMOUSE", "TRACKPADPAN", "TRACKPADZOOM"}:
            return {"PASS_THROUGH"}
        return {"PASS_THROUGH"}

    def cancel(self, context):
        self._finish(context)


class WGAME_RIGGING_OT_clear_current_base_region(Operator):
    bl_idname = "wgame_rigging.clear_current_base_region"
    bl_label = "移除当前组件标记"
    bl_description = "删除当前基础组件持久化的 base_region，让它恢复自动语义推断"
    bl_options = {"REGISTER", "UNDO"}

