class WGAME_RIGGING_OT_clear_base_region_overrides(Operator):
    bl_idname = "wgame_rigging.clear_base_region_overrides"
    bl_label = "批量移除基础组件标记"
    bl_description = "不依赖视图射线，清除全部指定类型的基础区域覆盖；需要重新执行基础蒙皮才会更新权重"
    bl_options = {"REGISTER", "UNDO"}

    region: StringProperty(default="", options={"HIDDEN"})

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        target = self.region if self.region in BASE_REGION_KEYS else ""
        _ensure_base_region_mask_groups(context, settings)
        changed = 0
        for mesh_obj in _participant_meshes(context, settings):
            regions = (target,) if target else BASE_REGION_KEYS
            for region_name in regions:
                vertex_ids = _mesh_vertex_group_ids(mesh_obj, _base_region_group_name(region_name))
                changed += _set_vertex_group_mask_vertices(
                    mesh_obj,
                    _base_region_group_name(region_name),
                    vertex_ids,
                    False,
                )
        if not changed:
            self.report({"WARNING"}, "没有找到要移除的基础区域标记")
            return {"CANCELLED"}
        _invalidate_base_region_overlay_cache()
        _sync_component_base_region_cache(context, settings)
        _tag_view3d_redraw()
        self.report({"INFO"}, f"已移除 {changed} 个 {target or '全部'} 基础区域标记；请重新执行基础蒙皮")
        return {"FINISHED"}


def _build_vertex_brush_cache(mesh_obj, area, region):
    if not mesh_obj or mesh_obj.type != "MESH" or mesh_obj.mode != "EDIT":
        return None
    bm = bmesh.from_edit_mesh(mesh_obj.data)
    bm.verts.ensure_lookup_table()
    bm.faces.ensure_lookup_table()
    if not bm.faces:
        return None
    projected = []
    for vert in bm.verts:
        if vert.hide:
            continue
        world = mesh_obj.matrix_world @ vert.co
        screen = view3d_utils.location_3d_to_region_2d(region, area.spaces.active.region_3d, world)
        if screen is not None:
            projected.append((vert.index, screen))
    screen_tree = KDTree(len(projected))
    for vertex_id, screen in projected:
        screen_tree.insert((float(screen.x), float(screen.y), 0.0), vertex_id)
    screen_tree.balance()
    surface_faces = [face for face in bm.faces if not face.hide and all(not vert.hide for vert in face.verts)]
    if not surface_faces:
        return None
    return {
        "bmesh": bm,
        "surface": BVHTree.FromPolygons(
            [tuple(vert.co) for vert in bm.verts],
            [[vert.index for vert in face.verts] for face in surface_faces],
            all_triangles=False,
        ),
        "surface_faces": surface_faces,
        "screen": screen_tree,
        "screen_by_vertex": {vertex_id: Vector((screen.x, screen.y)) for vertex_id, screen in projected},
    }


def _visible_vertices_in_brush(mesh_obj, area, region, mouse_region, radius, cache=None):
    cache = cache or _build_vertex_brush_cache(mesh_obj, area, region)
    if not cache:
        return set()
    bm = cache["bmesh"]
    tree = cache["surface"]
    inverse = mesh_obj.matrix_world.inverted()
    direction_transform = inverse.to_3x3()
    mesh_diagonal = max(float(mesh_obj.dimensions.length), 1e-6)
    result = set()
    candidates = cache["screen"].find_range((float(mouse_region[0]), float(mouse_region[1]), 0.0), float(radius))
    for _screen, vertex_id, _distance in candidates:
        if vertex_id < 0 or vertex_id >= len(bm.verts):
            continue
        vert = bm.verts[vertex_id]
        screen = Vector((_screen.x, _screen.y))
        origin_world = view3d_utils.region_2d_to_origin_3d(region, area.spaces.active.region_3d, screen)
        direction_world = view3d_utils.region_2d_to_vector_3d(region, area.spaces.active.region_3d, screen).normalized()
        origin_local = inverse @ origin_world
        direction_local = (direction_transform @ direction_world).normalized()
        location, _normal, face_index, _distance = tree.ray_cast(origin_local, direction_local)
        if location is None or face_index is None or face_index < 0 or face_index >= len(cache["surface_faces"]):
            continue
        face = cache["surface_faces"][face_index]
        candidate_depth = (vert.co - origin_local).dot(direction_local)
        surface_depth = (location - origin_local).dot(direction_local)
        depth_gap = candidate_depth - surface_depth
        linked_lengths = [edge.calc_length() for edge in vert.link_edges]
        local_spacing = min(linked_lengths) if linked_lengths else mesh_diagonal * 0.001
        visibility_tolerance = max(
            mesh_diagonal * 5e-5,
            min(mesh_diagonal * 0.002, local_spacing * 0.15),
        )
        if vert in face.verts or depth_gap <= visibility_tolerance:
            result.add(vert.index)
    return result


def _prepare_component_trim_mask(context, settings, component):
    _ensure_custom_mask_groups(context, settings)
    mesh_obj = context.scene.objects.get(component.get("object", ""))
    allowed_ids = set(component.get("vertex_indices") or [])
    existing_ids = _mesh_vertex_group_ids(mesh_obj, CUSTOM_BIND_MASK_GROUP) & allowed_ids if mesh_obj else set()
    changed = 0
    if mesh_obj and allowed_ids and not existing_ids:
        changed = _set_custom_mask_vertices(mesh_obj, allowed_ids, True)
        _sync_component_scopes_from_mask(context, settings, finalized=False)
    return mesh_obj, allowed_ids, changed


def _capture_component_brush_visibility(context, settings):
    result = {}
    for mesh_obj in _participant_meshes(context, settings):
        if mesh_obj.mode == "EDIT":
            mesh_obj.update_from_editmode()
        result[mesh_obj.name] = {
            "object_hidden": bool(mesh_obj.hide_get()),
            "vertices": [bool(vertex.hide) for vertex in mesh_obj.data.vertices],
            "edges": [bool(edge.hide) for edge in mesh_obj.data.edges],
            "polygons": [bool(polygon.hide) for polygon in mesh_obj.data.polygons],
        }
    return result


def _apply_component_brush_isolation(context, settings, target_obj, allowed_vertex_ids, snapshot, isolated):
    if getattr(context, "object", None) and context.object.mode != "OBJECT":
        bpy.ops.object.mode_set(mode="OBJECT")
    allowed_ids = set(allowed_vertex_ids)
    for mesh_obj in _participant_meshes(context, settings):
        saved = snapshot.get(mesh_obj.name)
        if not saved:
            continue
        if isolated and mesh_obj != target_obj:
            mesh_obj.hide_set(True)
            continue
        mesh_obj.hide_set(False if isolated else saved["object_hidden"])
        for vertex in mesh_obj.data.vertices:
            saved_hidden = saved["vertices"][vertex.index] if vertex.index < len(saved["vertices"]) else False
            vertex.hide = bool(saved_hidden or (isolated and mesh_obj == target_obj and vertex.index not in allowed_ids))
            if vertex.hide:
                vertex.select = False
        for edge in mesh_obj.data.edges:
            saved_hidden = saved["edges"][edge.index] if edge.index < len(saved["edges"]) else False
            outside_target = isolated and mesh_obj == target_obj and any(index not in allowed_ids for index in edge.vertices)
            edge.hide = bool(saved_hidden or outside_target)
            if edge.hide:
                edge.select = False
        for polygon in mesh_obj.data.polygons:
            saved_hidden = saved["polygons"][polygon.index] if polygon.index < len(saved["polygons"]) else False
            outside_target = isolated and mesh_obj == target_obj and any(index not in allowed_ids for index in polygon.vertices)
            polygon.hide = bool(saved_hidden or outside_target)
            if polygon.hide:
                polygon.select = False
        mesh_obj.data.update()
    target_obj.hide_set(False)
    _select_only(context, target_obj)
    bpy.ops.object.mode_set(mode="EDIT")
    context.tool_settings.mesh_select_mode = (True, False, False)
    bpy.ops.mesh.select_all(action="DESELECT")
    _invalidate_base_region_overlay_cache()
    _tag_view3d_redraw()


def _connected_vertex_region(mesh_obj, seed_vertex_id, candidate_vertex_ids):
    candidate_ids = set(candidate_vertex_ids)
    if seed_vertex_id not in candidate_ids:
        return set()
    if mesh_obj.mode == "EDIT" and bpy.context.object == mesh_obj:
        bm = bmesh.from_edit_mesh(mesh_obj.data)
        bm.verts.ensure_lookup_table()

        def neighbors(vertex_id):
            return (edge.other_vert(bm.verts[vertex_id]).index for edge in bm.verts[vertex_id].link_edges)
    else:
        adjacency = [[] for _vertex in mesh_obj.data.vertices]
        for edge in mesh_obj.data.edges:
            left, right = edge.vertices
            adjacency[left].append(right)
            adjacency[right].append(left)

        def neighbors(vertex_id):
            return iter(adjacency[vertex_id])

    result = {seed_vertex_id}
    stack = [seed_vertex_id]
    while stack:
        current = stack.pop()
        for neighbor in neighbors(current):
            if neighbor in candidate_ids and neighbor not in result:
                result.add(neighbor)
                stack.append(neighbor)
    return result


def _connected_custom_mask_region(mesh_obj, seed_vertex_id, allowed_vertex_ids):
    custom_ids = _mesh_vertex_group_ids(mesh_obj, CUSTOM_BIND_MASK_GROUP) & set(allowed_vertex_ids)
    return _connected_vertex_region(mesh_obj, seed_vertex_id, custom_ids)


def _connected_excluded_mask_region(mesh_obj, seed_vertex_id, allowed_vertex_ids):
    allowed_ids = set(allowed_vertex_ids)
    custom_ids = _mesh_vertex_group_ids(mesh_obj, CUSTOM_BIND_MASK_GROUP) & allowed_ids
    return _connected_vertex_region(mesh_obj, seed_vertex_id, allowed_ids - custom_ids)


def _vertices_in_xray_box(mesh_obj, area, region, start, end, allowed_vertex_ids=None):
    """Project all non-hidden candidates; surface occlusion does not narrow the box."""
    if not mesh_obj or mesh_obj.type != "MESH" or mesh_obj.mode != "EDIT":
        return set()
    xmin, xmax = sorted((start[0], end[0]))
    ymin, ymax = sorted((start[1], end[1]))
    xmin, xmax = max(0, xmin), min(region.width, xmax)
    ymin, ymax = max(0, ymin), min(region.height, ymax)
    bm = bmesh.from_edit_mesh(mesh_obj.data)
    bm.verts.ensure_lookup_table()
    projection = area.spaces.active.region_3d.perspective_matrix @ mesh_obj.matrix_world
    result = set()
    for vert in bm.verts:
        if vert.hide or (allowed_vertex_ids is not None and vert.index not in allowed_vertex_ids):
            continue
        clip = projection @ vert.co.to_4d()
        if clip.w <= 0 or not -clip.w <= clip.z <= clip.w:
            continue
        x = (clip.x / clip.w + 1.0) * region.width * 0.5
        y = (clip.y / clip.w + 1.0) * region.height * 0.5
        if xmin <= x <= xmax and ymin <= y <= ymax:
            result.add(vert.index)
    return result


class WGAME_RIGGING_OT_brush_custom_vertices(Operator):
    bl_idname = "wgame_rigging.brush_custom_vertices"
    bl_label = "刷选自定义绑定顶点"
    bl_description = "左键刷入自定义绑定，Ctrl+左键擦除；圆刷只处理可见表面，B开启透视框选"
    bl_options = {"REGISTER", "UNDO"}

    radius: IntProperty(name="笔刷半径", default=32, min=4, max=256, options={"SKIP_SAVE"})
    trim_current_component: BoolProperty(
        name="修剪当前孤岛",
        description="当前孤岛尚未标记时先整岛加入，然后左键擦除、Ctrl+左键恢复；不会影响其它孤岛",
        default=False,
        options={"SKIP_SAVE"},
    )
    base_region: StringProperty(default="", options={"HIDDEN", "SKIP_SAVE"})

    def _is_base_region_brush(self):
        return self.base_region in BASE_REGION_KEYS

    def _active_mask_ids(self):
        cached = getattr(self, "_active_ids_cache", None)
        if cached is not None:
            return set(cached)
        group_name = _base_region_group_name(self.base_region) if self._is_base_region_brush() else CUSTOM_BIND_MASK_GROUP
        return _mesh_vertex_group_ids(self._mesh_obj, group_name)

    def _set_active_mask_vertices(self, vertex_ids, enabled):
        if self._is_base_region_brush():
            changed = _set_base_region_mask_vertices(
                self._mesh_obj,
                vertex_ids,
                self.base_region if enabled else "AUTO",
            )
        else:
            changed = _set_custom_mask_vertices(self._mesh_obj, vertex_ids, enabled)
        if getattr(self, "_active_ids_cache", None) is not None:
            if enabled:
                self._active_ids_cache.update(vertex_ids)
            else:
                self._active_ids_cache.difference_update(vertex_ids)
        return changed

    def _sync_mask_state(self, context):
        settings = context.scene.wgame_rigging_assistant
        if self._is_base_region_brush():
            _sync_component_base_region_cache(context, settings)
        else:
            _sync_component_scopes_from_mask(context, settings, finalized=False)

    def _set_header(self, text):
        if self._area:
            self._area.header_text_set(text)

    def _update_header(self):
        if getattr(self, "_box_mode", False):
            action = "减去 / Ctrl+拖框恢复" if self.trim_current_component else "加入 / Ctrl+拖框擦除"
            self._set_header(f"WGame 透视框选 · 左键拖框{action} · 穿透前后层（不含隐藏顶点） · Esc/右键取消框选")
            return
        custom_ids = self._active_mask_ids()
        if self.trim_current_component:
            count = len(custom_ids & self._allowed_vertex_ids)
            scope = f"当前孤岛 {count}/{len(self._allowed_vertex_ids)}"
            context_control = "H显示上下文" if self._context_isolated else "H仅显示当前组件"
            state_legend = f"彩色={self.base_region} / 蓝=AUTO" if self._is_base_region_brush() else "粉=自定义 / 蓝=已减去"
            controls = (
                f"{state_legend} / 左键减 / Ctrl+左键恢复 / "
                f"Shift+左键排粉岛 / Ctrl+Shift+左键恢复蓝岛 / {context_control}"
            )
        else:
            count = len(custom_ids)
            scope = f"自定义 {count} 顶点"
            controls = "左键刷入 / Ctrl+左键擦除"
        mode = "擦除" if self._erase else "加入"
        self._set_header(
            f"WGame {self.base_region + '语义修剪' if self._is_base_region_brush() else '孤岛修剪' if self.trim_current_component else '顶点刷选'} · {mode} · "
            f"半径 {self.radius}px · {scope} · {controls} / Ctrl+Z撤回 / Ctrl+Shift+Z重做 / "
            "B透视框选 / [ ]调半径 / 中键与滚轮浏览 / Enter、Esc或右键退出"
        )

    def _mask_snapshot(self):
        if self._is_base_region_brush():
            return tuple(
                (region, frozenset(_mesh_vertex_group_ids(self._mesh_obj, _base_region_group_name(region))))
                for region in BASE_REGION_KEYS
            )
        return frozenset(_mesh_vertex_group_ids(self._mesh_obj, CUSTOM_BIND_MASK_GROUP))

    def _record_history(self, before):
        after = self._mask_snapshot()
        if after == before:
            return False
        self._history.append(frozenset(before))
        self._redo_history.clear()
        return True

    def _restore_mask_snapshot(self, context, target):
        current = self._mask_snapshot()
        if self._is_base_region_brush():
            current_by_region = {region: set(vertex_ids) for region, vertex_ids in current}
            target_by_region = {region: set(vertex_ids) for region, vertex_ids in target}
            all_ids = set().union(*current_by_region.values(), *target_by_region.values())
            _set_base_region_mask_vertices(self._mesh_obj, all_ids, "AUTO")
            for region in BASE_REGION_KEYS:
                _set_base_region_mask_vertices(self._mesh_obj, target_by_region.get(region, set()), region)
            self._active_ids_cache = set(target_by_region.get(self.base_region, set()))
        else:
            current_ids = set(current)
            target_ids = set(target)
            _set_custom_mask_vertices(self._mesh_obj, current_ids - target_ids, False)
            _set_custom_mask_vertices(self._mesh_obj, target_ids - current_ids, True)
            self._active_ids_cache = set(target_ids)
        self._sync_mask_state(context)
        self._brush_cache = None
        self._update_header()
        _tag_view3d_redraw()

    def _undo_history(self, context):
        self._finish_stroke(context)
        if not self._history:
            self.report({"WARNING"}, "当前修剪会话没有可撤回的操作")
            return False
        current = self._mask_snapshot()
        target = self._history.pop()
        self._redo_history.append(current)
        self._restore_mask_snapshot(context, target)
        self.report({"INFO"}, "已撤回上一笔自定义范围修改")
        return True

    def _redo_history_action(self, context):
        self._finish_stroke(context)
        if not self._redo_history:
            self.report({"WARNING"}, "当前修剪会话没有可重做的操作")
            return False
        current = self._mask_snapshot()
        target = self._redo_history.pop()
        self._history.append(current)
        self._restore_mask_snapshot(context, target)
        self.report({"INFO"}, "已重做上一笔自定义范围修改")
        return True

    def _toggle_component_context(self, context):
        self._finish_stroke(context)
        self._context_isolated = not self._context_isolated
        _apply_component_brush_isolation(
            context,
            context.scene.wgame_rigging_assistant,
            self._mesh_obj,
            self._allowed_vertex_ids,
            self._visibility_snapshot,
            self._context_isolated,
        )
        self._brush_cache = None
        self._update_header()
        self.report(
            {"INFO"},
            "已仅显示当前修剪组件；其它模型不再参与遮挡"
            if self._context_isolated
            else "已恢复其它模型作为观察上下文；它们可能遮挡当前组件",
        )

    def _draw_mask(self, _context):
        if not self._region or not self._area or not self._mesh_obj:
            return
        shader = gpu.shader.from_builtin("UNIFORM_COLOR")
        custom_ids = self._active_mask_ids()
        bm = bmesh.from_edit_mesh(self._mesh_obj.data)
        bm.verts.ensure_lookup_table()

        def positions(vertex_ids):
            result = []
            for vertex_id in vertex_ids:
                if vertex_id < 0 or vertex_id >= len(bm.verts) or bm.verts[vertex_id].hide:
                    continue
                result.append(tuple(self._mesh_obj.matrix_world @ bm.verts[vertex_id].co))
            return result

        if self.trim_current_component:
            custom_ids &= self._allowed_vertex_ids
            removed_ids = self._allowed_vertex_ids - custom_ids
            custom_points = positions(custom_ids)
            removed_points = positions(removed_ids)
            outline_points = custom_points + removed_points
        else:
            custom_points = positions(custom_ids)
            removed_points = []
            outline_points = custom_points
        try:
            gpu.state.blend_set("ALPHA")
            gpu.state.depth_test_set("LESS_EQUAL")
            gpu.state.depth_mask_set(False)
            shader.bind()
            if outline_points:
                gpu.state.point_size_set(11.0)
                shader.uniform_float("color", (0.015, 0.02, 0.03, 0.92))
                batch_for_shader(shader, "POINTS", {"pos": outline_points}).draw(shader)
            if removed_points:
                gpu.state.point_size_set(7.0)
                shader.uniform_float("color", (0.12, 0.68, 1.0, 1.0))
                batch_for_shader(shader, "POINTS", {"pos": removed_points}).draw(shader)
            if custom_points:
                gpu.state.point_size_set(8.0)
                active_color = BASE_REGION_COLORS.get(self.base_region, (1.0, 0.08, 0.62, 1.0))
                shader.uniform_float("color", (*active_color[:3], 1.0))
                batch_for_shader(shader, "POINTS", {"pos": custom_points}).draw(shader)
        finally:
            gpu.state.point_size_set(1.0)
            gpu.state.depth_mask_set(True)
            gpu.state.depth_test_set("NONE")
            gpu.state.blend_set("NONE")

    def _draw_cursor(self, _context):
        if not self._region or not self._area:
            return
        shader = gpu.shader.from_builtin("UNIFORM_COLOR")
        circle = [
            (
                self._mouse[0] + math.cos(index * math.tau / 64.0) * self.radius,
                self._mouse[1] + math.sin(index * math.tau / 64.0) * self.radius,
            )
            for index in range(65)
        ]
        if getattr(self, "_box_mode", False):
            start = getattr(self, "_box_start", None)
            if start is None:
                return
            x, y = start
            ex, ey = self._mouse
            circle = [(x, y), (ex, y), (ex, ey), (x, ey), (x, y)]
        try:
            gpu.state.blend_set("ALPHA")
            batch = batch_for_shader(shader, "LINE_STRIP", {"pos": circle})
            shader.bind()
            shader.uniform_float("color", (1.0, 0.18, 0.12, 0.95) if self._erase else (0.15, 1.0, 0.45, 0.95))
            batch.draw(shader)
        finally:
            gpu.state.blend_set("NONE")

    def _sample(self, mouse_region):
        vertex_ids = _visible_vertices_in_brush(
            self._mesh_obj,
            self._area,
            self._region,
            mouse_region,
            self.radius,
            self._brush_cache,
        )
        if self.trim_current_component:
            vertex_ids &= self._allowed_vertex_ids
        return vertex_ids

    def _apply_box(self, context, start, end):
        allowed = self._allowed_vertex_ids if self.trim_current_component else None
        vertex_ids = _vertices_in_xray_box(self._mesh_obj, self._area, self._region, start, end, allowed)
        before = self._mask_snapshot()
        changed = self._set_active_mask_vertices(vertex_ids, not self._erase) if vertex_ids else 0
        if changed:
            self._sync_mask_state(context)
            self._record_history(before)
        self._brush_cache = None
        self.report({"INFO"}, f"透视框选已{'减去' if self._erase else '加入'} {changed} 个顶点")

    def _box_event(self, context, event):
        if event.type in {"ESC", "RIGHTMOUSE", "B"} and event.value == "PRESS":
            self._box_mode = False
            self._box_start = None
            self._update_header()
            _tag_view3d_redraw()
            return {"RUNNING_MODAL"}
        if event.type == "LEFTMOUSE" and event.value == "PRESS":
            if (self._region.x <= event.mouse_x < self._region.x + self._region.width
                    and self._region.y <= event.mouse_y < self._region.y + self._region.height):
                self._box_start = (event.mouse_x - self._region.x, event.mouse_y - self._region.y)
                self._mouse = self._box_start
                self._erase = not bool(event.ctrl) if self.trim_current_component else bool(event.ctrl)
        elif event.type == "MOUSEMOVE":
            self._mouse = (event.mouse_x - self._region.x, event.mouse_y - self._region.y)
        elif event.type == "LEFTMOUSE" and event.value == "RELEASE" and self._box_start is not None:
            self._mouse = (event.mouse_x - self._region.x, event.mouse_y - self._region.y)
            self._apply_box(context, self._box_start, self._mouse)
            self._box_start = None
            self._box_mode = False
            self._update_header()
        _tag_view3d_redraw()
        return {"RUNNING_MODAL"}

    def _sample_segment(self, mouse_region):
        current = Vector(mouse_region)
        previous = Vector(self._last_sample) if self._last_sample else current
        distance = (current - previous).length
        steps = max(1, int(math.ceil(distance / max(self.radius * 0.35, 1.0))))
        segment_ids = set()
        for step in range(1, steps + 1):
            point = previous.lerp(current, step / steps)
            segment_ids.update(self._sample((float(point.x), float(point.y))))
        if segment_ids:
            self._stroke_changed += self._set_active_mask_vertices(segment_ids, not self._erase)
        self._last_sample = tuple(mouse_region)

    def _exclude_custom_island_at_cursor(self, context, mouse_region):
        cache = self._brush_cache or _build_vertex_brush_cache(self._mesh_obj, self._area, self._region)
        if not cache:
            self.report({"WARNING"}, "当前视图没有可修剪的可见表面")
            return False
        visible_ids = _visible_vertices_in_brush(
            self._mesh_obj,
            self._area,
            self._region,
            mouse_region,
            14,
            cache,
        )
        custom_ids = self._active_mask_ids() & self._allowed_vertex_ids
        candidates = visible_ids & custom_ids
        if not candidates:
            self.report({"WARNING"}, "请把鼠标放在要排除的粉色顶点上")
            return False
        mouse = Vector(mouse_region)
        seed = min(
            candidates,
            key=lambda vertex_id: (cache["screen_by_vertex"][vertex_id] - mouse).length_squared,
        )
        island = _connected_vertex_region(self._mesh_obj, seed, custom_ids)
        before = self._mask_snapshot()
        changed = self._set_active_mask_vertices(island, False)
        if not changed:
            return False
        self._sync_mask_state(context)
        self._record_history(before)
        self._erase = True
        self._update_header()
        _tag_view3d_redraw()
        self.report({"INFO"}, f"已排除粉色子岛：{changed} 个顶点")
        return True

    def _restore_excluded_island_at_cursor(self, context, mouse_region):
        cache = self._brush_cache or _build_vertex_brush_cache(self._mesh_obj, self._area, self._region)
        if not cache:
            self.report({"WARNING"}, "当前视图没有可修剪的可见表面")
            return False
        visible_ids = _visible_vertices_in_brush(
            self._mesh_obj,
            self._area,
            self._region,
            mouse_region,
            14,
            cache,
        )
        custom_ids = self._active_mask_ids() & self._allowed_vertex_ids
        candidates = visible_ids & (self._allowed_vertex_ids - custom_ids)
        if not candidates:
            self.report({"WARNING"}, "请把鼠标放在要恢复的蓝色顶点上")
            return False
        mouse = Vector(mouse_region)
        seed = min(
            candidates,
            key=lambda vertex_id: (cache["screen_by_vertex"][vertex_id] - mouse).length_squared,
        )
        island = _connected_vertex_region(self._mesh_obj, seed, self._allowed_vertex_ids - custom_ids)
        before = self._mask_snapshot()
        changed = self._set_active_mask_vertices(island, True)
        if not changed:
            return False
        self._sync_mask_state(context)
        self._record_history(before)
        self._erase = False
        self._update_header()
        _tag_view3d_redraw()
        self.report({"INFO"}, f"已恢复蓝色子岛：{changed} 个顶点")
        return True

    def _finish_stroke(self, context):
        if not self._drawing:
            return
        self._drawing = False
        if self._stroke_changed:
            self._sync_mask_state(context)
            self._record_history(self._stroke_before)
            self.report({"INFO"}, f"本笔已{'擦除' if self._erase else '加入'} {self._stroke_changed} 个顶点")
        self._stroke_changed = 0
        self._last_sample = None
        self._brush_cache = None
        self._update_header()

    def _finish(self, context):
        self._finish_stroke(context)
        self._sync_mask_state(context)
        if self._mask_draw_handle is not None:
            bpy.types.SpaceView3D.draw_handler_remove(self._mask_draw_handle, "WINDOW")
            self._mask_draw_handle = None
        if self._cursor_draw_handle is not None:
            bpy.types.SpaceView3D.draw_handler_remove(self._cursor_draw_handle, "WINDOW")
            self._cursor_draw_handle = None
        if self.trim_current_component and self._visibility_snapshot is not None:
            _apply_component_brush_isolation(
                context,
                context.scene.wgame_rigging_assistant,
                self._mesh_obj,
                self._allowed_vertex_ids,
                self._visibility_snapshot,
                False,
            )
        if self._is_base_region_brush() and self._base_region_overlay_was_visible:
            context.scene.wgame_rigging_assistant.show_wgame_base_region_overlays = True
        self._set_header(None)
        if getattr(context, "window", None):
            try:
                context.window.cursor_modal_restore()
            except RuntimeError:
                pass
        _tag_component_scope_undo()
        _tag_view3d_redraw()

    def invoke(self, context, event):
        settings = context.scene.wgame_rigging_assistant
        components = _unrigged_components(settings)
        if not components or not _component_scan_is_current(context, settings):
            self.report({"ERROR"}, "请先完成有效的连通组件扫描")
            return {"CANCELLED"}
        if not self._is_base_region_brush() and any(item.get("binding_scope") in {"BASE_SKIN", "MIXED"} for item in components):
            self.report({"ERROR"}, "范围已经确认；请先点击“继续调整自定义选择”")
            return {"CANCELLED"}
        area, region = _view3d_window_region_from_event(context, event)
        if not area or not region:
            area = context.area if context.area and context.area.type == "VIEW_3D" else None
            region = next((item for item in area.regions if item.type == "WINDOW"), None) if area else None
        if not area or not region:
            self.report({"ERROR"}, "请从 3D 视图侧栏启动刷选")
            return {"CANCELLED"}
        index = min(settings.unrigged_component_index, len(components) - 1)
        mesh_obj = context.scene.objects.get(components[index].get("object", ""))
        if not mesh_obj or mesh_obj.type != "MESH":
            self.report({"ERROR"}, "当前组件没有可刷选的 Mesh")
            return {"CANCELLED"}
        if context.object and context.object.mode != "OBJECT":
            bpy.ops.object.mode_set(mode="OBJECT")
        if self._is_base_region_brush():
            _ensure_base_region_mask_groups(context, settings)
            base_ids = _component_vertex_ids_for_scope(context, settings, components[index], "BASE_SKIN")
            region_assignments = _base_region_assignments_by_object(context, settings).get(mesh_obj.name, {})
            allowed_ids = {
                vertex_id
                for vertex_id in base_ids
                if region_assignments.get(vertex_id) in {None, self.base_region}
            }
            if not allowed_ids:
                self.report({"ERROR"}, "当前组件没有可设置语义的基础蒙皮顶点")
                return {"CANCELLED"}
            initial_mask = tuple(
                (region_name, frozenset(_mesh_vertex_group_ids(mesh_obj, _base_region_group_name(region_name))))
                for region_name in BASE_REGION_KEYS
            )
            existing_ids = _mesh_vertex_group_ids(mesh_obj, _base_region_group_name(self.base_region)) & allowed_ids
            prepared = 0
            if not existing_ids:
                prepared = _set_base_region_mask_vertices(mesh_obj, allowed_ids, self.base_region)
                _sync_component_base_region_cache(context, settings)
            self.trim_current_component = True
        else:
            initial_mask = frozenset(_custom_mask_vertex_ids_by_object(context, settings).get(mesh_obj.name, set()))
        if not self._is_base_region_brush() and self.trim_current_component:
            mesh_obj, allowed_ids, prepared = _prepare_component_trim_mask(context, settings, components[index])
        elif not self._is_base_region_brush():
            _ensure_custom_mask_groups(context, settings)
            allowed_ids = set(components[index].get("vertex_indices") or [])
            prepared = 0
        visibility_snapshot = _capture_component_brush_visibility(context, settings) if self.trim_current_component else None
        self._mesh_obj = mesh_obj
        self._allowed_vertex_ids = allowed_ids
        self._visibility_snapshot = visibility_snapshot
        self._context_isolated = bool(self.trim_current_component)
        if self.trim_current_component:
            _apply_component_brush_isolation(context, settings, mesh_obj, allowed_ids, visibility_snapshot, True)
        else:
            _select_only(context, mesh_obj)
            bpy.ops.object.mode_set(mode="EDIT")
            context.tool_settings.mesh_select_mode = (True, False, False)
            bpy.ops.mesh.select_all(action="DESELECT")
        self._area = area
        self._region = region
        self._mouse = (event.mouse_x - region.x, event.mouse_y - region.y)
        self._last_sample = None
        self._drawing = False
        self._erase = bool(self.trim_current_component)
        self._stroke_changed = 0
        self._brush_cache = None
        self._history = []
        self._redo_history = []
        active_group_name = _base_region_group_name(self.base_region) if self._is_base_region_brush() else CUSTOM_BIND_MASK_GROUP
        self._active_ids_cache = set(_mesh_vertex_group_ids(mesh_obj, active_group_name))
        if prepared:
            self._record_history(initial_mask)
        self._base_region_overlay_was_visible = bool(
            self._is_base_region_brush() and settings.show_wgame_base_region_overlays
        )
        if self._base_region_overlay_was_visible:
            settings.show_wgame_base_region_overlays = False
        self._mask_draw_handle = None
        self._cursor_draw_handle = None
        self._mask_draw_handle = bpy.types.SpaceView3D.draw_handler_add(self._draw_mask, (context,), "WINDOW", "POST_VIEW")
        self._cursor_draw_handle = bpy.types.SpaceView3D.draw_handler_add(self._draw_cursor, (context,), "WINDOW", "POST_PIXEL")
        context.window_manager.modal_handler_add(self)
        if getattr(context, "window", None):
            context.window.cursor_modal_set("CROSSHAIR")
        self._update_header()
        self.report(
            {"INFO"},
            f"{self.base_region} 逐顶点语义修剪已开启；左键减去，Ctrl+左键恢复"
            if self._is_base_region_brush()
            else "当前孤岛修剪已开启；左键减去，Ctrl+左键恢复"
            if self.trim_current_component
            else "逐顶点刷选已开启；默认只处理当前视角可见表面",
        )
        return {"RUNNING_MODAL"}

    def modal(self, context, event):
        if getattr(self, "_box_mode", False):
            return self._box_event(context, event)
        if event.type == "B" and event.value == "PRESS":
            self._finish_stroke(context)
            self._box_mode = True
            self._box_start = None
            self._update_header()
            _tag_view3d_redraw()
            return {"RUNNING_MODAL"}
        if event.type in {"ESC", "RIGHTMOUSE", "RET", "NUMPAD_ENTER"} and event.value == "PRESS":
            self._finish(context)
            return {"FINISHED"}
        if event.type == "Z" and event.ctrl and event.value == "PRESS":
            if event.shift:
                self._redo_history_action(context)
            else:
                self._undo_history(context)
            return {"RUNNING_MODAL"}
        if event.type == "H" and event.value == "PRESS" and self.trim_current_component:
            self._toggle_component_context(context)
            return {"RUNNING_MODAL"}
        if event.type in {"LEFT_BRACKET", "RIGHT_BRACKET"} and event.value == "PRESS":
            self.radius = max(4, min(256, self.radius + (-4 if event.type == "LEFT_BRACKET" else 4)))
            self._update_header()
            _tag_view3d_redraw()
            return {"RUNNING_MODAL"}
        if event.type == "LEFTMOUSE" and event.value == "PRESS":
            if not (
                self._region.x <= event.mouse_x < self._region.x + self._region.width
                and self._region.y <= event.mouse_y < self._region.y + self._region.height
            ):
                return {"PASS_THROUGH"}
            self._mouse = (event.mouse_x - self._region.x, event.mouse_y - self._region.y)
            if self.trim_current_component and event.shift:
                if event.ctrl:
                    self._restore_excluded_island_at_cursor(context, self._mouse)
                else:
                    self._exclude_custom_island_at_cursor(context, self._mouse)
                return {"RUNNING_MODAL"}
            self._drawing = True
            self._erase = not bool(event.ctrl) if self.trim_current_component else bool(event.ctrl)
            self._stroke_changed = 0
            self._stroke_before = self._mask_snapshot()
            self._last_sample = None
            self._brush_cache = _build_vertex_brush_cache(self._mesh_obj, self._area, self._region)
            self._sample_segment(self._mouse)
            self._update_header()
            _tag_view3d_redraw()
            return {"RUNNING_MODAL"}
        if event.type == "MOUSEMOVE":
            self._mouse = (event.mouse_x - self._region.x, event.mouse_y - self._region.y)
            if self._drawing:
                self._sample_segment(self._mouse)
            else:
                self._erase = not bool(event.ctrl) if self.trim_current_component else bool(event.ctrl)
                self._update_header()
            _tag_view3d_redraw()
            return {"RUNNING_MODAL"}
        if event.type == "LEFTMOUSE" and event.value == "RELEASE":
            self._finish_stroke(context)
            return {"RUNNING_MODAL"}
        if event.type in {"MIDDLEMOUSE", "WHEELUPMOUSE", "WHEELDOWNMOUSE", "TRACKPADPAN", "TRACKPADZOOM"}:
            return {"PASS_THROUGH"}
        return {"RUNNING_MODAL"}

    def cancel(self, context):
        self._finish(context)



def _tag_component_scope_undo():
    """Include Scene settings and Object masks in Blender's Edit Mesh undo step.

    Blender 5.2 otherwise records only BMesh data, leaving the component JSON,
    index and visibility flag at their new values. Creating/removing an ID marks
    Main for the pre-memfile snapshot used by edit-mode undo. Scene.update_tag()
    alone does not do this. The temporary Text never survives the operation.
    """
    marker = bpy.data.texts.new(".wgame_component_scope_undo")
    bpy.data.texts.remove(marker)


@persistent
def _component_scope_undo_redo_post(_unused):
    # Python caches are outside Blender's saved undo state. Do not rewrite the
    # restored mask or Scene properties here; only discard derived display data.
    _invalidate_base_region_overlay_cache()
    _COMPONENT_SCOPE_COUNTS_CACHE.clear()
    _tag_view3d_redraw()


_COMPONENT_PICK_HISTORY_FIELDS = (
    "unrigged_components_json", "unrigged_component_index",
    "unrigged_custom_selection_hidden", "wgame_base_skin_complete",
    "wgame_base_skin_report", "wgame_manual_binding_ui_tab",
    "wgame_custom_binding_complete", "wgame_custom_binding_report",
    "wgame_custom_auto_weight_report", "wgame_component_skin_complete",
    "wgame_component_skin_report", "wgame_preview_active", "wgame_preview_preset",
)


def _capture_component_pick_state(context):
    settings = context.scene.wgame_rigging_assistant
    meshes = {}
    for obj in _participant_meshes(context, settings):
        collections = (obj.data.vertices, obj.data.edges, obj.data.polygons)
        if obj.mode == "EDIT":
            bm = bmesh.from_edit_mesh(obj.data)
            collections = (bm.verts, bm.edges, bm.faces)
        meshes[obj.name] = {
            "mask": frozenset(_mesh_vertex_group_ids(obj, CUSTOM_BIND_MASK_GROUP)),
            "has_group": obj.vertex_groups.get(CUSTOM_BIND_MASK_GROUP) is not None,
            "authority": obj.get(CUSTOM_BIND_MASK_AUTHORITY_KEY),
            "hidden": bool(obj.hide_get()),
            "elements": tuple(
                (len(items), frozenset(i for i, v in enumerate(items) if v.select),
                 frozenset(i for i, v in enumerate(items) if v.hide))
                for items in collections
            ),
        }
    return {
        "meshes": meshes,
        "fields": {name: getattr(settings, name) for name in _COMPONENT_PICK_HISTORY_FIELDS},
        "active": context.object.name if context.object else None,
        "selected": frozenset(obj.name for obj in context.selected_objects),
        "mode": context.object.mode if context.object else "OBJECT",
        "select_mode": tuple(context.tool_settings.mesh_select_mode),
    }


def _restore_component_pick_state(context, state):
    # The picker owns only scope, selection and visibility; topology is never
    # restored or replaced. Refuse stale indices if an outside action changed it.
    for name, saved in state["meshes"].items():
        obj = context.scene.objects.get(name)
        if not obj or obj.type != "MESH" or tuple(len(c) for c in
                (obj.data.vertices, obj.data.edges, obj.data.polygons)) != tuple(
                    entry[0] for entry in saved["elements"]):
            raise ValueError("组件拓扑已变化，请退出点选并重新扫描")
    if context.object and context.object.mode != "OBJECT":
        bpy.ops.object.mode_set(mode="OBJECT")
    for name, saved in state["meshes"].items():
        obj = context.scene.objects[name]
        group = obj.vertex_groups.get(CUSTOM_BIND_MASK_GROUP)
        if saved["has_group"]:
            current = _mesh_vertex_group_ids(obj, CUSTOM_BIND_MASK_GROUP)
            _set_custom_mask_vertices(obj, current - saved["mask"], False)
            _set_custom_mask_vertices(obj, saved["mask"] - current, True)
        elif group:
            obj.vertex_groups.remove(group)
        if saved["authority"] is None:
            if CUSTOM_BIND_MASK_AUTHORITY_KEY in obj:
                del obj[CUSTOM_BIND_MASK_AUTHORITY_KEY]
        else:
            obj[CUSTOM_BIND_MASK_AUTHORITY_KEY] = saved["authority"]
        obj.hide_set(saved["hidden"])
        for items, (_count, selected, hidden) in zip(
                (obj.data.vertices, obj.data.edges, obj.data.polygons), saved["elements"]):
            for i, item in enumerate(items):
                item.hide = i in hidden
                item.select = i in selected
        obj.data.update()
    settings = context.scene.wgame_rigging_assistant
    for name, value in state["fields"].items():
        setattr(settings, name, value)
    for obj in context.view_layer.objects:
        obj.select_set(obj.name in state["selected"])
    active = context.view_layer.objects.get(state["active"] or "")
    context.view_layer.objects.active = active
    if active and state["mode"] != "OBJECT":
        bpy.ops.object.mode_set(mode=state["mode"])
    context.tool_settings.mesh_select_mode = state["select_mode"]
    _component_scope_undo_redo_post(None)


class WGAME_RIGGING_OT_pick_component_in_view(Operator):
    bl_idname = "wgame_rigging.pick_component_in_view"
    bl_label = "开启 3D 点击选择"
    bl_description = "左键把连通组件设为自定义并高亮；Shift+左键切换整岛标记；H切换显示隐藏"
    bl_options = {"REGISTER", "UNDO"}

    def _record_history(self, before, context):
        if before != _capture_component_pick_state(context):
            self._history.append(before)
            self._redo_history.clear()

    def _history_action(self, context, redo=False):
        history = self._redo_history if redo else self._history
        if not history:
            self.report({"WARNING"}, "当前点选会话没有可重做的操作" if redo else "当前点选会话没有可撤回的操作")
            return
        current = _capture_component_pick_state(context)
        target = history[-1]
        try:
            _restore_component_pick_state(context, target)
        except ValueError as exc:
            self.report({"ERROR"}, str(exc))
            return
        history.pop()
        (self._history if redo else self._redo_history).append(current)
        self.report({"INFO"}, "已重做上一项组件点选" if redo else "已撤回上一项组件点选")

    def _set_header(self, context, text):
        screen = getattr(context, "screen", None)
        if not screen:
            return
        for area in screen.areas:
            if area.type == "VIEW_3D":
                area.header_text_set(text)

    def _finish(self, context):
        self._set_header(context, None)
        if getattr(context, "window", None):
            try:
                context.window.cursor_modal_restore()
            except RuntimeError:
                pass

    def invoke(self, context, _event):
        settings = context.scene.wgame_rigging_assistant
        if not _unrigged_components(settings) or not _component_scan_is_current(context, settings):
            self.report({"ERROR"}, "请先完成连通组件扫描")
            return {"CANCELLED"}
        if _component_has_legacy_binding_data(settings):
            self.report({"ERROR"}, "请先清空旧六类用途")
            return {"CANCELLED"}
        if any(item.get("binding_scope") in {"BASE_SKIN", "MIXED"} for item in _unrigged_components(settings)):
            self.report({"ERROR"}, "范围已经确认；请先点击“继续调整自定义选择”")
            return {"CANCELLED"}
        self._initial_state = _capture_component_pick_state(context)
        self._history = []
        self._redo_history = []
        context.window_manager.modal_handler_add(self)
        if getattr(context, "window", None):
            context.window.cursor_modal_set("EYEDROPPER")
        self._set_header(
            context,
            "WGame 点选：左键=整岛设为自定义 · Shift+左键=切换整岛标记 · H=隐藏/显示自定义 · "
            "Ctrl+Z撤回 · Ctrl+Shift+Z重做 · 中键/滚轮浏览 · Esc/右键/回车退出",
        )
        self.report({"INFO"}, "3D 点击选择已开启；左键会直接把命中孤岛设为自定义绑定")
        return {"RUNNING_MODAL"}

    def modal(self, context, event):
        if event.type in {"ESC", "RIGHTMOUSE", "RET", "NUMPAD_ENTER"} and event.value == "PRESS":
            changed = self._initial_state != _capture_component_pick_state(context)
            self._finish(context)
            if changed:
                _tag_component_scope_undo()
            return {"FINISHED" if changed else "CANCELLED"}
        if event.type == "Z" and event.ctrl:
            if event.value == "PRESS":
                self._history_action(context, redo=event.shift)
            return {"RUNNING_MODAL"}
        if event.type == "H" and event.value == "PRESS":
            before = _capture_component_pick_state(context)
            settings = context.scene.wgame_rigging_assistant
            hidden, count = _toggle_picker_custom_visibility(context, settings)
            self._record_history(before, context)
            self.report({"INFO"}, f"已{'隐藏' if hidden else '显示'} {count} 个自定义绑定顶点")
            self._set_header(
                context,
                f"WGame 点选 · 自定义顶点当前{'隐藏' if hidden else '显示'} · 左键=整岛设为自定义 · "
                "Shift+左键=切换整岛标记 · H=切换显示隐藏 · Esc/右键/回车退出",
            )
            return {"RUNNING_MODAL"}
        if event.type == "LEFTMOUSE" and event.value == "PRESS":
            area, region = _view3d_window_region_from_event(context, event)
            if not area or not region:
                return {"PASS_THROUGH"}
            mouse_region = (event.mouse_x - region.x, event.mouse_y - region.y)
            with context.temp_override(area=area, region=region, space_data=area.spaces.active):
                component_index = _raycast_unrigged_component(context, context.scene.wgame_rigging_assistant, area, region, mouse_region)
                if component_index is None:
                    self.report({"WARNING"}, "点击位置没有命中可见的已扫描组件")
                    return {"RUNNING_MODAL"}
                before = _capture_component_pick_state(context)
                settings = context.scene.wgame_rigging_assistant
                components = _unrigged_components(settings)
                settings.unrigged_component_index = component_index
                if event.shift:
                    changed, message = _toggle_custom_component_from_view(context, settings, component_index)
                    self.report({"INFO" if changed else "WARNING"}, f"组件 {component_index + 1}/{len(components)}：{message}")
                else:
                    component = components[component_index]
                    component_ids = set(component.get("vertex_indices") or [])
                    custom_ids = _custom_mask_vertex_ids_by_object(context, settings).get(component.get("object", ""), set())
                    if component_ids and not component_ids.issubset(custom_ids):
                        changed, message = _toggle_custom_component_from_view(context, settings, component_index)
                        self.report(
                            {"INFO" if changed else "WARNING"},
                            f"组件 {component_index + 1}/{len(components)}：{message}",
                        )
                    else:
                        _focus_unrigged_component(context, component)
                        self.report({"INFO"}, f"组件 {component_index + 1}/{len(components)} 已是整岛自定义绑定")
                self._record_history(before, context)
            return {"RUNNING_MODAL"}
        if event.type == "LEFTMOUSE" and event.value == "RELEASE":
            # Consume the matching release as well. Passing only the release
            # through can invoke Blender's native Shift-select after the WGame
            # picker has changed modes and visibility.
            return {"RUNNING_MODAL"}
        if event.type in {"MIDDLEMOUSE", "WHEELUPMOUSE", "WHEELDOWNMOUSE", "TRACKPADPAN", "TRACKPADZOOM"}:
            return {"PASS_THROUGH"}
        return {"PASS_THROUGH"}

    def cancel(self, context):
        self._finish(context)


class WGAME_RIGGING_OT_scan_components(Operator):
    bl_idname = "wgame_rigging.scan_components"
    bl_label = "扫描连通组件"
    bl_description = "扫描模型几何块；已有用途分配时会先确认并清空旧进度"
    bl_options = {"REGISTER"}

    def invoke(self, context, event):
        if _unrigged_components(context.scene.wgame_rigging_assistant):
            return context.window_manager.invoke_confirm(self, event)
        return self.execute(context)

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        if not any(obj.type == "ARMATURE" for obj in context.scene.objects):
            if not _current_model_preflight(context, settings) or not settings.unrigged_pose_locked:
                self.report({"ERROR"}, "请先完成当前正式模型预检与姿势/区域确认")
                return {"CANCELLED"}
        _set_marked_custom_hidden(context, settings, False)
        components = _scan_unrigged_components(context)
        settings.unrigged_components_json = json.dumps(components, ensure_ascii=False, separators=(",", ":"))
        settings.unrigged_component_index = 0
        settings.unrigged_binding_groups_json = "[]"
        settings.unrigged_active_binding_group_id = ""
        settings.unrigged_component_scan_fingerprint = _unrigged_topology_fingerprint(context)
        _invalidate_binding_results(settings)
        if components:
            _focus_unrigged_component(context, components[0])
        self.report({"INFO"}, f"已扫描 {len(components)} 个组件；当前组件已在 3D 视图中选中")
        return {"FINISHED"}


class WGAME_RIGGING_OT_repair_component_scan(Operator):
    bl_idname = "wgame_rigging.repair_component_scan"
    bl_label = "修复组件记录"
    bl_description = "模型增删顶点后重新扫描，并按空间位置迁移可可靠匹配的用途和绑定组"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        _set_marked_custom_hidden(context, settings, False)
        result = _rescan_unrigged_components_preserving_state(context, settings)
        if settings.unrigged_active_binding_group_id and not _binding_group(
            settings,
            settings.unrigged_active_binding_group_id,
        ):
            settings.unrigged_active_binding_group_id = ""
        settings.unrigged_preflight_passed = False
        settings.unrigged_pose_locked = False
        settings.unrigged_model_fingerprint = ""
        _invalidate_binding_results(settings)
        components = _unrigged_components(settings)
        if components:
            _focus_unrigged_component(context, components[settings.unrigged_component_index])
        _set_report(
            context,
            "组件记录已修复",
            [
                f"重新扫描：{result['old_count']} → {result['new_count']} 个组件",
                f"可靠匹配：{result['matched']}",
                f"迁移二分类：{result['migrated_scopes']}",
                "旧六类用途与单骨分组不会迁移。",
                f"待重新确认：{result['unmatched_new']}",
                "模型预检和绑定姿势锁定已失效，请重新执行第 2、3 步。",
            ],
        )
        self.report(
            {"WARNING" if result["unmatched_new"] else "INFO"},
            f"组件记录已修复：迁移 {result['migrated_scopes']} 项二分类，{result['unmatched_new']} 项待重新确认",
        )
        return {"FINISHED"}


class WGAME_RIGGING_OT_focus_component(Operator):
    bl_idname = "wgame_rigging.focus_component"
    bl_label = "定位当前组件"
    bl_description = "在编辑模式中选中当前连通组件，并保持当前 3D 视图不变"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        components = _unrigged_components(settings)
        if not components:
            self.report({"ERROR"}, "请先扫描连通组件")
            return {"CANCELLED"}
        if not _component_scan_is_current(context, settings):
            self.report({"ERROR"}, "模型顶点已变化，请先点击“修复组件记录”")
            return {"CANCELLED"}
        index = min(settings.unrigged_component_index, len(components) - 1)
        if not _focus_unrigged_component(context, components[index]):
            self.report({"ERROR"}, "组件顶点记录已失效，请重新扫描")
            return {"CANCELLED"}
        self.report({"INFO"}, f"已选中组件 {index + 1}/{len(components)}；3D 视图保持不变")
        _tag_component_scope_undo()
        return {"FINISHED"}


class WGAME_RIGGING_OT_navigate_component(Operator):
    bl_idname = "wgame_rigging.navigate_component"
    bl_label = "切换组件"
    bl_description = "查看上一个或下一个组件，不改变已有绑定用途"
    bl_options = {"REGISTER", "UNDO"}

    step: bpy.props.IntProperty(default=1, min=-1, max=1, options={"HIDDEN"})

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        components = _unrigged_components(settings)
        if not components:
            self.report({"ERROR"}, "请先扫描连通组件")
            return {"CANCELLED"}
        if not _component_scan_is_current(context, settings):
            self.report({"ERROR"}, "模型顶点已变化，请先点击“修复组件记录”")
            return {"CANCELLED"}
        candidate = settings.unrigged_component_index
        probe = candidate + self.step
        while 0 <= probe < len(components):
            if not (
                settings.unrigged_custom_selection_hidden
                and components[probe].get("binding_scope") == "CUSTOM_BIND"
            ):
                candidate = probe
                break
            probe += self.step
        settings.unrigged_component_index = candidate
        component = components[settings.unrigged_component_index]
        if not _focus_unrigged_component(context, component):
            self.report({"ERROR"}, "组件顶点记录已失效，请重新扫描")
            return {"CANCELLED"}
        _tag_component_scope_undo()
        return {"FINISHED"}


class WGAME_RIGGING_OT_reset_binding_scopes(Operator):
    bl_idname = "wgame_rigging.reset_binding_scopes"
    bl_label = "清空旧用途并重新分类"
    bl_description = "清除组件用途、范围蒙版和刚性附件记录；不会删除模型、骨骼、修改器或现有 Deform 权重"
    bl_options = {"REGISTER", "UNDO"}

    def invoke(self, context, event):
        return context.window_manager.invoke_confirm(self, event)

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        components = _unrigged_components(settings)
        if settings.wgame_rigid_isolation_active:
            _set_rigid_vertex_isolation(context, settings, False)
        _set_marked_custom_hidden(context, settings, False)
        _clear_custom_mask_groups(context, settings)
        _clear_base_region_mask_groups(context, settings)
        for mesh_obj in _participant_meshes(context, settings):
            rigid_ids = _mesh_vertex_group_ids(mesh_obj, RIGID_BIND_MASK_GROUP)
            if rigid_ids:
                _set_vertex_group_mask_vertices(mesh_obj, RIGID_BIND_MASK_GROUP, rigid_ids, False)
        rig_obj = _wgame_rig_object(context)
        if rig_obj and RIGID_BIND_ATTACHMENTS_KEY in rig_obj:
            del rig_obj[RIGID_BIND_ATTACHMENTS_KEY]
        for component in components:
            component.pop("role", None)
            component.pop("binding_group_id", None)
            component.pop("base_region", None)
            component["binding_scope"] = ""
        settings.unrigged_components_json = json.dumps(components, ensure_ascii=False, separators=(",", ":"))
        settings.unrigged_binding_groups_json = "[]"
        settings.unrigged_active_binding_group_id = ""
        settings.unrigged_component_index = 0
        settings.wgame_secondary_bones_complete = False
        settings.wgame_rigid_attachment_report = ""
        settings.wgame_rigid_previous_custom_isolation = False
        _invalidate_binding_results(settings)
        if components:
            _focus_unrigged_component(context, components[0])
        self.report({"INFO"}, f"已清空 {len(components)} 个组件的旧用途；模型、骨骼和权重未修改")
        _tag_component_scope_undo()
        return {"FINISHED"}


class WGAME_RIGGING_OT_hide_marked_custom(Operator):
    bl_idname = "wgame_rigging.hide_marked_custom"
    bl_label = "隐藏已标记的自定义内容"
    bl_description = "隐藏所有已经标记为自定义绑定的组件，便于继续检查剩余基础候选"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        count = _set_marked_custom_hidden(context, settings, True)
        components = _unrigged_components(settings)
        next_pending = _next_unready_component_index(settings, components)
        if next_pending is not None:
            settings.unrigged_component_index = next_pending
            _focus_unrigged_component(context, components[next_pending])
        self.report({"INFO"}, f"已隐藏 {count} 个自定义绑定顶点")
        _tag_component_scope_undo()
        return {"FINISHED"}


class WGAME_RIGGING_OT_show_marked_custom(Operator):
    bl_idname = "wgame_rigging.show_marked_custom"
    bl_label = "恢复显示自定义内容"
    bl_description = "重新显示分类阶段隐藏的自定义绑定组件；不会修改分类"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        count = _set_marked_custom_hidden(context, settings, False)
        components = _unrigged_components(settings)
        if components:
            index = min(settings.unrigged_component_index, len(components) - 1)
            _focus_unrigged_component(context, components[index])
        self.report({"INFO"}, f"已恢复显示 {count} 个自定义绑定顶点")
        _tag_component_scope_undo()
        return {"FINISHED"}


class WGAME_RIGGING_OT_finalize_binding_scopes(Operator):
    bl_idname = "wgame_rigging.finalize_binding_scopes"
    bl_label = "完成自定义选择，其余作为基础蒙皮"
    bl_description = "把所有未标记组件一次性归入基础蒙皮，并恢复显示全部组件"
    bl_options = {"REGISTER", "UNDO"}

    def invoke(self, context, event):
        return context.window_manager.invoke_confirm(self, event)

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        components = _unrigged_components(settings)
        if not components or not _component_scan_is_current(context, settings):
            self.report({"ERROR"}, "组件扫描已失效，请先重新扫描")
            return {"CANCELLED"}
        if _component_has_legacy_binding_data(settings):
            self.report({"ERROR"}, "请先清空旧六类用途")
            return {"CANCELLED"}
        _ensure_custom_mask_groups(context, settings)
        custom_by_object = _custom_mask_vertex_ids_by_object(context, settings)
        total_vertices = sum(len(component.get("vertex_indices") or []) for component in components)
        custom_vertices = sum(len(indices) for indices in custom_by_object.values())
        if total_vertices <= 0 or custom_vertices >= total_vertices:
            self.report({"ERROR"}, "不能把全部顶点都设为自定义绑定；至少保留一个基础蒙皮顶点")
            return {"CANCELLED"}
        _set_marked_custom_hidden(context, settings, False)
        components = _sync_component_scopes_from_mask(context, settings, finalized=True)
        first_base = next(
            (
                index
                for index, item in enumerate(components)
                if _component_vertex_ids_for_scope(context, settings, item, "BASE_SKIN")
            ),
            0,
        )
        settings.unrigged_component_index = first_base
        _focus_unrigged_component(context, components[first_base])
        mixed_count = sum(item.get("binding_scope") == "MIXED" for item in components)
        self.report(
            {"INFO"},
            f"范围已确认：自定义 {custom_vertices} 顶点；基础 {total_vertices - custom_vertices} 顶点；混合组件 {mixed_count}",
        )
        _tag_component_scope_undo()
        return {"FINISHED"}


class WGAME_RIGGING_OT_reopen_custom_selection(Operator):
    bl_idname = "wgame_rigging.reopen_custom_selection"
    bl_label = "继续调整自定义选择"
    bl_description = "保留已标记的自定义组件，把基础组件恢复为未标记候选"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        _set_marked_custom_hidden(context, settings, False)
        components = _sync_component_scopes_from_mask(context, settings, finalized=False)
        next_pending = _next_unready_component_index(settings, components)
        if next_pending is not None:
            settings.unrigged_component_index = next_pending
            _focus_unrigged_component(context, components[next_pending])
        self.report({"INFO"}, "已保留逐顶点自定义蒙版；其它顶点恢复为基础蒙皮候选")
        _tag_component_scope_undo()
        return {"FINISHED"}


class WGAME_RIGGING_OT_reclassify_component(Operator):
    bl_idname = "wgame_rigging.reclassify_component"
    bl_label = "修改当前分类"
    bl_description = "清除当前组件的基础/自定义分类并重新开放分类按钮"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        components = _unrigged_components(settings)
        if not components:
            return {"CANCELLED"}
        if not _component_scan_is_current(context, settings):
            self.report({"ERROR"}, "模型顶点已变化，请先点击“修复组件记录”")
            return {"CANCELLED"}
        index = min(settings.unrigged_component_index, len(components) - 1)
        if settings.unrigged_custom_selection_hidden:
            _set_component_vertices_hidden(context, components[index], False)
        _ensure_custom_mask_groups(context, settings)
        mesh_obj = context.scene.objects.get(components[index].get("object", ""))
        _set_custom_mask_vertices(mesh_obj, components[index].get("vertex_indices") or [], False)
        components = _sync_component_scopes_from_mask(context, settings, finalized=False)
        components[index].pop("role", None)
        components[index].pop("binding_group_id", None)
        settings.unrigged_components_json = json.dumps(components, ensure_ascii=False, separators=(",", ":"))
        _focus_unrigged_component(context, components[index])
        self.report({"INFO"}, f"组件 {index + 1} 已全部移出自定义绑定并恢复为待确认")
        _tag_component_scope_undo()
        return {"FINISHED"}


