class WGAME_RIGGING_OT_create_binding_group(Operator):
    bl_idname = "wgame_rigging.create_binding_group"
    bl_label = "新建单骨绑定组"
    bl_description = "创建一个共享目标骨骼的绑定组，并收集当前选中的所有连通组件"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        components = _unrigged_components(settings)
        if not _component_scan_is_current(context, settings):
            self.report({"ERROR"}, "模型顶点已变化，请先点击“修复组件记录”")
            return {"CANCELLED"}
        _sync_attachment_generated_fields(settings)
        name = (settings.unrigged_binding_group_name or "").strip()
        target_bone = (settings.unrigged_binding_target_bone or "").strip()
        parent_bone = (settings.unrigged_binding_parent_bone or "").strip()
        if not name or not target_bone:
            self.report({"ERROR"}, "绑定组名称和目标骨骼不能为空")
            return {"CANCELLED"}
        groups = _unrigged_binding_groups(settings)
        used_ids = {item.get("id") for item in groups}
        number = 1
        while f"single_bone.{number:03d}" in used_ids:
            number += 1
        group_id = f"single_bone.{number:03d}"
        groups.append(
            {
                "id": group_id,
                "name": name,
                "target_bone": target_bone,
                "parent_bone": parent_bone,
                "attachment_type": settings.unrigged_attachment_type,
                "custom_key": _sanitize_attachment_key(settings.unrigged_attachment_custom_key),
                "side": settings.unrigged_attachment_side,
                "index": settings.unrigged_attachment_index,
                "parent_anchor": settings.unrigged_attachment_parent_anchor,
                "component_ids": [],
                "status": "ACTIVE",
            }
        )
        _save_unrigged_binding_groups(settings, groups)
        settings.unrigged_active_binding_group_id = group_id
        settings.unrigged_group_create_mode = False
        selected_ids = _selected_unrigged_component_ids(context, components)
        if not selected_ids and components:
            index = min(settings.unrigged_component_index, len(components) - 1)
            selected_ids = [components[index].get("id")]
        count = _assign_components_to_binding_group(context, settings, group_id, selected_ids)
        self.report({"INFO"}, f"已创建“{name}”，收集 {count} 个组件；继续选择零件后点击“收集当前选择”")
        return {"FINISHED"}


class WGAME_RIGGING_OT_activate_binding_group(Operator):
    bl_idname = "wgame_rigging.activate_binding_group"
    bl_label = "编辑单骨绑定组"
    bl_description = "打开已有绑定组，以便继续追加、移出或修改目标骨骼"
    bl_options = {"REGISTER"}

    group_id: StringProperty(options={"HIDDEN"})

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        if not _component_scan_is_current(context, settings):
            self.report({"ERROR"}, "模型顶点已变化，请先点击“修复组件记录”")
            return {"CANCELLED"}
        group = _binding_group(settings, self.group_id)
        if not group:
            return {"CANCELLED"}
        settings.unrigged_active_binding_group_id = self.group_id
        settings.unrigged_group_create_mode = False
        settings.unrigged_binding_group_name = group.get("name", "")
        _load_attachment_group_fields(settings, group)
        components = _unrigged_components(settings)
        first_component_id = next(iter(group.get("component_ids", [])), "")
        first_index = next((index for index, item in enumerate(components) if item.get("id") == first_component_id), None)
        if first_index is not None:
            settings.unrigged_component_index = first_index
        groups = _unrigged_binding_groups(settings)
        for item in groups:
            item["status"] = "ACTIVE" if item.get("id") == self.group_id else item.get("status", "COMPLETE")
        _save_unrigged_binding_groups(settings, groups)
        _focus_unrigged_component_ids(context, components, group.get("component_ids", []))
        return {"FINISHED"}


