class WGAME_RIGGING_OT_collect_binding_group(Operator):
    bl_idname = "wgame_rigging.collect_binding_group"
    bl_label = "收集当前选择"
    bl_description = "把 Edit Mode 中当前选中的所有连通组件加入活动单骨绑定组"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
