class WGAME_RIGGING_OT_remove_from_binding_group(Operator):
    bl_idname = "wgame_rigging.remove_from_binding_group"
    bl_label = "移出当前组件"
    bl_description = "把列表中的当前组件移出单骨绑定组，并恢复为待分配用途"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        components = _unrigged_components(settings)
        if not components:
            return {"CANCELLED"}
        index = min(settings.unrigged_component_index, len(components) - 1)
        component = components[index]
        group_id = component.get("binding_group_id", "")
        if not group_id:
            self.report({"WARNING"}, "当前组件不属于任何单骨绑定组")
            return {"CANCELLED"}
        _remove_components_from_binding_groups(settings, [component.get("id")])
        component["role"] = "RIGID"
        component.pop("binding_group_id", None)
        settings.unrigged_components_json = json.dumps(components, ensure_ascii=False, separators=(",", ":"))
        if not _binding_group(settings, group_id):
            settings.unrigged_active_binding_group_id = ""
        _focus_unrigged_component(context, component)
        self.report({"INFO"}, f"组件 {index + 1} 已移出绑定组")
        return {"FINISHED"}


class WGAME_RIGGING_OT_finish_binding_group(Operator):
    bl_idname = "wgame_rigging.finish_binding_group"
    bl_label = "完成单骨绑定组"
    bl_description = "保存组名和目标骨骼，锁定当前组并进入下一个待处理组件"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        group_id = settings.unrigged_active_binding_group_id
        groups = _unrigged_binding_groups(settings)
        group = next((item for item in groups if item.get("id") == group_id), None)
        if not group or not group.get("component_ids"):
            self.report({"ERROR"}, "当前绑定组还没有组件")
            return {"CANCELLED"}
        _sync_attachment_generated_fields(settings)
        name = (settings.unrigged_binding_group_name or "").strip()
        target_bone = (settings.unrigged_binding_target_bone or "").strip()
        if not name or not target_bone:
            self.report({"ERROR"}, "绑定组名称和目标骨骼不能为空")
            return {"CANCELLED"}
        group["name"] = name
        group["target_bone"] = target_bone
        group["parent_bone"] = (settings.unrigged_binding_parent_bone or "").strip()
        group["attachment_type"] = settings.unrigged_attachment_type
        group["custom_key"] = _sanitize_attachment_key(settings.unrigged_attachment_custom_key)
        group["side"] = settings.unrigged_attachment_side
        group["index"] = settings.unrigged_attachment_index
        group["parent_anchor"] = settings.unrigged_attachment_parent_anchor
        group["status"] = "COMPLETE"
        _save_unrigged_binding_groups(settings, groups)
        settings.unrigged_active_binding_group_id = ""
        settings.unrigged_group_create_mode = False
        components = _unrigged_components(settings)
        next_group = _next_ungrouped_single_bone_index(settings, components)
        if next_group is not None:
            settings.unrigged_component_index = next_group
            _focus_unrigged_component(context, components[next_group])
        else:
            if _unrigged_single_bone_groups_complete(settings):
                _set_rigid_component_isolation(context, settings, False)
            obj = context.scene.objects.get(components[0].get("object", "")) if components else None
            if obj:
                _select_only(context, obj)
        self.report({"INFO"}, f"已完成“{name}”：{len(group['component_ids'])} 个组件 → {target_bone}")
        return {"FINISHED"}


class WGAME_RIGGING_OT_confirm_active_binding_group(Operator):
    bl_idname = "wgame_rigging.confirm_active_binding_group"
    bl_label = "确认并完成当前组"
    bl_description = "保持绑定组已保存的名称和目标骨不变，直接确认完成并进入下一个批量建议"
    bl_options = {"REGISTER", "UNDO"}

    group_id: StringProperty(options={"HIDDEN"})

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        target_group_id = self.group_id or settings.unrigged_active_binding_group_id
        groups = _unrigged_binding_groups(settings)
        group = next(
            (item for item in groups if item.get("id") == target_group_id),
            None,
        )
        if not group or not group.get("component_ids"):
            self.report({"ERROR"}, "没有可确认的活动绑定组")
            return {"CANCELLED"}
        group["status"] = "COMPLETE"
        _save_unrigged_binding_groups(settings, groups)
        if settings.unrigged_active_binding_group_id == target_group_id:
            settings.unrigged_active_binding_group_id = ""
        settings.unrigged_group_create_mode = False
        suggestions = _rigid_group_suggestions(settings)
        settings.unrigged_rigid_suggestion_index = 0
        if suggestions:
            bpy.ops.wgame_rigging.focus_rigid_suggestion()
        elif _unrigged_single_bone_groups_complete(settings):
            _set_rigid_component_isolation(context, settings, False)
        self.report(
            {"INFO"},
            f"已确认“{group.get('name', '')}”：{len(group.get('component_ids', []))} 个组件 → {group.get('target_bone', '')}",
        )
        return {"FINISHED"}


class WGAME_RIGGING_OT_focus_rigid_suggestion(Operator):
    bl_idname = "wgame_rigging.focus_rigid_suggestion"
    bl_label = "定位批量建议"
    bl_description = "在 3D 视图中一次高亮当前空间聚类建议中的全部单骨组件"
    bl_options = {"REGISTER"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        suggestions = _rigid_group_suggestions(settings)
        if not suggestions:
            return {"CANCELLED"}
        index = min(settings.unrigged_rigid_suggestion_index, len(suggestions) - 1)
        settings.unrigged_rigid_suggestion_index = index
        suggestion = suggestions[index]
        center_x = float((suggestion.get("center") or [0.0])[0])
        settings.unrigged_attachment_side = "X" if abs(center_x) <= 0.02 else "L" if center_x > 0.0 else "R"
        _sync_attachment_generated_fields(settings)
        _focus_unrigged_component_ids(context, _unrigged_components(settings), suggestion["component_ids"])
        self.report({"INFO"}, f"已定位建议组 {index + 1}/{len(suggestions)}：{len(suggestion['component_ids'])} 个组件")
        return {"FINISHED"}


class WGAME_RIGGING_OT_navigate_rigid_suggestion(Operator):
    bl_idname = "wgame_rigging.navigate_rigid_suggestion"
    bl_label = "切换批量建议"
    bl_description = "查看上一个或下一个空间聚类建议"
    bl_options = {"REGISTER"}

    step: bpy.props.IntProperty(default=1, min=-1, max=1, options={"HIDDEN"})

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        suggestions = _rigid_group_suggestions(settings)
        if not suggestions:
            return {"CANCELLED"}
        settings.unrigged_rigid_suggestion_index = max(
            0,
            min(len(suggestions) - 1, settings.unrigged_rigid_suggestion_index + self.step),
        )
        return bpy.ops.wgame_rigging.focus_rigid_suggestion()


class WGAME_RIGGING_OT_accept_rigid_suggestion(Operator):
    bl_idname = "wgame_rigging.accept_rigid_suggestion"
    bl_label = "接受建议并完成分组"
    bl_description = "把当前建议中的全部组件一次加入新组并直接标记完成"
    bl_options = {"REGISTER", "UNDO"}

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        if settings.unrigged_active_binding_group_id:
            self.report({"ERROR"}, "请先完成正在编辑的单骨绑定组")
            return {"CANCELLED"}
        suggestions = _rigid_group_suggestions(settings)
        if not suggestions:
            return {"CANCELLED"}
        index = min(settings.unrigged_rigid_suggestion_index, len(suggestions) - 1)
        suggestion = suggestions[index]
        _sync_attachment_generated_fields(settings)
        name = (settings.unrigged_binding_group_name or "").strip()
        target_bone = (settings.unrigged_binding_target_bone or "").strip()
        if not name or not target_bone:
            self.report({"ERROR"}, "绑定组名称和自动骨骼名不能为空")
            return {"CANCELLED"}
        groups = _unrigged_binding_groups(settings)
        if any(item.get("target_bone") == target_bone for item in groups):
            self.report({"ERROR"}, f"目标骨骼 {target_bone} 已被其它绑定组使用")
            return {"CANCELLED"}
        used_ids = {item.get("id") for item in groups}
        number = 1
        while f"single_bone.{number:03d}" in used_ids:
            number += 1
        group_id = f"single_bone.{number:03d}"
        groups.append(
            {
                "id": group_id,
                "name": name,
                "target_bone": target_bone,
                "parent_bone": settings.unrigged_binding_parent_bone,
                "attachment_type": settings.unrigged_attachment_type,
                "custom_key": _sanitize_attachment_key(settings.unrigged_attachment_custom_key),
                "side": settings.unrigged_attachment_side,
                "index": settings.unrigged_attachment_index,
                "parent_anchor": settings.unrigged_attachment_parent_anchor,
                "component_ids": [],
                "status": "COMPLETE",
            }
        )
        _save_unrigged_binding_groups(settings, groups)
        assigned = _assign_components_to_binding_group(
            context,
            settings,
            group_id,
            suggestion["component_ids"],
        )
        remaining = _rigid_group_suggestions(settings)
        settings.unrigged_rigid_suggestion_index = 0
        if remaining:
            bpy.ops.wgame_rigging.focus_rigid_suggestion()
        else:
            if _unrigged_single_bone_groups_complete(settings):
                _set_rigid_component_isolation(context, settings, False)
            components = _unrigged_components(settings)
            obj = context.scene.objects.get(components[0].get("object", "")) if components else None
            if obj:
                _select_only(context, obj)
        self.report({"INFO"}, f"已批量完成“{name}”：{assigned} 个组件 / {suggestion['vertices']} 顶点")
        return {"FINISHED"}


class WGAME_RIGGING_OT_classify_component(Operator):
    bl_idname = "wgame_rigging.classify_component"
    bl_label = "设置当前组件绑定范围"
    bl_options = {"REGISTER", "UNDO"}

    scope: EnumProperty(
        items=(
            ("BASE_SKIN", COMPONENT_BINDING_SCOPE_LABELS["BASE_SKIN"], COMPONENT_BINDING_SCOPE_TOOLTIPS["BASE_SKIN"]),
            ("CUSTOM_BIND", COMPONENT_BINDING_SCOPE_LABELS["CUSTOM_BIND"], COMPONENT_BINDING_SCOPE_TOOLTIPS["CUSTOM_BIND"]),
        ),
        default="BASE_SKIN",
    )

    @classmethod
    def description(cls, _context, properties):
        return COMPONENT_BINDING_SCOPE_TOOLTIPS.get(getattr(properties, "scope", ""), "设置当前组件是否进入基础蒙皮")

    def execute(self, context):
        settings = context.scene.wgame_rigging_assistant
        components = _unrigged_components(settings)
        if not components:
            self.report({"ERROR"}, "请先扫描连通组件")
            return {"CANCELLED"}
        if not _component_scan_is_current(context, settings):
            self.report({"ERROR"}, "模型顶点已变化，请先点击“修复组件记录”")
            return {"CANCELLED"}
        if _component_has_legacy_binding_data(settings):
            self.report({"ERROR"}, "检测到旧六类用途；请先点击“清空旧用途并重新分类”")
            return {"CANCELLED"}
        if _unrigged_component_uses_complete(settings):
            self.report({"WARNING"}, "全部组件已经分类；如需修改，请先点击“修改当前分类”")
            return {"CANCELLED"}
        index = min(settings.unrigged_component_index, len(components) - 1)
        _ensure_custom_mask_groups(context, settings)
        mesh_obj = context.scene.objects.get(components[index].get("object", ""))
        _set_custom_mask_vertices(
            mesh_obj,
            components[index].get("vertex_indices") or [],
            self.scope == "CUSTOM_BIND",
        )
        components = _sync_component_scopes_from_mask(context, settings, finalized=False)
        components[index].pop("role", None)
        components[index].pop("binding_group_id", None)
        settings.unrigged_components_json = json.dumps(components, ensure_ascii=False, separators=(",", ":"))
        if self.scope == "CUSTOM_BIND" and settings.unrigged_custom_selection_hidden:
            _set_component_vertices_hidden(context, components[index], True)
        next_pending = _next_unready_component_index(settings, components)
        if next_pending is not None:
            settings.unrigged_component_index = next_pending
            _focus_unrigged_component(context, components[next_pending])
        else:
            obj = context.scene.objects.get(components[index].get("object", ""))
            if obj:
                _select_only(context, obj)
        completed = sum(1 for item in components if _component_use_ready(settings, item))
        self.report({"INFO"}, f"组件 {index + 1} → {COMPONENT_BINDING_SCOPE_LABELS[self.scope]}；已完成 {completed}/{len(components)}")
        _tag_component_scope_undo()
        return {"FINISHED"}


