        body_preview.prop(settings, "wgame_muscle_body_bend", slider=True)
        body_preview.prop(settings, "wgame_muscle_body_twist", slider=True)
        arm_preview = pose_box.box()
        arm_preview.label(text="肩、手臂与手指", icon="BONE_DATA")
        arm_preview.prop(settings, "wgame_muscle_arm_close", slider=True)
        arm_preview.prop(settings, "wgame_muscle_arm_front", slider=True)
        arm_preview.prop(settings, "wgame_muscle_elbow_bend", slider=True)
        arm_preview.prop(settings, "wgame_muscle_forearm_twist", slider=True)
        arm_preview.prop(settings, "wgame_muscle_finger_curl", slider=True)
        arm_preview.prop(settings, "wgame_muscle_finger_spread", slider=True)
        leg_preview = pose_box.box()
        leg_preview.label(text="髋、腿与足部", icon="CONSTRAINT_BONE")
        leg_preview.prop(settings, "wgame_muscle_leg_open", slider=True)
        leg_preview.prop(settings, "wgame_muscle_leg_front", slider=True)
        leg_preview.prop(settings, "wgame_muscle_knee_bend", slider=True)
        leg_preview.prop(settings, "wgame_muscle_foot_bend", slider=True)
        custom_preview = pose_box.box()
