_JOINT_GUIDE_KEYMAPS = []


def _register_joint_guide_keymap():
    config = bpy.context.window_manager.keyconfigs.addon
    if config and not _JOINT_GUIDE_KEYMAPS:
        keymap = config.keymaps.new(name="3D View", space_type="VIEW_3D")
        item = keymap.keymap_items.new("wgame_rigging.pick_joint_guide", "LEFTMOUSE", "PRESS", head=True)
        _JOINT_GUIDE_KEYMAPS.append((keymap, item))


def register():
    for cls in classes:
        # Existing import monitoring is allowed to finish while the user views
        # a preview. Every new authoring action requires the source scene.
        if issubclass(cls, Operator) and cls.bl_idname != 'wgame_rigging.monitor_unity_publish':
            _guard_authoring_operator(cls)
        bpy.utils.register_class(cls)
    bpy.types.Scene.wgame_rigging_assistant = PointerProperty(type=WGAME_RIGGING_Settings)
    if _joint_guide_live_mirror_handler not in bpy.app.handlers.depsgraph_update_post:
        bpy.app.handlers.depsgraph_update_post.append(_joint_guide_live_mirror_handler)
    _ensure_focus_draw_handler()
    _register_joint_guide_keymap()
    for handlers in (bpy.app.handlers.undo_post, bpy.app.handlers.redo_post):
        if _component_scope_undo_redo_post not in handlers:
            handlers.append(_component_scope_undo_redo_post)


def unregister():
    for handlers in (bpy.app.handlers.undo_post, bpy.app.handlers.redo_post):
        if _component_scope_undo_redo_post in handlers:
            handlers.remove(_component_scope_undo_redo_post)
    _RIGID_MARKS_CACHE.clear()
    _RIGID_PICK_FEEDBACK.clear()
    _RIGID_QUICK_LAST.clear()
    _close_chain_weight_view(bpy.context, restore=False)
    _BONE_EDIT_RETURN.clear()
    for keymap, item in _JOINT_GUIDE_KEYMAPS:
        keymap.keymap_items.remove(item)
    _JOINT_GUIDE_KEYMAPS.clear()
    if _joint_guide_live_mirror_handler in bpy.app.handlers.depsgraph_update_post:
        bpy.app.handlers.depsgraph_update_post.remove(_joint_guide_live_mirror_handler)
    _remove_focus_draw_handler()
    _FOCUS_STATE.clear()
    _BASE_REGION_OVERLAY_CACHE.clear()
    _BASE_REGION_ASSIGNMENTS_CACHE.clear()
    _COMPONENT_SCOPE_COUNTS_CACHE.clear()
    if hasattr(bpy.types.Scene, "wgame_rigging_assistant"):
        del bpy.types.Scene.wgame_rigging_assistant
    for cls in reversed(classes):
        bpy.utils.unregister_class(cls)


if __name__ == "__main__":
    register()
